/**
 * Toasts — mesmo desenho do admin: um `st-alert` que se move sozinho para a
 * pilha de toasts do Stratum. No legado isto era o banner de mensagem montado à
 * mão pelo estado raiz do Alpine.
 */

import type StAlert from '@marinx/stratum/components/alert/alert.js';

export type Variante = 'success' | 'danger' | 'warning' | 'neutral';

const DURACAO_MS = 4000;

const ICONES: Readonly<Record<Variante, string>> = {
  success: 'circle-check',
  danger: 'alert-triangle',
  warning: 'alert-triangle',
  neutral: 'info-circle',
};

export function notificar(mensagem: string, variante: Variante = 'success'): void {
  const alerta = Object.assign(document.createElement('st-alert'), {
    variant: variante,
    closable: true,
    duration: DURACAO_MS,
  }) as StAlert;

  const icone = document.createElement('st-icon');
  icone.setAttribute('slot', 'icon');
  icone.setAttribute('name', ICONES[variante]);

  alerta.append(icone, document.createTextNode(mensagem));
  document.body.append(alerta);

  void alerta.toast();
}
