/**
 * Os checklists do Esteja Preparado — porte de `modulos/prep/kits.js`.
 *
 * Os kits nascem do acervo curado (`dados/kits.json`) e passam a ser do usuário:
 * a semeadura acontece **sempre que o acervo local está vazio**, o que serve para
 * a primeira abertura e também para quem apagou tudo e quer os padrões de volta.
 * Enquanto existir um kit local, nada é tocado — não há marca em `localStorage`
 * dizendo "já semeei", porque "está vazio?" é a própria condição, e uma marca
 * poderia ficar selada com o acervo vazio.
 *
 * O progresso (o que está marcado) fica no `localStorage`, e não no registro do
 * kit: é estado de uso do aparelho, e uma mochila conferida hoje não muda o
 * conteúdo do checklist.
 */

import { epochDeDataISO } from '../../datas.ts';
import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';
import { S } from '../../strings.ts';

/** Um item do checklist. */
export interface ItemDoKit {
  id: number;
  descricao: string;
  quantidade: string;
  observacoes: string;
  data_vencimento: number;
}

export interface Kit extends Registro {
  id?: number;
  nome: string;
  icone: string;
  itens: ItemDoKit[];
  data_criacao: number;
  data_atualizacao: number;
}

/** O formato dos kits curados, que é mais frouxo que o local. */
interface KitCurado extends Registro {
  nome?: string;
  icone?: string;
  itens?: readonly {
    rotulo?: string;
    descricao?: string;
    quantidade?: string | number;
    observacoes?: string;
    data_vencimento?: number;
  }[];
}

const CHAVE_PROGRESSO = 'papiro_prep_kits';

const curados = () => repositorio('kits');
const locais = () => repositorio('kits_local');

export type Progresso = Record<string, Record<string, boolean>>;

export function lerProgresso(): Progresso {
  try {
    const bruto = JSON.parse(localStorage.getItem(CHAVE_PROGRESSO) ?? '{}') as unknown;
    return typeof bruto === 'object' && bruto !== null ? (bruto as Progresso) : {};
  } catch {
    return {};
  }
}

export function salvarProgresso(progresso: Progresso): void {
  localStorage.setItem(CHAVE_PROGRESSO, JSON.stringify(progresso));
}

/**
 * Semeia os kits curados no acervo local quando ele está vazio. Se a
 * sincronização ainda não trouxe o acervo curado, não faz nada — e a próxima
 * abertura tenta de novo.
 */
async function semearSeVazio(): Promise<void> {
  const meus = await locais().todos<Kit>();
  if (meus.length > 0) return;

  const acervo = await curados().todos<KitCurado>();
  if (acervo.length === 0) return;

  const agora = Date.now();
  // O `id` é explícito porque `substituirTudo` espelha a tabela por chave
  // primária: sem ele a gravação em massa não tem onde ancorar cada registro.
  const registros: Kit[] = acervo.map((kit, indice) => ({
    id: indice + 1,
    nome: kit.nome ?? '',
    icone: kit.icone ?? '',
    itens: (kit.itens ?? []).map((item, ordem) => ({
      id: ordem + 1,
      descricao: item.rotulo ?? item.descricao ?? '',
      quantidade: String(item.quantidade ?? ''),
      observacoes: item.observacoes ?? '',
      data_vencimento: item.data_vencimento ?? 0,
    })),
    data_criacao: agora,
    data_atualizacao: agora,
  }));

  await locais().substituirTudo(registros);
}

/** Os kits do usuário, em ordem alfabética, semeando se preciso. */
export async function carregarKits(): Promise<Kit[]> {
  await semearSeVazio();

  const meus = await locais().todos<Kit>();
  return meus.sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR', { sensitivity: 'base' }));
}

export function obterKit(id: number): Promise<Kit | undefined> {
  return locais().obter<Kit>(id);
}

// ── Progresso por item ──────────────────────────────────────────────────────

export function itemMarcado(progresso: Progresso, kit: Kit, itemId: number): boolean {
  return progresso[String(kit.id)]?.[String(itemId)] === true;
}

/** Liga/desliga um item e devolve o progresso novo, já persistido. */
export function alternarItem(progresso: Progresso, kit: Kit, itemId: number): Progresso {
  const chave = String(kit.id);
  const doKit = { ...(progresso[chave] ?? {}) };
  doKit[String(itemId)] = !doKit[String(itemId)];

  const novo: Progresso = { ...progresso, [chave]: doKit };
  salvarProgresso(novo);
  return novo;
}

export function marcadosDoKit(progresso: Progresso, kit: Kit): number {
  const doKit = progresso[String(kit.id)] ?? {};
  return kit.itens.filter((item) => doKit[String(item.id)] === true).length;
}

export function percentualDoKit(progresso: Progresso, kit: Kit): number {
  if (kit.itens.length === 0) return 0;
  return Math.round((marcadosDoKit(progresso, kit) / kit.itens.length) * 100);
}

export function kitCompleto(progresso: Progresso, kit: Kit): boolean {
  return kit.itens.length > 0 && marcadosDoKit(progresso, kit) === kit.itens.length;
}

// ── Gravação ────────────────────────────────────────────────────────────────

/** Um item do formulário: o vencimento em `YYYY-MM-DD`, como o campo o fala. */
export interface ItemEmEdicao {
  id: number;
  descricao: string;
  quantidade: string;
  observacoes: string;
  vencimento: string;
}

/**
 * Grava o checklist. Os ids dos itens são renumerados de 1 a N na ordem da tela:
 * eles só precisam ser estáveis dentro do kit, e é isso que a chave do progresso
 * usa.
 */
export async function salvarKit(entrada: {
  id: number;
  nome: string;
  icone: string;
  itens: readonly ItemEmEdicao[];
  criacao: number;
}): Promise<void> {
  const agora = Date.now();

  const itens: ItemDoKit[] = entrada.itens
    .map((item, indice) => ({
      id: indice + 1,
      descricao: item.descricao.trim(),
      quantidade: item.quantidade.trim(),
      observacoes: item.observacoes.trim(),
      data_vencimento: item.vencimento === '' ? 0 : epochDeDataISO(item.vencimento),
    }))
    .filter((item) => item.descricao !== '');

  await locais().salvar({
    ...(entrada.id > 0 ? { id: entrada.id } : {}),
    nome: entrada.nome.trim() === '' ? S.prep.kitSemNome : entrada.nome.trim(),
    icone: entrada.icone,
    itens,
    data_criacao: entrada.criacao === 0 ? agora : entrada.criacao,
    data_atualizacao: agora,
  });
}

/** Apaga o kit e o progresso dele — sem isso a chave ficaria órfã para sempre. */
export async function excluirKit(kit: Kit, progresso: Progresso): Promise<Progresso> {
  const novo = { ...progresso };
  delete novo[String(kit.id)];
  salvarProgresso(novo);

  if (kit.id !== undefined) await locais().excluir(kit.id);
  return novo;
}
