/**
 * Compartilhar um texto — porte do `compartilhar()` repetido em Guias, Poesia e
 * Receitas no legado.
 *
 * Caminho preferido é o `navigator.share` do sistema; sem ele, copia para a área
 * de transferência. O legado avisava a cópia com `alert()`; aqui o aviso é o
 * toast do app, que é o padrão de todo o resto.
 */

import { S } from '../strings.ts';
import { notificar } from './notificar.ts';

export async function compartilhar(titulo: string, corpo: string): Promise<void> {
  const texto = `${titulo}\n\n${corpo}`;

  // `typeof`, e não `'share' in navigator`: o tipo do DOM declara `share` como
  // sempre presente, e o `in` estreitaria o ramo do fallback para `never`.
  if (typeof navigator.share === 'function') {
    try {
      await navigator.share({ title: titulo, text: texto });
    } catch {
      // Cancelar o compartilhamento não é erro: o usuário desistiu.
    }
    return;
  }

  try {
    await navigator.clipboard.writeText(texto);
    notificar(S.leitura.copiado);
  } catch {
    notificar(S.leitura.semCopiar, 'warning');
  }
}
