/**
 * Os dados de "Teve um Projeto?" e "Entenda Melhor" — porte de
 * `modulos/criacao/criacao.js` e `modulos/criacao/progresso.js`.
 *
 * Os dois módulos são a mesma engine vista por duas rotas: `#/criacao` traz os
 * puzzles da criação, agrupados por categoria; `#/entenda` traz os raciocínios
 * bíblicos refeitos passo a passo, em lista corrida. Quem decide é o modo, e não
 * uma cópia do módulo — foi assim no legado e continua sendo.
 *
 * O catálogo é conteúdo curado (só leitura); o progresso é do aparelho e vive no
 * `localStorage`, na chave do legado (`papiro_criacao_progresso`). O "Caderno do
 * Investigador" não mora aqui: ele é uma anotação do Caderno de Estudo com
 * `origem: 'criacao'`, e é a presença dela que dá o selo de Estudo Diligente.
 *
 * Tudo neste arquivo é puro ou toca só armazenamento — quem desenha é a tela.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';
import { listarAnotacoes } from '../caderno/dados.ts';

/** Um módulo do catálogo, como vem do admin. */
export interface ModuloCriacao extends Registro {
  id?: number;
  titulo: string;
  categoria: string;
  /** Escolhe o renderizador do puzzle (ver `renderizadores/`). */
  tipo: string;
  icone: string;
  ordem: number;
  conceito: string;
  desafio: string;
  reflexao: string;
  referencia: string;
  link_jw: string;
  /** JSON com os parâmetros do puzzle, editado no admin. */
  config: string;
  imagem: string;
  publicar: number;
}

/** As categorias, em ordem de exibição (espelham `CriacaoPage::CATEGORIAS`). */
export const CATEGORIAS: Readonly<Record<string, string>> = {
  natureza: 'A Natureza',
  terra: 'A Terra',
  entenda: 'Entenda Melhor',
  matematica: 'Matemática',
  corpo: 'O Corpo Humano',
  animal: 'O Reino Animal',
  universo: 'Universo e Física',
};

const ORDEM_CATEGORIAS = Object.keys(CATEGORIAS);
const CATEGORIA_RESERVA = 'natureza';

export function rotuloCategoria(chave: string): string {
  return CATEGORIAS[chave] ?? chave;
}

/** Qual dos dois módulos está em cena. */
export type ModoId = 'criacao' | 'entenda';

export interface Modo {
  readonly id: ModoId;
  readonly titulo: string;
  readonly subtitulo: string;
  /** Filtro do catálogo: a categoria `entenda` fica de um lado, o resto do outro. */
  inclui(m: ModuloCriacao): boolean;
  /** "Teve um Projeto?" agrupa por categoria; "Entenda Melhor" é lista corrida. */
  readonly agrupado: boolean;
}

export const MODOS: Readonly<Record<ModoId, Modo>> = {
  criacao: {
    id: 'criacao',
    titulo: 'Teve um Projeto?',
    subtitulo:
      'Descubra os mistérios escondidos na criação e dê louvor à sabedoria do Criador, Jeová.',
    inclui: (m) => m.categoria !== 'entenda',
    agrupado: true,
  },
  entenda: {
    id: 'entenda',
    titulo: 'Entenda Melhor',
    subtitulo:
      'Raciocínios bíblicos que costumam travar as pessoas, refeitos passo a passo por você.',
    inclui: (m) => m.categoria === 'entenda',
    agrupado: false,
  },
};

export function modo(id: string): Modo {
  return id === 'entenda' ? MODOS.entenda : MODOS.criacao;
}

// ── Catálogo ────────────────────────────────────────────────────────────────

export async function carregarModulos(): Promise<ModuloCriacao[]> {
  const linhas = await repositorio('criacao_modulos').todos<ModuloCriacao>();
  return linhas.sort(
    (a, b) => Number(a.ordem) - Number(b.ordem) || Number(a.id ?? 0) - Number(b.id ?? 0),
  );
}

/** Um grupo da lista: uma categoria e os módulos dela. */
export interface Grupo {
  readonly chave: string;
  readonly rotulo: string;
  readonly modulos: readonly ModuloCriacao[];
  readonly concluida: boolean;
}

/**
 * Agrupa por categoria, na ordem canônica. Categoria desconhecida cai em
 * "A Natureza", como no legado — um módulo novo do admin aparece na lista mesmo
 * que a categoria dele ainda não exista aqui.
 */
export function agrupar(
  modulos: readonly ModuloCriacao[],
  concluido: (m: ModuloCriacao) => boolean,
): Grupo[] {
  const grupos = new Map<string, ModuloCriacao[]>();

  for (const m of modulos) {
    const chave = CATEGORIAS[m.categoria] === undefined ? CATEGORIA_RESERVA : m.categoria;
    const lista = grupos.get(chave);
    if (lista === undefined) grupos.set(chave, [m]);
    else lista.push(m);
  }

  return ORDEM_CATEGORIAS.filter((chave) => (grupos.get(chave)?.length ?? 0) > 0).map((chave) => {
    const lista = grupos.get(chave) ?? [];
    return {
      chave,
      rotulo: rotuloCategoria(chave),
      modulos: lista,
      concluida: lista.every(concluido),
    };
  });
}

/** Os parâmetros do puzzle. Config inválida vira objeto vazio (todo default vale). */
export function lerConfig(m: ModuloCriacao | null): Record<string, unknown> {
  if (m === null) return {};
  try {
    const bruto: unknown = JSON.parse(m.config === '' ? '{}' : m.config);
    return bruto !== null && typeof bruto === 'object' && !Array.isArray(bruto)
      ? (bruto as Record<string, unknown>)
      : {};
  } catch {
    return {};
  }
}

// ── Progresso (localStorage, chave do legado) ───────────────────────────────

const CHAVE_PROGRESSO = 'papiro_criacao_progresso';

export interface Conclusao {
  tentativas: number;
  concluidoEm: number;
}

export interface Progresso {
  concluidos: Record<string, Conclusao>;
}

export function progressoVazio(): Progresso {
  return { concluidos: {} };
}

export function lerProgresso(): Progresso {
  try {
    const bruto = JSON.parse(localStorage.getItem(CHAVE_PROGRESSO) ?? 'null') as unknown;
    return { ...progressoVazio(), ...(bruto as Partial<Progresso> | null) };
  } catch {
    return progressoVazio();
  }
}

export function salvarProgresso(progresso: Progresso): void {
  localStorage.setItem(CHAVE_PROGRESSO, JSON.stringify(progresso));
}

/** Marca a conclusão de um módulo, somando mais uma tentativa. */
export function registrarConclusao(progresso: Progresso, id: number): Progresso {
  const anterior = progresso.concluidos[String(id)];
  const atualizado: Progresso = {
    ...progresso,
    concluidos: {
      ...progresso.concluidos,
      [String(id)]: {
        tentativas: (anterior?.tentativas ?? 0) + 1,
        concluidoEm: Date.now(),
      },
    },
  };
  salvarProgresso(atualizado);
  return atualizado;
}

export function concluido(progresso: Progresso, m: ModuloCriacao | null): boolean {
  return m?.id !== undefined && progresso.concluidos[String(m.id)] !== undefined;
}

// ── Caderno do Investigador ─────────────────────────────────────────────────

/** Chave estável da anotação de um módulo no Caderno de Estudo unificado. */
export function refCaderno(id: number): string {
  return `criacao:${id}`;
}

/**
 * As anotações de "Teve um Projeto?" por id de módulo.
 *
 * É daqui que sai o selo de Estudo Diligente: concluir não basta — o selo é de
 * quem escreveu, com as próprias palavras, o que aprendeu.
 */
export async function carregarCaderno(): Promise<Map<number, string>> {
  const mapa = new Map<number, string>();

  for (const anotacao of await listarAnotacoes()) {
    if (anotacao.origem !== 'criacao' || anotacao.ref_chave === null) continue;
    const id = Number(anotacao.ref_chave.split(':')[1]);
    if (Number.isFinite(id)) mapa.set(id, anotacao.conteudo);
  }

  return mapa;
}
