/**
 * O inventário tático do Esteja Preparado — porte de `modulos/prep/estoque.js`.
 *
 * O estoque é semeado a partir do **catálogo curado** (admin → export → sync) e,
 * se ele ainda não chegou (primeiro uso offline), do `SEED` embutido em
 * `dados.ts`. A promessa da semeadura é memoizada: a carga do módulo e a
 * sincronização de boot podem acontecer juntas, e sem isso as duas semeariam o
 * inventário inteiro cada uma.
 *
 * O perfil da calculadora (idade, atividade, pessoas) fica no `localStorage` — é
 * a configuração de quem usa o app, não dado do inventário.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';
import {
  ATIVIDADES,
  CATEGORIA_FIBRAS,
  CATEGORIA_PADRAO,
  CATEGORIAS,
  caloriasDoItem,
  categoria,
  DIAS_ALVO,
  type FaixaDeIdade,
  IDADES,
  LITROS_POR_PESSOA_DIA,
  MESES_VALIDADE,
  MINIMO_FIBRAS,
  type NivelDeAtividade,
  necessidadeDoGrupo,
  PERFIL_PADRAO,
  type Perfil,
  SEED,
} from './dados.ts';

export interface ItemDoEstoque extends Registro {
  id?: number;
  item: string;
  categoria: string;
  quantidade: number;
  peso_unitario: number;
  calorias_por_100g: number;
  data_vencimento: number;
}

/** O catálogo curado, com a validade em meses em vez de data. */
interface ItemDoCatalogo extends Registro {
  item?: string;
  categoria?: string;
  quantidade?: number;
  peso_unitario?: number;
  calorias_por_100g?: number;
  validade_meses?: number;
}

const CHAVE_PERFIL = 'papiro_prep_calc';

const estoque = () => repositorio('estoque_alimentos');
const catalogo = () => repositorio('estoque_catalogo');

// ── Perfil da calculadora ───────────────────────────────────────────────────

export function lerPerfil(): Perfil {
  try {
    const bruto = JSON.parse(localStorage.getItem(CHAVE_PERFIL) ?? 'null') as unknown;
    return { ...PERFIL_PADRAO, ...(bruto as Partial<Perfil> | null) };
  } catch {
    return PERFIL_PADRAO;
  }
}

export function salvarPerfil(perfil: Perfil): void {
  const limpo: Perfil = { ...perfil, pessoas: Math.max(1, Number(perfil.pessoas) || 1) };
  localStorage.setItem(CHAVE_PERFIL, JSON.stringify(limpo));
}

export const FAIXAS: readonly FaixaDeIdade[] = [
  'BEBE',
  'CRIANCA',
  'ADOLESCENTE',
  'ADULTO_M',
  'ADULTO_F',
  'IDOSO',
  'MISTO',
];

export const NIVEIS: readonly NivelDeAtividade[] = ['SEDENTARIO', 'LEVE', 'MODERADO', 'INTENSO'];

export function rotuloDaFaixa(faixa: FaixaDeIdade): string {
  return IDADES[faixa]?.rotulo ?? faixa;
}

export function rotuloDoNivel(nivel: NivelDeAtividade): string {
  return ATIVIDADES[nivel]?.rotulo ?? nivel;
}

// ── Semeadura e carga ───────────────────────────────────────────────────────

const DIAS_POR_MES = 30;

let semeando: Promise<void> | undefined;

function semearSeVazio(): Promise<void> {
  semeando ??= (async () => {
    if ((await estoque().todos()).length > 0) return;

    const agora = Date.now();
    const curado = await catalogo().todos<ItemDoCatalogo>();

    const fonte =
      curado.length > 0
        ? curado.map((linha) => ({
            item: linha.item ?? '',
            categoria: linha.categoria ?? CATEGORIA_PADRAO,
            quantidade: Number(linha.quantidade) || 0,
            peso_unitario: Number(linha.peso_unitario) || 0,
            calorias_por_100g: Number(linha.calorias_por_100g) || 0,
            validadeMeses: Number(linha.validade_meses) || 12,
          }))
        : SEED.map(([nome, indice, quantidade, peso, kcal]) => ({
            item: nome,
            categoria: CATEGORIAS[indice]?.nome ?? CATEGORIA_PADRAO,
            quantidade,
            peso_unitario: peso,
            calorias_por_100g: kcal,
            validadeMeses: MESES_VALIDADE[indice] ?? 12,
          }));

    for (const linha of fonte) {
      await estoque().salvar({
        item: linha.item,
        categoria: linha.categoria,
        quantidade: linha.quantidade,
        peso_unitario: linha.peso_unitario,
        calorias_por_100g: linha.calorias_por_100g,
        // Validade relativa a hoje, nunca uma data fixa (ver `dados.ts`).
        data_vencimento: agora + linha.validadeMeses * DIAS_POR_MES * 86_400_000,
      });
    }
  })();

  return semeando;
}

export async function carregarEstoque(): Promise<ItemDoEstoque[]> {
  await semearSeVazio();
  return estoque().todos<ItemDoEstoque>();
}

export function obterItem(id: number): Promise<ItemDoEstoque | undefined> {
  return estoque().obter<ItemDoEstoque>(id);
}

export function salvarItem(item: ItemDoEstoque): Promise<number> {
  return estoque().salvar(item);
}

export function excluirItem(id: number): Promise<void> {
  return estoque().excluir(id);
}

// ── Lista e agrupamento ─────────────────────────────────────────────────────

/** Filtra pela busca e ordena pela ordem tática da categoria, depois pelo nome. */
export function visiveis(lista: readonly ItemDoEstoque[], busca: string): ItemDoEstoque[] {
  const alvo = busca.trim().toLowerCase();

  const filtrados =
    alvo === ''
      ? [...lista]
      : lista.filter(
          (item) =>
            item.item.toLowerCase().includes(alvo) || item.categoria.toLowerCase().includes(alvo),
        );

  return filtrados.sort(
    (a, b) =>
      categoria(a.categoria).ordem - categoria(b.categoria).ordem ||
      a.item.localeCompare(b.item, 'pt-BR', { sensitivity: 'base' }),
  );
}

export interface GrupoDoEstoque {
  readonly nome: string;
  readonly info: ReturnType<typeof categoria>;
  readonly itens: ItemDoEstoque[];
}

export function porCategoria(lista: readonly ItemDoEstoque[]): GrupoDoEstoque[] {
  const grupos = new Map<string, ItemDoEstoque[]>();

  for (const item of lista) {
    const nome = categoria(item.categoria).nome;
    const atual = grupos.get(nome);
    if (atual === undefined) grupos.set(nome, [item]);
    else atual.push(item);
  }

  return [...grupos].map(([nome, itens]) => ({ nome, info: categoria(nome), itens }));
}

export function pesoEmKg(item: ItemDoEstoque): number {
  return (item.quantidade * item.peso_unitario) / 1000;
}

// ── Autonomia e logística ───────────────────────────────────────────────────

export interface Autonomia {
  readonly kcalTotal: number;
  readonly porPessoa: number;
  readonly doGrupo: number;
  readonly dias: number;
  /** Avanço rumo aos 30 dias-alvo, em porcentagem. */
  readonly metaPercentual: number;
  readonly litrosDeAgua: number;
  readonly pesoTotalKg: number;
  readonly tom: 'sucesso' | 'aviso' | 'perigo';
}

export function calcularAutonomia(lista: readonly ItemDoEstoque[], perfil: Perfil): Autonomia {
  const kcalTotal = lista.reduce((soma, item) => soma + (caloriasDoItem(item) ?? 0), 0);
  const doGrupo = necessidadeDoGrupo(perfil);
  const dias = Math.floor(kcalTotal / doGrupo);
  const pessoas = Math.max(1, perfil.pessoas);

  return {
    kcalTotal,
    porPessoa: Math.round(doGrupo / pessoas),
    doGrupo,
    dias,
    metaPercentual: Math.min(100, Math.round((dias / DIAS_ALVO) * 100)),
    litrosDeAgua: Math.ceil(pessoas * dias * LITROS_POR_PESSOA_DIA),
    pesoTotalKg: Math.round(lista.reduce((soma, item) => soma + pesoEmKg(item), 0) * 10) / 10,
    tom: dias >= 30 ? 'sucesso' : dias >= 7 ? 'aviso' : 'perigo',
  };
}

export interface Logistica {
  readonly consolidadas: number;
  /** Dias de autonomia só com o que se come sem água nem fogo. */
  readonly diasFrios: number;
  readonly diasTotais: number;
  readonly fibras: number;
  readonly vulneravel: boolean;
}

/**
 * A logística tática: quanto do estoque se come de imediato e quanto depende de
 * água e fogo, mais a vulnerabilidade em fibras. O corte frio/quente é a pergunta
 * "e se faltar gás e água?", que uma soma única de calorias esconde.
 */
export function calcularLogistica(lista: readonly ItemDoEstoque[], perfil: Perfil): Logistica {
  let frias = 0;
  let quentes = 0;
  let fibras = 0;

  for (const item of lista) {
    const info = categoria(item.categoria);
    const kcal = caloriasDoItem(item) ?? 0;

    if (info.fria) frias += kcal;
    else if (info.quente) quentes += kcal;

    if (info.nome === CATEGORIA_FIBRAS) fibras += item.quantidade;
  }

  const meta = necessidadeDoGrupo(perfil);
  const consolidadas = frias + quentes;

  return {
    consolidadas,
    diasFrios: Math.floor(frias / meta),
    diasTotais: Math.floor(consolidadas / meta),
    fibras,
    vulneravel: fibras < MINIMO_FIBRAS,
  };
}

// ── Validade ────────────────────────────────────────────────────────────────

const JANELA_ALERTA_MS = 7 * 86_400_000;

export type StatusDeValidade = 'vencido' | 'proximo' | 'ok';

export function statusDeValidade(item: ItemDoEstoque): StatusDeValidade {
  if (item.data_vencimento === 0) return 'ok';

  const restante = item.data_vencimento - Date.now();
  if (restante < 0) return 'vencido';
  return restante < JANELA_ALERTA_MS ? 'proximo' : 'ok';
}

export interface Alertas {
  readonly vencidos: ItemDoEstoque[];
  readonly aVencer: ItemDoEstoque[];
  readonly total: number;
}

export function alertas(lista: readonly ItemDoEstoque[]): Alertas {
  const agora = Date.now();
  const limite = agora + JANELA_ALERTA_MS;

  const vencidos = lista.filter((item) => item.data_vencimento > 0 && item.data_vencimento < agora);
  const aVencer = lista.filter(
    (item) => item.data_vencimento >= agora && item.data_vencimento < limite,
  );

  return { vencidos, aVencer, total: vencidos.length + aVencer.length };
}

/** Dias até vencer — negativo quando já venceu; `null` sem data. */
export function diasParaVencer(item: ItemDoEstoque): number | null {
  if (item.data_vencimento === 0) return null;
  return Math.ceil((item.data_vencimento - Date.now()) / 86_400_000);
}
