/**
 * A tela do Calendário — porte da seção `calendario` do `index.html` legado.
 *
 * O painel de KPIs, o seletor de vista, o salto por mês/ano, a navegação do
 * período e as cinco vistas. O formulário de evento e a gestão de tipos eram
 * overlays e continuam sendo diálogos — são interrupções curtas sobre o
 * calendário, e tirar o calendário da tela para pedir um título seria pior.
 *
 * **O FullCalendar saiu.** As vistas são grade CSS alimentada por `vistas.ts`
 * (ver o cabeçalho de lá para o que isso custou: arrastar e redimensionar o
 * evento). Em troca, o módulo não carrega seis pacotes em tempo de execução, e o
 * desenho usa os mesmos tokens do resto do app em vez do tema de outra
 * biblioteca — que era o motivo de o legado ter uma folha de correções só para
 * ele.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { atualizar, type Tela } from '../../app/tela.ts';
import { dataLocalISO, epochDeDataISO } from '../../datas.ts';
import { S } from '../../strings.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { notificar } from '../../ui/notificar.ts';
import {
  CORES,
  calcularKpis,
  carregar as carregarDados,
  comoHora,
  corDoTipo,
  deHora,
  diaFinal,
  diaInicial,
  type Evento,
  eventosDoDia,
  excluirEvento,
  excluirTipo,
  ICONES,
  iconeDoTipo,
  type Kpis,
  proximaOrdem,
  salvarEvento,
  salvarTipo,
  type Tipo,
  tipoEmUso,
  tipoPorId,
} from './dados.ts';
import {
  type CelulaDoMes,
  diasDaSemana,
  diasDoPeriodo,
  faixaNaGrade,
  gradeDoMes,
  horasDaGrade,
  mesesDoAno,
  navegado,
  periodoDa,
  rotuloLongoDoDia,
  tituloDoPeriodo,
  VISTAS,
  type Vista,
} from './vistas.ts';

/** O formulário do evento, com datas e horas como o campo as fala. */
interface FormEvento {
  id: number;
  titulo: string;
  tipoId: number;
  diaInteiro: boolean;
  dataInicio: string;
  horaInicio: string;
  dataFim: string;
  horaFim: string;
  descricao: string;
}

interface FormTipo {
  id: number;
  nome: string;
  cor: string;
  icone: string;
  especial: boolean;
}

let tipos: Tipo[] = [];
let eventos: Evento[] = [];
let kpis: Kpis = { horas: 0, conflitos: 0, diasParaEspecial: null };

let vista: Vista = 'semana';
let referencia = new Date();

let formEvento: FormEvento | null = null;
let painelDeTipos = false;
let formTipo: FormTipo | null = null;

let carregado = false;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregar(): Promise<void> {
  const dados = await carregarDados();
  tipos = dados.tipos;
  eventos = dados.eventos;
  kpis = calcularKpis(eventos, tipos);
  atualizar();
}

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      await recarregar();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Painel de KPIs ──────────────────────────────────────────────────────────

function textoDoEspecial(): string {
  if (kpis.diasParaEspecial === null) return S.calendario.kpiNenhum;
  if (kpis.diasParaEspecial === 0) return S.calendario.kpiHoje;
  return S.calendario.kpiDias(kpis.diasParaEspecial);
}

function painelKpis(): TemplateResult {
  return html`
    <div class="placares">
      <div class="placar">
        <span class="placar__valor" data-tom="primaria">${kpis.horas}h</span>
        <span class="placar__rotulo">${S.calendario.kpiHoras}</span>
      </div>
      <div class="placar">
        <span class="placar__valor" data-tom=${kpis.conflitos > 0 ? 'perigo' : 'neutro'}>
          ${kpis.conflitos}
        </span>
        <span class="placar__rotulo">${S.calendario.kpiConflitos}</span>
      </div>
      <div class="placar">
        <span class="placar__valor" data-tom="sucesso">${textoDoEspecial()}</span>
        <span class="placar__rotulo">${S.calendario.kpiEspecial}</span>
      </div>
    </div>
  `;
}

// ── Barra de navegação ──────────────────────────────────────────────────────

function anosDisponiveis(): number[] {
  const base = referencia.getFullYear();
  return Array.from({ length: 11 }, (_, indice) => base - 5 + indice);
}

function irPara(ano: number, mes: number): void {
  referencia = new Date(ano, mes, 1);
  atualizar();
}

function barra(): TemplateResult {
  return html`
    <div class="chips" role="group" aria-label=${S.calendario.vista}>
      ${VISTAS.map(
        (chave) => html`
          <button
            class="chip"
            ?data-ativo=${vista === chave}
            @click=${() => {
              vista = chave;
              atualizar();
            }}
          >
            ${S.calendario.vistas[chave]}
          </button>
        `,
      )}
    </div>

    <div class="calendario__salto">
      <st-select
        label=${S.calendario.mes}
        size="small"
        .value=${String(referencia.getMonth())}
        @st-change=${(evento: Event) =>
          irPara(referencia.getFullYear(), Number((evento.target as HTMLInputElement).value))}
      >
        ${S.calendario.meses.map(
          (nome, indice) => html`<st-option value=${indice}>${nome}</st-option>`,
        )}
      </st-select>

      <st-select
        label=${S.calendario.ano}
        size="small"
        .value=${String(referencia.getFullYear())}
        @st-change=${(evento: Event) =>
          irPara(Number((evento.target as HTMLInputElement).value), referencia.getMonth())}
      >
        ${anosDisponiveis().map((ano) => html`<st-option value=${ano}>${ano}</st-option>`)}
      </st-select>
    </div>

    <div class="calendario__nav">
      <st-icon-button
        name="chevron-left"
        label=${S.calendario.anterior}
        @click=${() => {
          referencia = navegado(vista, referencia, -1);
          atualizar();
        }}
      ></st-icon-button>
      <st-button
        size="small"
        outline
        @click=${() => {
          referencia = new Date();
          atualizar();
        }}
      >
        ${S.calendario.hoje}
      </st-button>
      <st-icon-button
        name="chevron-right"
        label=${S.calendario.proximo}
        @click=${() => {
          referencia = navegado(vista, referencia, 1);
          atualizar();
        }}
      ></st-icon-button>
      <span class="calendario__periodo">${tituloDoPeriodo(vista, referencia)}</span>
    </div>
  `;
}

// ── Pastilhas de evento ─────────────────────────────────────────────────────

function abrirEdicao(evento: Evento): void {
  formEvento = {
    id: evento.id ?? 0,
    titulo: evento.titulo,
    tipoId: evento.tipo_id,
    diaInteiro: evento.dia_inteiro === 1,
    dataInicio: diaInicial(evento),
    horaInicio: comoHora(evento.hora_inicio_min),
    dataFim: diaFinal(evento),
    horaFim: comoHora(evento.hora_fim_min),
    descricao: evento.descricao,
  };
  atualizar();
}

/** A pastilha compacta, para as grades de mês e ano. */
function pastilha(evento: Evento): TemplateResult {
  const cor = corDoTipo(tipos, evento.tipo_id);

  return html`
    <button
      class="pastilha"
      style=${`--cor-evento:${cor}`}
      title=${evento.titulo}
      @click=${() => abrirEdicao(evento)}
    >
      ${
        evento.dia_inteiro === 1
          ? nothing
          : html`<span class="pastilha__hora">${comoHora(evento.hora_inicio_min)}</span>`
      }
      <span class="pastilha__titulo">${evento.titulo}</span>
    </button>
  `;
}

/** A linha completa, para o dia e a agenda. */
function linhaDoEvento(evento: Evento): TemplateResult {
  const cor = corDoTipo(tipos, evento.tipo_id);
  const tipo = tipoPorId(tipos, evento.tipo_id);

  return html`
    <button class="evento" style=${`--cor-evento:${cor}`} @click=${() => abrirEdicao(evento)}>
      <span class="evento__quando">
        ${
          evento.dia_inteiro === 1
            ? S.calendario.diaInteiro
            : `${comoHora(evento.hora_inicio_min)} – ${comoHora(evento.hora_fim_min)}`
        }
      </span>
      <span class="evento__titulo">
        <st-icon name=${iconeDoTipo(tipos, evento.tipo_id)}></st-icon>${evento.titulo}
      </span>
      ${tipo === undefined ? nothing : html`<span class="evento__tipo">${tipo.nome}</span>`}
      ${
        evento.descricao === ''
          ? nothing
          : html`<span class="evento__descricao">${evento.descricao}</span>`
      }
    </button>
  `;
}

function novoEm(dia: string, horaInicio?: number): void {
  formEvento = {
    id: 0,
    titulo: '',
    tipoId: tipos[0]?.id ?? 0,
    diaInteiro: horaInicio === undefined,
    dataInicio: dia,
    horaInicio: comoHora(horaInicio ?? 8 * 60),
    dataFim: dia,
    horaFim: comoHora((horaInicio ?? 8 * 60) + 60),
    descricao: '',
  };
  atualizar();
}

// ── Vistas ──────────────────────────────────────────────────────────────────

/**
 * Uma célula do mês. A célula é um `div`, e não um botão: as pastilhas dos
 * eventos são botões, e botão dentro de botão não é HTML válido — o navegador
 * desfaz o aninhamento e o clique passa a cair no lugar errado. Quem cria o
 * evento do dia é o número, que também é o alvo de teclado da célula.
 */
function celulaDoMes(celula: CelulaDoMes, hoje: string): TemplateResult {
  const doDia = eventosDoDia(eventos, celula.dia);

  return html`
    <div class="mes__celula" ?data-fora=${!celula.doMes} ?data-hoje=${celula.dia === hoje}>
      <button
        class="mes__numero"
        aria-label=${S.calendario.novoEm(celula.dia)}
        @click=${() => novoEm(celula.dia)}
      >
        ${celula.numero}
      </button>
      <div class="mes__eventos">${doDia.map((evento) => pastilha(evento))}</div>
    </div>
  `;
}

function vistaDoMes(): TemplateResult {
  const hoje = dataLocalISO();

  return html`
    <div class="mes">
      ${diasDaSemana(referencia).map(
        (dia) => html`<span class="mes__cabecalho">${dia.rotulo}</span>`,
      )}
      ${gradeDoMes(referencia.getFullYear(), referencia.getMonth()).map((celula) =>
        celulaDoMes(celula, hoje),
      )}
    </div>
  `;
}

/** A grade de horas de um ou de sete dias — o mesmo desenho, colunas a mais. */
function grade(dias: readonly { dia: string; rotulo: string; numero: number }[]): TemplateResult {
  const horas = horasDaGrade();
  const hoje = dataLocalISO();

  return html`
    <div class="grade" style=${`--colunas:${dias.length}`}>
      <span class="grade__canto"></span>
      ${dias.map(
        (dia) => html`
          <span class="grade__dia" ?data-hoje=${dia.dia === hoje}>
            ${dia.rotulo} ${dia.numero}
          </span>
        `,
      )}

      <div class="grade__horas">
        ${horas.map((hora) => html`<span class="grade__hora">${comoHora(hora * 60)}</span>`)}
      </div>

      ${dias.map((dia) => {
        const doDia = eventosDoDia(eventos, dia.dia);
        const inteiros = doDia.filter((evento) => evento.dia_inteiro === 1);
        const comHora = doDia.filter((evento) => evento.dia_inteiro === 0);

        return html`
          <div class="grade__coluna">
            ${horas.map(
              (hora) => html`
                <button
                  class="grade__vaga"
                  aria-label=${S.calendario.novoAs(dia.rotulo, comoHora(hora * 60))}
                  @click=${() => novoEm(dia.dia, hora * 60)}
                ></button>
              `,
            )}

            ${inteiros.map(
              (evento) => html`
                <span class="grade__inteiro" style=${`--cor-evento:${corDoTipo(tipos, evento.tipo_id)}`}>
                  ${pastilha(evento)}
                </span>
              `,
            )}

            ${comHora.map((evento) => {
              const faixa = faixaNaGrade(evento.hora_inicio_min, evento.hora_fim_min);

              return html`
                <button
                  class="grade__evento"
                  style=${`--cor-evento:${corDoTipo(tipos, evento.tipo_id)};top:${faixa.topo * 100}%;height:${faixa.altura * 100}%`}
                  @click=${() => abrirEdicao(evento)}
                >
                  <span class="grade__evento-hora">${comoHora(evento.hora_inicio_min)}</span>
                  <span class="grade__evento-titulo">${evento.titulo}</span>
                </button>
              `;
            })}
          </div>
        `;
      })}
    </div>
  `;
}

function vistaDoDia(): TemplateResult {
  const dia = dataLocalISO(referencia);

  return grade([
    {
      dia,
      rotulo: referencia.toLocaleDateString('pt-BR', { weekday: 'short' }),
      numero: referencia.getDate(),
    },
  ]);
}

function vistaDaSemana(): TemplateResult {
  return grade(diasDaSemana(referencia));
}

function vistaDoAno(): TemplateResult {
  const hoje = dataLocalISO();

  return html`
    <div class="ano">
      ${mesesDoAno(referencia.getFullYear()).map(
        (mes) => html`
          <div class="ano__mes">
            <button
              class="ano__titulo"
              @click=${() => {
                referencia = new Date(referencia.getFullYear(), mes.mes, 1);
                vista = 'mes';
                atualizar();
              }}
            >
              ${mes.rotulo}
            </button>

            <div class="ano__grade">
              ${diasDaSemana(referencia).map(
                (dia) => html`<span class="ano__cabecalho">${dia.rotulo.slice(0, 1)}</span>`,
              )}
              ${mes.celulas.map((celula) => {
                const quantos = eventosDoDia(eventos, celula.dia).length;

                return html`
                  <button
                    class="ano__dia"
                    ?data-fora=${!celula.doMes}
                    ?data-hoje=${celula.dia === hoje}
                    ?data-com-evento=${quantos > 0}
                    title=${quantos === 0 ? '' : S.calendario.eventos(quantos)}
                    @click=${() => {
                      referencia = new Date(epochDeDataISO(celula.dia));
                      vista = 'dia';
                      atualizar();
                    }}
                  >
                    ${celula.numero}
                  </button>
                `;
              })}
            </div>
          </div>
        `,
      )}
    </div>
  `;
}

function vistaDaAgenda(): TemplateResult {
  const dias = diasDoPeriodo(periodoDa('agenda', referencia)).filter(
    (dia) => eventosDoDia(eventos, dia).length > 0,
  );

  if (dias.length === 0) {
    return html`
      <div class="vazio">
        <st-icon class="vazio__icone" name="calendar"></st-icon>
        <p>${S.calendario.semEventos}</p>
      </div>
    `;
  }

  return html`
    <div class="agenda">
      ${dias.map(
        (dia) => html`
          <div class="agenda__dia">
            <span class="agenda__data">${rotuloLongoDoDia(dia)}</span>
            ${eventosDoDia(eventos, dia).map((evento) => linhaDoEvento(evento))}
          </div>
        `,
      )}
    </div>
  `;
}

function vistaAtual(): TemplateResult {
  if (vista === 'dia') return vistaDoDia();
  if (vista === 'semana') return vistaDaSemana();
  if (vista === 'mes') return vistaDoMes();
  if (vista === 'ano') return vistaDoAno();
  return vistaDaAgenda();
}

// ── Formulário do evento ────────────────────────────────────────────────────

async function gravarEvento(form: FormEvento): Promise<void> {
  // Fim antes do início é engano de digitação, não intenção: alinha no início.
  const dataFim =
    form.dataFim === '' || form.dataFim < form.dataInicio ? form.dataInicio : form.dataFim;
  const inteiro = form.diaInteiro ? 1 : 0;

  await salvarEvento({
    ...(form.id > 0 ? { id: form.id } : {}),
    titulo: form.titulo.trim() === '' ? S.acervo.semTitulo : form.titulo.trim(),
    tipo_id: Number(form.tipoId) || (tipos[0]?.id ?? 0),
    data_inicio_epoch: epochDeDataISO(form.dataInicio),
    hora_inicio_min: inteiro === 1 ? 0 : deHora(form.horaInicio),
    data_fim_epoch: epochDeDataISO(dataFim),
    hora_fim_min: inteiro === 1 ? 23 * 60 + 59 : deHora(form.horaFim),
    dia_inteiro: inteiro,
    descricao: form.descricao.trim(),
  });

  formEvento = null;
  notificar(S.calendario.eventoSalvo);
  await recarregar();
}

async function apagarEvento(form: FormEvento): Promise<void> {
  const ok = await confirmar({
    titulo: S.calendario.excluirEvento,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await excluirEvento(form.id);
  formEvento = null;
  notificar(S.calendario.eventoExcluido);
  await recarregar();
}

function dialogoDoEvento(form: FormEvento): TemplateResult {
  return html`
    <st-dialog
      open
      label=${form.id > 0 ? S.calendario.editarEvento : S.calendario.novoEvento}
      @st-after-hide=${() => {
        formEvento = null;
        atualizar();
      }}
    >
      <div class="formulario">
        <st-input
          label=${S.calendario.titulo}
          placeholder=${S.calendario.tituloPlaceholder}
          .value=${form.titulo}
          @st-input=${(evento: Event) => {
            formEvento = { ...form, titulo: (evento.target as HTMLInputElement).value };
          }}
        ></st-input>

        <div>
          <span class="formulario__rotulo">${S.calendario.tipo}</span>
          <div class="tipos-escolha">
            ${tipos.map(
              (tipo) => html`
                <button
                  class="tipo-chip"
                  ?data-ativo=${form.tipoId === tipo.id}
                  @click=${() => {
                    formEvento = { ...form, tipoId: tipo.id ?? 0 };
                    atualizar();
                  }}
                >
                  <span
                    class="tipo-chip__cor"
                    style=${`background:${CORES[tipo.cor_chave] ?? ''}`}
                  ></span>
                  ${tipo.nome}
                </button>
              `,
            )}
          </div>
        </div>

        <st-switch
          ?checked=${form.diaInteiro}
          @st-change=${(evento: Event) => {
            formEvento = { ...form, diaInteiro: (evento.target as HTMLInputElement).checked };
            atualizar();
          }}
        >
          ${S.calendario.diaInteiro}
        </st-switch>

        <div class="formulario__par">
          <st-input
            type="date"
            label=${S.calendario.dataInicio}
            .value=${form.dataInicio}
            @st-change=${(evento: Event) => {
              const dataInicio = (evento.target as HTMLInputElement).value;
              formEvento = {
                ...form,
                dataInicio,
                dataFim: form.dataFim < dataInicio ? dataInicio : form.dataFim,
              };
              atualizar();
            }}
          ></st-input>
          ${
            form.diaInteiro
              ? nothing
              : html`
                <st-input
                  type="time"
                  label=${S.calendario.horaInicio}
                  .value=${form.horaInicio}
                  @st-change=${(evento: Event) => {
                    formEvento = { ...form, horaInicio: (evento.target as HTMLInputElement).value };
                  }}
                ></st-input>
              `
          }
        </div>

        <div class="formulario__par">
          <st-input
            type="date"
            label=${S.calendario.dataFim}
            min=${form.dataInicio}
            .value=${form.dataFim}
            @st-change=${(evento: Event) => {
              formEvento = { ...form, dataFim: (evento.target as HTMLInputElement).value };
            }}
          ></st-input>
          ${
            form.diaInteiro
              ? nothing
              : html`
                <st-input
                  type="time"
                  label=${S.calendario.horaFim}
                  .value=${form.horaFim}
                  @st-change=${(evento: Event) => {
                    formEvento = { ...form, horaFim: (evento.target as HTMLInputElement).value };
                  }}
                ></st-input>
              `
          }
        </div>

        <st-textarea
          rows="2"
          label=${S.calendario.descricao}
          placeholder=${S.calendario.descricaoPlaceholder}
          .value=${form.descricao}
          @st-input=${(evento: Event) => {
            formEvento = { ...form, descricao: (evento.target as HTMLInputElement).value };
          }}
        ></st-textarea>
      </div>

      <div slot="footer" class="dialogo__acoes">
        ${
          form.id > 0
            ? html`
              <st-button variant="danger" outline @click=${() => void apagarEvento(form)}>
                <st-icon slot="prefix" name="trash"></st-icon>${S.acoes.excluir}
              </st-button>
            `
            : nothing
        }
        <st-button
          @click=${() => {
            formEvento = null;
            atualizar();
          }}
        >
          ${S.acoes.cancelar}
        </st-button>
        <st-button variant="primary" @click=${() => void gravarEvento(form)}>
          <st-icon slot="prefix" name="check"></st-icon>${S.acoes.salvar}
        </st-button>
      </div>
    </st-dialog>
  `;
}

// ── Gestão de tipos ─────────────────────────────────────────────────────────

async function gravarTipo(form: FormTipo): Promise<void> {
  const nome = form.nome.trim() === '' ? S.calendario.tipoSemNome : form.nome.trim();
  const atual = form.id > 0 ? tipoPorId(tipos, form.id) : undefined;

  await salvarTipo({
    ...(atual ?? { ordem: proximaOrdem(tipos) }),
    ...(form.id > 0 ? { id: form.id } : {}),
    nome,
    cor_chave: form.cor,
    icone: form.icone,
    marca_especial: form.especial ? 1 : 0,
  });

  formTipo = null;
  await recarregar();
}

async function apagarTipo(tipo: Tipo): Promise<void> {
  if (tipo.id === undefined) return;

  // Um tipo com eventos não pode sair: os eventos ficariam sem cor nem nome.
  if (tipoEmUso(eventos, tipo.id)) {
    await confirmar({
      titulo: S.calendario.tipoEmUsoTitulo,
      texto: S.calendario.tipoEmUsoTexto,
      rotuloConfirmar: S.acoes.fechar,
    });
    return;
  }

  const ok = await confirmar({
    titulo: S.calendario.excluirTipo,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await excluirTipo(tipo.id);
  await recarregar();
}

function formularioDoTipo(form: FormTipo): TemplateResult {
  return html`
    <div class="formulario formulario--cartao">
      <st-input
        label=${S.calendario.tipoNome}
        .value=${form.nome}
        @st-input=${(evento: Event) => {
          formTipo = { ...form, nome: (evento.target as HTMLInputElement).value };
        }}
      ></st-input>

      <div>
        <span class="formulario__rotulo">${S.calendario.cor}</span>
        <div class="tipos-escolha">
          ${Object.entries(CORES).map(
            ([chave, hex]) => html`
              <button
                class="cor-chip"
                ?data-ativo=${form.cor === chave}
                style=${`background:${hex}`}
                aria-label=${chave}
                @click=${() => {
                  formTipo = { ...form, cor: chave };
                  atualizar();
                }}
              ></button>
            `,
          )}
        </div>
      </div>

      <div>
        <span class="formulario__rotulo">${S.calendario.icone}</span>
        <div class="tipos-escolha">
          ${Object.entries(ICONES).map(
            ([chave, nome]) => html`
              <button
                class="tipo-chip"
                ?data-ativo=${form.icone === chave}
                aria-label=${chave}
                @click=${() => {
                  formTipo = { ...form, icone: chave };
                  atualizar();
                }}
              >
                <st-icon name=${nome}></st-icon>
              </button>
            `,
          )}
        </div>
      </div>

      <st-switch
        ?checked=${form.especial}
        @st-change=${(evento: Event) => {
          formTipo = { ...form, especial: (evento.target as HTMLInputElement).checked };
        }}
      >
        ${S.calendario.marcaEspecial}
      </st-switch>

      <div class="editor__acoes">
        <st-button variant="primary" @click=${() => void gravarTipo(form)}>
          <st-icon slot="prefix" name="check"></st-icon>${S.acoes.salvar}
        </st-button>
        <st-button
          @click=${() => {
            formTipo = null;
            atualizar();
          }}
        >
          ${S.acoes.cancelar}
        </st-button>
      </div>
    </div>
  `;
}

function dialogoDeTipos(): TemplateResult {
  return html`
    <st-dialog
      open
      label=${S.calendario.tipos}
      @st-after-hide=${() => {
        painelDeTipos = false;
        formTipo = null;
        atualizar();
      }}
    >
      ${
        formTipo === null
          ? html`
            <div class="tipos-lista">
              ${tipos.map(
                (tipo) => html`
                  <div class="tipo-linha">
                    <span
                      class="tipo-chip__cor"
                      style=${`background:${CORES[tipo.cor_chave] ?? ''}`}
                    ></span>
                    <st-icon name=${ICONES[tipo.icone] ?? 'calendar-event'}></st-icon>
                    <span class="tipo-linha__nome">${tipo.nome}</span>
                    ${
                      tipo.marca_especial === 1
                        ? html`<st-badge variant="success" pill>${S.calendario.especial}</st-badge>`
                        : nothing
                    }
                    <st-icon-button
                      name="pencil"
                      label=${S.acoes.editar}
                      @click=${() => {
                        formTipo = {
                          id: tipo.id ?? 0,
                          nome: tipo.nome,
                          cor: tipo.cor_chave,
                          icone: tipo.icone,
                          especial: tipo.marca_especial === 1,
                        };
                        atualizar();
                      }}
                    ></st-icon-button>
                    <st-icon-button
                      name="trash"
                      label=${S.calendario.excluirTipo}
                      @click=${() => void apagarTipo(tipo)}
                    ></st-icon-button>
                  </div>
                `,
              )}
            </div>

            <st-button
              slot="footer"
              variant="primary"
              outline
              @click=${() => {
                formTipo = {
                  id: 0,
                  nome: '',
                  cor: 'primary',
                  icone: 'evento',
                  especial: false,
                };
                atualizar();
              }}
            >
              <st-icon slot="prefix" name="plus"></st-icon>${S.calendario.novoTipo}
            </st-button>
          `
          : formularioDoTipo(formTipo)
      }
    </st-dialog>
  `;
}

// ── A tela ──────────────────────────────────────────────────────────────────

export const telaCalendario: Tela = {
  acoes() {
    return html`
      <st-icon-button
        name="tags"
        label=${S.calendario.tipos}
        @click=${() => {
          painelDeTipos = true;
          formTipo = null;
          atualizar();
        }}
      ></st-icon-button>
      <st-icon-button
        name="plus"
        label=${S.calendario.novoEvento}
        @click=${() => novoEm(dataLocalISO())}
      ></st-icon-button>
    `;
  },

  conteudo() {
    carregar();
    if (!carregado) return html`<div class="carregando"><st-spinner></st-spinner></div>`;

    return html`
      ${painelKpis()}
      ${barra()}
      ${vistaAtual()}
      ${formEvento === null ? nothing : dialogoDoEvento(formEvento)}
      ${painelDeTipos ? dialogoDeTipos() : nothing}
    `;
  },
};
