/**
 * O catálogo de renderizadores, por `tipo` de módulo.
 *
 * O `tipo` vem do admin, junto do conteúdo curado: é ele que decide qual puzzle
 * o módulo abre. Um tipo desconhecido — um módulo novo criado no admin antes de
 * o puzzle existir aqui — cai no arquétipo `pronto`, que lê o conceito e vai
 * direto à reflexão, em vez de deixar a tela vazia.
 */

import { carbono } from '../entenda/carbono.ts';
import { dinheiroBiblia } from '../entenda/dinheiro-biblia.ts';
import { medidasBiblia } from '../entenda/medidas-biblia.ts';
import { revelacao } from '../entenda/revelacao.ts';
import { seteTempos } from '../entenda/sete-tempos.ts';
import { trajetoriaBiblia } from '../entenda/trajetoria-biblia.ts';
import type { Renderizador } from './base.ts';
import {
  atomo,
  bilhar,
  conica,
  desconto,
  difracao,
  elementos,
  equacao,
  fluxo,
  fractal,
  funcao,
  microscopio,
  musica,
  ondas,
  proteina,
  relatividade,
  terra,
  universoEscuro,
} from './fisica.ts';
import {
  area,
  campo,
  ciclosVida,
  harmonia,
  linhaCriacao,
  orbita,
  pareamento,
  pronto,
  rotas,
  sandbox,
  sequencia,
  tesselacao,
} from './montagem.ts';
import {
  beijaFlor,
  bigodeGato,
  bioluz,
  cardume,
  castor,
  cicatrizacao,
  concha,
  denteLeao,
  dnaDados,
  eco,
  formigaPrata,
  fotossintese,
  gaivota,
  girassol,
  grilo,
  hemoglobina,
  libelula,
  linguaGato,
  martim,
  osso,
  plantaNoite,
  podometro,
  polvo,
  pomelo,
  raVidro,
  sonar,
  sustentacao,
  turbina,
  vagaLume,
  vetores,
} from './vida.ts';

/**
 * As chaves são os `tipo` gravados no banco, e por isso vêm em `snake_case` —
 * são identificadores de dados, não nomes de variável.
 */
const RENDERIZADORES: Readonly<Record<string, Renderizador>> = {
  // A Natureza e A Terra
  girassol,
  sequencia,
  concha,
  dente_leao: denteLeao,
  planta_noite: plantaNoite,
  fotossintese,
  pomelo,
  tesselacao,
  terra,
  linha_criacao: linhaCriacao,
  ciclos_vida: ciclosVida,
  campo,

  // O Reino Animal
  vetores,
  podometro,
  formiga_prata: formigaPrata,
  ra_vidro: raVidro,
  beija_flor: beijaFlor,
  grilo,
  vaga_lume: vagaLume,
  martim,
  libelula,
  bioluz,
  eco,
  castor,
  lingua_gato: linguaGato,
  bigode_gato: bigodeGato,
  polvo,
  cardume,
  turbina,
  sonar,
  gaivota,
  sustentacao,
  rotas,
  dna_dados: dnaDados,

  // O Corpo Humano
  hemoglobina,
  osso,
  cicatrizacao,
  proteina,
  pareamento,

  // Matemática
  equacao,
  funcao,
  harmonia,
  area,
  desconto,
  bilhar,
  musica,
  fractal,

  // Universo e Física
  orbita,
  conica,
  fluxo,
  difracao,
  ondas,
  atomo,
  microscopio,
  relatividade,
  universo_escuro: universoEscuro,
  elementos,
  sandbox,

  // Entenda Melhor
  carbono,
  sete_tempos: seteTempos,
  revelacao,
  medidas_biblia: medidasBiblia,
  dinheiro_biblia: dinheiroBiblia,
  trajetoria_biblia: trajetoriaBiblia,
};

/** O renderizador de um tipo; `pronto` quando o tipo ainda não existe aqui. */
export function renderizador(tipo: string): Renderizador {
  return RENDERIZADORES[tipo] ?? pronto;
}

/** Se o tipo tem puzzle próprio — o que distingue um módulo novo de um `pronto`. */
export function temPuzzle(tipo: string): boolean {
  return RENDERIZADORES[tipo] !== undefined;
}

export type { Renderizador };
