/**
 * Modo apresentação + leitura em voz alta, como recurso reutilizável.
 *
 * No legado cada módulo de texto (Anotações, Guias, Poesia, Receitas) repetia o
 * mesmo bloco: um `discurso`/`_pararRolagem`, um par `ttsAtivo`/`ttsPausado` e a
 * barra de controles. Aqui isso é um objeto só — quem usa diz o que apresentar
 * e o que falar; o estado, os botões e a barra vêm de graça.
 *
 * A rolagem procura `.apresentacao__rolagem` no documento depois do desenho: o
 * conteúdo apresentado é sempre o que o próprio módulo renderizou dentro do
 * overlay, e não uma cópia que este arquivo precisaria conhecer.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { atualizar } from '../app/tela.ts';
import { S } from '../strings.ts';
import { textoLimpo } from '../texto.ts';
import {
  falar,
  iniciarRolagem,
  pararFala,
  pausarFala,
  retomarFala,
  ttsDisponivel,
} from './apresentacao.ts';
import { processarNotas } from './notas.ts';

/** Controle de uma sessão de leitura: rolagem automática e voz. */
export class Leitura {
  /** O overlay de apresentação está aberto? */
  apresentando = false;
  /** A rolagem está pausada (o overlay segue aberto)? */
  pausada = false;
  /** 1 lenta, 2 média, 3 rápida — mesma escala do legado. */
  nivel = 2;

  falando = false;
  falaPausada = false;

  #pararRolagem: (() => void) | undefined;

  /**
   * Abre o overlay e começa a rolar. O módulo já deve ter renderizado
   * `.apresentacao__rolagem` no desenho que este `atualizar()` provoca — o
   * `render()` do Lit é síncrono, então o elemento existe na linha seguinte.
   */
  abrir(): void {
    this.apresentando = true;
    this.pausada = false;
    atualizar();

    const alvo = document.querySelector<HTMLElement>('.apresentacao__rolagem');
    if (alvo === null) return;

    processarNotas(alvo);
    this.#pararRolagem = iniciarRolagem(alvo, () => ({
      ativo: this.apresentando,
      pausado: this.pausada,
      nivel: this.nivel,
    }));
  }

  /** Fecha o overlay e cala a voz. Idempotente: serve para trocar de rota. */
  fechar(): void {
    this.apresentando = false;
    this.pausada = false;
    this.#pararRolagem?.();
    this.#pararRolagem = undefined;
    this.calar();
  }

  ajustar(passo: number): void {
    this.nivel = Math.min(3, Math.max(1, this.nivel + passo));
    atualizar();
  }

  alternarPausa(): void {
    this.pausada = !this.pausada;
    atualizar();
  }

  calar(): void {
    pararFala();
    this.falando = false;
    this.falaPausada = false;
  }

  /** Um botão, três estados: começar, pausar, retomar — como no legado. */
  alternarFala(texto: string): void {
    if (!this.falando) {
      falar(textoLimpo(texto), () => {
        this.falando = false;
        this.falaPausada = false;
        atualizar();
      });
      this.falando = true;
      this.falaPausada = false;
    } else if (!this.falaPausada) {
      pausarFala();
      this.falaPausada = true;
    } else {
      retomarFala();
      this.falaPausada = false;
    }

    atualizar();
  }

  /** Botão de voz para o cabeçalho. Ausente onde o aparelho não tem síntese. */
  botaoFala(texto: () => string): TemplateResult | typeof nothing {
    if (!ttsDisponivel()) return nothing;

    const nome = !this.falando ? 'volume' : this.falaPausada ? 'player-play' : 'player-pause';
    const rotulo = !this.falando
      ? S.leitura.ler
      : this.falaPausada
        ? S.leitura.retomarLeitura
        : S.leitura.pausarLeitura;

    return html`
      <st-icon-button
        name=${nome}
        label=${rotulo}
        @click=${() => this.alternarFala(texto())}
      ></st-icon-button>
    `;
  }

  /** Botão que abre a apresentação, para o cabeçalho. */
  botaoApresentar(): TemplateResult {
    return html`
      <st-icon-button
        name="presentation"
        label=${S.leitura.apresentar}
        @click=${() => this.abrir()}
      ></st-icon-button>
    `;
  }

  /**
   * O overlay inteiro, com o conteúdo dado dentro da área que rola. Devolve
   * `nothing` quando a apresentação está fechada, para que o módulo possa
   * chamá-lo sem condicional.
   */
  overlay(conteudo: TemplateResult, texto: () => string): TemplateResult | typeof nothing {
    if (!this.apresentando) return nothing;

    return html`
      <div class="apresentacao">
        <div class="apresentacao__rolagem">${conteudo}</div>
        ${this.controles(texto)}
      </div>
    `;
  }

  private controles(texto: () => string): TemplateResult {
    return html`
      <div class="apresentacao__controles">
        <st-icon-button
          name="minus"
          label=${S.leitura.maisDevagar}
          ?disabled=${this.nivel <= 1}
          @click=${() => this.ajustar(-1)}
        ></st-icon-button>
        <span class="apresentacao__velocidade">${S.leitura.velocidade(this.nivel)}</span>
        <st-icon-button
          name="plus"
          label=${S.leitura.maisRapido}
          ?disabled=${this.nivel >= 3}
          @click=${() => this.ajustar(1)}
        ></st-icon-button>
        <st-icon-button
          name=${this.pausada ? 'player-play' : 'player-pause'}
          label=${this.pausada ? S.leitura.continuar : S.leitura.pausar}
          @click=${() => this.alternarPausa()}
        ></st-icon-button>
        ${this.botaoFala(texto)}
        <st-icon-button
          name="x"
          label=${S.acoes.fechar}
          @click=${() => {
            this.fechar();
            atualizar();
          }}
        ></st-icon-button>
      </div>
    `;
  }
}
