/**
 * A tela "Sobre" — porte da seção `sobre` do `index.html` legado, mais as cinco
 * páginas institucionais que viviam soltas em `Pwa/publico/*.html`.
 *
 * No legado o Sobre abria por um botão na barra de topo e os documentos legais
 * eram links para HTML fora do app: saía-se do Papiro, perdia-se a barra e
 * voltava-se por um "← Voltar ao app". Aqui os cinco são sub-rotas
 * (`#/sobre/termos`, `#/sobre/licenca`, …), desenhadas pela mesma casca — a
 * navegação de volta é a que o app já tem, e o conteúdo cabe no service worker
 * sem cinco entradas extras de precache.
 *
 * **A versão não é digitada.** O legado tinha um `x-text="versao"` alimentado à
 * mão; aqui ela sai do `package.json` pelo `define` do Vite, como no admin.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { navegar, type Rota } from '../../app/rotas.ts';
import type { Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { abrirBoasVindas } from '../../ui/boasvindas.ts';
import type { Bloco, Documento, Trecho } from './documentos.ts';
import { DOCUMENTOS, documento } from './documentos.ts';

/**
 * A versão do build.
 *
 * Sai do `package.json` do app, colhida pelo `define` do Vite — o legado tinha um
 * `x-text="versao"` alimentado à mão, que é a constante que ninguém lembra de
 * editar (foi o que deixou o admin em `v0.0.0` durante duas fases). Fora do
 * bundle, no `bun test`, a constante não existe e o selo simplesmente não aparece.
 */
const VERSAO =
  typeof __MARINX_METADADOS__ === 'object'
    ? (__MARINX_METADADOS__.projetos.papiro?.versao ?? '')
    : '';

// ── Documentos ──────────────────────────────────────────────────────────────

function trechos(partes: readonly Trecho[]): TemplateResult {
  return html`${partes.map((parte) =>
    parte.forte === true ? html`<strong>${parte.texto}</strong>` : html`${parte.texto}`,
  )}`;
}

function bloco(b: Bloco): TemplateResult {
  switch (b.tipo) {
    case 'titulo':
      return html`<h2 class="doc__titulo">${b.texto}</h2>`;

    case 'paragrafo':
      return html`<p>${trechos(b.partes)}</p>`;

    case 'lista':
      return html`<ul class="doc__lista">
        ${b.itens.map((item) => html`<li>${trechos(item)}</li>`)}
      </ul>`;

    case 'definicoes':
      return html`<dl class="doc__definicoes">
        ${b.itens.map(
          (item) => html`
            <div class="doc__definicao">
              <dt>${item.nome}</dt>
              <dd>${item.texto}</dd>
            </div>
          `,
        )}
      </dl>`;

    case 'tabela':
      return html`
        <div class="doc__rolagem">
          <table class="doc__tabela">
            <thead>
              <tr>
                <th>${b.colunas[0]}</th>
                <th>${b.colunas[1]}</th>
              </tr>
            </thead>
            <tbody>
              ${b.linhas.map((linha) => html`<tr><td>${linha[0]}</td><td>${linha[1]}</td></tr>`)}
            </tbody>
          </table>
        </div>
      `;

    case 'veja':
      return html`
        <nav class="doc__veja" aria-label=${S.sobre.vejaTambem}>
          <h2 class="doc__titulo">${S.sobre.vejaTambem}</h2>
          ${b.documentos.map((id) => {
            const alvo = documento(id);
            return alvo === undefined ? nothing : linhaDeDocumento(alvo);
          })}
        </nav>
      `;
  }
}

function documentoInteiro(doc: Documento): TemplateResult {
  return html`
    <article class="doc">
      <p class="doc__sub">${doc.subtitulo}</p>
      ${doc.blocos.map((b) => bloco(b))}
    </article>
  `;
}

// ── O Sobre ─────────────────────────────────────────────────────────────────

function linhaDeDocumento(doc: Documento): TemplateResult {
  return html`
    <button class="linha" @click=${() => navegar(`sobre/${doc.id}`)}>
      <st-icon class="linha__icone" name=${doc.icone}></st-icon>
      <span class="linha__rotulo">${doc.titulo}</span>
      <st-icon class="linha__seta" name="chevron-right"></st-icon>
    </button>
  `;
}

function selo(icone: string, texto: string): TemplateResult {
  return html`
    <span class="selo">
      <st-icon name=${icone}></st-icon>
      ${texto}
    </span>
  `;
}

function recurso(icone: string, cor: string, titulo: string, texto: string): TemplateResult {
  return html`
    <div class="recurso" style="--cor: ${cor}">
      <st-icon class="recurso__icone" name=${icone}></st-icon>
      <span class="recurso__titulo">${titulo}</span>
      <span class="recurso__texto">${texto}</span>
    </div>
  `;
}

function sobre(): TemplateResult {
  return html`
    <section class="sobre__capa">
      <img class="sobre__logo" src="./icons/papiro.svg" alt="" width="96" height="96" />
      <h2 class="sobre__nome">${S.app.nome}</h2>
      ${VERSAO === '' ? nothing : html`<st-badge variant="primary" pill>${S.sobre.versao(VERSAO)}</st-badge>`}
      <p class="sobre__lema">${S.sobre.lema}</p>
    </section>

    <div class="selos">
      ${selo('wifi-off', S.sobre.seloOffline)}
      ${selo('shield-lock', S.sobre.seloPrivado)}
      ${selo('eye-off', S.sobre.seloSemRastreio)}
      ${selo('device-mobile', S.sobre.seloInstalavel)}
    </div>

    <h2 class="secao">${S.sobre.tudoNumLugar}</h2>
    <div class="recursos">
      ${recurso('book', '#6f42c1', S.sobre.recEstudo, S.sobre.recEstudoTexto)}
      ${recurso('device-gamepad-2', '#198754', S.sobre.recJogo, S.sobre.recJogoTexto)}
      ${recurso('feather', '#e0399a', S.sobre.recCriar, S.sobre.recCriarTexto)}
      ${recurso('cash', '#16a34a', S.sobre.recFinancas, S.sobre.recFinancasTexto)}
      ${recurso('shield-check', '#dc2626', S.sobre.recPreparo, S.sobre.recPreparoTexto)}
      ${recurso('users', '#0dcaf0', S.sobre.recMinisterio, S.sobre.recMinisterioTexto)}
    </div>

    <div class="sobre__privacidade">
      <st-icon class="sobre__cadeado" name="shield-lock"></st-icon>
      <div>
        <strong>${S.sobre.privacidadeTitulo}</strong>
        <p>${S.sobre.privacidadeTexto}</p>
      </div>
    </div>

    <div class="lista sobre__boasvindas">
      <button class="linha" @click=${() => void abrirBoasVindas()}>
        <st-icon class="linha__icone" name="sparkles"></st-icon>
        <span class="linha__rotulo">${S.boasVindas.reabrir}</span>
        <st-icon class="linha__seta" name="chevron-right"></st-icon>
      </button>
    </div>

    <h2 class="secao">${S.sobre.documentos}</h2>
    <div class="lista sobre__documentos">${DOCUMENTOS.map((doc) => linhaDeDocumento(doc))}</div>

    <p class="sobre__contato">
      <st-icon name="mail"></st-icon>
      ${S.sobre.contato}
      <a href="mailto:${S.sobre.email}">${S.sobre.email}</a>
    </p>
  `;
}

// ── A tela ──────────────────────────────────────────────────────────────────

export const telaSobre: Tela = {
  voltarPara(rota) {
    return rota.args.length === 0 ? 'home' : 'sobre';
  },

  titulo(rota) {
    const [id] = rota.args;
    return id === undefined ? undefined : documento(id)?.titulo;
  },

  conteudo(rota: Rota) {
    const [id] = rota.args;
    if (id === undefined) return sobre();

    const doc = documento(id);
    // Documento inexistente na URL não é erro de app: cai no índice, que é o
    // lugar de onde o link deveria ter saído.
    return doc === undefined ? sobre() : documentoInteiro(doc);
  },
};
