/**
 * A tela do Financeiro.
 *
 * A interface inteira é o `st-financeiro` do Stratum — saldo, painel do mês,
 * lançamentos, categorias e recorrências. O que sobra aqui é o que só o app
 * sabe: a rota, o banco e a confirmação de exclusão.
 *
 * Quatro sub-rotas, como no legado: painel (`#/financeiro`), transações,
 * categorias e recorrências. Trocar de sub-tela descarta o formulário aberto —
 * o componente cuida disso ao ver a `vista` mudar.
 *
 * **Privacidade:** os valores nascem ocultos e voltam a ocultar cada vez que se
 * entra no módulo de fora. Revelar vale só para a visita atual, e não é
 * preferência guardada: quem abre o app no ônibus não quer o saldo na tela por
 * decisão tomada semanas antes.
 */

import type {
  FinanceiroCategoria,
  FinanceiroRecorrencia,
  FinanceiroTransacao,
  FinanceiroVista,
  default as StFinanceiro,
} from '@marinx/stratum/components/financeiro/financeiro.js';
import { html, type TemplateResult } from 'lit';
import { ref } from 'lit/directives/ref.js';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { notificar } from '../../ui/notificar.ts';
import {
  alternarAtivo,
  alternarPago,
  type Categoria,
  carregar as carregarDados,
  excluirCategoria,
  excluirRecorrencia,
  excluirTransacao,
  gerarPendentes,
  paraCategoria,
  paraRecorrencia,
  paraTransacao,
  type Recorrencia,
  salvarCategoria,
  salvarRecorrencia,
  salvarTransacao,
  type Transacao,
} from './dados.ts';

/** O que o componente devolve nos eventos de registro, junto do que ele é. */
type Especie = 'transacao' | 'categoria' | 'recorrencia';

type DetalheDeRegistro =
  | { especie: 'transacao'; registro: FinanceiroTransacao }
  | { especie: 'categoria'; registro: FinanceiroCategoria }
  | { especie: 'recorrencia'; registro: FinanceiroRecorrencia };

let categorias: Categoria[] = [];
let transacoes: Transacao[] = [];
let recorrencias: Recorrencia[] = [];

let oculto = true;
let dentroDoModulo = false;
let mesFiltro = '';
let formularioAberto = false;

let carregado = false;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregar(): Promise<void> {
  const dados = await carregarDados();
  categorias = dados.categorias;
  transacoes = dados.transacoes;
  recorrencias = dados.recorrencias;
  atualizar();
}

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      await recarregar();
      // As recorrências vencidas são lançadas na abertura do módulo; se algo
      // nasceu, a lista precisa ser lida outra vez.
      if (await gerarPendentes(recorrencias)) await recarregar();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

function subTelaDe(rota: Rota): FinanceiroVista {
  const sub = rota.args[0];
  if (sub === 'transacoes' || sub === 'categorias' || sub === 'recorrencias') return sub;
  return 'painel';
}

/**
 * Reage à rota: esconde os valores ao (re)entrar no módulo. A casca não avisa
 * quando uma tela sai de cena, então a detecção é por comparação — como o
 * `_sincronizar` do legado fazia no hashchange.
 */
function sincronizar(): void {
  if (dentroDoModulo) return;

  oculto = true;
  dentroDoModulo = true;
  vigiarSaida();
}

let vigiando = false;

function vigiarSaida(): void {
  if (vigiando) return;
  vigiando = true;

  addEventListener('hashchange', () => {
    if (location.hash.replace(/^#\/?/, '').split('/')[0] === 'financeiro') return;

    dentroDoModulo = false;
    // Sair do módulo descarta o que estava sendo editado. Trocar de sub-tela já
    // é cuidado pelo próprio componente, ao ver a `vista` mudar — o que ele não
    // tem como saber é que a tela inteira saiu de cena.
    componente?.fechar();
    formularioAberto = false;
  });
}

// ── Gravação ────────────────────────────────────────────────────────────────

/** A linha de banco que deu origem a um registro da tela, quando já existia. */
function anterior<T extends { id?: number }>(lista: readonly T[], id: number): T | undefined {
  return id > 0 ? lista.find((linha) => linha.id === id) : undefined;
}

async function gravar(detalhe: DetalheDeRegistro): Promise<void> {
  if (detalhe.especie === 'transacao') {
    await salvarTransacao(detalhe.registro, anterior(transacoes, detalhe.registro.id));
    notificar(S.financeiro.transacaoSalva);
    await recarregar();
    return;
  }

  if (detalhe.especie === 'categoria') {
    await salvarCategoria(detalhe.registro);
    notificar(S.financeiro.categoriaSalva);
    await recarregar();
    return;
  }

  await salvarRecorrencia(detalhe.registro, anterior(recorrencias, detalhe.registro.id));
  notificar(S.financeiro.recorrenciaSalva);
  await recarregar();
  // Uma recorrência criada com dia já passado no mês corrente lança agora.
  if (await gerarPendentes(recorrencias)) await recarregar();
}

/** O que a exclusão pergunta e o que ela avisa, por espécie. */
const EXCLUSAO: Readonly<
  Record<
    Especie,
    { titulo: string; texto: string; feito: string; excluir: (id: number) => Promise<void> }
  >
> = {
  transacao: {
    titulo: S.financeiro.excluirTransacao,
    texto: S.acervo.excluirTexto,
    feito: S.financeiro.transacaoExcluida,
    excluir: excluirTransacao,
  },
  categoria: {
    titulo: S.financeiro.excluirCategoria,
    texto: S.financeiro.excluirCategoriaTexto,
    feito: S.financeiro.categoriaExcluida,
    excluir: excluirCategoria,
  },
  recorrencia: {
    titulo: S.financeiro.excluirRecorrencia,
    texto: S.financeiro.excluirRecorrenciaTexto,
    feito: S.financeiro.recorrenciaExcluida,
    excluir: excluirRecorrencia,
  },
};

async function apagar(detalhe: DetalheDeRegistro): Promise<void> {
  const acao = EXCLUSAO[detalhe.especie];

  const ok = await confirmar({
    titulo: acao.titulo,
    texto: acao.texto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await acao.excluir(detalhe.registro.id);
  notificar(acao.feito);
  await recarregar();
}

/**
 * O botão de pago e o de pausar não passam por formulário: gravam a linha do
 * banco como ela está, com um campo virado.
 */
async function alternar(detalhe: DetalheDeRegistro): Promise<void> {
  if (detalhe.especie === 'transacao') {
    const linha = anterior(transacoes, detalhe.registro.id);
    if (linha !== undefined) await alternarPago(linha);
  }

  if (detalhe.especie === 'recorrencia') {
    const linha = anterior(recorrencias, detalhe.registro.id);
    if (linha !== undefined) await alternarAtivo(linha);
  }

  await recarregar();
}

// ── A tela ──────────────────────────────────────────────────────────────────

const TITULOS: Readonly<Record<FinanceiroVista, string | undefined>> = {
  painel: undefined,
  transacoes: S.financeiro.transacoes,
  categorias: S.financeiro.categorias,
  recorrencias: S.financeiro.recorrencias,
};

const NOVO: Readonly<Record<Exclude<FinanceiroVista, 'painel'>, string>> = {
  transacoes: S.financeiro.novaTransacao,
  categorias: S.financeiro.novaCategoria,
  recorrencias: S.financeiro.novaRecorrencia,
};

/**
 * O componente em cena. O "+" que abre o formulário mora no cabeçalho da casca,
 * fora dele — daí a referência guardada no desenho.
 */
let componente: StFinanceiro | undefined;

function detalheDe(evento: Event): DetalheDeRegistro {
  return (evento as CustomEvent<DetalheDeRegistro>).detail;
}

export const telaFinanceiro: Tela = {
  voltarPara(rota) {
    return subTelaDe(rota) === 'painel' ? 'hub/pessoal' : 'financeiro';
  },

  titulo(rota) {
    return TITULOS[subTelaDe(rota)];
  },

  acoes(rota) {
    const sub = subTelaDe(rota);
    if (sub === 'painel' || formularioAberto) return undefined;

    return html`
      <st-icon-button
        name="plus"
        label=${NOVO[sub]}
        @click=${() => componente?.novo()}
      ></st-icon-button>
    `;
  },

  conteudo(rota): TemplateResult {
    carregar();
    sincronizar();

    if (!carregado) return html`<div class="carregando"><st-spinner></st-spinner></div>`;

    return html`
      <st-financeiro
        vista=${subTelaDe(rota)}
        mes=${mesFiltro}
        ?oculto=${oculto}
        .categorias=${categorias.map(paraCategoria)}
        .transacoes=${transacoes.map(paraTransacao)}
        .recorrencias=${recorrencias.map(paraRecorrencia)}
        ${ref((elemento) => {
          componente = elemento as StFinanceiro | undefined;
        })}
        @st-navigate=${(evento: Event) => {
          const { vista } = (evento as CustomEvent<{ vista: FinanceiroVista }>).detail;
          navegar(`financeiro/${vista}`);
        }}
        @st-month=${(evento: Event) => {
          mesFiltro = (evento as CustomEvent<{ mes: string }>).detail.mes;
        }}
        @st-visibility=${(evento: Event) => {
          oculto = (evento as CustomEvent<{ oculto: boolean }>).detail.oculto;
        }}
        @st-form=${(evento: Event) => {
          formularioAberto = (evento as CustomEvent<{ aberto: boolean }>).detail.aberto;
          atualizar();
        }}
        @st-save=${(evento: Event) => void gravar(detalheDe(evento))}
        @st-delete=${(evento: Event) => void apagar(detalheDe(evento))}
        @st-toggle=${(evento: Event) => void alternar(detalheDe(evento))}
      ></st-financeiro>
    `;
  },
};
