/**
 * O esquema que NÃO veio do banco legado.
 *
 * `esquema.ts` e `tipos.ts` reproduzem o que veio do `sang.local`, e a separação
 * é de origem, não de formato: tabela que nasce no monorepo entra aqui, em DDL
 * escrito à mão, e é aplicada depois do esquema base (ver as migrações do worker
 * do admin).
 *
 * Convenções do legado valem igual: prefixo `pap_`, `publicar` como 0/1 e datas
 * em epoch de milissegundos.
 */

// ── A ajuda do Papiro ───────────────────────────────────────────────────────

/** Linha da tabela `pap_tutorial`. */
export interface PapTutorial {
  id: number;
  /**
   * O módulo que este tópico explica — a mesma chave do registro de módulos do
   * PWA (`anotacoes`, `financeiro`, …). Vazio é a visão geral do app.
   */
  modulo_id: string;
  titulo: string;
  resumo: string;
  /** HTML curado, escrito no editor do admin. */
  conteudo: string;
  ordem: number;
  /** booleano 0 | 1 */
  publicar: number;
  /** epoch em milissegundos */
  data_criacao: number;
  /** epoch em milissegundos */
  data_atualizacao: number;
}

/**
 * Um tópico de fábrica: o texto, sem as datas.
 *
 * As datas são de quem grava (o admin as carimba ao semear), e não do texto —
 * inventá-las na constante faria toda instalação nascer com a mesma data falsa.
 */
export type TopicoDeFabrica = Omit<PapTutorial, 'data_criacao' | 'data_atualizacao'>;

/**
 * `pap_tutorial` — a ajuda do Papiro, um tópico por módulo.
 *
 * O PWA já esperava por ela: `ARQUIVO_PARA_STORE` da sincronização mapeia
 * `tutorial.json` desde a Fase 3, e o módulo caía nos tópicos de fábrica por não
 * haver tabela do outro lado.
 */
export const ddlExtra: readonly string[] = [
  `CREATE TABLE pap_tutorial (
  id               INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  modulo_id        TEXT    NOT NULL DEFAULT '',
  titulo           TEXT    NOT NULL,
  resumo           TEXT    NOT NULL DEFAULT '',
  conteudo         TEXT    NOT NULL DEFAULT '',
  ordem            INTEGER NOT NULL DEFAULT 0,
  publicar         INTEGER NOT NULL DEFAULT 1,
  data_criacao     INTEGER NOT NULL DEFAULT 0,
  data_atualizacao INTEGER NOT NULL DEFAULT 0
  );`,
  `CREATE INDEX idx_pap_tutorial_ordem ON pap_tutorial(ordem);`,
];

// ── Os produtos vendáveis ───────────────────────────────────────────────────

/** Linha da tabela `mar_produtos`. */
export interface MarProdutos {
  id: number;
  /**
   * O identificador que **entra na licença** — é este texto que o alvo compara
   * para saber se está destravado (`localzap`, `localzap-rh`, …). Minúsculo, sem
   * acento e sem espaço, porque ele viaja dentro do payload assinado e aparece
   * em URL e em log.
   */
  chave: string;
  /** O nome comercial, que é o que a tela mostra. */
  nome: string;
  descricao: string;
  /** Em **centavos**, como todo dinheiro do projeto. 0 é "sob consulta". */
  preco: number;
  /** booleano 0 | 1 — um produto fora de linha some do formulário de emissão. */
  ativo: number;
  ordem: number;
  /** epoch em milissegundos */
  data_criacao: number;
  /** epoch em milissegundos */
  data_atualizacao: number;
}

/** Um produto de fábrica: o texto, sem as datas (quem as carimba é quem grava). */
export type ProdutoDeFabrica = Omit<MarProdutos, 'data_criacao' | 'data_atualizacao'>;

/**
 * `mar_produtos` — o catálogo do que se vende, e a origem da lista de produtos do
 * formulário de emissão de licença.
 *
 * **Isto reverte uma decisão anterior, e vale dizer qual.** Até aqui não havia
 * tabela: o campo `produto` era texto livre, e a lista de sugestões emergia do
 * `SELECT DISTINCT produto FROM mar_licencas` — o que já tinha sido vendido. O
 * argumento era bom (*"os plugins serão vendáveis e sempre haverá um novo em
 * oferta; a lista não pode ser hardcoded"*), mas ele mirava o alvo errado: o que
 * não podia ser fixo era o **código**, não o **dado**. Uma tabela é dado — cadastrar
 * um plugin novo continua sendo digitar o nome dele uma vez, sem migração e sem
 * deploy — e resolve o que o texto livre não resolvia: um `localzap-rh` digitado
 * como `localzap_rh` numa venda vira um produto que nenhum alvo destrava, e o erro
 * só aparece no cliente.
 *
 * `chave` é UNIQUE por isso mesmo: é ela que a licença carrega, e duas linhas com a
 * mesma chave fariam a lista oferecer duas vezes a mesma coisa com nomes diferentes.
 */
export const ddlProdutos: readonly string[] = [
  `CREATE TABLE IF NOT EXISTS mar_produtos (
  id               INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  chave            TEXT    NOT NULL UNIQUE,
  nome             TEXT    NOT NULL,
  descricao        TEXT    NOT NULL DEFAULT '',
  preco            INTEGER NOT NULL DEFAULT 0,
  ativo            INTEGER NOT NULL DEFAULT 1,
  ordem            INTEGER NOT NULL DEFAULT 0,
  data_criacao     INTEGER NOT NULL DEFAULT 0,
  data_atualizacao INTEGER NOT NULL DEFAULT 0
  );`,
  `CREATE INDEX IF NOT EXISTS idx_mar_produtos_ordem ON mar_produtos(ordem);`,
];

/**
 * O produto que já existe. Entra semeado para que a tabela não nasça vazia num
 * banco que já tem licenças de `localzap` emitidas — uma lista vazia faria a tela
 * de emissão parecer quebrada no primeiro uso.
 */
export const PRODUTOS_DE_FABRICA: readonly ProdutoDeFabrica[] = [
  {
    id: 1,
    chave: 'localzap',
    nome: 'LocalZap',
    descricao: 'O CRM que roda dentro do WhatsApp Web, como extensão do Chrome.',
    preco: 0,
    ativo: 1,
    ordem: 1,
  },
];

/** Tabelas criadas aqui, na mesma forma da lista do esquema base. */
export const tabelasExtras = ['mar_produtos', 'pap_tutorial'] as const;
