/**
 * Os dados dos dois puzzles de montagem — porte do topo de
 * `modulos/criacao/renderizadores.js`.
 *
 * Ficam num arquivo só porque são consumidos dos dois lados: o renderizador
 * monta o puzzle com eles, e a viz 3D lê os mesmos objetos para transformar o
 * planeta e fazer o anel do ciclo fluir. Duas cópias e a cena mostraria um
 * estágio diferente do que o card diz.
 */

/** O que a viz 3D lê para transformar o planeta em cada estágio. */
export interface TerraNoEstagio {
  readonly luz: number;
  readonly nuvens: number;
  readonly terraFirme: boolean;
  readonly verde: boolean;
  readonly sol: boolean;
  readonly vida: number;
  readonly humanos: boolean;
}

export interface EstagioCriacao {
  readonly id: string;
  readonly estagio: number;
  readonly rotulo: string;
  readonly verso: string;
  readonly texto: string;
  readonly terra: TerraNoEstagio;
}

