/** A ordem montada fecha o ciclo se for uma ROTAÇÃO da canônica, no mesmo sentido. */
export function cicloCorreto(canonica: readonly string[], ordem: readonly string[]): boolean {
  if (ordem.length !== canonica.length) return false;
  const inicio = canonica.indexOf(ordem[0] ?? '');
  if (inicio < 0) return false;
  return ordem.every((id, i) => id === canonica[(inicio + i) % canonica.length]);
}
