/**
 * Utilidades de texto — porte de `texto.js` e do `textoPlano` de
 * `apresentacao.js` do legado.
 *
 * O legado decodificava as entidades jogando o HTML num `<div>` e lendo o
 * `textContent`. Aqui a decodificação é uma tabela: as funções são usadas na
 * pré-visualização dos cartões, na busca e no texto que vai para a leitura em
 * voz alta, e nenhuma delas precisa de DOM — o que as torna testáveis sem
 * navegador e utilizáveis dentro de um worker.
 */

/** As entidades que de fato aparecem no conteúdo do editor. */
const ENTIDADES: Readonly<Record<string, string>> = {
  '&nbsp;': ' ',
  '&amp;': '&',
  '&lt;': '<',
  '&gt;': '>',
  '&quot;': '"',
  '&apos;': "'",
  '&#39;': "'",
  '&ldquo;': '“',
  '&rdquo;': '”',
  '&lsquo;': '‘',
  '&rsquo;': '’',
  '&hellip;': '…',
  '&mdash;': '—',
  '&ndash;': '–',
};

function decodificar(texto: string): string {
  return texto
    .replace(/&[a-z]+;|&#\d+;/gi, (entidade) => {
      const conhecida = ENTIDADES[entidade.toLowerCase()];
      if (conhecida !== undefined) return conhecida;

      const numerica = /^&#(\d+);$/.exec(entidade);
      return numerica?.[1] === undefined ? entidade : String.fromCodePoint(Number(numerica[1]));
    })
    .replace(/&amp;/g, '&');
}

/**
 * HTML → texto corrido. As fronteiras de bloco viram espaço; sem isso um
 * título e o parágrafo seguinte sairiam colados na pré-visualização.
 */
export function textoLimpo(html: string): string {
  return decodificar(
    (html || '')
      .replace(/<br\s*\/?>/gi, ' ')
      .replace(/<\/(p|div|h[1-6]|li|blockquote|tr|section|article)>/gi, ' ')
      .replace(/<[^>]+>/g, ''),
  )
    .replace(/\s+/g, ' ')
    .trim();
}

/** Pré-visualização com reticências, para os cartões da lista. */
export function resumo(html: string, max = 180): string {
  const texto = textoLimpo(html);
  return texto.length > max ? `${texto.slice(0, max)}…` : texto;
}

/** Data e hora no formato do Brasil, como no `formatarData` do legado. */
export function dataHora(ms: number | undefined): string {
  if (ms === undefined || ms === 0 || Number.isNaN(ms)) return '';

  return new Date(ms).toLocaleString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}
