/**
 * Os dados das Metas — porte de `modulos/metas/metas.js` e
 * `modulos/metas/progresso.js`.
 *
 * O ponto do módulo é que a maioria das metas **não guarda o próprio progresso**:
 * ele é derivado dos dados reais dos outros módulos (as horas do Ministério, as
 * despesas do Financeiro, as sessões do Modo Estudo). Uma meta automática tem
 * `progresso_atual` sempre 0 no banco, e ler esse campo mostraria zero para
 * sempre — é o erro que `carregarFontes` + `valorAtual` existem para evitar.
 *
 * Enquanto os módulos de origem não estiverem migrados, os stores deles estão
 * vazios e o valor derivado é 0. Isso é correto, não um defeito: a meta passa a
 * andar sozinha no dia em que a origem chegar.
 */

import { moeda, numero } from '../../datas.ts';
import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

export interface Meta extends Registro {
  id?: number;
  titulo: string;
  /** A chave da categoria (ver `CATEGORIAS`). */
  item: string;
  ativo_id?: number;
  /** Nome do ativo vinculado — só as categorias com `precisaAtivo` usam. */
  ativo_nome: string;
  data_meta: number;
  prazo_final: number;
  progresso_atual: number;
  progresso_alvo: number;
  esta_concluida: number;
}

export type Unidade = 'VALOR' | 'TEMPO_HORAS' | 'TEMPO_MINUTOS' | 'PERCENTUAL' | 'QUANTIDADE';

export interface Categoria {
  readonly chave: string;
  readonly modulo: string;
  readonly ativo: string;
  readonly unidade: Unidade;
  /** `true` quando o usuário precisa nomear o ativo (categoria do Financeiro). */
  readonly precisaAtivo?: boolean;
}

/** Catálogo de categorias de meta — espelha o `CategoriaMeta` do app Kotlin. */
export const CATEGORIAS: readonly Categoria[] = [
  { chave: 'fin_poupanca', modulo: 'Financeiro', ativo: 'Poupança / Saldo', unidade: 'VALOR' },
  { chave: 'fin_gastos', modulo: 'Financeiro', ativo: 'Total de Gastos', unidade: 'VALOR' },
  {
    chave: 'fin_categoria',
    modulo: 'Financeiro',
    ativo: 'Categoria Específica',
    unidade: 'VALOR',
    precisaAtivo: true,
  },
  { chave: 'min_horas', modulo: 'Ministério', ativo: 'Horas de Campo', unidade: 'TEMPO_HORAS' },
  { chave: 'min_estudos', modulo: 'Ministério', ativo: 'Estudos Bíblicos', unidade: 'QUANTIDADE' },
  { chave: 'min_revisitas', modulo: 'Ministério', ativo: 'Revisitas', unidade: 'QUANTIDADE' },
  {
    chave: 'est_foco_min',
    modulo: 'Modo Estudo',
    ativo: 'Minutos de Foco',
    unidade: 'TEMPO_MINUTOS',
  },
  {
    chave: 'est_sessoes',
    modulo: 'Modo Estudo',
    ativo: 'Sessões Completadas',
    unidade: 'QUANTIDADE',
  },
  {
    chave: 'jog_perguntas',
    modulo: 'Jogo Língua Pura',
    ativo: 'Perguntas Respondidas',
    unidade: 'QUANTIDADE',
  },
  { chave: 'poe_lidas', modulo: 'Poesias', ativo: 'Poesias Lidas', unidade: 'QUANTIDADE' },
];

/**
 * Categorias cujo progresso é derivado dos dados reais. `poe_lidas` fica fora: o
 * usuário informa à mão, no +/− da lista.
 */
export const AUTOMATICAS = new Set([
  'fin_poupanca',
  'fin_gastos',
  'fin_categoria',
  'min_horas',
  'min_estudos',
  'min_revisitas',
  'est_foco_min',
  'est_sessoes',
  'jog_perguntas',
]);

/**
 * A categoria de uma chave. Metas antigas podem apontar para categorias já
 * removidas do catálogo: caem numa pseudo-categoria de progresso manual, em vez
 * de sumir da lista.
 */
export function categoriaDe(chave: string): Categoria {
  return (
    CATEGORIAS.find((categoria) => categoria.chave === chave) ?? {
      chave,
      modulo: 'Geral',
      ativo: 'Meta',
      unidade: 'QUANTIDADE',
    }
  );
}

// ── Fontes do progresso automático ──────────────────────────────────────────

const TIPO_RECEITA = 0;
const TIPO_DESPESA = 1;

/** Onde o Jogo guarda o progresso dele. */
const CHAVE_JOGO = 'papiro_jogo_progresso';

/** Os agregados de que as metas automáticas precisam. */
export interface Fontes {
  readonly receitas: number;
  readonly despesas: number;
  readonly despesaPorCategoria: Readonly<Record<string, number>>;
  readonly horas: number;
  readonly revisitas: number;
  readonly estudos: number;
  readonly focoMin: number;
  readonly sessoes: number;
  readonly perguntas: number;
}

interface Transacao extends Registro {
  tipo: number;
  valor: number;
  categoria_id?: number;
}

interface ComNome extends Registro {
  id?: number;
  nome?: string;
}

function soma<T>(itens: readonly T[], valor: (item: T) => unknown): number {
  return itens.reduce((total, item) => total + (Number(valor(item)) || 0), 0);
}

function lerLocal<T>(chave: string, reserva: T): T {
  try {
    return (JSON.parse(localStorage.getItem(chave) ?? 'null') as T | null) ?? reserva;
  } catch {
    return reserva;
  }
}

const metas = () => repositorio('meta');

/** Lê os stores de origem e monta os agregados, mais as categorias do Financeiro. */
export async function carregarFontes(): Promise<{
  fontes: Fontes;
  categoriasFinanceiro: ComNome[];
}> {
  const vazio =
    <T extends Registro>() =>
    (): Promise<T[]> =>
      Promise.resolve([]);

  const [transacoes, categorias, relatorios, contadores, estudosBiblicos, sessoes] =
    await Promise.all([
      repositorio('transacoes').todos<Transacao>().catch(vazio<Transacao>()),
      repositorio('categorias_financeiro').todos<ComNome>().catch(vazio<ComNome>()),
      repositorio('relatorios_ministerio').todos().catch(vazio()),
      repositorio('contadores_ministerio').todos().catch(vazio()),
      repositorio('estudos_biblicos').todos().catch(vazio()),
      repositorio('sessoes_estudo').todos().catch(vazio()),
    ]);

  const despesas = transacoes.filter((t) => t.tipo === TIPO_DESPESA);

  const nomePorId = new Map(categorias.map((categoria) => [categoria.id, categoria.nome ?? '']));
  const despesaPorCategoria: Record<string, number> = {};
  for (const transacao of despesas) {
    const nome = nomePorId.get(transacao.categoria_id) ?? '';
    despesaPorCategoria[nome] = (despesaPorCategoria[nome] ?? 0) + (Number(transacao.valor) || 0);
  }

  const fontes: Fontes = {
    receitas: soma(
      transacoes.filter((t) => t.tipo === TIPO_RECEITA),
      (t) => t.valor,
    ),
    despesas: soma(despesas, (t) => t.valor),
    despesaPorCategoria,
    horas: soma(relatorios, (r) => (r as { horas?: number }).horas),
    revisitas: soma(contadores, (c) => (c as { revisitas?: number }).revisitas),
    estudos: estudosBiblicos.length,
    focoMin: soma(sessoes, (s) => (s as { duracao_minutos?: number }).duracao_minutos),
    sessoes: sessoes.length,
    perguntas: (
      lerLocal(CHAVE_JOGO, {} as { perguntasRespondidas?: unknown[] }).perguntasRespondidas ?? []
    ).length,
  };

  const categoriasFinanceiro = [...categorias].sort((a, b) =>
    (a.nome ?? '').localeCompare(b.nome ?? '', 'pt-BR', { sensitivity: 'base' }),
  );

  return { fontes, categoriasFinanceiro };
}

/** O valor derivado da categoria; `null` quando ela é manual. */
export function valorAutomatico(meta: Meta, fontes: Fontes | null): number | null {
  if (fontes === null || !AUTOMATICAS.has(meta.item)) return null;

  switch (meta.item) {
    case 'fin_poupanca':
      return fontes.receitas - fontes.despesas;
    case 'fin_gastos':
      return fontes.despesas;
    case 'fin_categoria':
      return fontes.despesaPorCategoria[meta.ativo_nome] ?? 0;
    case 'min_horas':
      return fontes.horas;
    case 'min_estudos':
      return fontes.estudos;
    case 'min_revisitas':
      return fontes.revisitas;
    case 'est_foco_min':
      return fontes.focoMin;
    case 'est_sessoes':
      return fontes.sessoes;
    case 'jog_perguntas':
      return fontes.perguntas;
    default:
      return null;
  }
}

/** O progresso exibido: derivado nas automáticas, informado nas manuais. */
export function valorAtual(meta: Meta, fontes: Fontes | null): number {
  const derivado = valorAutomatico(meta, fontes);
  return derivado === null ? Number(meta.progresso_atual) || 0 : derivado;
}

/** Manual respeita o sinalizador; automática conclui ao atingir o alvo. */
export function concluida(meta: Meta, fontes: Fontes | null): boolean {
  if (meta.esta_concluida === 1) return true;

  const alvo = Number(meta.progresso_alvo) || 0;
  return AUTOMATICAS.has(meta.item) && alvo > 0 && valorAtual(meta, fontes) >= alvo;
}

export function percentual(meta: Meta, fontes: Fontes | null): number {
  const alvo = Number(meta.progresso_alvo) || 0;
  if (alvo <= 0) return 0;
  return Math.max(0, Math.min(100, Math.round((valorAtual(meta, fontes) / alvo) * 100)));
}

const SEMANA_MS = 7 * 86_400_000;

export type StatusPrazo = 'concluida' | 'atrasada' | 'proxima' | 'normal';

export function statusPrazo(meta: Meta, fontes: Fontes | null): StatusPrazo {
  if (concluida(meta, fontes)) return 'concluida';

  const prazo = Number(meta.prazo_final) || 0;
  if (prazo <= 0) return 'normal';

  const agora = Date.now();
  if (prazo < agora) return 'atrasada';
  if (prazo < agora + SEMANA_MS) return 'proxima';
  return 'normal';
}

/** Formata um valor conforme a unidade da categoria. */
export function medida(valor: number, chave: string): string {
  const unidade = categoriaDe(chave).unidade;

  if (unidade === 'VALOR') return moeda(valor);
  if (unidade === 'TEMPO_HORAS') return `${numero(valor)} h`;
  if (unidade === 'TEMPO_MINUTOS') return `${numero(valor)} min`;
  if (unidade === 'PERCENTUAL') return `${numero(valor)}%`;
  return numero(valor);
}

/** O sufixo curto da unidade, para o formulário. */
export function sufixo(chave: string): string {
  const unidades: Record<Unidade, string> = {
    VALOR: 'R$',
    TEMPO_HORAS: 'h',
    TEMPO_MINUTOS: 'min',
    PERCENTUAL: '%',
    QUANTIDADE: 'un',
  };
  return unidades[categoriaDe(chave).unidade];
}

/** O rótulo "Módulo: Ativo", com o ativo nomeado quando houver. */
export function rotuloCategoria(meta: Meta): string {
  const categoria = categoriaDe(meta.item);
  const base = `${categoria.modulo}: ${categoria.ativo}`;
  return meta.ativo_nome === '' ? base : `${base} · ${meta.ativo_nome}`;
}

// ── Lista e gravação ────────────────────────────────────────────────────────

export type Filtro = 'ativas' | 'concluidas' | 'todas';

/** Filtra e ordena: abertas primeiro, e dentro delas o prazo mais próximo. */
export function listar(
  todas: readonly Meta[],
  fontes: Fontes | null,
  filtro: Filtro,
  busca: string,
): Meta[] {
  const alvo = busca.trim().toLowerCase();

  return todas
    .filter((meta) => {
      const fechada = concluida(meta, fontes);
      if (filtro === 'ativas' && fechada) return false;
      if (filtro === 'concluidas' && !fechada) return false;
      if (alvo === '') return true;

      return (
        meta.titulo.toLowerCase().includes(alvo) ||
        rotuloCategoria(meta).toLowerCase().includes(alvo)
      );
    })
    .sort((a, b) => {
      const fechadas = Number(concluida(a, fontes)) - Number(concluida(b, fontes));
      if (fechadas !== 0) return fechadas;
      return (a.prazo_final || 0) - (b.prazo_final || 0);
    });
}

export function listarMetas(): Promise<Meta[]> {
  return metas().todos<Meta>();
}

export function salvarMeta(meta: Meta): Promise<number> {
  return metas().salvar(meta);
}

export function excluirMeta(id: number): Promise<void> {
  return metas().excluir(id);
}

/**
 * Ajuste rápido na lista: um décimo do alvo por toque, preso entre zero e o
 * alvo. Só faz sentido em meta manual — a automática espelha outro módulo.
 */
export async function ajustar(meta: Meta, sinal: number): Promise<void> {
  const alvo = Number(meta.progresso_alvo) || 1;
  const passo = Math.max(1, Math.round(alvo / 10));
  const atual = Math.min(alvo, Math.max(0, Number(meta.progresso_atual) + sinal * passo));

  await salvarMeta({
    ...meta,
    progresso_atual: atual,
    esta_concluida: atual >= alvo ? 1 : meta.esta_concluida,
  });
}

/** Conclui ou reabre. Concluir à mão preenche o progresso até o alvo. */
export async function alternarConclusao(meta: Meta): Promise<void> {
  const novo = meta.esta_concluida === 1 ? 0 : 1;

  await salvarMeta({
    ...meta,
    esta_concluida: novo,
    progresso_atual: novo === 1 ? Number(meta.progresso_alvo) : meta.progresso_atual,
  });
}
