/**
 * A tela das Guias — porte de `modulos/guias/guias.js` e da seção correspondente
 * do `index.html` do legado.
 *
 * Três vistas na mesma rota, como no original: a lista (`#/guias`), a leitura
 * (`#/guias/<id>` para o acervo curado, `#/guias/local/<id>` para as suas) e o
 * editor (`#/guias/nova`, `#/guias/editar/<id>`). A origem viaja no hash porque
 * o mesmo número existe nos dois acervos — sem ela, recarregar a página abriria
 * a guia errada.
 *
 * O modo discurso e a leitura em voz alta vêm de `ui/leitura.ts`, compartilhados
 * com Anotações, Poesia e Receitas.
 */

import type StEditor from '@marinx/stratum/components/editor/editor.js';
import { sanitizeHtml } from '@marinx/stratum/components/editor/editor.js';
import { html, nothing, type TemplateResult } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { dataHora, resumo, textoLimpo } from '../../texto.ts';
import { compartilhar } from '../../ui/compartilhar.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { Leitura } from '../../ui/leitura.ts';
import { notificar } from '../../ui/notificar.ts';
import type { ComOrigem } from '../acervo.ts';
import { semTexto } from '../acervo.ts';
import {
  corpoDaGuia,
  excluirGuia,
  type Guia,
  listarGuias,
  obterGuia,
  salvarGuia,
} from './dados.ts';

const ESPERA_BUSCA_MS = 400;
const ESPERA_SALVAR_MS = 1200;

/** A guia aberta no editor, enquanto ela ainda não foi gravada. */
interface Edicao {
  id: number | null;
  titulo: string;
  texto: string;
  status: string;
}

let lista: ComOrigem<Guia>[] = [];
let busca = '';

let aberta: Guia | null = null;
let abertaLocal = false;

let edicao: Edicao | null = null;

let carregada: string | undefined;
let carregando = false;

let timerBusca: ReturnType<typeof setTimeout> | undefined;
let timerSalvar: ReturnType<typeof setTimeout> | undefined;

const leitura = new Leitura();

function editorNoDocumento(): StEditor | null {
  return document.querySelector('st-editor');
}

/**
 * Impõe o conteúdo ao editor que está no documento.
 *
 * Atribuir `value` é o que troca o texto inteiro; o componente ignora a
 * atribuição quando o valor é o mesmo que já está lá, e é isso que impede o
 * cursor de voltar ao começo a cada redesenho da tela.
 */
function atribuirAoEditor(conteudo: string): void {
  const editor = editorNoDocumento();
  if (editor !== null) editor.value = conteudo;
}

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregarLista(): Promise<void> {
  lista = await listarGuias(busca);
  atualizar();
}

async function abrirLeitura(id: number, local: boolean): Promise<void> {
  abertaLocal = local;
  aberta = (await obterGuia(id, local)) ?? null;
  if (aberta === null) navegar('guias');
}

async function abrirEditor(id: number | null): Promise<void> {
  if (id === null) {
    edicao = { id: null, titulo: '', texto: '', status: '' };
  } else {
    const guia = await obterGuia(id, true);
    if (guia === undefined) {
      navegar('guias');
      return;
    }
    edicao = { id: guia.id ?? null, titulo: guia.titulo, texto: guia.texto, status: '' };
  }

  atualizar();
  atribuirAoEditor(edicao.texto);
}

/** Sincroniza a tela com o hash; sai na hora quando a rota não mudou. */
function sincronizar(rota: Rota): void {
  const chave = rota.args.join('/');
  if (carregada === chave || carregando) return;

  carregada = chave;
  carregando = true;
  leitura.fechar();

  void (async () => {
    try {
      const [primeiro, segundo] = rota.args;

      if (primeiro === undefined) {
        aberta = null;
        edicao = null;
        await recarregarLista();
      } else if (primeiro === 'nova') {
        aberta = null;
        await abrirEditor(null);
      } else if (primeiro === 'editar') {
        aberta = null;
        await abrirEditor(Number.parseInt(segundo ?? '', 10));
      } else if (primeiro === 'local') {
        edicao = null;
        await abrirLeitura(Number.parseInt(segundo ?? '', 10), true);
      } else {
        edicao = null;
        await abrirLeitura(Number.parseInt(primeiro, 10), false);
      }
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Lista ───────────────────────────────────────────────────────────────────

function aoBuscar(texto: string): void {
  busca = texto;
  clearTimeout(timerBusca);
  timerBusca = setTimeout(() => void recarregarLista(), ESPERA_BUSCA_MS);
}

function cartao(guia: ComOrigem<Guia>): TemplateResult {
  const previa = resumo(guia.texto, 180);

  return html`
    <button
      class="cartao"
      @click=${() => navegar(guia.local ? `guias/local/${guia.id ?? ''}` : `guias/${guia.id ?? ''}`)}
    >
      <span class="cartao__topo">
        <st-icon class="cartao__icone" name="map-2"></st-icon>
        <span class="cartao__titulo">${guia.titulo || S.acervo.semTitulo}</span>
        ${guia.local ? html`<st-badge variant="success" pill>${S.acervo.meu}</st-badge>` : nothing}
      </span>

      ${previa === '' ? nothing : html`<span class="cartao__previa">${previa}</span>`}
    </button>
  `;
}

function telaDaLista(): TemplateResult {
  return html`
    <div class="filtros">
      <st-input
        class="filtros__busca"
        type="search"
        clearable
        placeholder=${S.guias.buscar}
        .value=${busca}
        @st-input=${(evento: Event) => aoBuscar((evento.target as HTMLInputElement).value)}
      >
        <st-icon slot="prefix" name="search"></st-icon>
      </st-input>
    </div>

    ${
      lista.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="map-2"></st-icon>
            <p>${S.guias.vazio}</p>
          </div>
        `
        : html`<div class="cartoes">${lista.map((guia) => cartao(guia))}</div>`
    }
  `;
}

// ── Leitura ─────────────────────────────────────────────────────────────────

/** O que a voz pronuncia e o que o compartilhamento envia: título + corpo. */
function textoDaGuia(guia: Guia): string {
  return `${guia.titulo}. ${corpoDaGuia(guia)}`;
}

function corpo(guia: Guia): TemplateResult {
  return html`<div class="prosa">${unsafeHTML(sanitizeHtml(corpoDaGuia(guia)))}</div>`;
}

function telaDaLeitura(guia: Guia): TemplateResult {
  return html`
    ${corpo(guia)}
    ${leitura.overlay(
      html`
          <h1>${guia.titulo}</h1>
          ${corpo(guia)}
        `,
      () => textoDaGuia(guia),
    )}
  `;
}

async function excluirAtual(): Promise<void> {
  const id = aberta?.id;
  if (id === undefined || !abertaLocal) return;

  const ok = await confirmar({
    titulo: S.guias.excluir,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await excluirGuia(id);
  notificar(S.guias.excluida);
  navegar('guias');
}

// ── Editor ──────────────────────────────────────────────────────────────────

function agendarSalvar(): void {
  if (edicao === null) return;
  edicao = { ...edicao, status: S.acervo.salvando };
  atualizar();

  clearTimeout(timerSalvar);
  timerSalvar = setTimeout(() => void salvar(), ESPERA_SALVAR_MS);
}

/** Grava a guia local. Sem título ou sem corpo não há o que gravar. */
async function salvar(): Promise<void> {
  if (edicao === null) return;

  if (edicao.titulo.trim() === '' || semTexto(edicao.texto)) {
    edicao = { ...edicao, status: S.acervo.tituloEConteudo };
    atualizar();
    return;
  }

  const agora = Date.now();
  const registro: Guia = {
    titulo: edicao.titulo,
    texto: edicao.texto,
    // `publicar` é a chave do admin; num registro do aparelho ela é sempre 0.
    publicar: 0,
    data_atualizacao: agora,
    ...(edicao.id === null ? { data_criacao: agora } : { id: edicao.id }),
  };

  const id = await salvarGuia(registro);

  if (edicao.id === null) {
    edicao = { ...edicao, id };
    // `replaceState` em vez de navegar: trocar o hash recarregaria o editor no
    // meio da digitação (mesma razão explicada em Anotações).
    history.replaceState(null, '', `#/guias/editar/${id}`);
  }

  edicao = { ...edicao, status: S.acervo.salvoAs(dataHora(agora)) };
  atualizar();
}

function telaDoEditor(estado: Edicao): TemplateResult {
  return html`
    <div class="editor">
      <st-input
        class="editor__titulo"
        placeholder=${S.guias.tituloPlaceholder}
        .value=${estado.titulo}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, titulo: (evento.target as HTMLInputElement).value };
          agendarSalvar();
        }}
      ></st-input>

      <div class="editor__linha">
        <span class="editor__status">${estado.status}</span>
      </div>

      <st-editor
        @st-input=${(evento: CustomEvent<{ value: string }>) => {
          edicao = { ...estado, texto: evento.detail.value };
          agendarSalvar();
        }}
      ></st-editor>
    </div>
  `;
}

// ── A tela ──────────────────────────────────────────────────────────────────

function acoesDaLeitura(guia: Guia): TemplateResult {
  return html`
    ${leitura.botaoApresentar()}
    ${leitura.botaoFala(() => textoDaGuia(guia))}
    <st-icon-button
      name="share"
      label=${S.leitura.compartilhar}
      @click=${() => void compartilhar(guia.titulo, textoLimpo(corpoDaGuia(guia)))}
    ></st-icon-button>
    ${
      abertaLocal
        ? html`
          <st-icon-button
            name="pencil"
            label=${S.acoes.editar}
            @click=${() => navegar(`guias/editar/${guia.id ?? ''}`)}
          ></st-icon-button>
          <st-icon-button
            name="trash"
            label=${S.guias.excluir}
            @click=${() => void excluirAtual()}
          ></st-icon-button>
        `
        : nothing
    }
  `;
}

export const telaGuias: Tela = {
  voltarPara(rota) {
    // "Guias" não tem tile na home: entra-se por "Esteja Preparado", e é para lá
    // que se volta (o `dentroDe: 'prep'` do registro diz a mesma coisa).
    return rota.args.length === 0 ? 'prep' : 'guias';
  },

  titulo(rota) {
    const [primeiro] = rota.args;
    if (primeiro === undefined) return undefined;
    if (primeiro === 'nova' || primeiro === 'editar') {
      const titulo = edicao?.titulo.trim() ?? '';
      return titulo === '' ? S.guias.novaTitulo : titulo;
    }
    return aberta?.titulo;
  },

  acoes(rota) {
    const [primeiro] = rota.args;

    if (primeiro === undefined) {
      return html`
        <st-icon-button
          name="plus"
          label=${S.guias.nova}
          @click=${() => navegar('guias/nova')}
        ></st-icon-button>
      `;
    }

    if (primeiro === 'nova' || primeiro === 'editar') return undefined;
    return aberta === null ? undefined : acoesDaLeitura(aberta);
  },

  conteudo(rota) {
    sincronizar(rota);

    const [primeiro] = rota.args;
    if (primeiro === undefined) return telaDaLista();

    if (primeiro === 'nova' || primeiro === 'editar') {
      return edicao === null ? carregandoTela() : telaDoEditor(edicao);
    }

    return aberta === null ? carregandoTela() : telaDaLeitura(aberta);
  },
};

function carregandoTela(): TemplateResult {
  return html`<div class="carregando"><st-spinner></st-spinner></div>`;
}
