/**
 * Os puzzles de sliders da física, do cosmo e da matemática do dia a dia.
 *
 * Porte da metade "não biológica" de `modulos/criacao/renderizadores.js`. Duas
 * simulações moram aqui porque são fonte única de duas coisas ao mesmo tempo —
 * a leitura do renderizador e o desenho da viz: a trajetória do bilhar (que
 * reflete nas tabelas) e os trastes do monocórdio de Pitágoras.
 */

import { S } from '../../../strings.ts';
import { CATEGORIAS_QUIMICAS, ELEMENTOS, ESTADOS, FATOS } from '../elementos.ts';
import {
  type Config,
  type Info,
  int,
  num,
  ptBR,
  type Renderizador,
  slider,
  type Valores,
  virgula,
} from './base.ts';

function v(valores: Valores, prop: string): number {
  const bruto = valores[prop];
  return typeof bruto === 'number' && Number.isFinite(bruto) ? bruto : 0;
}

/**
 * A asa longa e estreita plana mais longe: o alongamento é AR = b²/S. O albatroz
 * plana horas sem bater as asas por causa dele.
 */
export const equacao: Renderizador = slider<{ alvo: number; tol: number }>({
  viz: { comp: 'asa' },
  preparar: (cfg) => ({
    params: { alvo: num(cfg.alvo, 25), tol: num(cfg.tol, 0.5) },
    controles: [
      {
        rotulo: 'Envergadura (b)',
        prop: 'b',
        min: num(cfg.bMin, 1),
        max: num(cfg.bMax, 12),
        step: 0.1,
        suf: ' m',
      },
      {
        rotulo: 'Área da asa (S)',
        prop: 's',
        min: num(cfg.sMin, 0.5),
        max: num(cfg.sMax, 8),
        step: 0.1,
        suf: ' m²',
      },
    ],
    valores: { b: num(cfg.b0, 5), s: num(cfg.s0, 3) },
  }),
  medir(valores, p): Info {
    const b = v(valores, 'b');
    const s = v(valores, 's');
    const alongamento = s > 0 ? (b * b) / s : 0;
    const ok = Math.abs(alongamento - p.alvo) <= p.tol;

    const planeio = ok
      ? 'planeio longo e plano ✔'
      : alongamento < p.alvo
        ? 'asa curta/larga: cai logo no mar'
        : 'passou do alvo — ajuste b e S';

    return {
      ok,
      ar: alongamento,
      leitura: `Asa longa e estreita plana mais longe. AR = b²/S = ${alongamento.toFixed(1)} (alvo ${p.alvo}) — ${planeio}`,
    };
  },
});

/** A sincronia de um ritmo biológico com o ciclo solar: amplitude e fase. */
export const funcao: Renderizador = slider<{
  ampAlvo: number;
  faseAlvo: number;
  tol: number;
  tolFase: number;
}>({
  extra: 'funcao',
  viz: { comp: 'funcao' },
  preparar: (cfg) => ({
    params: {
      ampAlvo: num(cfg.ampAlvo, 3),
      faseAlvo: num(cfg.faseAlvo, 90),
      tol: num(cfg.tol, 0.2),
      tolFase: num(cfg.tolFase, 6),
    },
    controles: [
      { rotulo: 'Amplitude (A)', prop: 'a', min: 0.5, max: 5, step: 0.1 },
      { rotulo: 'Fase (φ)', prop: 'fase', min: 0, max: 180, step: 1, suf: '°' },
    ],
    valores: { a: num(cfg.a0, 1), fase: num(cfg.fase0, 0) },
  }),
  medir(valores, p): Info {
    const ok =
      Math.abs(v(valores, 'a') - p.ampAlvo) <= p.tol &&
      Math.abs(v(valores, 'fase') - p.faseAlvo) <= p.tolFase;

    return {
      ok,
      ampAlvo: p.ampAlvo,
      faseAlvo: p.faseAlvo,
      leitura: `Sincronia com o ciclo solar: ${ok ? 'alinhada ✔' : 'ajuste A e φ'}`,
    };
  },
});

/** A lente do olho: os raios só convergem num único foco na curvatura certa. */
export const conica: Renderizador = slider<{ alvo: number; tol: number }>({
  viz: { comp: 'lente' },
  preparar: (cfg) => ({
    params: { alvo: num(cfg.alvo, 50), tol: num(cfg.tol, 3) },
    controles: [{ rotulo: 'Curvatura da lente', prop: 'c', min: 0, max: 100, step: 1, suf: '%' }],
    valores: { c: num(cfg.c0, 10) },
  }),
  medir(valores, p): Info {
    const ok = Math.abs(v(valores, 'c') - p.alvo) <= p.tol;

    return {
      ok,
      leitura: ok ? 'Os raios convergem num único foco ✔' : 'Os raios ainda não focam num ponto.',
    };
  },
});

/** As ranhuras da pele do tubarão: no espaçamento certo, a turbulência some. */
export const fluxo: Renderizador = slider<{ alvo: number; tol: number }>({
  viz: { comp: 'fluxo' },
  preparar: (cfg) => ({
    params: { alvo: num(cfg.alvo, 35), tol: num(cfg.tol, 3) },
    controles: [
      { rotulo: 'Espaçamento das ranhuras', prop: 'e', min: 1, max: 100, step: 1, suf: ' µm' },
    ],
    valores: { e: num(cfg.e0, 80) },
  }),
  medir(valores, p): Info {
    const e = v(valores, 'e');
    const turbulencia = Math.round(Math.abs(e - p.alvo) * 1.5 + 5);

    return {
      ok: Math.abs(e - p.alvo) <= p.tol,
      turb: turbulencia,
      leitura: `Turbulência: ${turbulencia}%`,
    };
  },
});

/** A cor da asa da borboleta não é pigmento: é difração nas escamas. */
export const difracao: Renderizador = slider<{ alvo: number; tol: number }>({
  extra: 'difracao',
  viz: { comp: 'difracao' },
  preparar: (cfg) => ({
    params: { alvo: num(cfg.lambdaAlvo, 470), tol: num(cfg.tol, 12) },
    controles: [
      { rotulo: 'Distância entre fendas (d)', prop: 'd', min: 200, max: 800, step: 5, suf: ' nm' },
    ],
    valores: { d: num(cfg.d0, 600) },
  }),
  medir(valores, p): Info {
    // Aproximação didática: o comprimento de onda refletido acompanha `d`.
    const lambda = v(valores, 'd') * 0.78;

    return {
      ok: Math.abs(lambda - p.alvo) <= p.tol,
      lambda,
      leitura: `Comprimento de onda refletido ≈ ${lambda.toFixed(0)} nm (azul ≈ ${p.alvo})`,
    };
  },
});

/** Interferência: em oposição de fase, as ondas se cancelam e o ruído some. */
export const ondas: Renderizador = slider<{ tol: number }>({
  extra: 'ondas',
  viz: { comp: 'ondas' },
  preparar: (cfg) => ({
    params: { tol: num(cfg.tol, 4) },
    controles: [
      { rotulo: 'Defasagem das franjas', prop: 'fase', min: 0, max: 360, step: 1, suf: '°' },
    ],
    valores: { fase: num(cfg.fase0, 30) },
  }),
  medir(valores, p): Info {
    const fase = v(valores, 'fase');
    const amplitude = Math.round(Math.abs(2 * Math.cos((fase * Math.PI) / 360)) * 50);

    return {
      ok: amplitude <= p.tol,
      ruido: amplitude,
      leitura: `Ruído aerodinâmico: ${amplitude}%`,
    };
  },
});

/** Fractais: cada subdivisão dobra a área de contato sem ocupar mais espaço. */
export const fractal: Renderizador = slider<{ base: number; alvoArea: number }>({
  extra: 'fractal',
  viz: { comp: 'fractal' },
  preparar: (cfg) => ({
    params: { base: num(cfg.base, 1), alvoArea: num(cfg.alvoArea, 256) },
    controles: [{ rotulo: 'Nível de subdivisão', prop: 'n', min: 0, max: 12, step: 1 }],
    valores: { n: int(cfg.n0, 0) },
  }),
  medir(valores, p): Info {
    const area = p.base * 2 ** v(valores, 'n');

    return {
      ok: area >= p.alvoArea,
      area,
      leitura: `Área de contato: ${ptBR(area)}× a base`,
    };
  },
});

/**
 * A inclinação do eixo da Terra (~23,5°) é o que produz estações amenas e clima
 * habitável. Reto demais congela os polos; inclinado demais, estações extremas.
 */
export const terra: Renderizador = slider<{ alvo: number; tol: number }>({
  extra: 'terra',
  viz: { comp: 'terra3d' },
  preparar: (cfg) => ({
    params: { alvo: num(cfg.alvo, 23.5), tol: num(cfg.tol, 3) },
    controles: [{ rotulo: 'Inclinação do eixo', prop: 't', min: 0, max: 45, step: 0.5, suf: '°' }],
    valores: { t: num(cfg.t0, 0) },
  }),
  medir(valores, p): Info {
    const t = v(valores, 't');
    const ok = Math.abs(t - p.alvo) <= p.tol;

    return {
      ok,
      leitura: ok
        ? 'Inclinação de ~23,5°: estações equilibradas e clima ameno na maior parte da Terra ✔'
        : t < p.alvo - p.tol
          ? 'Eixo muito reto: quase sem estações — polos congelam e trópicos fervem.'
          : 'Eixo muito inclinado: estações extremas e clima instável.',
    };
  },
});

/**
 * "Partículas elementares do mundo do átomo" (Despertai!): se o núcleo fosse
 * uma bola de tênis, o elétron giraria a uns 3 km dali — a matéria "sólida" é
 * quase toda espaço vazio.
 */
export const atomo: Renderizador = slider<{
  raioCm: number;
  razao: number;
  alvo: number;
  tol: number;
}>({
  extra: 'atomo',
  viz: { comp: 'atomo' },
  preparar: (cfg) => ({
    params: {
      raioCm: num(cfg.raioCm, 3.5),
      razao: num(cfg.razao, 86000),
      alvo: num(cfg.alvo, 3000),
      tol: num(cfg.tol, 150),
    },
    controles: [
      {
        rotulo: 'Distância do elétron (na escala da bola)',
        prop: 'd',
        min: 0,
        max: int(cfg.dMax, 5000),
        step: 50,
        suf: ' m',
      },
    ],
    valores: { d: int(cfg.d0, 200) },
  }),
  medir(valores, p): Info {
    const d = v(valores, 'd');
    const ok = Math.abs(d - p.alvo) <= p.tol;

    // Fração do volume realmente ocupada pelo núcleo: (raio ÷ distância)³.
    const raioM = p.raioCm / 100;
    const fracao = d > 0 ? (raioM / d) ** 3 : 1;
    const expoente = d > 0 ? Math.round(-Math.log10(fracao)) : 0;
    const conta = `${virgula(p.raioCm)} cm × ${ptBR(p.razao)} ≈ ${ptBR(Math.round(raioM * p.razao))} m`;

    return {
      ok,
      exp: expoente,
      frac: fracao,
      d,
      alvo: p.alvo,
      raioCm: p.raioCm,
      razao: p.razao,
      leitura: ok
        ? `Elétron a ${ptBR(d)} m (${conta}) — o núcleo ocupa 1 parte em 10^${expoente} do volume: o átomo é quase todo VAZIO. ✔`
        : d < p.alvo
          ? `Elétron a ${ptBR(d)} m — perto demais. O átomo tem cerca de ${ptBR(p.razao)} vezes o raio do núcleo: multiplique.`
          : `Elétron a ${ptBR(d)} m — longe demais. Refaça a conta: raio da bola × ${ptBR(p.razao)}.`,
    };
  },
});

/**
 * "O que não se vê a olho nu" (Despertai!): o menor grão visível já tem mais de
 * 10 bilhões de átomos. O botão da ampliação desce as escalas até o núcleo.
 */
export const microscopio: Renderizador = slider<{ alvo: number }>({
  extra: 'microscopio',
  viz: { comp: 'microscopio' },
  preparar: (cfg) => ({
    params: { alvo: num(cfg.alvo, 8) },
    controles: [{ rotulo: 'Ampliação (10ˣ)', prop: 'x', min: 0, max: num(cfg.xMax, 9), step: 0.1 }],
    valores: { x: num(cfg.x0, 0) },
  }),
  medir(valores, p): Info {
    const x = v(valores, 'x');
    const vezes = ptBR(Math.round(10 ** x));

    return {
      ok: x >= p.alvo,
      x,
      leitura:
        x < 1
          ? `${vezes}× — a olho nu: o menor grão que você enxerga já tem mais de 10 bilhões de átomos.`
          : x < 2.5
            ? `${vezes}× — a gota de água "sem vida" fervilha de criaturas que se mexem.`
            : x < 4
              ? `${vezes}× — uma célula: fábricas, transporte e uma biblioteca de instruções lá dentro.`
              : x < 6
                ? `${vezes}× — moléculas: átomos ligados numa ordem exata (a hélice do DNA).`
                : x < 8
                  ? `${vezes}× — o átomo: uma nuvem de elétrons girando bilhões de vezes por milissegundo.`
                  : `${vezes}× — o núcleo: prótons e nêutrons, ~100.000 vezes menores que o átomo. Um próton pesa como 1.840 elétrons. ✔`,
    };
  },
});

/**
 * "O ano extraordinário de Einstein" (Despertai!): quanto mais rápido se viaja,
 * mais devagar o relógio anda (γ = 1 ÷ √(1 − v²/c²)). A meta é γ = 2 — o relógio
 * de bordo andando pela metade.
 */
export const relatividade: Renderizador = slider<{ alvoGama: number; tol: number; c: number }>({
  extra: 'relatividade',
  viz: { comp: 'relatividade' },
  preparar: (cfg) => ({
    params: { alvoGama: num(cfg.alvoGama, 2), tol: num(cfg.tol, 0.06), c: num(cfg.c, 299792) },
    controles: [
      {
        rotulo: 'Velocidade da nave (fração de c)',
        prop: 'v',
        min: 0,
        max: 99.5,
        step: 0.1,
        suf: '% de c',
      },
    ],
    valores: { v: num(cfg.v0, 10) },
  }),
  medir(valores, p): Info {
    const beta = v(valores, 'v') / 100;
    const gama = 1 / Math.sqrt(Math.max(1e-9, 1 - beta * beta));
    const ok = Math.abs(gama - p.alvoGama) <= p.tol;

    const kms = ptBR(Math.round(beta * p.c));
    const meses = virgula(12 / gama);
    const base = `${kms} km/s · γ = ${virgula(gama, 2)} — 12 meses na Terra = ${meses} meses na nave.`;

    return {
      ok,
      gama,
      beta,
      leitura: ok
        ? `${base} O tempo da nave anda pela METADE — e a energia dela também dobrou (E = γmc²). ✔`
        : gama < p.alvoGama
          ? `${base} Acelere: perto de c o relógio de bordo desacelera de vez.`
          : `${base} Passou do ponto — o relógio da nave ficou lento demais.`,
    };
  },
});

/**
 * "Um universo cheio de surpresas" (Despertai!): tudo o que se vê é só ~4% do
 * universo. Fora da receita, as galáxias se despedaçam ou o cosmo colapsa.
 */
export const universoEscuro: Renderizador = slider<{
  alvos: { comum: number; escura: number; energia: number };
  tol: number;
}>({
  extra: 'universo_escuro',
  viz: { comp: 'universo_escuro' },
  preparar: (cfg) => ({
    params: {
      alvos: {
        comum: num(cfg.comum, 4),
        escura: num(cfg.escura, 22),
        energia: num(cfg.energia, 74),
      },
      tol: num(cfg.tol, 1.5),
    },
    controles: [
      { rotulo: 'Matéria comum (o que se vê)', prop: 'comum', min: 0, max: 100, step: 1, suf: '%' },
      {
        rotulo: 'Matéria escura (segura as galáxias)',
        prop: 'escura',
        min: 0,
        max: 100,
        step: 1,
        suf: '%',
      },
      {
        rotulo: 'Energia escura (afasta as galáxias)',
        prop: 'energia',
        min: 0,
        max: 100,
        step: 1,
        suf: '%',
      },
    ],
    valores: {
      comum: int(cfg.comum0, 60),
      escura: int(cfg.escura0, 30),
      energia: int(cfg.energia0, 10),
    },
  }),
  medir(valores, p): Info {
    const comum = v(valores, 'comum');
    const escura = v(valores, 'escura');
    const energia = v(valores, 'energia');
    const soma = comum + escura + energia;

    const dentro = (atual: number, alvo: number): boolean => Math.abs(atual - alvo) <= p.tol;
    const okComum = dentro(comum, p.alvos.comum);
    const okEscura = dentro(escura, p.alvos.escura);
    const okEnergia = dentro(energia, p.alvos.energia);
    const ok = okComum && okEscura && okEnergia;

    const leitura = ok
      ? `Receita do cosmo: ${p.alvos.comum}% comum · ${p.alvos.escura}% escura · ${p.alvos.energia}% energia escura. Tudo o que se vê é só ${p.alvos.comum}% — 96% do universo continua um mistério. ✔`
      : Math.abs(soma - 100) > 3
        ? `As partes somam ${Math.round(soma)}% — o universo inteiro tem de dar 100%.`
        : !okEscura
          ? escura < p.alvos.escura
            ? 'Matéria escura de menos: sem essa "cola" invisível, as galáxias giram tão rápido que se despedaçam.'
            : 'Matéria escura demais: a gravidade freia tudo e as galáxias se enrolam.'
          : !okEnergia
            ? energia < p.alvos.energia
              ? 'Energia escura de menos: o universo para de se expandir e começa a colapsar.'
              : 'Energia escura demais: a expansão dispara e rasga as galáxias.'
            : 'Matéria comum fora da conta: estrelas, planetas e nós somos só uma fração do total.';

    return { ok, soma, alvos: p.alvos, leitura };
  },
});

/**
 * "A matemática é para todos" (Despertai! 22/05/2003): a porcentagem nas
 * compras. Preço final = preço × (100 − ajuste) ÷ 100. O slider vai de −100 a
 * 100 para cobrir descontos (+) e acréscimos (−).
 */
export const desconto: Renderizador = slider<{ preco: number; alvo: number; tol: number }>({
  extra: 'desconto',
  viz: { comp: 'desconto' },
  preparar: (cfg) => ({
    params: { preco: num(cfg.preco, 35), alvo: num(cfg.alvo, 26.25), tol: num(cfg.tol, 0.3) },
    controles: [
      {
        rotulo: 'Desconto (+) ou acréscimo (−)',
        prop: 'aj',
        min: -100,
        max: 100,
        step: 1,
        suf: '%',
      },
    ],
    valores: { aj: int(cfg.aj0, 0) },
  }),
  medir(valores, p): Info {
    const ajuste = Math.trunc(v(valores, 'aj'));
    const fator = (100 - ajuste) / 100;
    const pago = p.preco * fator;
    // Positivo é economia (desconto); negativo, o quanto se paga a mais.
    const diferenca = p.preco - pago;
    const ok = Math.abs(pago - p.alvo) <= p.tol;

    const conta = `R$ ${p.preco.toFixed(0)} × ${virgula(fator, 2)} = R$ ${virgula(pago, 2)}`;
    const base =
      ajuste > 0
        ? `Desconto de ${ajuste}%: ${conta} — você economiza R$ ${virgula(diferenca, 2)}.`
        : ajuste < 0
          ? `Acréscimo de ${-ajuste}%: ${conta} — você paga R$ ${virgula(-diferenca, 2)} a mais.`
          : `Sem ajuste: você paga o preço cheio, R$ ${virgula(p.preco, 2)}.`;

    return {
      ok,
      pago,
      delta: diferenca,
      fator,
      aj: ajuste,
      preco: p.preco,
      alvo: p.alvo,
      leitura: ok ? `${base} ✔` : base,
    };
  },
});

// ── Bilhar: a geometria que deixa prever o futuro ───────────────────────────

interface Mesa {
  readonly W: number;
  readonly H: number;
  readonly R: number;
  readonly maxB: number;
  readonly start: readonly [number, number];
  readonly target: readonly [number, number];
}

export interface Trajetoria {
  readonly pts: readonly (readonly [number, number])[];
  readonly ok: boolean;
  /** Em quantas tabelas bateu antes de acertar; −1 se errou. */
  readonly bounce: number;
}

/**
 * Simula a esfera numa mesa retangular, refletindo nas tabelas (ângulo de
 * incidência = ângulo de reflexão) até acertar o alvo ou esgotar os rebotes.
 *
 * Fonte única: o renderizador a usa para a leitura, e a viz desenha a mesma
 * polilinha. Duas contas separadas fariam a linha de previsão mentir.
 */
export function simularBilhar(mesa: Mesa, angulo: number): Trajetoria {
  const rad = (angulo * Math.PI) / 180;
  // Parte para cima e à esquerda, como no legado.
  const velocidade = { x: -Math.cos(rad), y: Math.sin(rad) };
  let pos = { x: mesa.start[0], y: mesa.start[1] };

  const pontos: [number, number][] = [[pos.x, pos.y]];
  const limX = mesa.W / 2;
  const limY = mesa.H / 2;

  for (let rebote = 0; rebote <= mesa.maxB; rebote++) {
    const tx =
      velocidade.x > 0
        ? (limX - pos.x) / velocidade.x
        : velocidade.x < 0
          ? (-limX - pos.x) / velocidade.x
          : Number.POSITIVE_INFINITY;
    const ty =
      velocidade.y > 0
        ? (limY - pos.y) / velocidade.y
        : velocidade.y < 0
          ? (-limY - pos.y) / velocidade.y
          : Number.POSITIVE_INFINITY;
    const ateTabela = Math.min(tx, ty);

    // Menor aproximação do alvo neste trecho.
    const dx = mesa.target[0] - pos.x;
    const dy = mesa.target[1] - pos.y;
    const tPerto = Math.max(0, Math.min(ateTabela, dx * velocidade.x + dy * velocidade.y));
    const cx = pos.x + velocidade.x * tPerto;
    const cy = pos.y + velocidade.y * tPerto;

    if (Math.hypot(mesa.target[0] - cx, mesa.target[1] - cy) <= mesa.R) {
      pontos.push([cx, cy]);
      return { pts: pontos, ok: true, bounce: rebote };
    }

    pos = { x: pos.x + velocidade.x * ateTabela, y: pos.y + velocidade.y * ateTabela };
    pontos.push([pos.x, pos.y]);

    // Reflete na tabela atingida.
    if (tx < ty) velocidade.x *= -1;
    else velocidade.y *= -1;
  }

  return { pts: pontos, ok: false, bounce: -1 };
}

/**
 * "A matemática nos esportes" (mesmo artigo): no bilhar a geometria deixa você
 * PREVER o futuro — o ângulo de saída é igual ao de entrada, e a linha de
 * previsão calcula os rebotes antes da tacada.
 */
export const bilhar: Renderizador = slider<Mesa>({
  extra: 'bilhar',
  viz: { comp: 'bilhar' },
  preparar(cfg: Config) {
    const start = Array.isArray(cfg.start) ? (cfg.start as number[]) : [8, -3.5];
    const target = Array.isArray(cfg.target) ? (cfg.target as number[]) : [-7, -2];

    return {
      params: {
        W: num(cfg.W, 20),
        H: num(cfg.H, 12),
        R: num(cfg.R, 1.25),
        maxB: int(cfg.maxB, 4),
        start: [num(start[0], 8), num(start[1], -3.5)] as const,
        target: [num(target[0], -7), num(target[1], -2)] as const,
      },
      controles: [
        {
          rotulo: 'Ângulo da tacada',
          prop: 'ang',
          min: num(cfg.angMin, 12),
          max: num(cfg.angMax, 80),
          step: 0.5,
          suf: '°',
        },
      ],
      valores: { ang: num(cfg.ang0, 30) },
    };
  },
  medir(valores, mesa): Info {
    const angulo = v(valores, 'ang');
    const simulacao = simularBilhar(mesa, angulo);

    const leitura = simulacao.ok
      ? simulacao.bounce === 0
        ? 'Na bucha! A esfera foi direto ao alvo. ✔'
        : `Encaçapou após ${simulacao.bounce} ${simulacao.bounce === 1 ? 'tabela' : 'tabelas'}! Ângulo de entrada = ângulo de saída. ✔`
      : 'A esfera passa longe do alvo — gire o ângulo e siga a linha de previsão até acertar.';

    return {
      ok: simulacao.ok,
      caminho: simulacao.pts,
      bounce: simulacao.bounce,
      ang: angulo,
      start: mesa.start,
      target: mesa.target,
      W: mesa.W,
      H: mesa.H,
      R: mesa.R,
      leitura,
    };
  },
});

// ── Música: o som é fração ──────────────────────────────────────────────────

export interface NotaMonocordio {
  /** Comprimento que vibra, em % da corda inteira. */
  readonly p: number;
  readonly nome: string;
  readonly nota: string;
  readonly razao: string;
  readonly frac: string;
}

/**
 * Os intervalos consonantes do monocórdio de Pitágoras: cada um é o comprimento
 * que faz o trecho vibrante soar uma nota da escala em relação à fundamental
 * (corda inteira = Dó). Frações SIMPLES casam; comprimentos intermediários
 * arranham. Fonte única da leitura e dos trastes desenhados na viz.
 */
export const NOTAS_MUSICA: readonly NotaMonocordio[] = [
  { p: 50, nome: 'Oitava', nota: 'Dó⁸', razao: '2 : 1', frac: '1/2' },
  { p: 60, nome: 'Sexta', nota: 'Lá', razao: '5 : 3', frac: '3/5' },
  { p: 200 / 3, nome: 'Quinta', nota: 'Sol', razao: '3 : 2', frac: '2/3' },
  { p: 75, nome: 'Quarta', nota: 'Fá', razao: '4 : 3', frac: '3/4' },
  { p: 80, nome: 'Terça', nota: 'Mi', razao: '5 : 4', frac: '4/5' },
  { p: 100, nome: 'Uníssono', nota: 'Dó', razao: '1 : 1', frac: '1/1' },
];

/**
 * A harmonia oculta na música: a altura do som é 1/comprimento, então dividir a
 * corda por uma fração simples produz uma nota que casa. O desafio pede a
 * OITAVA — a corda pela metade, a mesma nota o dobro mais aguda.
 */
export const musica: Renderizador = slider<{ alvo: number; tol: number; tolNota: number }>({
  extra: 'musica',
  viz: { comp: 'musica' },
  preparar: (cfg) => ({
    params: { alvo: num(cfg.alvo, 50), tol: num(cfg.tol, 1.5), tolNota: num(cfg.tolNota, 1.2) },
    controles: [
      {
        rotulo: 'Comprimento que vibra (fração da corda)',
        prop: 'comp',
        min: num(cfg.compMin, 40),
        max: num(cfg.compMax, 100),
        step: 0.5,
        suf: '%',
      },
    ],
    valores: { comp: num(cfg.comp0, 88) },
  }),
  medir(valores, p): Info {
    const comprimento = v(valores, 'comp');

    // Nota consonante mais próxima do comprimento atual.
    let notaPerto = NOTAS_MUSICA[0];
    let menorDistancia = Number.POSITIVE_INFINITY;
    for (const nota of NOTAS_MUSICA) {
      const distancia = Math.abs(comprimento - nota.p);
      if (distancia < menorDistancia) {
        menorDistancia = distancia;
        notaPerto = nota;
      }
    }

    const consonante = menorDistancia <= p.tolNota;
    const ok = Math.abs(comprimento - p.alvo) <= p.tol;

    const leitura = ok
      ? 'Oitava! A corda dividida pela metade (1/2) soa a MESMA nota, o dobro da frequência (2 : 1). Matemática pura em forma de som ✔'
      : consonante && notaPerto !== undefined
        ? `Que acorde bonito — ${notaPerto.nome} (${notaPerto.nota}), razão ${notaPerto.razao} (fração ${notaPerto.frac}). Mas o desafio pede a OITAVA: divida a corda pela metade (1/2).`
        : 'A corda "arranha" — este comprimento não é uma fração simples. Deslize até uma divisão exata (uma das notas marcadas).';

    return {
      ok,
      leitura,
      comp: comprimento,
      alvo: p.alvo,
      consonante,
      nota: consonante ? notaPerto : null,
      notas: NOTAS_MUSICA,
    };
  },
});

/**
 * "Uma proteína por acaso?" (jw.org): uma proteína é uma cadeia de aminoácidos
 * numa ordem exata. O usuário dá ao ACASO todas as chances — encurta a cadeia,
 * reduz o alfabeto, infla as tentativas — e descobre que só "vence" quando a
 * cadeia deixa de ser uma proteína funcional de verdade.
 *
 * Improbabilidade: 1 em 10^D, com D = aa · log₁₀(2·tipos) — o fator 2 é a forma
 * canhota (L) de cada aminoácido.
 */
export const proteina: Renderizador = slider<{ aaFunc: number; expUniverso: number }>({
  extra: 'proteina',
  viz: { comp: 'proteina', aspecto: '2/1' },
  preparar: (cfg) => ({
    params: { aaFunc: int(cfg.aaFunc, 100), expUniverso: int(cfg.expUniverso, 110) },
    controles: [
      { rotulo: 'Aminoácidos na cadeia', prop: 'aa', min: 2, max: int(cfg.aaMax, 300), step: 1 },
      { rotulo: 'Tipos de aminoácidos no sorteio', prop: 'tipos', min: 2, max: 20, step: 1 },
      {
        rotulo: 'Tentativas do acaso (10ˣ)',
        prop: 'exp',
        min: 0,
        max: int(cfg.expMax, 150),
        step: 1,
      },
    ],
    valores: { aa: int(cfg.aa0, 150), tipos: int(cfg.tipos0, 20), exp: int(cfg.exp0, 60) },
  }),
  medir(valores, p): Info {
    const aa = v(valores, 'aa');
    const tipos = v(valores, 'tipos');
    const expoente = v(valores, 'exp');

    // Cada posição precisa do aminoácido certo (1/tipos) E na forma canhota
    // (1/2) → 2·tipos escolhas por posição.
    const D = aa * Math.log10(2 * tipos);
    const saldo = expoente - D;
    // O acaso, em média, acertaria ao menos uma vez.
    const ok = saldo >= 0;
    const funcional = aa >= p.aaFunc && tipos >= 20;

    const dez = (x: number): string => `10^${Math.round(x)}`;
    const motivo =
      tipos < 20
        ? `só ${tipos} tipos de aminoácido (a vida usa os 20)`
        : `curta demais — ${aa} aminoácidos (uma proteína funcional tem ~${p.aaFunc}+)`;

    const leitura = ok
      ? `1 em ${dez(D)} — com ${dez(expoente)} tentativas o acaso alcançaria. Mas isto NÃO é uma proteína funcional: ${motivo}. Uma proteína real precisa dos 20 tipos e de ~${p.aaFunc}+ aminoácidos. ✔`
      : `${
          funcional
            ? `Proteína funcional (${aa} aminoácidos, 20 tipos): 1 em ${dez(D)}.`
            : `1 em ${dez(D)}.`
        } Nem ${dez(expoente)} tentativas bastam — faltam ${dez(D - expoente)} vezes. (O universo inteiro desde o Big Bang daria ~${dez(p.expUniverso)} tentativas.) Teve um Projeto?`;

    return {
      ok,
      D,
      saldo,
      real: funcional,
      aa,
      tipos,
      exp: expoente,
      leitura,
      // Relógio da improbabilidade: a 1 bilhão (10^9) de tentativas por segundo,
      // 10^D tentativas levam 10^(D−16,5) anos.
      relogio: {
        necessarias: Math.round(D),
        disponiveis: expoente,
        faltam: Math.max(0, Math.round(D - expoente)),
        anos: Math.max(0, Math.round(D - 16.5)),
        concluido: ok,
      },
    };
  },
});

/**
 * "Os elementos químicos surgiram por acaso?" (Despertai!): a ordem natural dos
 * elementos se baseia no número de PRÓTONS — 1 a 92, sem lacunas; Mendeleyev
 * previu o germânio pela lacuna 32. A missão é montar o átomo de ouro (79) — o
 * vizinho 80, com um próton a mais, é o mercúrio, um líquido prateado.
 */
export const elementos: Renderizador = slider<{ alvo: number }>({
  extra: 'elementos',
  // A dica era a de girar, herdada de quando esta cena seria 3D. Ela é 2D, e
  // nada respondia ao arrasto que o texto prometia.
  viz: { comp: 'elementos', aspecto: '16/11', dica: S.criacao.atomoDica },
  preparar: (cfg) => ({
    params: { alvo: int(cfg.alvo, 79) },
    controles: [
      {
        rotulo: 'Prótons no núcleo (número atômico Z)',
        prop: 'p',
        min: 1,
        max: int(cfg.pMax, 118),
        step: 1,
        botoes: true,
      },
    ],
    valores: { p: int(cfg.p0, 1) },
  }),
  medir(valores, p): Info {
    const z = Math.min(118, Math.max(1, Math.trunc(v(valores, 'p'))));
    const elemento = ELEMENTOS[z - 1];
    const alvo = ELEMENTOS[p.alvo - 1];
    if (elemento === undefined || alvo === undefined) {
      return { ok: false, leitura: '', z };
    }

    const [simbolo, nome, massa, categoria, estado, camadas] = elemento;
    const ok = z === p.alvo;
    const sintetico = z >= 93;
    const massaTxt = `${
      sintetico ? `[${massa}]` : massa.toLocaleString('pt-BR', { maximumFractionDigits: 3 })
    } u`;

    const fato =
      FATOS[z] ??
      (sintetico
        ? 'Produzido em laboratório — e, como era de se esperar, encaixou-se no padrão da tabela periódica.'
        : '');

    const rumo = ok
      ? ''
      : z < p.alvo
        ? ` Sua missão: o ${alvo[1]} (${alvo[0]}), com ${p.alvo} prótons — faltam ${p.alvo - z}.`
        : ` Passou do ${alvo[1]}: volte ${z - p.alvo} próton${z - p.alvo > 1 ? 's' : ''}.`;

    const vizinho =
      p.alvo === 79 ? ' Um próton a mais (80) e seria o mercúrio — um líquido prateado.' : '';

    return {
      ok,
      z,
      simbolo,
      nome,
      massaTxt,
      fato,
      camadas,
      catNome: CATEGORIAS_QUIMICAS[categoria]?.nome ?? categoria,
      catCor: CATEGORIAS_QUIMICAS[categoria]?.cor ?? '#6c757d',
      estadoNome: ESTADOS[estado]?.nome ?? '',
      estadoIcone: ESTADOS[estado]?.icone ?? 'help-circle',
      camadasTxt: camadas.split(',').join(' · '),
      leitura: ok
        ? `${p.alvo} prótons: ${nome.toUpperCase()} (${simbolo}).${vizinho} Cada próton muda tudo, e a ordem 1→92 não tem lacunas. ✔`
        : `Z = ${z}: ${nome} (${simbolo}), ${massaTxt}.${rumo}`,
    };
  },
});
