/**
 * A tela da Cronologia — porte de `modulos/cronologia/cronologia.js` e da seção
 * correspondente do `index.html` do legado.
 *
 * Uma linha do tempo de duas trilhas: a cronologia bíblica de um lado do eixo, os
 * fatos da história do outro, cada evento com o link da fonte de onde saiu.
 *
 * **Bug do legado corrigido aqui** (relatado em `FAZER_PAPIRO.md`): saltar para
 * "Expansão Mundial" funcionava, mas saltar para "Os Patriarcas" ou "A Criação"
 * parava no lugar errado. A causa era o posicionamento por `scroll-margin`, que
 * dependia de uma altura de barra medida antes e publicada numa variável CSS: se
 * a barra tivesse mudado de altura (quebra de linha, giro da tela) desde a
 * medição, todo salto herdava o valor velho. Agora o destino é calculado no
 * instante do salto, a partir da altura real das duas barras fixas — não há mais
 * medida guardada para envelhecer.
 */

import { html, nothing, type TemplateResult } from 'lit';
import type { Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import {
  agrupar,
  type Evento,
  FILTROS_INICIAIS,
  type Filtros,
  filtrar,
  type Grupo,
  listarEventos,
  paradas,
  rotuloDoAno,
  TRILHAS,
} from './dados.ts';

let eventos: Evento[] = [];
let filtros: Filtros = FILTROS_INICIAIS;
let abertoId: number | null = null;
let periodoAtual = '';

let carregado = false;
let carregando = false;

/**
 * Até quando ignorar a marcação por rolagem. Uma rolagem suave atravessa vários
 * cabeçalhos no caminho, e sem esta trava o marcador piscaria entre as eras
 * intermediárias antes de assentar no destino.
 */
let travadoAte = 0;

// ── Carga ───────────────────────────────────────────────────────────────────

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      eventos = await listarEventos();
      periodoAtual = agrupar(filtrar(eventos, filtros))[0]?.chave ?? '';
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Posição e marcação ──────────────────────────────────────────────────────

/** A altura somada das duas barras fixas, agora. */
function alturaDasBarras(): number {
  const barra = document.querySelector('.barra')?.getBoundingClientRect().height ?? 0;
  const contexto = document.querySelector('.crono__contexto')?.getBoundingClientRect().height ?? 0;
  return barra + contexto;
}

function saltarPara(chave: string): void {
  // Marca o destino já: a rolagem é suave e o marcador não deve esperar por ela.
  periodoAtual = chave;
  travadoAte = performance.now() + 900;
  atualizar();

  const alvo = document.getElementById(`crono-periodo-${chave}`);
  if (alvo === null) return;

  const topo = alvo.getBoundingClientRect().top + scrollY - alturaDasBarras() - 8;
  scrollTo({ top: Math.max(topo, 0), behavior: 'smooth' });
}

let ligado = false;

/**
 * Marca a era corrente conforme os cabeçalhos passam sob as barras.
 *
 * É um ouvinte de rolagem, e não o `IntersectionObserver` do legado: a faixa
 * estreita de detecção do original deixava passar uma era curta sem disparar, e o
 * marcador ficava na anterior. Aqui a resposta é sempre "o último cabeçalho que
 * já passou", que não tem como pular nenhum.
 *
 * O ouvinte se remove quando não encontra mais cabeçalhos — é assim que ele sai
 * de cena ao trocar de módulo, num contrato de tela que não tem desmontagem.
 */
function ligarMarcacao(): void {
  if (ligado) return;
  ligado = true;

  let agendado = false;

  const aoRolar = (): void => {
    if (agendado) return;
    agendado = true;

    requestAnimationFrame(() => {
      agendado = false;

      const cabecalhos = document.querySelectorAll<HTMLElement>('[data-periodo]');
      if (cabecalhos.length === 0) {
        removeEventListener('scroll', aoRolar);
        ligado = false;
        return;
      }

      if (performance.now() < travadoAte) return;

      const limite = alturaDasBarras() + 12;
      let corrente = '';
      for (const cabecalho of cabecalhos) {
        if (cabecalho.getBoundingClientRect().top <= limite) {
          corrente = cabecalho.dataset.periodo ?? '';
        }
      }

      if (corrente !== '' && corrente !== periodoAtual) {
        periodoAtual = corrente;
        atualizar();
      }
    });
  };

  addEventListener('scroll', aoRolar, { passive: true });
}

// ── Desenho ─────────────────────────────────────────────────────────────────

function alternarTrilha(trilha: string): void {
  filtros = {
    ...filtros,
    trilhas: { ...filtros.trilhas, [trilha]: filtros.trilhas[trilha] === false },
  };
  atualizar();
}

function limpar(): void {
  filtros = FILTROS_INICIAIS;
  atualizar();
}

function cartaoDoEvento(evento: Evento): TemplateResult {
  const aberto = abertoId === evento.id;
  const trilha = TRILHAS[evento.trilha] === undefined ? 'biblica' : evento.trilha;

  return html`
    <li class="crono__item" data-trilha=${trilha}>
      <span class="crono__marca" aria-hidden="true"></span>

      <div class="crono__cartao">
        <button
          class="crono__alvo"
          aria-expanded=${aberto ? 'true' : 'false'}
          @click=${() => {
            abertoId = aberto ? null : (evento.id ?? null);
            atualizar();
          }}
        >
          <span class="crono__ano">${rotuloDoAno(evento)}</span>
          <span class="crono__titulo">${evento.titulo}</span>
          <span class="crono__trilha">${TRILHAS[trilha]}</span>
        </button>

        ${
          !aberto
            ? nothing
            : html`
              <div class="crono__detalhe">
                ${evento.resumo === '' ? nothing : html`<p>${evento.resumo}</p>`}
                ${
                  evento.referencia === ''
                    ? nothing
                    : html`<p class="crono__referencia">${evento.referencia}</p>`
                }
                ${
                  evento.link_fonte === ''
                    ? nothing
                    : html`
                      <a class="crono__fonte" href=${evento.link_fonte} target="_blank" rel="noreferrer">
                        <st-icon name="external-link"></st-icon>
                        ${evento.obra_fonte === '' ? S.cronologia.fonte : evento.obra_fonte}
                      </a>
                    `
                }
              </div>
            `
        }
      </div>
    </li>
  `;
}

function trecho(grupo: Grupo): TemplateResult {
  return html`
    <section class="crono__trecho">
      <h2 class="crono__era" id=${`crono-periodo-${grupo.chave}`} data-periodo=${grupo.chave}>
        ${grupo.rotulo}
        <small>${S.cronologia.eventos(grupo.eventos.length)}</small>
      </h2>
      <ol class="crono__lista">${grupo.eventos.map((evento) => cartaoDoEvento(evento))}</ol>
    </section>
  `;
}

export const telaCronologia: Tela = {
  voltarPara() {
    return 'hub/estudo';
  },

  conteudo(_rota: Rota) {
    carregar();

    if (!carregado) return html`<div class="carregando"><st-spinner></st-spinner></div>`;

    const visiveis = filtrar(eventos, filtros);
    const grupos = agrupar(visiveis);

    // O ouvinte de rolagem é ligado no primeiro desenho com conteúdo — antes
    // disso não há cabeçalho para ele encontrar.
    if (grupos.length > 0) queueMicrotask(ligarMarcacao);

    return html`
      <p class="intro">${S.cronologia.intro}</p>

      <div class="crono__contexto">
        <div class="crono__paradas">
          ${paradas(eventos, grupos).map(
            (parada) => html`
              <button
                class="chip chip--pequeno"
                ?data-ativo=${parada.chave === periodoAtual}
                ?disabled=${!parada.presente}
                @click=${() => saltarPara(parada.chave)}
              >
                ${parada.rotulo}
              </button>
            `,
          )}
        </div>
      </div>

      <div class="filtros">
        <st-input
          class="filtros__busca"
          type="search"
          clearable
          placeholder=${S.cronologia.buscar}
          .value=${filtros.busca}
          @st-input=${(evento: Event) => {
            filtros = { ...filtros, busca: (evento.target as HTMLInputElement).value };
            atualizar();
          }}
        >
          <st-icon slot="prefix" name="search"></st-icon>
        </st-input>
      </div>

      <div class="chips">
        ${Object.entries(TRILHAS).map(
          ([chave, rotulo]) => html`
            <button
              class="chip"
              data-trilha=${chave}
              ?data-ativo=${filtros.trilhas[chave] !== false}
              @click=${() => alternarTrilha(chave)}
            >
              ${rotulo}
            </button>
          `,
        )}
        <button class="chip" title=${S.cronologia.limpar} @click=${limpar}>
          <st-icon name="filter-off"></st-icon>
        </button>
      </div>

      ${
        grupos.length === 0
          ? html`
            <div class="vazio">
              <st-icon class="vazio__icone" name="timeline"></st-icon>
              <p>${eventos.length === 0 ? S.cronologia.vazio : S.cronologia.semFiltro}</p>
            </div>
          `
          : html`<div class="crono">${grupos.map((grupo) => trecho(grupo))}</div>`
      }
    `;
  },
};
