const FORA_DO_ROLO =
  'Esta visão corre em sequência: ela não se abre em outra série. Siga em frente.';

export const revelacao: Renderizador = {
  arquetipo: 'explorar',
  criar() {
    const puzzle: Puzzle = {
      arquetipo: 'explorar',
      extra: 'revelacao',
      viz: {
        comp: 'revelacao',
        aspecto: '6/5',
        dica: 'O rolo aberto: os selos de um lado; ao abrir o 7º, o rolo VIRA nas trombetas.',
      },
      valores: {},
      mapa: VISOES.map((visao) => ({ id: visao.n, rotulo: `${visao.n}ª` })),
      ativoMapa: 1,
      vistos: [1],
    };

    return {
      puzzle,
      info: (): Info => {
        const atual = VISOES.find((visao) => visao.n === puzzle.ativoMapa) ?? VISOES[0];
        const vistos = puzzle.vistos ?? [];
        const faltam = VISOES.length - vistos.length;
        const ok = faltam === 0;
        if (atual === undefined) return { ok, leitura: '' };

        return {
          ok,
          ativo: atual.n,
          vistos: [...vistos],
          total: VISOES.length,
          rotulo: `${atual.n}ª`,
          ref: atual.ref,
          resumo: atual.resumo,
          ramo: atual.ramo,
          visoes: VISOES,
          encaixe: atual.ramo === null ? FORA_DO_ROLO : (ENCAIXE[atual.ramo] ?? FORA_DO_ROLO),
          // As duas visões em que a espiral entra para dentro.
          desdobra: atual.ramo === 'selo7' || atual.ramo === 'tromb7',
          leitura: ok
            ? 'As 16 visões percorridas. O livro não é uma fila: o 7º selo abre as sete trombetas, ' +
              'e a 7ª trombeta traz o Reino. ✔'
            : `${vistos.length} de ${VISOES.length} visões abertas — faltam ${faltam}.`,
        };
      },
      // O botão só habilita com as 16 abertas, então aqui é sempre conclusão.
      verificar: () => ({
        ...ACERTO,
        mensagem: 'Mapa completo — e agora o encaixe do rolo está à vista.',
      }),
    };
  },
};
