/**
 * Os dados das Guias — porte da parte de banco de
 * `sang.local/src/Papiro/Pwa/modulos/guias/guias.js`.
 *
 * Dois stores: `guias` é curado (vem do admin, só leitura) e `guias_local` é do
 * usuário. A lista mostra os dois juntos, e é a origem que decide se o item pode
 * ser editado — daí `ComOrigem` acompanhar cada registro.
 */

import { repositorio } from '../../db/banco.ts';
import { buscar, type ComOrigem, type ItemDeAcervo, juntar, ordenarPorTitulo } from '../acervo.ts';

/** Uma guia, curada ou local. O corpo é HTML rico. */
export interface Guia extends ItemDeAcervo {
  id?: number;
  titulo: string;
  texto: string;
  publicar?: number;
  data_criacao?: number;
  data_atualizacao?: number;
}

const curadas = () => repositorio('guias');
const locais = () => repositorio('guias_local');

/** A lista das duas origens, filtrada pela busca e em ordem alfabética. */
export async function listarGuias(termo: string): Promise<ComOrigem<Guia>[]> {
  const [doAdmin, doAparelho] = await Promise.all([
    curadas().todos<Guia>(),
    locais().todos<Guia>(),
  ]);

  const todas = juntar(doAdmin, doAparelho);
  return ordenarPorTitulo(buscar(todas, termo, (guia) => [guia.titulo, guia.texto]));
}

export function obterGuia(id: number, local: boolean): Promise<Guia | undefined> {
  return (local ? locais() : curadas()).obter<Guia>(id);
}

/** Grava uma guia local e devolve o id. Curadas não são graváveis: são acervo. */
export function salvarGuia(guia: Guia): Promise<number> {
  return locais().salvar(guia);
}

export function excluirGuia(id: number): Promise<void> {
  return locais().excluir(id);
}

/**
 * O corpo para exibição, sem o `<h1>` inicial: ele repete o título que o
 * cabeçalho já mostra. Vem do legado, e vale só para as guias — Poesia e
 * Receitas não embutem o título no conteúdo.
 */
export function corpoDaGuia(guia: Guia | null): string {
  return (guia?.texto ?? '').replace(/^\s*<h1\b[^>]*>[\s\S]*?<\/h1>\s*/i, '');
}
