/**
 * Tela de hub (`#/hub/<id>`): só navegação, agrupando os módulos de uma
 * categoria. Não tem store nem estado próprio.
 */

import { html, type TemplateResult } from 'lit';
import { hub, type Modulo, modulo } from '../app/modulos.ts';
import { naoEncontrado } from './erro.ts';
import { linhaDoModulo } from './home.ts';

/**
 * Os módulos de um hub, em ordem alfabética.
 *
 * A ordenação é aqui, e não no registro: em `app/modulos.ts` a lista de cada hub
 * é o que ele agrupa, e reordená-la à mão é uma combinação que se desfaz no
 * primeiro módulo novo. `sensitivity: 'base'` para "Ág…" e "Ag…" caírem no mesmo
 * lugar, como no resto do app (`modulos/acervo.ts`).
 */
function emOrdem(ids: readonly string[]): Modulo[] {
  return ids
    .map((id) => modulo(id))
    .filter((m): m is Modulo => m !== undefined)
    .sort((a, b) => a.rotulo.localeCompare(b.rotulo, 'pt-BR', { sensitivity: 'base' }));
}

export function telaDoHub(id: string): TemplateResult {
  const h = hub(id);
  if (h === undefined) return naoEncontrado();

  return html`
    <p class="intro">${h.resumo}</p>
    <div class="lista">${emOrdem(h.modulos).map((m) => linhaDoModulo(m))}</div>
  `;
}
