/**
 * Banner de "app atualizado".
 *
 * O service worker é registrado em modo `prompt` (ver vite.config.ts): quando
 * uma versão nova termina de instalar, ela fica esperando, e quem decide trocar
 * é o usuário. Trocar sozinho no meio de uma anotação é pior do que um aviso.
 *
 * O legado fazia o mesmo com `sw.js` escrito à mão e um CustomEvent; aqui o
 * `virtual:pwa-register` do plugin entrega o mesmo par de callbacks.
 */

import { registerSW } from 'virtual:pwa-register';
import type StAlert from '@marinx/stratum/components/alert/alert.js';
import { S } from './strings.ts';

export function registrarServiceWorker(): void {
  const atualizar = registerSW({
    onNeedRefresh() {
      avisar(() => {
        void atualizar(true);
      });
    },
  });
}

/** Um toast persistente (sem `duration`) com o botão que aplica a atualização. */
function avisar(aplicar: () => void): void {
  const alerta = Object.assign(document.createElement('st-alert'), {
    variant: 'primary',
    closable: true,
  }) as StAlert;

  const icone = document.createElement('st-icon');
  icone.setAttribute('slot', 'icon');
  icone.setAttribute('name', 'sparkles');

  const forte = document.createElement('strong');
  forte.textContent = S.atualizacao.titulo;

  const botao = document.createElement('st-button');
  botao.setAttribute('size', 'small');
  botao.setAttribute('variant', 'primary');
  botao.textContent = S.atualizacao.acao;
  botao.addEventListener('click', aplicar);

  alerta.append(icone, forte, document.createTextNode(` ${S.atualizacao.texto} `), botao);
  document.body.append(alerta);

  void alerta.toast();
}
