/**
 * Os dados do Perfil / ICE — porte de `modulos/perfil/perfil.js`.
 *
 * Registro único (id 1) no store privado `meu_perfil`. **Nunca é exportado**: são
 * dados de saúde e identificação, e não há caminho de código que os mande para a
 * rede — o QR do cartão é gerado no próprio aparelho.
 *
 * O vCard e as regras derivadas (tem ficha? quando renovar o DPA?) ficam aqui,
 * puras, porque são a regra do módulo e não desenho de tela.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

/** O registro único do perfil. Os booleanos são 0/1, como estão gravados. */
export interface Perfil extends Registro {
  id: number;
  nome: string;
  telefone: string;
  email: string;
  link: string;
  comentario: string;
  nomeSecretario: string;
  telefoneSecretario: string;
  tipoSanguineo: string;
  doadorOrgaos: number;
  alergias: string;
  medicamentosEmUso: string;
  observacoesMedicas: string;
  gravida: number;
  gravidezMeses: string;
  dataPrevistaParto: string;
  recusaTransfusao: number;
  fracoesAceitas: string;
  uriScanDpa: string;
  contatoEmergencia: string;
  contatoEmergenciaTelefone: string;
  nomeColih: string;
  telefoneColih: string;
  cartaoSusNumero: string;
  cpfTitular: string;
  upaReferencia: string;
  dpaCategoriaAtualizado: number;
  /** Quando o cartão físico foi marcado como assinado; 0 = não assinado. */
  dpaAssinadoEmEpoch: number;
}

const ID = 1;

export const PERFIL_VAZIO: Perfil = {
  id: ID,
  nome: '',
  telefone: '',
  email: '',
  link: '',
  comentario: '',
  nomeSecretario: '',
  telefoneSecretario: '',
  tipoSanguineo: '',
  doadorOrgaos: 0,
  alergias: '',
  medicamentosEmUso: '',
  observacoesMedicas: '',
  gravida: 0,
  gravidezMeses: '',
  dataPrevistaParto: '',
  recusaTransfusao: 0,
  fracoesAceitas: '',
  uriScanDpa: '',
  contatoEmergencia: '',
  contatoEmergenciaTelefone: '',
  nomeColih: '',
  telefoneColih: '',
  cartaoSusNumero: '',
  cpfTitular: '',
  upaReferencia: '',
  dpaCategoriaAtualizado: 0,
  dpaAssinadoEmEpoch: 0,
};

export const TIPOS_SANGUINEOS: readonly string[] = [
  'A+',
  'A−',
  'B+',
  'B−',
  'AB+',
  'AB−',
  'O+',
  'O−',
  'Desconhecido',
];

const repo = () => repositorio('meu_perfil');

/** Lê o perfil, completando com os campos que faltam num registro antigo. */
export async function carregarPerfil(): Promise<Perfil> {
  const gravado = await repo()
    .obter<Perfil>(ID)
    .catch(() => undefined);

  return gravado === undefined ? { ...PERFIL_VAZIO } : { ...PERFIL_VAZIO, ...gravado };
}

/**
 * Normaliza e grava. A normalização não é cosmética: um campo de gestação
 * preenchido depois de a gestação ser desmarcada apareceria na ficha de
 * emergência, e é a ficha que outra pessoa vai ler no seu lugar.
 */
export async function salvarPerfil(perfil: Perfil): Promise<Perfil> {
  const gravida = perfil.gravida ? 1 : 0;
  const dpaAtualizado = perfil.dpaCategoriaAtualizado ? 1 : 0;

  const normalizado: Perfil = {
    ...perfil,
    id: ID,
    doadorOrgaos: perfil.doadorOrgaos ? 1 : 0,
    recusaTransfusao: perfil.recusaTransfusao ? 1 : 0,
    gravida,
    gravidezMeses: gravida === 0 ? '' : perfil.gravidezMeses,
    dataPrevistaParto: gravida === 0 ? '' : perfil.dataPrevistaParto,
    dpaCategoriaAtualizado: dpaAtualizado,
    // Registra a data ao marcar e zera ao desmarcar: é dela que sai o aviso de
    // renovação anual.
    dpaAssinadoEmEpoch: dpaAtualizado === 0 ? 0 : perfil.dpaAssinadoEmEpoch || Date.now(),
  };

  await repo().salvar(normalizado);
  return normalizado;
}

// ── Regras derivadas ────────────────────────────────────────────────────────

function soDigitos(telefone: string): string {
  return telefone.replace(/[^\d+]/g, '');
}

/** vCard 3.0 enriquecido — espelha o `FormatadorQrCode.vCardEnriquecido`. */
export function vCard(perfil: Perfil): string {
  const numero = soDigitos(perfil.telefone);
  const linhas = [
    'BEGIN:VCARD',
    'VERSION:3.0',
    `N:;${perfil.nome};;;`,
    `FN:${perfil.nome}`,
    `TEL;TYPE=CELL:${perfil.telefone}`,
  ];

  if (perfil.email !== '') linhas.push(`EMAIL:${perfil.email}`);
  if (numero !== '') linhas.push(`URL:https://wa.me/${numero}`);

  const link = perfil.link.trim();
  const eEndereco = /^https?:\/\//i.test(link);
  if (eEndereco) linhas.push(`URL;TYPE=WORK:${link}`);

  // Um "link" que não é endereço ainda é informação: vai como nota.
  const nota = link !== '' && !eEndereco ? link : perfil.comentario.trim();
  if (nota !== '') linhas.push(`NOTE:${nota}`);

  linhas.push('END:VCARD');
  return linhas.join('\n');
}

export function linkWhatsApp(perfil: Perfil): string {
  const numero = soDigitos(perfil.telefone);
  return numero === '' ? '' : `https://wa.me/${numero}`;
}

/** O QR do cartão, como data URL. Vazio enquanto não há nome nem telefone. */
export async function qrDoCartao(perfil: Perfil): Promise<string> {
  if (perfil.nome === '' && perfil.telefone === '') return '';

  // Import tardio: o gerador só é baixado por quem abre o cartão.
  const { default: qrcode } = await import('qrcode-generator');
  const qr = qrcode(0, 'M');
  qr.addData(vCard(perfil));
  qr.make();
  return qr.createDataURL(6, 8);
}

/** Se há o que mostrar na ficha de emergência. */
export function temFichaIce(perfil: Perfil): boolean {
  return (
    perfil.nome !== '' ||
    perfil.tipoSanguineo !== '' ||
    perfil.doadorOrgaos === 1 ||
    perfil.gravida === 1 ||
    perfil.alergias !== '' ||
    perfil.medicamentosEmUso !== '' ||
    perfil.contatoEmergencia !== '' ||
    perfil.nomeColih !== ''
  );
}

/** `2026-07-29` → `29/07/2026`. */
export function partoPrevisto(perfil: Perfil): string {
  const data = perfil.dataPrevistaParto.trim();
  if (data === '') return '';

  const [ano, mes, dia] = data.split('-');
  return ano !== undefined && mes !== undefined && dia !== undefined
    ? `${dia}/${mes}/${ano}`
    : data;
}

const UM_DIA = 86_400_000;

/** Quando o DPA foi assinado e quantos dias faltam para renovar (anual). */
export function renovacaoDpa(perfil: Perfil): { data: string; dias: number } | null {
  if (perfil.dpaAssinadoEmEpoch === 0) return null;

  const renovacao = perfil.dpaAssinadoEmEpoch + 365 * UM_DIA;
  return {
    data: new Date(perfil.dpaAssinadoEmEpoch).toLocaleDateString('pt-BR'),
    dias: Math.ceil((renovacao - Date.now()) / UM_DIA),
  };
}
