/**
 * Rolagem automática do "modo apresentação" e leitura em voz alta — porte de
 * `apresentacao.js` do legado.
 *
 * São dois recursos independentes e é assim que o usuário os usa: apresentar
 * sem som (ler do próprio texto rolando) ou ouvir sem apresentar. O módulo
 * mantém os dois separados, como no original.
 */

/** Pixels por quadro (~16 ms) em cada nível: 1 lenta, 2 média, 3 rápida. */
export const NIVEIS_VELOCIDADE = [0.3, 0.6, 1.2] as const;

export function pxPorNivel(nivel: number): number {
  return NIVEIS_VELOCIDADE[nivel - 1] ?? NIVEIS_VELOCIDADE[1];
}

/** O que a rolagem consulta a cada quadro. */
export interface EstadoDaRolagem {
  readonly ativo: boolean;
  readonly pausado: boolean;
  readonly nivel: number;
}

/**
 * Rola um elemento sozinho. `estado()` é lido a cada quadro — assim quem chamou
 * controla o laço só mexendo no próprio estado, sem precisar reiniciar nada.
 * Devolve a função que cancela.
 */
export function iniciarRolagem(el: HTMLElement, estado: () => EstadoDaRolagem): () => void {
  let quadro = requestAnimationFrame(function passo() {
    const { ativo, pausado, nivel } = estado();
    if (!ativo) return;
    if (!pausado) el.scrollTop += pxPorNivel(nivel);
    quadro = requestAnimationFrame(passo);
  });

  return () => cancelAnimationFrame(quadro);
}

// ── Leitura em voz alta ─────────────────────────────────────────────────────

export function ttsDisponivel(): boolean {
  return typeof speechSynthesis !== 'undefined';
}

/**
 * Lê um texto em voz alta, em pt-BR. `aoFim` dispara tanto no fim normal quanto
 * no erro: quem chamou sempre volta ao estado "não está falando".
 */
export function falar(texto: string, aoFim?: () => void): void {
  if (!ttsDisponivel()) {
    aoFim?.();
    return;
  }

  const fala = new SpeechSynthesisUtterance(texto);
  fala.lang = 'pt-BR';
  fala.rate = 0.9;
  fala.onend = () => aoFim?.();
  fala.onerror = () => aoFim?.();

  speechSynthesis.cancel();
  speechSynthesis.speak(fala);
}

export function pausarFala(): void {
  if (ttsDisponivel()) speechSynthesis.pause();
}

export function retomarFala(): void {
  if (ttsDisponivel()) speechSynthesis.resume();
}

export function pararFala(): void {
  if (ttsDisponivel()) speechSynthesis.cancel();
}
