/**
 * As duas telas que aparecem quando a rota não leva a um módulo pronto:
 * "em breve" (o módulo existe, mas ainda não foi migrado) e "não encontrado"
 * (o endereço não corresponde a nada).
 */

import { html, type TemplateResult } from 'lit';
import type { Modulo } from '../app/modulos.ts';
import { navegar } from '../app/rotas.ts';
import { S } from '../strings.ts';

export function emBreve(m: Modulo): TemplateResult {
  return html`
    <div class="aviso">
      <st-icon class="aviso__icone" style="color: ${m.cor}" name=${m.icone}></st-icon>
      <h2>${S.emBreve.titulo}</h2>
      <p>${S.emBreve.texto(m.rotulo)}</p>
      <p class="discreto">${S.emBreve.ajuda}</p>
      <st-button variant="primary" @click=${() => navegar('home')}>
        ${S.emBreve.voltar}
      </st-button>
    </div>
  `;
}

export function naoEncontrado(): TemplateResult {
  return html`
    <div class="aviso">
      <st-icon class="aviso__icone" name="map-question"></st-icon>
      <h2>${S.erro.naoEncontrado}</h2>
      <p>${S.erro.naoEncontradoTexto}</p>
      <st-button variant="primary" @click=${() => navegar('home')}>
        ${S.emBreve.voltar}
      </st-button>
    </div>
  `;
}
