/**
 * A tela da Poesia — porte de `modulos/poesia/poesia.js` e da seção
 * correspondente do `index.html` do legado.
 *
 * Mesmas três vistas das Guias (lista, leitura, editor) com o que é próprio da
 * Poesia: favoritos, o aviso sobre o acervo, a navegação sequencial entre as
 * curadas e a barra de progresso da leitura.
 *
 * A barra de progresso deixou de ser JS. O legado calculava o percentual num
 * `@scroll` e reatribuía a largura a cada quadro; aqui ela é uma animação
 * dirigida pela rolagem (`animation-timeline: scroll()`), o que evita redesenhar
 * o app inteiro a cada pixel — nesta arquitetura, um estado que muda no scroll
 * custaria um `render()` da casca por evento.
 */

import type StEditor from '@marinx/stratum/components/editor/editor.js';
import { sanitizeHtml } from '@marinx/stratum/components/editor/editor.js';
import { html, nothing, type TemplateResult } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { alternarFavorito, chaveFavorito, lerFavoritos } from '../../favoritos.ts';
import { S } from '../../strings.ts';
import { dataHora, textoLimpo } from '../../texto.ts';
import { compartilhar } from '../../ui/compartilhar.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { Leitura } from '../../ui/leitura.ts';
import { notificar } from '../../ui/notificar.ts';
import { type ComOrigem, semTexto } from '../acervo.ts';
import {
  CHAVE_FAVORITOS,
  conteudoSemImagem,
  excluirPoesia,
  listarPoesias,
  obterPoesia,
  type Poesia,
  salvarPoesia,
  textoDoCartao,
} from './dados.ts';

const ESPERA_BUSCA_MS = 400;
const ESPERA_SALVAR_MS = 1200;

interface Edicao {
  id: number | null;
  titulo: string;
  conteudo: string;
  status: string;
}

let lista: ComOrigem<Poesia>[] = [];
let busca = '';
let favoritos = new Set<string>();
let favoritosCarregados = false;
let avisoAberto = false;

let aberta: Poesia | null = null;
let abertaLocal = false;

let edicao: Edicao | null = null;

let carregada: string | undefined;
let carregando = false;

let timerBusca: ReturnType<typeof setTimeout> | undefined;
let timerSalvar: ReturnType<typeof setTimeout> | undefined;

const leitura = new Leitura();

function editorNoDocumento(): StEditor | null {
  return document.querySelector('st-editor');
}

/**
 * Impõe o conteúdo ao editor que está no documento.
 *
 * Atribuir `value` é o que troca o texto inteiro; o componente ignora a
 * atribuição quando o valor é o mesmo que já está lá, e é isso que impede o
 * cursor de voltar ao começo a cada redesenho da tela.
 */
function atribuirAoEditor(conteudo: string): void {
  const editor = editorNoDocumento();
  if (editor !== null) editor.value = conteudo;
}

// ── Favoritos ───────────────────────────────────────────────────────────────

function chave(poesia: Poesia, local: boolean): string {
  return chaveFavorito(local ? 'local' : 'curado', poesia.id);
}

function eFavorita(poesia: Poesia, local: boolean): boolean {
  return favoritos.has(chave(poesia, local));
}

async function alternar(poesia: Poesia, local: boolean): Promise<void> {
  favoritos = alternarFavorito(CHAVE_FAVORITOS, favoritos, chave(poesia, local));
  // Na lista a estrela também muda a ordem (favoritas no topo), então recarrega.
  if (aberta === null) await recarregarLista();
  else atualizar();
}

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregarLista(): Promise<void> {
  lista = await listarPoesias(busca, (poesia) => eFavorita(poesia, poesia.local));
  atualizar();
}

async function abrirLeitura(id: number, local: boolean): Promise<void> {
  abertaLocal = local;
  aberta = (await obterPoesia(id, local)) ?? null;
  if (aberta === null) navegar('poesia');
}

async function abrirEditor(id: number | null): Promise<void> {
  if (id === null) {
    edicao = { id: null, titulo: '', conteudo: '', status: '' };
  } else {
    const poesia = await obterPoesia(id, true);
    if (poesia === undefined) {
      navegar('poesia');
      return;
    }
    edicao = {
      id: poesia.id ?? null,
      titulo: poesia.titulo,
      conteudo: poesia.conteudo,
      status: '',
    };
  }

  atualizar();
  atribuirAoEditor(edicao.conteudo);
}

function sincronizar(rota: Rota): void {
  const chaveRota = rota.args.join('/');
  if (carregada === chaveRota || carregando) return;

  carregada = chaveRota;
  carregando = true;
  leitura.fechar();

  if (!favoritosCarregados) {
    favoritos = lerFavoritos(CHAVE_FAVORITOS);
    favoritosCarregados = true;
  }

  void (async () => {
    try {
      const [primeiro, segundo] = rota.args;

      if (primeiro === undefined) {
        aberta = null;
        edicao = null;
        await recarregarLista();
      } else if (primeiro === 'nova') {
        aberta = null;
        await abrirEditor(null);
      } else if (primeiro === 'editar') {
        aberta = null;
        await abrirEditor(Number.parseInt(segundo ?? '', 10));
      } else if (primeiro === 'local') {
        edicao = null;
        await abrirLeitura(Number.parseInt(segundo ?? '', 10), true);
      } else {
        edicao = null;
        await abrirLeitura(Number.parseInt(primeiro, 10), false);
      }
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Lista ───────────────────────────────────────────────────────────────────

function aoBuscar(texto: string): void {
  busca = texto;
  clearTimeout(timerBusca);
  timerBusca = setTimeout(() => void recarregarLista(), ESPERA_BUSCA_MS);
}

function cartao(poesia: ComOrigem<Poesia>): TemplateResult {
  const favorita = eFavorita(poesia, poesia.local);

  return html`
    <div class="cartao cartao--com-acao" ?data-favorito=${favorita}>
      <button
        class="cartao__alvo"
        @click=${() =>
          navegar(poesia.local ? `poesia/local/${poesia.id ?? ''}` : `poesia/${poesia.id ?? ''}`)}
      >
        <span class="cartao__topo">
          <st-badge variant="neutral" pill>${S.poesia.referencia(poesia.id)}</st-badge>
          <span class="cartao__titulo cartao__titulo--serif">
            ${poesia.titulo || S.acervo.semTitulo}
          </span>
          ${
            poesia.local
              ? html`<st-badge variant="success" pill>${S.acervo.meu}</st-badge>`
              : nothing
          }
        </span>
        <span class="cartao__previa">${textoDoCartao(poesia)}</span>
      </button>

      <st-icon-button
        class="cartao__estrela"
        name="star"
        variant=${favorita ? 'filled' : 'outline'}
        label=${favorita ? S.poesia.desfavoritar : S.poesia.favoritar}
        @click=${() => void alternar(poesia, poesia.local)}
      ></st-icon-button>
    </div>
  `;
}

function telaDaLista(): TemplateResult {
  return html`
    ${
      avisoAberto
        ? html`
          <st-alert open variant="primary" class="aviso-acervo">
            <st-icon slot="icon" name="info-circle"></st-icon>
            ${S.poesia.aviso.map((paragrafo) => html`<p>${paragrafo}</p>`)}
          </st-alert>
        `
        : nothing
    }

    <div class="filtros">
      <st-input
        class="filtros__busca"
        type="search"
        clearable
        placeholder=${S.poesia.buscar}
        .value=${busca}
        @st-input=${(evento: Event) => aoBuscar((evento.target as HTMLInputElement).value)}
      >
        <st-icon slot="prefix" name="search"></st-icon>
      </st-input>
    </div>

    ${
      lista.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="feather"></st-icon>
            <p>${S.poesia.vazio}</p>
          </div>
        `
        : html`<div class="cartoes cartoes--duas">${lista.map((poesia) => cartao(poesia))}</div>`
    }
  `;
}

// ── Leitura ─────────────────────────────────────────────────────────────────

function textoDaPoesia(poesia: Poesia): string {
  return `${poesia.titulo}. ${conteudoSemImagem(poesia)}`;
}

function corpo(poesia: Poesia): TemplateResult {
  return html`
    <div class="prosa prosa--verso">${unsafeHTML(sanitizeHtml(conteudoSemImagem(poesia)))}</div>
  `;
}

function telaDaLeitura(poesia: Poesia): TemplateResult {
  return html`
    <div class="progresso" aria-hidden="true"><div class="progresso__barra"></div></div>

    ${corpo(poesia)}

    ${
      // Navegação sequencial: só o acervo curado tem vizinhos (o export do admin
      // os injeta pela ordem de publicação).
      abertaLocal
        ? nothing
        : html`
          <nav class="sequencia">
            <st-button
              size="small"
              ?disabled=${!poesia.anteriorId}
              @click=${() => navegar(`poesia/${poesia.anteriorId ?? ''}`)}
            >
              <st-icon slot="prefix" name="chevron-left"></st-icon>${S.poesia.anterior}
            </st-button>
            <st-button
              size="small"
              ?disabled=${!poesia.proximoId}
              @click=${() => navegar(`poesia/${poesia.proximoId ?? ''}`)}
            >
              ${S.poesia.proxima}<st-icon slot="suffix" name="chevron-right"></st-icon>
            </st-button>
          </nav>
        `
    }

    ${leitura.overlay(
      html`
          <h1 class="titulo--serif">${poesia.titulo}</h1>
          ${corpo(poesia)}
        `,
      () => textoDaPoesia(poesia),
    )}
  `;
}

async function excluirAtual(): Promise<void> {
  const id = aberta?.id;
  if (id === undefined || !abertaLocal) return;

  const ok = await confirmar({
    titulo: S.poesia.excluir,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await excluirPoesia(id);
  notificar(S.poesia.excluida);
  navegar('poesia');
}

// ── Editor ──────────────────────────────────────────────────────────────────

function agendarSalvar(): void {
  if (edicao === null) return;
  edicao = { ...edicao, status: S.acervo.salvando };
  atualizar();

  clearTimeout(timerSalvar);
  timerSalvar = setTimeout(() => void salvar(), ESPERA_SALVAR_MS);
}

async function salvar(): Promise<void> {
  if (edicao === null) return;

  if (edicao.titulo.trim() === '' || semTexto(edicao.conteudo)) {
    edicao = { ...edicao, status: S.acervo.tituloEConteudo };
    atualizar();
    return;
  }

  const agora = Date.now();
  const registro: Poesia = {
    titulo: edicao.titulo,
    conteudo: edicao.conteudo,
    publicar: 0,
    data_atualizacao: agora,
    ...(edicao.id === null ? { data_criacao: agora } : { id: edicao.id }),
  };

  const id = await salvarPoesia(registro);

  if (edicao.id === null) {
    edicao = { ...edicao, id };
    history.replaceState(null, '', `#/poesia/editar/${id}`);
  }

  edicao = { ...edicao, status: S.acervo.salvoAs(dataHora(agora)) };
  atualizar();
}

function telaDoEditor(estado: Edicao): TemplateResult {
  return html`
    <div class="editor">
      <st-input
        class="editor__titulo editor__titulo--serif"
        placeholder=${S.poesia.tituloPlaceholder}
        .value=${estado.titulo}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, titulo: (evento.target as HTMLInputElement).value };
          agendarSalvar();
        }}
      ></st-input>

      <div class="editor__linha">
        <span class="editor__status">${estado.status}</span>
      </div>

      <st-editor
        @st-input=${(evento: CustomEvent<{ value: string }>) => {
          edicao = { ...estado, conteudo: evento.detail.value };
          agendarSalvar();
        }}
      ></st-editor>
    </div>
  `;
}

// ── A tela ──────────────────────────────────────────────────────────────────

function acoesDaLista(): TemplateResult {
  return html`
    <st-icon-button
      name="info-circle"
      label=${S.poesia.sobre}
      @click=${() => {
        avisoAberto = !avisoAberto;
        atualizar();
      }}
    ></st-icon-button>
    <st-icon-button
      name="plus"
      label=${S.poesia.nova}
      @click=${() => navegar('poesia/nova')}
    ></st-icon-button>
  `;
}

function acoesDaLeitura(poesia: Poesia): TemplateResult {
  const favorita = eFavorita(poesia, abertaLocal);

  return html`
    <st-icon-button
      name="star"
      variant=${favorita ? 'filled' : 'outline'}
      label=${favorita ? S.poesia.desfavoritar : S.poesia.favoritar}
      @click=${() => void alternar(poesia, abertaLocal)}
    ></st-icon-button>
    ${leitura.botaoApresentar()}
    ${leitura.botaoFala(() => textoDaPoesia(poesia))}
    <st-icon-button
      name="share"
      label=${S.leitura.compartilhar}
      @click=${() => void compartilhar(poesia.titulo, textoLimpo(conteudoSemImagem(poesia)))}
    ></st-icon-button>
    ${
      abertaLocal
        ? html`
          <st-icon-button
            name="pencil"
            label=${S.acoes.editar}
            @click=${() => navegar(`poesia/editar/${poesia.id ?? ''}`)}
          ></st-icon-button>
          <st-icon-button
            name="trash"
            label=${S.poesia.excluir}
            @click=${() => void excluirAtual()}
          ></st-icon-button>
        `
        : nothing
    }
  `;
}

export const telaPoesia: Tela = {
  voltarPara(rota) {
    // A Poesia é acessada de dentro do hub "Meu Estudo Pessoal"; a lista volta
    // para lá, e as sub-vistas para a lista.
    return rota.args.length === 0 ? 'hub/estudo' : 'poesia';
  },

  titulo(rota) {
    const [primeiro] = rota.args;
    if (primeiro === undefined) return undefined;
    if (primeiro === 'nova' || primeiro === 'editar') {
      const titulo = edicao?.titulo.trim() ?? '';
      return titulo === '' ? S.poesia.novaTitulo : titulo;
    }
    return aberta?.titulo;
  },

  acoes(rota) {
    const [primeiro] = rota.args;
    if (primeiro === undefined) return acoesDaLista();
    if (primeiro === 'nova' || primeiro === 'editar') return undefined;
    return aberta === null ? undefined : acoesDaLeitura(aberta);
  },

  conteudo(rota) {
    sincronizar(rota);

    const [primeiro] = rota.args;
    if (primeiro === undefined) return telaDaLista();

    if (primeiro === 'nova' || primeiro === 'editar') {
      return edicao === null
        ? html`<div class="carregando"><st-spinner></st-spinner></div>`
        : telaDoEditor(edicao);
    }

    return aberta === null
      ? html`<div class="carregando"><st-spinner></st-spinner></div>`
      : telaDaLeitura(aberta);
  },
};
