/**
 * A tela do Perfil / ICE — porte de `modulos/perfil/perfil.js` e das três seções
 * (`perfil`, `cartao`, `ice`) do `index.html` legado.
 *
 * Lá as três eram módulos de topo (`#/cartao`, `#/ice`) compartilhando o mesmo
 * componente Alpine; aqui são sub-rotas de `#/perfil` — `#/perfil/cartao` e
 * `#/perfil/ice`. O registro do app tem um módulo só, e é ele que aparece na
 * home; as outras duas são vistas dele, não áreas próprias.
 *
 * A ficha de emergência é a tela que **outra pessoa** vai abrir no seu lugar: ela
 * não pede toque nenhum para revelar o essencial, e o aviso de recusa de sangue
 * vem antes de qualquer outra coisa.
 */

import { html, nothing, type TemplateResult } from 'lit';
import type { Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { dataHora } from '../../texto.ts';
import { compartilhar } from '../../ui/compartilhar.ts';
import {
  carregarPerfil,
  linkWhatsApp,
  PERFIL_VAZIO,
  type Perfil,
  partoPrevisto,
  qrDoCartao,
  renovacaoDpa,
  salvarPerfil,
  TIPOS_SANGUINEOS,
  temFichaIce,
  vCard,
} from './dados.ts';

const ESPERA_SALVAR_MS = 1000;

let perfil: Perfil = { ...PERFIL_VAZIO };
let qr = '';
let status = '';

let carregado = false;
let carregando = false;
let timerSalvar: ReturnType<typeof setTimeout> | undefined;

// ── Carga e gravação ────────────────────────────────────────────────────────

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      perfil = await carregarPerfil();
      qr = await qrDoCartao(perfil);
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

function agendarSalvar(): void {
  status = S.acervo.salvando;
  atualizar();

  clearTimeout(timerSalvar);
  timerSalvar = setTimeout(() => void salvar(), ESPERA_SALVAR_MS);
}

async function salvar(): Promise<void> {
  perfil = await salvarPerfil(perfil);
  qr = await qrDoCartao(perfil);
  status = S.acervo.salvoAs(dataHora(Date.now()));
  atualizar();
}

/** Muda um campo de texto e agenda a gravação. */
function mudar<C extends keyof Perfil>(campo: C, valor: Perfil[C]): void {
  perfil = { ...perfil, [campo]: valor };
  agendarSalvar();
}

function texto(
  campo: keyof Perfil & string,
  rotulo: string,
  tipo: 'text' | 'tel' | 'email' | 'date' = 'text',
): TemplateResult {
  return html`
    <st-input
      type=${tipo}
      label=${rotulo}
      .value=${String(perfil[campo] ?? '')}
      @st-input=${(evento: Event) => mudar(campo, (evento.target as HTMLInputElement).value)}
    ></st-input>
  `;
}

function area(campo: keyof Perfil & string, rotulo: string): TemplateResult {
  return html`
    <st-textarea
      rows="2"
      resize="auto"
      label=${rotulo}
      .value=${String(perfil[campo] ?? '')}
      @st-input=${(evento: Event) => mudar(campo, (evento.target as HTMLTextAreaElement).value)}
    ></st-textarea>
  `;
}

function chave(campo: keyof Perfil & string, rotulo: string): TemplateResult {
  return html`
    <st-switch
      ?checked=${perfil[campo] === 1}
      @st-change=${(evento: Event) =>
        mudar(campo, ((evento.target as HTMLInputElement).checked ? 1 : 0) as never)}
    >
      ${rotulo}
    </st-switch>
  `;
}

// ── Formulário ──────────────────────────────────────────────────────────────

function telaDoFormulario(): TemplateResult {
  return html`
    <div class="formulario">
      <p class="editor__status">${status}</p>

      <h2 class="secao">${S.perfil.cartao}</h2>
      ${texto('nome', S.perfil.nome)}
      ${texto('telefone', S.perfil.telefone, 'tel')}
      ${texto('email', S.perfil.email, 'email')}
      ${texto('link', S.perfil.link)}
      ${texto('comentario', S.perfil.comentario)}

      <h2 class="secao">${S.perfil.secretario}</h2>
      ${texto('nomeSecretario', S.perfil.nome)}
      ${texto('telefoneSecretario', S.perfil.telefone, 'tel')}

      <h2 class="secao">${S.perfil.saude}</h2>
      <st-select
        label=${S.perfil.tipoSanguineo}
        .value=${perfil.tipoSanguineo}
        @st-change=${(evento: Event) =>
          mudar('tipoSanguineo', (evento.target as HTMLInputElement).value)}
      >
        <st-option value="">${S.perfil.selecione}</st-option>
        ${TIPOS_SANGUINEOS.map((tipo) => html`<st-option value=${tipo}>${tipo}</st-option>`)}
      </st-select>
      ${chave('doadorOrgaos', S.perfil.doador)}
      ${texto('alergias', S.perfil.alergias)}
      ${area('medicamentosEmUso', S.perfil.medicamentos)}
      ${area('observacoesMedicas', S.perfil.observacoes)}

      <h2 class="secao">${S.perfil.gestacao}</h2>
      ${chave('gravida', S.perfil.gestante)}
      ${
        perfil.gravida !== 1
          ? nothing
          : html`
            <div class="formulario__par">
              <st-select
                label=${S.perfil.meses}
                .value=${perfil.gravidezMeses}
                @st-change=${(evento: Event) =>
                  mudar('gravidezMeses', (evento.target as HTMLInputElement).value)}
              >
                <st-option value="">—</st-option>
                ${Array.from({ length: 9 }, (_, i) => i + 1).map(
                  (mes) => html`<st-option value=${String(mes)}>${S.perfil.mes(mes)}</st-option>`,
                )}
              </st-select>
              ${texto('dataPrevistaParto', S.perfil.parto, 'date')}
            </div>
          `
      }

      <h2 class="secao">${S.perfil.dpa}</h2>
      ${chave('recusaTransfusao', S.perfil.recusa)}
      ${
        perfil.recusaTransfusao !== 1
          ? nothing
          : html`
            <st-alert open variant="danger">
              <st-icon slot="icon" name="alert-octagon"></st-icon>
              <strong>${S.perfil.naoApliqueSangue}</strong>
            </st-alert>
          `
      }
      ${area('fracoesAceitas', S.perfil.fracoes)}
      ${texto('uriScanDpa', S.perfil.scanDpa)}
      ${chave('dpaCategoriaAtualizado', S.perfil.dpaAssinado)}

      <h2 class="secao">${S.perfil.emergencia}</h2>
      ${texto('contatoEmergencia', S.perfil.contatoNome)}
      ${texto('contatoEmergenciaTelefone', S.perfil.contatoTelefone, 'tel')}

      <h2 class="secao">${S.perfil.colih}</h2>
      ${texto('nomeColih', S.perfil.contatoNome)}
      ${texto('telefoneColih', S.perfil.contatoTelefone, 'tel')}

      <h2 class="secao">${S.perfil.identificacao}</h2>
      ${texto('cartaoSusNumero', S.perfil.sus)}
      ${texto('cpfTitular', S.perfil.cpf)}
      ${texto('upaReferencia', S.perfil.upa)}
    </div>
  `;
}

// ── Cartão de contato ───────────────────────────────────────────────────────

function telaDoCartao(): TemplateResult {
  const whats = linkWhatsApp(perfil);

  return html`
    <div class="cartao-contato">
      <h2 class="cartao-contato__nome">${perfil.nome || S.perfil.semNome}</h2>
      <p class="cartao-contato__telefone">${perfil.telefone}</p>

      ${
        qr === ''
          ? html`
            <div class="vazio">
              <st-icon class="vazio__icone" name="qrcode"></st-icon>
              <p>${S.perfil.semCartao}</p>
            </div>
          `
          : html`<img class="cartao-contato__qr" src=${qr} alt=${S.perfil.qrAlt} />`
      }

      ${
        perfil.comentario === ''
          ? nothing
          : html`<p class="cartao-contato__nota">${perfil.comentario}</p>`
      }

      ${
        qr === ''
          ? nothing
          : html`
            <div class="cartao-contato__acoes">
              ${
                whats === ''
                  ? nothing
                  : html`
                    <st-button variant="success" href=${whats} target="_blank">
                      <st-icon slot="prefix" name="brand-whatsapp"></st-icon>WhatsApp
                    </st-button>
                  `
              }
              <st-button
                variant="primary"
                outline
                @click=${() => void compartilhar(perfil.nome || S.perfil.semNome, vCard(perfil))}
              >
                <st-icon slot="prefix" name="share"></st-icon>${S.leitura.compartilhar}
              </st-button>
            </div>
          `
      }
    </div>
  `;
}

// ── Ficha de emergência ─────────────────────────────────────────────────────

function dado(rotulo: string, valor: string): TemplateResult | typeof nothing {
  if (valor === '') return nothing;
  return html`
    <div class="ice__dado">
      <span class="ice__rotulo">${rotulo}</span>
      <span class="ice__valor">${valor}</span>
    </div>
  `;
}

function telefone(rotulo: string, nome: string, numero: string): TemplateResult | typeof nothing {
  if (nome === '') return nothing;

  return html`
    <div class="ice__contato">
      <span><strong>${rotulo}</strong> ${nome}</span>
      ${
        numero === ''
          ? nothing
          : html`
            <st-button size="small" variant="success" outline href=${`tel:${numero}`}>
              <st-icon slot="prefix" name="phone"></st-icon>${numero}
            </st-button>
          `
      }
    </div>
  `;
}

function telaDaFicha(): TemplateResult {
  const gestacao = [
    perfil.gravidezMeses === '' ? '' : S.perfil.mesesGestacao(Number(perfil.gravidezMeses)),
    partoPrevisto(perfil) === '' ? '' : S.perfil.partoEm(partoPrevisto(perfil)),
  ]
    .filter((parte) => parte !== '')
    .join(' · ');

  const dpa = renovacaoDpa(perfil);

  return html`
    ${
      perfil.recusaTransfusao !== 1
        ? nothing
        : html`
          <st-alert open variant="danger" class="ice__alerta">
            <st-icon slot="icon" name="alert-octagon"></st-icon>
            <strong>${S.perfil.naoApliqueSangue}</strong>
            <span>${S.perfil.portadorDiretriz}</span>
          </st-alert>
        `
    }

    ${
      perfil.gravida !== 1
        ? nothing
        : html`
          <st-alert open variant="warning" class="ice__alerta">
            <st-icon slot="icon" name="alert-triangle"></st-icon>
            <strong>${S.perfil.gestanteMaiusculo}</strong>
            <span>${gestacao}</span>
          </st-alert>
        `
    }

    ${
      !temFichaIce(perfil)
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="heartbeat"></st-icon>
            <p>${S.perfil.semFicha}</p>
          </div>
        `
        : html`
          <div class="ice">
            <h2 class="ice__nome">${perfil.nome || '—'}</h2>
            <div class="ice__grade">
              ${dado(S.perfil.tipoSanguineo, perfil.tipoSanguineo)}
              ${dado(S.perfil.doador, perfil.doadorOrgaos === 1 ? S.perfil.sim : '')}
              ${dado(S.perfil.alergias, perfil.alergias)}
              ${dado(S.perfil.gestante, perfil.gravida === 1 ? gestacao : '')}
            </div>
            ${dado(S.perfil.medicamentos, perfil.medicamentosEmUso)}
            ${dado(S.perfil.observacoes, perfil.observacoesMedicas)}
            ${dado(S.perfil.fracoes, perfil.fracoesAceitas)}
          </div>

          ${
            perfil.contatoEmergencia === '' && perfil.nomeColih === ''
              ? nothing
              : html`
                <div class="ice">
                  ${telefone(
                    S.perfil.emergencia,
                    perfil.contatoEmergencia,
                    perfil.contatoEmergenciaTelefone,
                  )}
                  ${telefone(S.perfil.colih, perfil.nomeColih, perfil.telefoneColih)}
                </div>
              `
          }

          <div class="ice">
            ${dado(S.perfil.sus, perfil.cartaoSusNumero)}
            ${dado(S.perfil.cpf, perfil.cpfTitular)}
            ${dado(S.perfil.upa, perfil.upaReferencia)}
            ${
              dpa === null
                ? nothing
                : html`
                  <p class="ice__dpa" ?data-vencido=${dpa.dias < 0}>
                    <st-icon name="calendar-check"></st-icon>
                    ${S.perfil.dpaAssinadoEm(dpa.data)}
                    ${dpa.dias < 0 ? S.perfil.dpaVencido : S.perfil.dpaRenovar(dpa.dias)}
                  </p>
                `
            }
          </div>
        `
    }
  `;
}

// ── A tela ──────────────────────────────────────────────────────────────────

export const telaPerfil: Tela = {
  voltarPara(rota) {
    return rota.args.length === 0 ? 'hub/pessoal' : 'perfil';
  },

  titulo(rota) {
    const [vista] = rota.args;
    if (vista === 'cartao') return S.perfil.tituloCartao;
    if (vista === 'ice') return S.perfil.tituloFicha;
    return undefined;
  },

  // Sem `acoes`: os botões do cartão e da ficha subiram para a casca na Leva 4.2
  // e agora são permanentes, em toda tela. Repeti-los aqui daria dois pares de
  // ícones idênticos lado a lado no cabeçalho do Perfil.

  conteudo(rota: Rota) {
    carregar();
    if (!carregado) return html`<div class="carregando"><st-spinner></st-spinner></div>`;

    const [vista] = rota.args;
    if (vista === 'cartao') return telaDoCartao();
    if (vista === 'ice') return telaDaFicha();
    return telaDoFormulario();
  },
};
