/**
 * A tela do Modo Estudo — porte de `modulos/estudo/estudo.js` e da seção
 * correspondente do `index.html` legado.
 *
 * O fluxo do original, em quatro passos: escolher (`#/estudo`) → orar → cronômetro
 * → pérola. Os três últimos não são rotas: uma sessão em andamento não pode ser
 * "navegada para fora" pelo botão de voltar do navegador, e no legado eram
 * igualmente sub-vistas de estado. O histórico, sim, é rota (`#/estudo/historico`).
 *
 * O anel do cronômetro é SVG, e não um gráfico: é um arco só, e uma dependência
 * de desenho para ele seria peso sem retorno.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { notificar } from '../../ui/notificar.ts';
import {
  ALVOS_MIN,
  emojiDoTipo,
  excluirSessao,
  horasEMinutos,
  listarSessoes,
  ordenar,
  perolaComoAnotacao,
  perolaNoCaderno,
  relogio,
  rotuloDoTipo,
  type Sessao,
  salvarSessao,
  TIPOS,
  totalDeMinutos,
} from './dados.ts';

/** Onde a sessão está. Só `inicio` e `historico` correspondem a rotas. */
type Passo = 'inicio' | 'oracao' | 'cronometro' | 'perola';

const RAIO = 90;
const CIRCUNFERENCIA = 2 * Math.PI * RAIO;

let passo: Passo = 'inicio';
let tipo = 'pessoal';
let assunto = '';
let alvoMin = 30;

let rodando = false;
let decorridoSeg = 0;
let acumuladoSeg = 0;
let inicioMs = 0;
let intervalo: ReturnType<typeof setInterval> | undefined;

let nota = '';
let sessaoSalva: Sessao | null = null;
let anotacaoCriada = false;
let cadernoSalvo = false;

let sessoes: Sessao[] = [];
let carregado = false;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregar(): Promise<void> {
  sessoes = await listarSessoes();
  atualizar();
}

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      await recarregar();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Cronômetro ──────────────────────────────────────────────────────────────

/**
 * Retoma a contagem. O decorrido é sempre `acumulado + (agora − início)`: contar
 * ticks de um `setInterval` atrasaria a cada vez que a aba perdesse prioridade.
 */
function retomar(): void {
  rodando = true;
  inicioMs = Date.now();

  clearInterval(intervalo);
  intervalo = setInterval(() => {
    decorridoSeg = acumuladoSeg + Math.floor((Date.now() - inicioMs) / 1000);
    atualizar();
  }, 250);

  atualizar();
}

function pausar(): void {
  if (!rodando) return;

  acumuladoSeg += Math.floor((Date.now() - inicioMs) / 1000);
  decorridoSeg = acumuladoSeg;
  rodando = false;
  clearInterval(intervalo);
  intervalo = undefined;
  atualizar();
}

function fracaoDoAlvo(): number {
  const alvoSeg = alvoMin * 60;
  return alvoSeg <= 0 ? 0 : Math.min(1, decorridoSeg / alvoSeg);
}

function duracaoMin(): number {
  return Math.max(0, Math.round(decorridoSeg / 60));
}

// ── Passos ──────────────────────────────────────────────────────────────────

function comecar(): void {
  passo = 'oracao';
  atualizar();
}

function confirmarOracao(): void {
  decorridoSeg = 0;
  acumuladoSeg = 0;
  nota = '';
  sessaoSalva = null;
  anotacaoCriada = false;
  cadernoSalvo = false;
  passo = 'cronometro';
  retomar();
}

function encerrar(): void {
  pausar();
  passo = 'perola';
  atualizar();
}

async function gravarSessao(): Promise<Sessao> {
  const registro: Sessao = {
    ...(sessaoSalva?.id === undefined ? {} : { id: sessaoSalva.id }),
    assunto: assunto === '' ? S.estudo.semAssunto : assunto,
    tipo_ciclo: tipo,
    duracao_minutos: duracaoMin(),
    concluido_em: Date.now(),
    nota_meditacao: nota,
    anotacao_criada: anotacaoCriada ? 1 : 0,
  };

  const id = await salvarSessao(registro);
  sessaoSalva = { ...registro, id };
  await recarregar();
  return sessaoSalva;
}

async function concluir(): Promise<void> {
  if (sessaoSalva === null) await gravarSessao();
  assunto = '';
  passo = 'inicio';
  navegar('estudo/historico');
}

function descartar(): void {
  clearInterval(intervalo);
  intervalo = undefined;
  rodando = false;
  assunto = '';
  decorridoSeg = 0;
  acumuladoSeg = 0;
  passo = 'inicio';
  atualizar();
}

// ── Vistas ──────────────────────────────────────────────────────────────────

function telaDoInicio(): TemplateResult {
  return html`
    <p class="intro">${S.estudo.intro}</p>

    <h2 class="secao">${S.estudo.tipo}</h2>
    <div class="tipos">
      ${Object.entries(TIPOS).map(
        ([chave, valor]) => html`
          <button
            class="tipo"
            ?data-ativo=${tipo === chave}
            @click=${() => {
              tipo = chave;
              atualizar();
            }}
          >
            <span class="tipo__emoji" aria-hidden="true">${valor.emoji}</span>
            <span>${valor.rotulo}</span>
          </button>
        `,
      )}
    </div>

    <st-input
      label=${S.estudo.assunto}
      placeholder=${S.estudo.assuntoPlaceholder}
      .value=${assunto}
      @st-input=${(evento: Event) => {
        assunto = (evento.target as HTMLInputElement).value;
      }}
    ></st-input>

    <h2 class="secao">${S.estudo.alvo}</h2>
    <div class="chips">
      ${ALVOS_MIN.map(
        (minutos) => html`
          <button
            class="chip"
            ?data-ativo=${alvoMin === minutos}
            @click=${() => {
              alvoMin = minutos;
              atualizar();
            }}
          >
            ${S.estudo.minutos(minutos)}
          </button>
        `,
      )}
    </div>

    <div class="editor__acoes">
      <st-button variant="primary" size="large" @click=${comecar}>
        <st-icon slot="prefix" name="player-play"></st-icon>${S.estudo.comecar}
      </st-button>
    </div>
  `;
}

function telaDaOracao(): TemplateResult {
  return html`
    <div class="oracao">
      <st-icon class="oracao__icone" name="hand-stop"></st-icon>
      <h2>${S.estudo.oracaoTitulo}</h2>
      <p>${S.estudo.oracaoTexto}</p>

      <div class="editor__acoes">
        <st-button variant="primary" @click=${confirmarOracao}>${S.estudo.orei}</st-button>
        <st-button
          @click=${() => {
            passo = 'inicio';
            atualizar();
          }}
        >
          ${S.acoes.cancelar}
        </st-button>
      </div>
    </div>
  `;
}

function telaDoCronometro(): TemplateResult {
  const fracao = fracaoDoAlvo();
  const atingiu = decorridoSeg >= alvoMin * 60;

  return html`
    <div class="cronometro">
      <svg class="cronometro__anel" viewBox="0 0 200 200" aria-hidden="true">
        <circle class="cronometro__trilho" cx="100" cy="100" r=${RAIO}></circle>
        <circle
          class="cronometro__arco"
          cx="100"
          cy="100"
          r=${RAIO}
          ?data-completo=${atingiu}
          stroke-dasharray=${CIRCUNFERENCIA}
          stroke-dashoffset=${CIRCUNFERENCIA * (1 - fracao)}
        ></circle>
      </svg>

      <div class="cronometro__centro">
        <span class="cronometro__tempo">${relogio(decorridoSeg)}</span>
        <span class="cronometro__alvo">${S.estudo.de(alvoMin)}</span>
      </div>
    </div>

    <p class="cronometro__assunto">
      ${emojiDoTipo(tipo)} ${assunto === '' ? rotuloDoTipo(tipo) : assunto}
    </p>

    ${
      atingiu
        ? html`
          <st-alert open variant="success">
            <st-icon slot="icon" name="circle-check"></st-icon>${S.estudo.alvoAtingido}
          </st-alert>
        `
        : nothing
    }

    <div class="editor__acoes">
      <st-button variant="primary" @click=${() => (rodando ? pausar() : retomar())}>
        <st-icon slot="prefix" name=${rodando ? 'player-pause' : 'player-play'}></st-icon>
        ${rodando ? S.leitura.pausar : S.leitura.continuar}
      </st-button>
      <st-button variant="success" outline @click=${encerrar}>
        <st-icon slot="prefix" name="flag"></st-icon>${S.estudo.encerrar}
      </st-button>
      <st-button variant="danger" outline @click=${descartar}>${S.estudo.descartar}</st-button>
    </div>
  `;
}

function telaDaPerola(): TemplateResult {
  return html`
    <p class="intro">${S.estudo.perolaIntro(duracaoMin())}</p>

    <st-textarea
      rows="5"
      resize="auto"
      label=${S.estudo.perola}
      placeholder=${S.estudo.perolaPlaceholder}
      .value=${nota}
      @st-input=${(evento: Event) => {
        nota = (evento.target as HTMLTextAreaElement).value;
        atualizar();
      }}
    ></st-textarea>

    <div class="editor__acoes">
      <st-button
        ?disabled=${nota.trim() === '' || anotacaoCriada}
        @click=${async () => {
          const sessao = sessaoSalva ?? (await gravarSessao());
          await perolaComoAnotacao({ ...sessao, nota_meditacao: nota });
          anotacaoCriada = true;
          notificar(S.estudo.viraAnotacaoFeito);
          await recarregar();
        }}
      >
        <st-icon slot="prefix" name="notes"></st-icon>
        ${anotacaoCriada ? S.estudo.viraAnotacaoFeito : S.estudo.viraAnotacao}
      </st-button>

      <st-button
        ?disabled=${nota.trim() === '' || cadernoSalvo}
        @click=${async () => {
          const sessao = sessaoSalva ?? (await gravarSessao());
          await perolaNoCaderno({ ...sessao, nota_meditacao: nota });
          cadernoSalvo = true;
          notificar(S.estudo.vaiCadernoFeito);
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="book-2"></st-icon>
        ${cadernoSalvo ? S.estudo.vaiCadernoFeito : S.estudo.vaiCaderno}
      </st-button>
    </div>

    <div class="editor__acoes">
      <st-button variant="primary" @click=${() => void concluir()}>
        <st-icon slot="prefix" name="check"></st-icon>${S.estudo.salvarSessao}
      </st-button>
      <st-button variant="danger" outline @click=${descartar}>${S.estudo.descartar}</st-button>
    </div>
  `;
}

function telaDoHistorico(): TemplateResult {
  const lista = ordenar(sessoes);
  const minutos = totalDeMinutos(sessoes);

  return html`
    <p class="intro">${S.estudo.totais(lista.length, horasEMinutos(minutos))}</p>

    ${
      lista.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="hourglass"></st-icon>
            <p>${S.estudo.semSessoes}</p>
          </div>
        `
        : html`
          <div class="cartoes cartoes--duas">
            ${lista.map(
              (sessao) => html`
                <div class="cartao cartao--parado">
                  <span class="cartao__topo">
                    <span class="cartao__emoji" aria-hidden="true">
                      ${emojiDoTipo(sessao.tipo_ciclo)}
                    </span>
                    <span class="cartao__titulo">${sessao.assunto}</span>
                    <st-badge variant="neutral" pill>
                      ${S.estudo.minutos(sessao.duracao_minutos)}
                    </st-badge>
                  </span>

                  <span class="cartao__referencia">
                    ${rotuloDoTipo(sessao.tipo_ciclo)} ·
                    ${new Date(sessao.concluido_em).toLocaleString('pt-BR', {
                      dateStyle: 'short',
                      timeStyle: 'short',
                    })}
                  </span>

                  ${
                    sessao.nota_meditacao === ''
                      ? nothing
                      : html`<p class="cartao__texto">${sessao.nota_meditacao}</p>`
                  }

                  <span class="cartao__rodape">
                    ${
                      sessao.nota_meditacao.trim() === '' || sessao.anotacao_criada === 1
                        ? nothing
                        : html`
                          <st-button
                            size="small"
                            @click=${async () => {
                              await perolaComoAnotacao(sessao);
                              await recarregar();
                            }}
                          >
                            <st-icon slot="prefix" name="notes"></st-icon>${S.estudo.viraAnotacao}
                          </st-button>
                        `
                    }
                    <st-button
                      size="small"
                      variant="danger"
                      outline
                      @click=${() => void excluir(sessao)}
                    >
                      <st-icon slot="prefix" name="trash"></st-icon>
                    </st-button>
                  </span>
                </div>
              `,
            )}
          </div>
        `
    }
  `;
}

async function excluir(sessao: Sessao): Promise<void> {
  const ok = await confirmar({
    titulo: S.estudo.excluir,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok || sessao.id === undefined) return;

  await excluirSessao(sessao.id);
  await recarregar();
}

// ── A tela ──────────────────────────────────────────────────────────────────

export const telaEstudo: Tela = {
  voltarPara(rota) {
    return rota.args[0] === 'historico' ? 'estudo' : 'hub/estudo';
  },

  titulo(rota) {
    if (rota.args[0] === 'historico') return S.estudo.historico;
    if (passo === 'oracao') return S.estudo.oracaoTitulo;
    if (passo === 'cronometro') return S.estudo.emSessao;
    if (passo === 'perola') return S.estudo.perola;
    return undefined;
  },

  acoes(rota) {
    // Durante a sessão o cabeçalho não oferece saída lateral: sair é encerrar ou
    // descartar, e os dois estão no corpo, com nome.
    if (passo !== 'inicio' || rota.args[0] === 'historico') return undefined;

    return html`
      <st-icon-button
        name="history"
        label=${S.estudo.historico}
        @click=${() => navegar('estudo/historico')}
      ></st-icon-button>
    `;
  },

  conteudo(rota: Rota) {
    carregar();

    if (rota.args[0] === 'historico') return telaDoHistorico();
    if (passo === 'oracao') return telaDaOracao();
    if (passo === 'cronometro') return telaDoCronometro();
    if (passo === 'perola') return telaDaPerola();
    return telaDoInicio();
  },
};
