/**
 * A tela do Caderno de Estudo — porte de `modulos/caderno/caderno.js` e da seção
 * correspondente do `index.html` do legado.
 *
 * Duas vistas: a lista (`#/caderno`) e o editor (`#/caderno/novo`,
 * `#/caderno/<id>`). No legado a vista era um campo de estado (`vista`) que o
 * hash só influenciava; aqui ela é a própria rota, e por isso o botão de voltar
 * do navegador funciona no meio de uma anotação.
 *
 * O editor é de texto puro, e não o `<st-editor>`: o que se escreve aqui é o
 * que se aprendeu, com as próprias palavras. Formatação não ajuda, e o legado
 * também não a oferecia.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { notificar } from '../../ui/notificar.ts';
import {
  type Anotacao,
  consumirRascunho,
  excluirAnotacao,
  FILTROS_INICIAIS,
  type Filtros,
  filtrar,
  listarAnotacoes,
  ORIGENS,
  type Origem,
  origem,
  salvarAnotacao,
} from './dados.ts';

/** A anotação aberta no editor. */
interface Edicao {
  id: number | null;
  titulo: string;
  conteudo: string;
  origem: Origem;
  referencia: string;
  refChave: string | null;
  criado: number | null;
  aviso: string;
}

let lista: Anotacao[] = [];
let filtros: Filtros = FILTROS_INICIAIS;
let edicao: Edicao | null = null;

let carregada: string | undefined;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregar(): Promise<void> {
  lista = await listarAnotacoes();
  atualizar();
}

function novaEdicao(): Edicao {
  // Outro módulo pode ter deixado um contexto antes de mandar para cá.
  const rascunho = consumirRascunho();

  return {
    id: null,
    titulo: rascunho.titulo ?? '',
    conteudo: rascunho.conteudo ?? '',
    origem: rascunho.origem ?? 'avulso',
    referencia: rascunho.referencia ?? '',
    refChave: rascunho.ref_chave ?? null,
    criado: null,
    aviso: '',
  };
}

function sincronizar(rota: Rota): void {
  const chave = rota.args.join('/');
  if (carregada === chave || carregando) return;

  carregada = chave;
  carregando = true;

  void (async () => {
    try {
      // A lista é recarregada sempre: outra tela desta mesma sessão (Modo
      // Estudo, Língua Pura) pode ter gravado aqui enquanto o usuário estava lá.
      await recarregar();

      const [primeiro] = rota.args;

      if (primeiro === undefined) {
        edicao = null;
      } else if (primeiro === 'novo') {
        edicao = novaEdicao();
      } else {
        const id = Number.parseInt(primeiro, 10);
        const registro = lista.find((item) => item.id === id);

        if (registro === undefined) {
          navegar('caderno');
          return;
        }

        edicao = {
          id: registro.id ?? null,
          titulo: registro.titulo,
          conteudo: registro.conteudo,
          origem: registro.origem,
          referencia: registro.referencia,
          refChave: registro.ref_chave,
          criado: registro.criado,
          aviso: '',
        };
      }
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Lista ───────────────────────────────────────────────────────────────────

function data(ms: number | undefined): string {
  if (ms === undefined || ms === 0) return '—';
  return new Date(ms).toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  });
}

function cartao(anotacao: Anotacao): TemplateResult {
  const marca = origem(anotacao.origem);

  return html`
    <div class="cartao cartao--parado" style=${`--cor:${marca.cor}`}>
      <span class="cartao__topo">
        <span class="cartao__selo">
          <st-icon name=${marca.icone}></st-icon>${marca.rotulo}
        </span>
        <span class="cartao__data">${data(anotacao.atualizado)}</span>
      </span>

      <span class="cartao__titulo">${anotacao.titulo}</span>
      ${
        anotacao.referencia === ''
          ? nothing
          : html`<span class="cartao__referencia">${anotacao.referencia}</span>`
      }
      <p class="cartao__texto">${anotacao.conteudo}</p>

      <span class="cartao__rodape">
        <st-button size="small" @click=${() => navegar(`caderno/${anotacao.id ?? ''}`)}>
          <st-icon slot="prefix" name="pencil"></st-icon>${S.acoes.editar}
        </st-button>
        <st-button
          size="small"
          variant="danger"
          outline
          @click=${() => void excluir(anotacao)}
        >
          <st-icon slot="prefix" name="trash"></st-icon>
        </st-button>
      </span>
    </div>
  `;
}

async function excluir(anotacao: Anotacao): Promise<void> {
  const ok = await confirmar({
    titulo: S.caderno.excluir,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok || anotacao.id === undefined) return;

  await excluirAnotacao(anotacao.id);
  notificar(S.caderno.excluida);
  await recarregar();
}

function telaDaLista(): TemplateResult {
  const filtrada = filtrar(lista, filtros);

  return html`
    <p class="intro">${S.caderno.intro}</p>

    <div class="filtros">
      <st-select
        .value=${filtros.origem}
        @st-change=${(evento: Event) => {
          filtros = { ...filtros, origem: (evento.target as HTMLInputElement).value };
          atualizar();
        }}
      >
        <st-option value="todas">${S.caderno.todasOrigens}</st-option>
        ${Object.entries(ORIGENS).map(
          ([chave, valor]) => html`<st-option value=${chave}>${valor.rotulo}</st-option>`,
        )}
      </st-select>

      <st-input
        class="filtros__busca"
        type="search"
        clearable
        placeholder=${S.caderno.buscar}
        .value=${filtros.busca}
        @st-input=${(evento: Event) => {
          filtros = { ...filtros, busca: (evento.target as HTMLInputElement).value };
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="search"></st-icon>
      </st-input>
    </div>

    ${
      filtrada.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="book-2"></st-icon>
            <p>${lista.length === 0 ? S.caderno.vazio : S.caderno.semFiltro}</p>
          </div>
        `
        : html`<div class="cartoes cartoes--duas">${filtrada.map((item) => cartao(item))}</div>`
    }
  `;
}

// ── Editor ──────────────────────────────────────────────────────────────────

/** Grava a anotação. Sem conteúdo não há anotação — o título é opcional. */
async function salvar(): Promise<void> {
  if (edicao === null) return;

  if (edicao.conteudo.trim() === '') {
    edicao = { ...edicao, aviso: S.caderno.semConteudo };
    atualizar();
    return;
  }

  const agora = Date.now();
  const registro: Anotacao = {
    ...(edicao.id === null ? {} : { id: edicao.id }),
    // Sem título, o rótulo da origem serve de título — como no legado.
    titulo: edicao.titulo.trim() || origem(edicao.origem).rotulo,
    conteudo: edicao.conteudo.trim(),
    origem: edicao.origem,
    referencia: edicao.referencia,
    ref_chave: edicao.refChave,
    criado: edicao.criado ?? agora,
    atualizado: agora,
  };

  await salvarAnotacao(registro);
  notificar(S.caderno.salva);
  navegar('caderno');
}

function telaDoEditor(estado: Edicao): TemplateResult {
  return html`
    <div class="editor">
      <st-select
        label=${S.caderno.origem}
        .value=${estado.origem}
        @st-change=${(evento: Event) => {
          edicao = { ...estado, origem: (evento.target as HTMLInputElement).value as Origem };
          atualizar();
        }}
      >
        ${Object.entries(ORIGENS).map(
          ([chave, valor]) => html`<st-option value=${chave}>${valor.rotulo}</st-option>`,
        )}
      </st-select>

      <st-input
        label=${S.caderno.titulo}
        placeholder=${S.caderno.tituloPlaceholder}
        .value=${estado.titulo}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, titulo: (evento.target as HTMLInputElement).value };
        }}
      ></st-input>

      <st-input
        label=${S.caderno.referencia}
        placeholder=${S.caderno.referenciaPlaceholder}
        .value=${estado.referencia}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, referencia: (evento.target as HTMLInputElement).value };
        }}
      ></st-input>

      <st-textarea
        label=${S.caderno.conteudo}
        rows="6"
        resize="auto"
        placeholder=${S.caderno.conteudoPlaceholder}
        .value=${estado.conteudo}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, conteudo: (evento.target as HTMLTextAreaElement).value };
        }}
      ></st-textarea>

      ${
        estado.aviso === ''
          ? nothing
          : html`
            <st-alert open variant="warning">
              <st-icon slot="icon" name="alert-triangle"></st-icon>${estado.aviso}
            </st-alert>
          `
      }

      <div class="editor__acoes">
        <st-button variant="primary" @click=${() => void salvar()}>
          <st-icon slot="prefix" name="check"></st-icon>${S.acoes.salvar}
        </st-button>
        <st-button @click=${() => navegar('caderno')}>${S.acoes.cancelar}</st-button>
      </div>
    </div>
  `;
}

export const telaCaderno: Tela = {
  voltarPara(rota) {
    // O caderno é acessado pelo hub "Meu Estudo Pessoal", como no legado.
    return rota.args.length === 0 ? 'hub/estudo' : 'caderno';
  },

  titulo(rota) {
    if (rota.args.length === 0) return undefined;
    return edicao?.id === null ? S.caderno.nova : S.caderno.editar;
  },

  acoes(rota) {
    if (rota.args.length > 0) return undefined;

    return html`
      <st-icon-button
        name="plus"
        label=${S.caderno.nova}
        @click=${() => navegar('caderno/novo')}
      ></st-icon-button>
    `;
  },

  conteudo(rota) {
    sincronizar(rota);

    if (rota.args.length === 0) return telaDaLista();
    return edicao === null
      ? html`<div class="carregando"><st-spinner></st-spinner></div>`
      : telaDoEditor(edicao);
  },
};
