/**
 * O painel da home — o resumo que a Fase 3 deixou para o fim.
 *
 * A home nasceu só com os tiles: o resumo de cada módulo dependia de o módulo
 * estar migrado para haver o que contar. Com 16 dos 17 portados, ele entra aqui.
 *
 * **Dinheiro não aparece.** O Financeiro esconde os valores a cada entrada, por
 * decisão de projeto — quem abre o app no ônibus não quer o saldo na tela. Um
 * painel que estampasse o saldo na primeira tela desfaria isso, então o que sai
 * daqui é *contagem* ("2 contas a vencer"), nunca cifra.
 *
 * A carga é preguiçosa e tolerante: cada fonte falha por conta própria e volta
 * vazia. Um store que ainda não existe (banco recém-criado, sincronização que
 * não rodou) não pode derrubar a primeira tela do app.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { migrado } from '../app/modulos.ts';
import { atualizar } from '../app/tela.ts';
import { dataLocalISO, mesLocalISO } from '../datas.ts';
import { S } from '../strings.ts';

/** O que o painel mostra. Tudo derivado; nada é gravado. */
export interface Resumo {
  readonly anotacoes: number;
  readonly eventosHoje: readonly { readonly titulo: string; readonly quando: string }[];
  /** Despesas não pagas com vencimento até hoje. Contagem, nunca valor. */
  readonly contasVencendo: number;
  readonly leituraPercentual: number;
  readonly metasAtivas: number;
  readonly metasConcluidas: number;
  /** Minutos de estudo focado no mês corrente. */
  readonly focoMinutos: number;
  /** Horas de campo no mês corrente, do contador do Ministério. */
  readonly horasDoMes: number;
  readonly receitasFavoritas: number;
}

const VAZIO: Resumo = {
  anotacoes: 0,
  eventosHoje: [],
  contasVencendo: 0,
  leituraPercentual: 0,
  metasAtivas: 0,
  metasConcluidas: 0,
  focoMinutos: 0,
  horasDoMes: 0,
  receitasFavoritas: 0,
};

let resumo: Resumo = VAZIO;
let carregado = false;
let carregando = false;

/**
 * O painel é um retrato: sai de moda assim que a pessoa lança uma despesa ou
 * marca um capítulo. Sair da home o invalida, e voltar o relê — refazer a
 * leitura a cada redesenho seria ir ao banco a cada tecla digitada em qualquer
 * lugar do app.
 */
let precisaRecarregar = true;
let vigiando = false;

function vigiarSaida(): void {
  if (vigiando) return;
  vigiando = true;

  addEventListener('hashchange', () => {
    if (location.hash.replace(/^#\/?/, '').split('/')[0] !== 'home') precisaRecarregar = true;
  });
}

/** Roda uma leitura que pode não ter store do outro lado. */
async function tentar<T>(leitura: () => Promise<T>, reserva: T): Promise<T> {
  try {
    return await leitura();
  } catch {
    return reserva;
  }
}

/**
 * Monta o resumo lendo cada módulo migrado. Os imports são dinâmicos porque o
 * painel não deve arrastar para o pedaço inicial o código de dezesseis telas —
 * ele é a primeira coisa que a pessoa vê, e o número aparece um instante depois.
 */
async function montarResumo(): Promise<Resumo> {
  const hoje = dataLocalISO();
  const mes = mesLocalISO();

  const [anotacoes, agenda, financeiro, leitura, metas, estudo, ministerio, favoritos] =
    await Promise.all([
      tentar(async () => {
        const { FILTROS_INICIAIS, listarAnotacoes } = await import('../modulos/anotacoes/dados.ts');
        return (await listarAnotacoes(FILTROS_INICIAIS)).length;
      }, 0),

      tentar(
        async () => {
          const dados = await import('../modulos/calendario/dados.ts');
          const { eventos, tipos } = await dados.carregar();
          return dados.eventosDoDia(eventos, hoje).map((evento) => ({
            titulo: evento.titulo,
            quando:
              evento.dia_inteiro === 1
                ? S.painel.diaInteiro
                : dados.comoHora(evento.hora_inicio_min),
            cor: dados.corDoTipo(tipos, evento.tipo_id),
          }));
        },
        [] as { titulo: string; quando: string; cor: string }[],
      ),

      tentar(async () => {
        const { carregar, TIPO_DESPESA } = await import('../modulos/financeiro/dados.ts');
        const { transacoes } = await carregar();
        const fimDoDia = new Date(`${hoje}T23:59:59`).getTime();
        return transacoes.filter(
          (t) =>
            t.tipo === TIPO_DESPESA &&
            t.esta_pago !== 1 &&
            t.data_vencimento !== 0 &&
            t.data_vencimento <= fimDoDia,
        ).length;
      }, 0),

      tentar(async () => {
        const { lerLidos, percentualGeral } = await import('../modulos/leitura/dados.ts');
        return percentualGeral(lerLidos());
      }, 0),

      tentar(
        async () => {
          const { listarMetas } = await import('../modulos/metas/dados.ts');
          const lista = await listarMetas();
          return {
            ativas: lista.filter((meta) => meta.esta_concluida !== 1).length,
            concluidas: lista.filter((meta) => meta.esta_concluida === 1).length,
          };
        },
        { ativas: 0, concluidas: 0 },
      ),

      tentar(async () => {
        const { listarSessoes, totalDeMinutos } = await import('../modulos/estudo/dados.ts');
        const sessoes = await listarSessoes();
        return totalDeMinutos(sessoes.filter((sessao) => mesLocalISO(sessao.concluido_em) === mes));
      }, 0),

      tentar(async () => {
        const { carregar } = await import('../modulos/ministerio/dados.ts');
        const { contador } = await carregar();
        return Math.floor(contador.minutos / 60);
      }, 0),

      tentar(async () => {
        const { lerFavoritos } = await import('../favoritos.ts');
        const { CHAVE_FAVORITOS } = await import('../modulos/receitas/dados.ts');
        return lerFavoritos(CHAVE_FAVORITOS).size;
      }, 0),
    ]);

  return {
    anotacoes,
    eventosHoje: agenda,
    contasVencendo: financeiro,
    leituraPercentual: leitura,
    metasAtivas: metas.ativas,
    metasConcluidas: metas.concluidas,
    focoMinutos: estudo,
    horasDoMes: ministerio,
    receitasFavoritas: favoritos,
  };
}

/** Lê o resumo quando ele é a primeira vez ou quando envelheceu. */
export function carregarPainel(): void {
  vigiarSaida();
  if (carregando || !precisaRecarregar) return;

  precisaRecarregar = false;
  carregando = true;

  void (async () => {
    try {
      // Os números velhos ficam na tela até os novos chegarem: trocar por zeros
      // durante a leitura faria o painel piscar a cada volta para a home.
      resumo = await montarResumo();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

/**
 * O resumo de um tile, quando há algo a dizer. Devolve `undefined` para o que
 * ainda não carregou ou não tem número — o tile fica como estava, sem linha
 * vazia ocupando espaço.
 */
export function resumoDoModulo(id: string): string | undefined {
  if (!carregado || !migrado(id)) return undefined;

  if (id === 'anotacoes' && resumo.anotacoes > 0) return S.painel.anotacoes(resumo.anotacoes);
  if (id === 'calendario' && resumo.eventosHoje.length > 0) {
    return S.painel.eventosHoje(resumo.eventosHoje.length);
  }
  if (id === 'financeiro' && resumo.contasVencendo > 0) {
    return S.painel.contasVencendo(resumo.contasVencendo);
  }
  if (id === 'leitura' && resumo.leituraPercentual > 0) {
    return S.painel.leitura(resumo.leituraPercentual);
  }
  if (id === 'metas' && resumo.metasAtivas > 0) return S.painel.metas(resumo.metasAtivas);
  if (id === 'ministerio' && resumo.horasDoMes > 0) return S.painel.horas(resumo.horasDoMes);
  if (id === 'estudo' && resumo.focoMinutos > 0) return S.painel.foco(resumo.focoMinutos);
  if (id === 'receitas' && resumo.receitasFavoritas > 0) {
    return S.painel.favoritas(resumo.receitasFavoritas);
  }

  return undefined;
}

/** O mesmo, para um hub: soma o que os módulos dele têm a dizer. */
export function resumoDoHub(modulos: readonly string[]): string | undefined {
  const linhas = modulos.map((id) => resumoDoModulo(id)).filter((linha) => linha !== undefined);
  return linhas.length === 0 ? undefined : linhas.join(' · ');
}

// ── Desenho ─────────────────────────────────────────────────────────────────

function indicador(valor: string, rotulo: string, icone: string): TemplateResult {
  return html`
    <div class="indicador">
      <st-icon class="indicador__icone" name=${icone}></st-icon>
      <span class="indicador__valor">${valor}</span>
      <span class="indicador__rotulo">${rotulo}</span>
    </div>
  `;
}

/** A agenda de hoje. Sem eventos, uma linha dizendo isso — e não um vazio. */
function hoje(): TemplateResult {
  const data = new Date().toLocaleDateString('pt-BR', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  });

  return html`
    <section class="painel__hoje">
      <header class="painel__topo">
        <span class="painel__data">${data}</span>
        ${
          resumo.contasVencendo === 0
            ? nothing
            : html`
              <st-badge variant="warning" pill>
                ${S.painel.contasVencendo(resumo.contasVencendo)}
              </st-badge>
            `
        }
      </header>

      ${
        resumo.eventosHoje.length === 0
          ? html`<p class="discreto">${S.painel.semEventos}</p>`
          : html`
            <ul class="agenda">
              ${resumo.eventosHoje.map(
                (evento) => html`
                  <li class="agenda__linha">
                    <span class="agenda__hora">${evento.quando}</span>
                    <span class="agenda__titulo">${evento.titulo}</span>
                  </li>
                `,
              )}
            </ul>
          `
      }
    </section>
  `;
}

/** A faixa de números do mês. Só entra quando há o que mostrar. */
function indicadores(): TemplateResult | typeof nothing {
  const itens: readonly (TemplateResult | typeof nothing)[] = [
    resumo.leituraPercentual > 0
      ? indicador(`${resumo.leituraPercentual}%`, S.painel.rotuloLeitura, 'book')
      : nothing,
    resumo.horasDoMes > 0
      ? indicador(String(resumo.horasDoMes), S.painel.rotuloHoras, 'users')
      : nothing,
    resumo.focoMinutos > 0
      ? indicador(S.painel.emHoras(resumo.focoMinutos), S.painel.rotuloFoco, 'hourglass')
      : nothing,
    resumo.metasAtivas + resumo.metasConcluidas > 0
      ? indicador(
          `${resumo.metasConcluidas}/${resumo.metasAtivas + resumo.metasConcluidas}`,
          S.painel.rotuloMetas,
          'target',
        )
      : nothing,
  ];

  const visiveis = itens.filter((item) => item !== nothing);
  if (visiveis.length === 0) return nothing;

  return html`<div class="indicadores">${visiveis}</div>`;
}

/**
 * O painel inteiro. Enquanto a leitura não volta, fica a frase de abertura — o
 * topo da primeira tela não pode piscar vazio esperando o banco.
 */
export function painel(): TemplateResult {
  carregarPainel();
  if (!carregado) return html`<p class="intro">${S.home.sub}</p>`;

  return html`${hoje()} ${indicadores()}`;
}
