export async function carregarViz(nome: string): Promise<FabricaViz | undefined> {
  const carregar = VIZ[nome];
  if (carregar === undefined) return undefined;

  try {
    return (await carregar()).default;
  } catch {
    // Uma cena que não carrega não pode derrubar o puzzle: o resto da tela
    // continua jogável sem ela.
    return undefined;
  }
}
