/**
 * A tela da Leitura da Bíblia — porte da seção `leitura` do `index.html` legado.
 *
 * Um rastreador dos 66 livros (1189 capítulos) com quatro visões, como as visões
 * de um calendário: canônica, cronológica, por escritor e o roteiro da
 * Celebração. A visão escolhida é lembrada entre sessões — é a que aquele leitor
 * usa, não uma preferência a refazer a cada abertura.
 *
 * O livro expandido não vai para a rota: é estado de leitura da lista, e uma
 * volta do navegador deveria sair do módulo, não recolher um acordeão.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { LIVROS, ROTEIRO_CELEBRACAO, TOTAL_CAPITULOS } from './biblia.ts';
import {
  alternarCapitulo,
  alternarDia,
  capituloLido,
  capitulosDe,
  capitulosDoGrupo,
  detalheDoLivro,
  diasLidos,
  type ItemDaLista,
  itensDaVisao,
  type Lidos,
  lerCelebracao,
  lerLidos,
  lerVisao,
  lidosDoGrupo,
  lidosDoLivro,
  livroCompleto,
  livrosConcluidos,
  marcarLivro,
  percentualCelebracao,
  percentualDoLivro,
  percentualGeral,
  salvarVisao,
  totalLidos,
  VISOES,
  type Visao,
} from './dados.ts';

let lidos: Lidos = new Map();
let celebracao: Set<string> = new Set();
let visao: Visao = 'canonica';
let livroAberto: number | null = null;

let carregado = false;

/**
 * O progresso vem do `localStorage`, que é síncrono: dá para carregar no
 * primeiro desenho, sem o vaivém de tela vazia → tela cheia dos módulos que
 * leem o banco.
 */
function carregar(): void {
  if (carregado) return;
  carregado = true;

  lidos = lerLidos();
  celebracao = lerCelebracao();
  visao = lerVisao();
}

function trocarVisao(nova: Visao): void {
  visao = nova;
  // Recolhe o acordeão: o livro aberto numa visão não é o mesmo item na outra.
  livroAberto = null;
  salvarVisao(nova);
  atualizar();
}

// ── Progresso geral ─────────────────────────────────────────────────────────

function barra(percentual: number): TemplateResult {
  return html`
    <div class="progresso-leitura__barra" role="presentation">
      <div class="progresso-leitura__preenchido" style=${`width:${percentual}%`}></div>
    </div>
  `;
}

function resumoGeral(): TemplateResult {
  const percentual = percentualGeral(lidos);

  return html`
    <div class="progresso-leitura">
      <div class="progresso-leitura__topo">
        <span class="progresso-leitura__rotulo">${S.leituraBiblia.progressoGeral}</span>
        <span class="progresso-leitura__percentual">${percentual}%</span>
      </div>
      ${barra(percentual)}
      <span class="progresso-leitura__detalhe">
        ${S.leituraBiblia.capitulos(totalLidos(lidos), TOTAL_CAPITULOS)} ·
        ${S.leituraBiblia.livros(livrosConcluidos(lidos), LIVROS.length)}
      </span>
    </div>
  `;
}

// ── Visões de livros ────────────────────────────────────────────────────────

function grade(livro: number): TemplateResult {
  const total = capitulosDe(livro);

  return html`
    <div class="capitulos">
      ${Array.from({ length: total }, (_, indice) => indice + 1).map(
        (capitulo) => html`
          <button
            type="button"
            class="capitulo"
            ?data-lido=${capituloLido(lidos, livro, capitulo)}
            aria-pressed=${capituloLido(lidos, livro, capitulo)}
            @click=${() => {
              lidos = alternarCapitulo(lidos, livro, capitulo);
              atualizar();
            }}
          >
            ${capitulo}
          </button>
        `,
      )}
    </div>

    <div class="capitulos__acoes">
      <st-button
        size="small"
        variant="success"
        outline
        @click=${() => {
          lidos = marcarLivro(lidos, livro, true);
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="checks"></st-icon>${S.leituraBiblia.livroInteiro}
      </st-button>
      <st-button
        size="small"
        outline
        @click=${() => {
          lidos = marcarLivro(lidos, livro, false);
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="eraser"></st-icon>${S.leituraBiblia.limpar}
      </st-button>
    </div>
  `;
}

function linhaDoLivro(livro: number): TemplateResult {
  const aberto = livroAberto === livro;
  const completo = livroCompleto(lidos, livro);
  const detalhe = detalheDoLivro(visao, livro);

  return html`
    <div class="livro" ?data-completo=${completo}>
      <button
        type="button"
        class="livro__alvo"
        aria-expanded=${aberto}
        @click=${() => {
          livroAberto = aberto ? null : livro;
          atualizar();
        }}
      >
        <st-icon class="livro__icone" name=${completo ? 'circle-check' : 'book'}></st-icon>
        <span class="livro__nome">${LIVROS[livro]?.nome ?? ''}</span>
        <span class="livro__contagem">${lidosDoLivro(lidos, livro)}/${capitulosDe(livro)}</span>
        <st-icon name=${aberto ? 'chevron-up' : 'chevron-down'}></st-icon>
      </button>

      ${detalhe === '' ? nothing : html`<span class="livro__detalhe">${detalhe}</span>`}
      ${barra(percentualDoLivro(lidos, livro))}
      ${aberto ? grade(livro) : nothing}
    </div>
  `;
}

function cabecalhoDeGrupo(nome: string, livros: readonly number[]): TemplateResult {
  return html`
    <div class="grupo-escritor">
      <st-icon name="user-check"></st-icon>
      <span class="grupo-escritor__nome">${nome}</span>
      <span class="grupo-escritor__contagem">
        ${S.leituraBiblia.capituloAbrev(lidosDoGrupo(lidos, livros), capitulosDoGrupo(livros))}
      </span>
    </div>
  `;
}

function item(entrada: ItemDaLista): TemplateResult {
  return entrada.tipo === 'grupo'
    ? cabecalhoDeGrupo(entrada.grupo.nome, entrada.grupo.livros)
    : linhaDoLivro(entrada.livro);
}

function telaDosLivros(): TemplateResult {
  return html`
    ${resumoGeral()}
    <div class="livros">${itensDaVisao(visao).map((entrada) => item(entrada))}</div>
  `;
}

// ── Roteiro da Celebração ───────────────────────────────────────────────────

function telaDaCelebracao(): TemplateResult {
  const percentual = percentualCelebracao(celebracao);

  return html`
    <div class="progresso-leitura">
      <div class="progresso-leitura__topo">
        <span class="progresso-leitura__rotulo">${S.leituraBiblia.roteiro}</span>
        <span class="progresso-leitura__percentual">${percentual}%</span>
      </div>
      ${barra(percentual)}
      <span class="progresso-leitura__detalhe">
        ${S.leituraBiblia.trechos(diasLidos(celebracao), ROTEIRO_CELEBRACAO.length)}
      </span>
      <p class="progresso-leitura__nota">${S.leituraBiblia.roteiroNota}</p>
    </div>

    <div class="livros">
      ${ROTEIRO_CELEBRACAO.map((dia) => {
        const lido = celebracao.has(dia.id);

        return html`
          <div class="dia" ?data-lido=${lido}>
            <button
              type="button"
              class="dia__alvo"
              aria-pressed=${lido}
              @click=${() => {
                celebracao = alternarDia(celebracao, dia.id);
                atualizar();
              }}
            >
              <st-icon class="dia__icone" name=${lido ? 'circle-check' : 'circle'}></st-icon>
              <span class="dia__texto">
                <span class="dia__nome">${dia.dia}</span>
                <span class="dia__evento">${dia.evento}</span>
                <span class="dia__leituras">
                  ${dia.leituras.map(
                    (referencia) => html`<st-badge variant="success" pill>${referencia}</st-badge>`,
                  )}
                </span>
              </span>
            </button>
          </div>
        `;
      })}
    </div>
  `;
}

// ── Seletor de visão ────────────────────────────────────────────────────────

const ICONES: Readonly<Record<Visao, string>> = {
  canonica: 'list-numbers',
  cronologica: 'hourglass',
  escritor: 'user-check',
  celebracao: 'calendar-week',
};

function seletor(): TemplateResult {
  return html`
    <div class="chips" role="group" aria-label=${S.leituraBiblia.visualizacao}>
      ${VISOES.map(
        (chave) => html`
          <button
            class="chip"
            ?data-ativo=${visao === chave}
            title=${S.leituraBiblia.visoesAjuda[chave]}
            @click=${() => trocarVisao(chave)}
          >
            <st-icon name=${ICONES[chave]}></st-icon>
            ${S.leituraBiblia.visoes[chave]}
          </button>
        `,
      )}
    </div>
  `;
}

export const telaLeitura: Tela = {
  voltarPara() {
    // A Leitura vive no hub Estudo, como no legado.
    return 'hub/estudo';
  },

  conteudo() {
    carregar();

    return html`
      ${seletor()}
      ${visao === 'celebracao' ? telaDaCelebracao() : telaDosLivros()}
    `;
  },
};
