/**
 * Ponto de entrada do Papiro.
 *
 * Fluxo: registra os componentes do Stratum → abre o banco local (SQLite WASM no
 * OPFS, dentro de um worker) → desenha a rota do hash → sincroniza o conteúdo
 * curado em segundo plano. A sincronização vem por último de propósito: o app
 * abre e funciona com o que já está no aparelho, mesmo sem rede.
 */

import { papiro } from '@marinx/flavors';
import { setBasePath } from '@marinx/stratum/utilities/base-path.js';
import { html, nothing, render, type TemplateResult } from 'lit';
import { HOME, HUBS, hub, MODULOS, migrado, modulo } from './app/modulos.ts';
import { aoMudarRota, navegar, type Rota } from './app/rotas.ts';
import { definirRedesenho, type Tela } from './app/tela.ts';
import { registrarServiceWorker } from './atualizacao.ts';
import { abrirBanco, repositorio } from './db/banco.ts';
import { sincronizarConteudo } from './db/sincronizar.ts';
import { type CabecalhoOpcoes, casca } from './layout/casca.ts';
import { telaAnotacoes } from './modulos/anotacoes/tela.ts';
import { telaCaderno } from './modulos/caderno/tela.ts';
import { telaCalendario } from './modulos/calendario/tela.ts';
import { telaCriacao } from './modulos/criacao/tela.ts';
import { telaCronologia } from './modulos/cronologia/tela.ts';
import { telaEstudo } from './modulos/estudo/tela.ts';
import { telaFinanceiro } from './modulos/financeiro/tela.ts';
import { telaGuias } from './modulos/guias/tela.ts';
import { telaJogo } from './modulos/jogo/tela.ts';
import { telaLeitura } from './modulos/leitura/tela.ts';
import { telaMetas } from './modulos/metas/tela.ts';
import { telaMinisterio } from './modulos/ministerio/tela.ts';
import { telaPerfil } from './modulos/perfil/tela.ts';
import { telaPoesia } from './modulos/poesia/tela.ts';
import { telaPrep } from './modulos/prep/tela.ts';
import { telaReceitas } from './modulos/receitas/tela.ts';
import { telaServico } from './modulos/servico/tela.ts';
import { telaSobre } from './modulos/sobre/tela.ts';
import { telaTutorial } from './modulos/tutorial/tela.ts';
import { emBreve, naoEncontrado } from './paginas/erro.ts';
import { home } from './paginas/home.ts';
import { telaDoHub } from './paginas/hub.ts';
import { S } from './strings.ts';
import { boasVindasNaPrimeiraAbertura } from './ui/boasvindas.ts';
import { notificar } from './ui/notificar.ts';
import './componentes.ts';
import './estilo.css';

/**
 * Os ícones do Stratum são buscados em runtime. Como aqui a biblioteca é
 * empacotada pelo Vite (e não servida como `stratum.min.js`), a detecção
 * automática da pasta não funciona: o caminho é declarado à mão, e o
 * `vite.config.ts` copia `assets/` para cá no build.
 */
setBasePath('./stratum');

const raiz = document.querySelector<HTMLElement>('#app');

/** Resolve a rota atual na tela e no cabeçalho que a acompanha. */
function resolver(rota: Rota): { cabecalho: CabecalhoOpcoes; conteudo: TemplateResult } {
  if (rota.modulo === 'home') {
    // Sem ação no cabeçalho: o botão de sincronizar virou tile na grade
    // (Leva 4.2), e os dois na mesma tela seriam a mesma coisa duas vezes.
    return {
      cabecalho: { titulo: S.home.saudacao },
      conteudo: home({ executar: () => void sincronizar(true), ocupado: sincronizando }),
    };
  }

  if (rota.modulo === 'hub') {
    const id = rota.args[0] ?? '';
    return {
      cabecalho: { titulo: hubTitulo(id), voltarPara: 'home' },
      conteudo: telaDoHub(id),
    };
  }

  const m = modulo(rota.modulo);
  if (m === undefined) {
    return {
      cabecalho: { titulo: S.erro.naoEncontrado, voltarPara: 'home' },
      conteudo: naoEncontrado(),
    };
  }

  const tela = TELAS[m.id];
  // Um módulo cuja chave está ligada no flavour mas sem tela registrada seria
  // um botão que não faz nada; cair no aviso é o comportamento honesto.
  if (tela === undefined || !migrado(m.id)) {
    return {
      cabecalho: {
        titulo: m.rotulo,
        voltarPara: 'home',
        // O tutorial explica o módulo mesmo antes de ele existir por aqui.
        acoes: acoesComAjuda(m.id, rota, undefined),
      },
      conteudo: emBreve(m),
    };
  }

  return {
    cabecalho: {
      titulo: tela.titulo?.(rota) ?? m.rotulo,
      voltarPara: tela.voltarPara?.(rota) ?? 'home',
      aoVoltar: () => tela.aoVoltar?.(rota) ?? false,
      acoes: acoesComAjuda(m.id, rota, tela.acoes?.(rota)),
    },
    conteudo: tela.conteudo(rota),
  };
}

/**
 * As telas dos módulos migrados, por id.
 *
 * A Fase 2 entregou a casca com este mapa vazio; a Fase 3 o enche um módulo por
 * vez, e cada entrada nova aqui vem junto de ligar a chave correspondente em
 * `papiro.features`.
 */
const TELAS: Readonly<Record<string, Tela>> = {
  anotacoes: telaAnotacoes,
  caderno: telaCaderno,
  calendario: telaCalendario,
  criacao: telaCriacao,
  entenda: telaCriacao,
  cronologia: telaCronologia,
  estudo: telaEstudo,
  financeiro: telaFinanceiro,
  guias: telaGuias,
  jogo: telaJogo,
  leitura: telaLeitura,
  metas: telaMetas,
  ministerio: telaMinisterio,
  perfil: telaPerfil,
  poesia: telaPoesia,
  prep: telaPrep,
  receitas: telaReceitas,
  servico: telaServico,
  sobre: telaSobre,
  tutorial: telaTutorial,
};

/**
 * O botão “?” de cada módulo, que abre o tópico dele no Tutorial.
 *
 * Fica aqui, e não em cada tela: o legado teria de repetir o mesmo botão nas 17
 * seções do `index.html`, e é justamente o tipo de repetição que a casca única
 * dispensa. Some quando o próprio Tutorial está aberto — ali o botão levaria à
 * tela em que o usuário já está.
 */
function acoesComAjuda(id: string, rota: Rota, acoes: TemplateResult | undefined): TemplateResult {
  // Numa sub-vista (editor, leitura) o cabeçalho já está cheio de ações da
  // própria tela; a ajuda fica na raiz do módulo, que é onde se procura por ela.
  //
  // O Tutorial e o Sobre ficam de fora porque são eles próprios a referência: o
  // "?" do Sobre levaria a `tutorial/sobre`, que não é um dos tópicos curados, e
  // um botão que sempre cai em "sem tópico" é um botão morto.
  const referencia = id === 'tutorial' || id === 'sobre';
  const ajuda = !referencia && migrado('tutorial') && rota.args.length === 0;

  return html`
    ${acoes ?? nothing}
    ${
      ajuda
        ? html`
          <st-icon-button
            name="help-circle"
            label=${S.tutorial.ajuda}
            @click=${() => navegar(`tutorial/${id}`)}
          ></st-icon-button>
        `
        : nothing
    }
  `;
}

function hubTitulo(id: string): string {
  return hub(id)?.rotulo ?? S.erro.naoEncontrado;
}

let sincronizando = false;

function desenhar(): void {
  if (raiz === null) return;

  const rota = rotaCorrente;
  const { cabecalho, conteudo } = resolver(rota);
  document.title =
    rota.modulo === 'home' ? papiro.displayName : `${cabecalho.titulo} — ${papiro.displayName}`;
  render(casca(cabecalho, conteudo, desenhar), raiz);
}

let rotaCorrente: Rota = { modulo: 'home', args: [], query: new URLSearchParams() };

/**
 * Sincroniza o conteúdo curado. `avisar` distingue a sincronização de boot (que
 * é silenciosa — ninguém pediu) da que o usuário disparou no botão.
 */
async function sincronizar(avisar: boolean): Promise<void> {
  if (sincronizando) return;
  sincronizando = true;
  desenhar();

  try {
    const resultado = await sincronizarConteudo();
    if (!avisar) return;

    if (resultado.ok) {
      notificar(S.home.sincronizado(resultado.atualizados.length));
    } else {
      notificar(resultado.motivo === 'offline' ? S.home.semRede : S.home.semManifesto, 'warning');
    }
  } finally {
    sincronizando = false;
    desenhar();
  }
}

function mostrarCarregando(): void {
  if (raiz === null) return;
  render(
    html`
      <div class="carregando">
        <st-spinner></st-spinner>
        <p>${S.app.carregando}</p>
      </div>
    `,
    raiz,
  );
}

function mostrarFalha(detalhe: string): void {
  if (raiz === null) return;
  render(
    html`
      <div class="aviso">
        <st-icon class="aviso__icone" name="alert-triangle"></st-icon>
        <h2>${S.erro.banco}</h2>
        <pre class="detalhe">${detalhe}</pre>
      </div>
    `,
    raiz,
  );
}

async function iniciar(): Promise<void> {
  mostrarCarregando();
  // As telas dos módulos redesenham por aqui: elas mudam o próprio estado e
  // pedem o redesenho, sem conhecer a casca (ver `app/tela.ts`).
  definirRedesenho(desenhar);

  try {
    const estado = await abrirBanco();
    // O fallback em memória + IndexedDB funciona, mas é um degrau abaixo: o
    // usuário precisa saber que o armazenamento definitivo depende de HTTPS.
    if (!estado.persistente) notificar(S.armazenamento.memoria, 'warning');
  } catch (erro) {
    mostrarFalha(String(erro));
    return;
  }

  raiz?.removeAttribute('aria-busy');

  aoMudarRota((rota) => {
    rotaCorrente = rota;
    desenhar();
    scrollTo({ top: 0 });
  });

  registrarServiceWorker();
  void sincronizar(false);

  // Por último, e sobre a home já desenhada: a apresentação é sobre o app, e
  // um app que ainda não apareceu não tem o que apresentar. Nas aberturas
  // seguintes ela não faz nada.
  void boasVindasNaPrimeiraAbertura();
}

/**
 * Alça de verificação: dá a `scripts/verificar.ts` acesso à camada de
 * armazenamento e ao registro de navegação — as duas partes do app que nenhuma
 * inspeção de DOM alcançaria.
 *
 * O registro entra porque a home mostra tiles e hubs, não a lista de tudo:
 * contar elementos na tela não diz se algum módulo ficou sem caminho até ele.
 * Com o registro em mãos, a verificação compara o que existe com o que é
 * alcançável e reprova o órfão.
 *
 * Não muda o modelo de segurança: o app é local-first, não há servidor nem
 * segredo no banco, e o JS da própria página já podia chamar tudo isto. O que
 * ela evita é um caminho de teste falso — verificar o armazenamento por seus
 * efeitos na tela em vez de exercitá-lo de verdade.
 */
declare global {
  interface Window {
    __papiro?: {
      repositorio: typeof repositorio;
      navegacao: { MODULOS: typeof MODULOS; HUBS: typeof HUBS; HOME: typeof HOME };
    };
  }
}
window.__papiro = { repositorio, navegacao: { MODULOS, HUBS, HOME } };

// Hash vazio (primeira visita, `start_url` do manifest) vira a home explícita,
// para que o botão de voltar do navegador tenha para onde voltar.
if (location.hash === '') navegar('home');

void iniciar();
