/**
 * Índices dos 66 livros pela estimativa de quando a escrita foi completada;
 * empate desfeito pela ordem canônica.
 */
export const ORDEM_CRONOLOGICA: readonly number[] = LIVROS.map((_, indice) => indice).sort(
  (a, b) => (DETALHES[a]?.ano ?? 0) - (DETALHES[b]?.ano ?? 0) || a - b,
);

/** Um grupo da visão "Por escritor". */
export interface GrupoEscritor {
  readonly nome: string;
  readonly livros: readonly number[];
}

/**
 * Grupos por escritor: ordenados pelo livro mais antigo de cada um (é a ordem em
 * que os índices saem de `ORDEM_CRONOLOGICA`), e dentro do grupo, ordem
 * canônica.
 */
export const GRUPOS_ESCRITOR: readonly GrupoEscritor[] = (() => {
  const grupos = new Map<string, number[]>();

  for (const indice of ORDEM_CRONOLOGICA) {
    const detalhe = DETALHES[indice];
    if (detalhe === undefined) continue;

    const nome = detalhe.grupo ?? detalhe.escritor;
    const livros = grupos.get(nome);
    if (livros === undefined) {
      grupos.set(nome, [indice]);
    } else {
      livros.push(indice);
    }
  }

  return [...grupos].map(([nome, livros]) => ({ nome, livros: [...livros].sort((a, b) => a - b) }));
})();

