/**
 * Ordem dos tiles da home. "Vida e Ministério" fica direto no topo; "Metas" é
 * acessado de dentro dele, e por isso não tem tile próprio.
 *
 * Os três últimos são a cauda de referência, não área de uso diário: o Tutorial,
 * depois "Sincronizar" e depois "Sobre" (ordem pedida na Leva 4.2). Sincronizar
 * não é módulo — é uma **ação** com tile, declarada aqui para ocupar o lugar
 * certo na grade; quem a executa é a home, e o `verificar:papiro` a ignora ao
 * cobrar que todo módulo tenha caminho.
 */
export const HOME: readonly ItemDaHome[] = [
  { tipo: 'modulo', id: 'anotacoes' },
  { tipo: 'modulo', id: 'calendario' },
  { tipo: 'hub', id: 'estudo' },
  { tipo: 'modulo', id: 'ministerio' },
  { tipo: 'modulo', id: 'prep' },
  { tipo: 'modulo', id: 'receitas' },
  { tipo: 'hub', id: 'pessoal' },
  { tipo: 'modulo', id: 'tutorial' },
  { tipo: 'acao', id: 'sincronizar' },
  // Passar o app adiante é ação, não módulo: não tem tela própria nem conteúdo,
  // abre um diálogo e fecha. Fica antes do "Sobre" porque é ali que a pessoa já
  // vai procurar quando quer falar do app com alguém (Fase 9).
  { tipo: 'acao', id: 'convite' },
  { tipo: 'modulo', id: 'sobre' },
];

const PORTABELO = new Map(MODULOS.map((modulo) => [modulo.id, modulo]));
const PORTAHUB = new Map(HUBS.map((hub) => [hub.id, hub]));

/** Busca um módulo pelo id. */
export function modulo(id: string): Modulo | undefined {
  return PORTABELO.get(id);
}

/** Busca um hub pelo id. */
export function hub(id: string): Hub | undefined {
  return PORTAHUB.get(id);
}

/**
 * Diz se o módulo já foi migrado para este alvo. Um id desconhecido conta como
 * não migrado — é o que faz uma rota digitada à mão cair na tela "em breve" em
 * vez de numa página em branco.
 */
export function migrado(id: string): boolean {
  return papiro.features[id] === true;
}
