/**
 * "Como fazer mais para Jeová" — a conta que transforma uma meta anual num
 * compromisso de terça-feira à tarde.
 *
 * O módulo existe porque "600 horas" não cabe na cabeça de ninguém, e "duas
 * horas e meia, três vezes por semana" cabe. Tudo aqui é função pura: a tela só
 * escolhe os números e desenha o resultado, e a conta pode ser testada sem DOM.
 *
 * **Sobre as horas de cada modalidade.** Elas são um PONTO DE PARTIDA que
 * preenche o campo, não uma afirmação do app: quem define o que se espera de
 * cada um é a instrução vigente, e ela muda. Por isso o total continua sendo um
 * controle que o usuário move à vontade, e a tela mostra as referências.
 */

import { epochDeDataISO } from '../../datas.ts';
import type { Meta } from '../metas/dados.ts';

/** Semanas num mês médio: 365,25 ÷ 12 ÷ 7. Usar 4 erraria ~8% no ano. */
export const SEMANAS_POR_MES = 4.348;

export interface Modalidade {
  readonly chave: string;
  readonly nome: string;
  /** Horas por mês que costumam acompanhar a modalidade; 0 = sem meta de horas. */
  readonly horasMes: number;
  readonly resumo: string;
}

export const MODALIDADES: readonly Modalidade[] = [
  {
    chave: 'publicador',
    nome: 'Publicador',
    horasMes: 0,
    resumo: 'Sem cota de horas — o que se relata é a participação.',
  },
  {
    chave: 'auxiliar',
    nome: 'Pioneiro auxiliar',
    horasMes: 30,
    resumo: 'Um mês por vez, ao lado do trabalho ou do estudo.',
  },
  {
    chave: 'regular',
    nome: 'Pioneiro regular',
    horasMes: 50,
    resumo: 'O ano de serviço inteiro, como rotina de vida.',
  },
  {
    chave: 'especial',
    nome: 'Pioneiro especial',
    horasMes: 100,
    resumo: 'Designação de tempo integral, sustentada pela organização.',
  },
];

export function modalidadeDe(chave: string): Modalidade {
  return MODALIDADES.find((m) => m.chave === chave) ?? (MODALIDADES[0] as Modalidade);
}

/** Os sete dias, na ordem em que a grade os mostra. Índice = `getDay()`. */
export const DIAS_DA_SEMANA: readonly string[] = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

export interface Escolha {
  /** Total de horas que se quer alcançar no período. */
  readonly totalHoras: number;
  readonly meses: number;
  /** Índices de `getDay()` dos dias em que se pretende sair. */
  readonly dias: readonly number[];
}

export interface Plano {
  readonly porMes: number;
  readonly porSemana: number;
  readonly porAno: number;
  /** Horas em cada saída — é este o número que vira compromisso. */
  readonly porSaida: number;
  readonly saidasPorMes: number;
  readonly saidasTotais: number;
  /** `true` quando a conta pede mais do que um dia comporta. */
  readonly inviavel: boolean;
}

/**
 * Distribui o total pelo período.
 *
 * Sem dia de serviço escolhido não há como dividir a semana: `porSaida` sai
 * zero e a tela pede que se escolha ao menos um. Devolver `Infinity` faria a
 * grade desenhar `∞ h`, que é pior do que não desenhar nada.
 */
export function planejar(escolha: Escolha): Plano {
  const meses = Math.max(1, escolha.meses);
  const total = Math.max(0, escolha.totalHoras);
  const dias = escolha.dias.length;

  const porMes = total / meses;
  const porSemana = porMes / SEMANAS_POR_MES;
  const saidasPorMes = dias * SEMANAS_POR_MES;
  const porSaida = dias === 0 ? 0 : porSemana / dias;

  return {
    porMes,
    porSemana,
    porAno: porMes * 12,
    porSaida,
    saidasPorMes,
    saidasTotais: Math.round(saidasPorMes * meses),
    // Mais de dez horas numa saída não é plano, é aviso de que a conta não fecha.
    inviavel: porSaida > 10,
  };
}

/** `2,5 h` vira `2 h 30 min` — quem sai de casa pensa em minutos, não em decimal. */
export function horasEMinutos(horas: number): string {
  if (!Number.isFinite(horas) || horas <= 0) return '0 min';

  const totalMinutos = Math.round(horas * 60);
  const h = Math.floor(totalMinutos / 60);
  const min = totalMinutos % 60;

  if (h === 0) return `${min} min`;
  if (min === 0) return `${h} h`;
  return `${h} h ${min} min`;
}

/** Um dia da grade do mês. `fora` marca o preenchimento antes do dia 1º. */
export interface DiaDaGrade {
  readonly dia: number;
  readonly fora: boolean;
  readonly deServico: boolean;
}

/**
 * A grade de um mês, começando no domingo — as seis semanas fixas evitam a
 * grade "pular" de altura ao trocar de mês.
 */
export function gradeDoMes(ano: number, mes: number, dias: readonly number[]): DiaDaGrade[] {
  const primeiro = new Date(ano, mes, 1);
  const diasNoMes = new Date(ano, mes + 1, 0).getDate();
  const vazios = primeiro.getDay();
  const escolhidos = new Set(dias);

  const grade: DiaDaGrade[] = [];
  for (let i = 0; i < 42; i++) {
    const dia = i - vazios + 1;
    const dentro = dia >= 1 && dia <= diasNoMes;
    grade.push({
      dia: dentro ? dia : 0,
      fora: !dentro,
      deServico: dentro && escolhidos.has(new Date(ano, mes, dia).getDay()),
    });
  }

  return grade;
}

/**
 * "Agosto de 2026".
 *
 * `toLocaleDateString` devolve o mês em minúscula, e `text-transform:
 * capitalize` no CSS resolveria a primeira letra e estragaria a segunda
 * palavra — "Agosto De 2026". Capitalizar só a inicial é trabalho de quem
 * monta a string.
 */
export function nomeDoMes(ano: number, mes: number): string {
  const nome = new Date(ano, mes, 1).toLocaleDateString('pt-BR', {
    month: 'long',
    year: 'numeric',
  });
  return nome.charAt(0).toUpperCase() + nome.slice(1);
}

/** Quantos dias de serviço o mês de fato tem — a grade real, não a média. */
export function saidasNoMes(ano: number, mes: number, dias: readonly number[]): number {
  return gradeDoMes(ano, mes, dias).filter((d) => d.deServico).length;
}

/**
 * A meta que o botão grava.
 *
 * `min_horas` é categoria AUTOMÁTICA (ver `metas/dados.ts`): o progresso sai da
 * soma das horas dos relatórios do Ministério, não de um número digitado. É por
 * isso que `progresso_atual` nasce zero e assim fica — preenchê-lo aqui daria
 * um avanço que ninguém trabalhou.
 */
export function metaDoPlano(escolha: Escolha, titulo: string, hoje = new Date()): Meta {
  const fim = new Date(hoje.getFullYear(), hoje.getMonth() + Math.max(1, escolha.meses), 0);

  return {
    titulo,
    item: 'min_horas',
    ativo_nome: '',
    data_meta: hoje.getTime(),
    prazo_final: epochDeDataISO(
      `${fim.getFullYear()}-${String(fim.getMonth() + 1).padStart(2, '0')}-${String(fim.getDate()).padStart(2, '0')}`,
    ),
    progresso_atual: 0,
    progresso_alvo: Math.round(escolha.totalHoras),
    esta_concluida: 0,
  };
}
