import { notificar } from '../../ui/notificar.ts';
import {
  ajustado,
  alternarEnviado,
  type CampoDoContador,
  type Contador,
  carregar as carregarDados,
  comoHorario,
  contadorTemAtividade,
  contadorZerado,
  corDoEstudo,
  DIAS_DA_SEMANA,
  deHorario,
  type Estudo,
  esfriando,
  estudosVisiveis,
  excluirEstudo,
  excluirRegistro,
  excluirRelatorio,
  horasDoContador,
  iniciais,
  L7_DIAS,
  lembreteDoRelatorio,
  MESES,
  mesEAno,
  observacoesDoContador,
  ordenarRelatorios,
  type RegistroDeEstudo,
  type Relatorio,
  registrosDoEstudo,
  relataHoras,
  salvarContador,
  salvarEstudo,
  salvarRegistro,
  salvarRelatorio,
  TIPOS_PUBLICADOR,
  type TipoPublicador,
  textoDoEstudo,
  textoDoRelatorio,
  ultimoRelativo,
  ultimoRelatorio,
} from './dados.ts';

/** O formulário do relatório, com os números já como número. */
interface FormRelatorio {
  id: number;
  mes: number;
  ano: number;
  horas: number;
  estudos: number;
  participacao: number;
  tipo: string;
  metaHoras: number;
  observacoes: string;
  enviado: number;
  dataEnvio: number;
}

interface FormEstudo {
  id: number;
  nome: string;
  contato: string;
  endereco: string;
  publicacao: string;
  dia: string;
  /** `HH:MM`, que é o que o campo de hora fala. */
  horario: string;
  notas: string;
}

interface FormRegistro {
  id: number;
  estudoId: number;
  data: string;
  ondeParou: string;
  comentario: string;
  erro: boolean;
}

let relatorios: Relatorio[] = [];
let estudos: Estudo[] = [];
let registros: RegistroDeEstudo[] = [];
let contador: Contador | null = null;

let busca = '';
let formRelatorio: FormRelatorio | null = null;
let formEstudo: FormEstudo | null = null;
let formRegistro: FormRegistro | null = null;

let carregado = false;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregar(): Promise<void> {
  const dados = await carregarDados();
  relatorios = dados.relatorios;
  estudos = dados.estudos;
  registros = dados.registros;
  contador = dados.contador;
  atualizar();
}

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      await recarregar();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Home ────────────────────────────────────────────────────────────────────

function atalho(icone: string, rotulo: string, resumo: string, destino: string): TemplateResult {
  return html`
    <button class="atalho" @click=${() => navegar(destino)}>
      <st-icon class="atalho__icone" name=${icone}></st-icon>
      <span class="atalho__rotulo">${rotulo}</span>
      <span class="atalho__resumo">${resumo}</span>
    </button>
  `;
}

function linhaDoContador(
  campo: CampoDoContador,
  icone: string,
  rotulo: string,
  passo: number,
  valor: string,
  extra?: TemplateResult,
): TemplateResult {
  return html`
    <div class="tally__linha">
      <span class="tally__nome"><st-icon name=${icone}></st-icon>${rotulo}</span>
      <st-icon-button
        name="minus"
        label=${S.ministerio.diminuir(rotulo)}
        @click=${() => void ajustarContador(campo, -passo)}
      ></st-icon-button>
      <span class="tally__valor">${valor}</span>
      <st-icon-button
        name="plus"
        label=${S.ministerio.aumentar(rotulo)}
        @click=${() => void ajustarContador(campo, passo)}
      ></st-icon-button>
      ${extra ?? nothing}
    </div>
  `;
}

async function ajustarContador(campo: CampoDoContador, passo: number): Promise<void> {
  if (contador === null) return;

  contador = await salvarContador(ajustado(contador, campo, passo));
  atualizar();
}

async function zerarContador(): Promise<void> {
  if (contador === null) return;

  const ok = await confirmar({
    titulo: S.ministerio.zerar,
    texto: S.ministerio.zerarTexto,
    rotuloConfirmar: S.ministerio.zerar,
    variante: 'warning',
  });
  if (!ok || contador === null) return;

  contador = await salvarContador(contadorZerado(contador));
  atualizar();
}

function painelDoContador(tally: Contador): TemplateResult {
  const temAtividade = contadorTemAtividade(tally);

  return html`
    <div class="tally">
      <div class="tally__topo">
        <st-icon class="tally__icone" name="stopwatch"></st-icon>
        <span class="tally__titulo">
          ${S.ministerio.contadores}
          <small>${mesEAno(tally.mes, tally.ano)}</small>
        </span>
        ${
          temAtividade
            ? html`
              <st-icon-button
                name="rotate-clockwise"
                label=${S.ministerio.zerar}
                @click=${() => void zerarContador()}
              ></st-icon-button>
            `
            : nothing
        }
      </div>

      ${linhaDoContador(
        'minutos',
        'clock',
        S.ministerio.tempo,
        15,
        comoHorario(tally.minutos),
        html`
          <st-button size="small" outline @click=${() => void ajustarContador('minutos', 60)}>
            ${S.ministerio.maisUmaHora}
          </st-button>
        `,
      )}
      ${linhaDoContador('estudos', 'book', S.ministerio.estudos, 1, String(tally.estudos))}
      ${linhaDoContador('revisitas', 'rotate', S.ministerio.revisitas, 1, String(tally.revisitas))}
      ${linhaDoContador('publicacoes', 'books', S.ministerio.publicacoes, 1, String(tally.publicacoes))}
      ${linhaDoContador('videos', 'player-play', S.ministerio.videos, 1, String(tally.videos))}

      <st-button variant="primary" class="tally__gerar" @click=${gerarRelatorioDoContador}>
        <st-icon slot="prefix" name="file-text"></st-icon>${S.ministerio.gerarRelatorio}
      </st-button>
    </div>
  `;
}

/**
 * Abre o relatório do mês já preenchido pelo contador. O tipo de publicador vem
 * do último relatório: é o dado que quase nunca muda de um mês para o outro.
 */
function gerarRelatorioDoContador(): void {
  if (contador === null) return;

  formRelatorio = {
    id: 0,
    mes: contador.mes,
    ano: contador.ano,
    horas: horasDoContador(contador.minutos),
    estudos: contador.estudos,
    participacao: contadorTemAtividade(contador) ? 1 : 0,
    tipo: ultimoRelatorio(relatorios)?.tipo_publicador ?? 'publicador',
    metaHoras: 0,
    observacoes: observacoesDoContador(contador),
    enviado: 0,
    dataEnvio: 0,
  };

  navegar('ministerio/relatorios');
}

/** O mês que o lembrete cobra: usa o contador quando é o mesmo mês. */
function abrirLembrete(): void {
  const lembrete = lembreteDoRelatorio(relatorios);
  if (lembrete === null) return;

  if (contador !== null && contador.mes === lembrete.mes && contador.ano === lembrete.ano) {
    gerarRelatorioDoContador();
    return;
  }

  formRelatorio = { ...relatorioNovo(), mes: lembrete.mes, ano: lembrete.ano };
  navegar('ministerio/relatorios');
}

function telaDaHome(): TemplateResult {
  const frios = esfriando(estudos, registros);
  const lembrete = lembreteDoRelatorio(relatorios);
  const ultimo = ultimoRelatorio(relatorios);

  return html`
    ${
      frios.length === 0
        ? nothing
        : html`
          <st-alert variant="danger" open>
            <st-icon slot="icon" name="temperature-snow"></st-icon>
            ${S.ministerio.esfriando(frios.length, L7_DIAS)}
            <a href="#/ministerio/estudos">${S.ministerio.verEstudos}</a>
          </st-alert>
        `
    }

    ${
      lembrete === null
        ? nothing
        : html`
          <st-alert variant="warning" open>
            <st-icon slot="icon" name="bell"></st-icon>
            ${S.ministerio.lembrete(mesEAno(lembrete.mes, lembrete.ano), lembrete.existe)}
            <st-button size="small" variant="warning" @click=${abrirLembrete}>
              ${S.ministerio.preencher}
            </st-button>
          </st-alert>
        `
    }

    <div class="atalhos atalhos--quatro">
      ${atalho(
        'file-text',
        S.ministerio.atalhoRelatorios,
        S.ministerio.atalhoRelatoriosSub(relatorios.length),
        'ministerio/relatorios',
      )}
      ${atalho(
        'book',
        S.ministerio.atalhoEstudos,
        S.ministerio.atalhoEstudosSub(estudos.length),
        'ministerio/estudos',
      )}
      ${atalho('target', S.ministerio.atalhoMetas, S.ministerio.atalhoMetasSub, 'metas')}
      ${atalho('trending-up', S.ministerio.atalhoServico, S.ministerio.atalhoServicoSub, 'servico')}
    </div>

    ${contador === null ? nothing : painelDoContador(contador)}

    ${
      ultimo === null
        ? nothing
        : html`
          <div class="ultimo">
            <span class="ultimo__rotulo">${S.ministerio.ultimoRelatorio}</span>
            <div class="ultimo__linha">
              <span class="ultimo__mes">
                ${mesEAno(ultimo.mes, ultimo.ano)}
                <small>
                  ${ultimo.participacao === 1 ? S.ministerio.participou : S.ministerio.naoParticipou}
                  · ${S.ministerio.estudosDoRelatorio(ultimo.estudos)}
                </small>
              </span>
              <st-badge variant=${ultimo.relatorio_enviado === 1 ? 'success' : 'neutral'} pill>
                ${ultimo.relatorio_enviado === 1 ? S.ministerio.enviado : S.ministerio.pendente}
              </st-badge>
            </div>
          </div>
        `
    }
  `;
}

// ── Relatórios ──────────────────────────────────────────────────────────────

function relatorioNovo(): FormRelatorio {
  const agora = new Date();

  return {
    id: 0,
    mes: agora.getMonth() + 1,
    ano: agora.getFullYear(),
    horas: 0,
    estudos: 0,
    participacao: 1,
    tipo: 'publicador',
    metaHoras: 0,
    observacoes: '',
    enviado: 0,
    dataEnvio: 0,
  };
}

async function gravarRelatorio(form: FormRelatorio): Promise<void> {
  await salvarRelatorio({
    ...(form.id > 0 ? { id: form.id } : {}),
    mes: Number(form.mes),
    ano: Number(form.ano),
    ano_servico: 0, // recalculado por `salvarRelatorio`
    horas: Math.max(0, Number(form.horas)),
    estudos: Math.max(0, Number(form.estudos)),
    participacao: form.participacao === 1 ? 1 : 0,
    tipo_publicador: form.tipo,
    meta_horas: Math.max(0, Number(form.metaHoras)),
    notas_publicacoes: form.observacoes,
    telefone_dirigente: '',
    nome_dirigente: '',
    relatorio_enviado: form.enviado === 1 ? 1 : 0,
    data_envio_relatorio: form.dataEnvio,
  });

  formRelatorio = null;
  notificar(S.ministerio.relatorioSalvo);
  await recarregar();
}

