async function enviarRelatorio(relatorio: Relatorio): Promise<void> {
  await compartilhar(
    S.ministerio.relatorioDe(mesEAno(relatorio.mes, relatorio.ano)),
    textoDoRelatorio(relatorio),
  );

  // Compartilhar é o ato de entregar: se ainda estava pendente, passa a enviado.
  if (relatorio.relatorio_enviado !== 1) {
    await salvarRelatorio({
      ...relatorio,
      relatorio_enviado: 1,
      data_envio_relatorio: Date.now(),
    });
    await recarregar();
  }
}

async function apagarRelatorio(relatorio: Relatorio): Promise<void> {
  const ok = await confirmar({
    titulo: S.ministerio.excluirRelatorio,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok || relatorio.id === undefined) return;

  await excluirRelatorio(relatorio.id);
  notificar(S.ministerio.relatorioExcluido);
  await recarregar();
}

function cartaoDoRelatorio(relatorio: Relatorio): TemplateResult {
  const enviado = relatorio.relatorio_enviado === 1;
  const tipo =
    TIPOS_PUBLICADOR[relatorio.tipo_publicador as TipoPublicador] ?? relatorio.tipo_publicador;

  return html`
    <div class="registro" data-status=${enviado ? 'enviado' : 'pendente'}>
      <span class="registro__avatar">${(MESES[relatorio.mes] ?? '').slice(0, 3)}</span>

      <button
        class="registro__alvo"
        @click=${() => {
          formRelatorio = {
            id: relatorio.id ?? 0,
            mes: relatorio.mes,
            ano: relatorio.ano,
            horas: relatorio.horas,
            estudos: relatorio.estudos,
            participacao: relatorio.participacao,
            tipo: relatorio.tipo_publicador,
            metaHoras: relatorio.meta_horas,
            observacoes: relatorio.notas_publicacoes,
            enviado: relatorio.relatorio_enviado,
            dataEnvio: relatorio.data_envio_relatorio,
          };
          atualizar();
        }}
      >
        <span class="registro__topo">
          <span class="registro__titulo">${mesEAno(relatorio.mes, relatorio.ano)}</span>
          <st-badge variant=${enviado ? 'success' : 'warning'} pill>
            ${enviado ? S.ministerio.enviado : S.ministerio.pendente}
          </st-badge>
        </span>
        <span class="registro__resumo">
          ${S.ministerio.resumoRelatorio(
            tipo,
            relatorio.participacao === 1,
            relatorio.estudos,
            relataHoras(relatorio.tipo_publicador) ? S.ministerio.sufixoHoras(relatorio.horas) : '',
          )}
        </span>
      </button>

      <div class="registro__acoes">
        <st-icon-button
          name="share"
          label=${S.ministerio.compartilhar}
          @click=${() => void enviarRelatorio(relatorio)}
        ></st-icon-button>
        <st-icon-button
          name=${enviado ? 'mail-check' : 'send'}
          label=${enviado ? S.ministerio.marcarPendente : S.ministerio.marcarEnviado}
          @click=${async () => {
            await alternarEnviado(relatorio);
            await recarregar();
          }}
        ></st-icon-button>
        <st-icon-button
          name="trash"
          label=${S.ministerio.excluirRelatorio}
          @click=${() => void apagarRelatorio(relatorio)}
        ></st-icon-button>
      </div>
    </div>
  `;
}

function telaDosRelatorios(): TemplateResult {
  if (formRelatorio !== null) return formularioDoRelatorio(formRelatorio);

  const lista = ordenarRelatorios(relatorios);

  if (lista.length === 0) {
    return html`
      <div class="vazio">
        <st-icon class="vazio__icone" name="file-text"></st-icon>
        <p>${S.ministerio.semRelatorios}</p>
      </div>
    `;
  }

  return html`<div class="registros">${lista.map((item) => cartaoDoRelatorio(item))}</div>`;
}

// ── Estudos ─────────────────────────────────────────────────────────────────

function estudoNovo(): FormEstudo {
  return {
    id: 0,
    nome: '',
    contato: '',
    endereco: '',
    publicacao: '',
    dia: '',
    horario: '19:00',
    notas: '',
  };
}

async function gravarEstudo(form: FormEstudo): Promise<void> {
  if (form.nome.trim() === '') {
    notificar(S.ministerio.informeNome, 'warning');
    return;
  }

  await salvarEstudo({
    ...(form.id > 0 ? { id: form.id } : {}),
    nome: form.nome.trim(),
    contato: form.contato,
    endereco: form.endereco,
    publicacao_atual: form.publicacao,
    dia_semana: form.dia,
    horario_minutos: deHorario(form.horario),
    notas: form.notas,
  });

  formEstudo = null;
  notificar(S.ministerio.estudoSalvo);
  await recarregar();
}

