/**
 * Os dados do Modo Estudo — porte de `modulos/estudo/estudo.js`.
 *
 * Uma sessão de estudo é: escolher o tipo e o assunto, orar, cronometrar, e no
 * fim registrar a "pérola" — o que se aprendeu. A pérola pode virar uma anotação
 * (na pasta “Pérolas”, criada sob demanda) e/ou uma entrada no Caderno de Estudo.
 *
 * O cronômetro **não conta ticks**: guarda o instante de início e o acumulado, e
 * calcula a diferença. Um intervalo que soma 1 a cada segundo atrasa sempre que a
 * aba perde prioridade, e uma sessão de 45 minutos terminaria valendo 40.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';
import { gravarNoCaderno } from '../caderno/dados.ts';

export interface Sessao extends Registro {
  id?: number;
  assunto: string;
  tipo_ciclo: string;
  duracao_minutos: number;
  concluido_em: number;
  nota_meditacao: string;
  anotacao_criada: number;
}

export interface Tipo {
  readonly rotulo: string;
  readonly emoji: string;
}

export const TIPOS: Readonly<Record<string, Tipo>> = {
  leitura: { rotulo: 'Leitura da Bíblia', emoji: '📖' },
  pessoal: { rotulo: 'Estudo Pessoal', emoji: '🔍' },
  reuniao: { rotulo: 'Preparação de Reunião', emoji: '👥' },
  meditacao: { rotulo: 'Meditação', emoji: '⏳' },
};

/** Os alvos oferecidos, em minutos. */
export const ALVOS_MIN: readonly number[] = [15, 25, 45, 60];

export function rotuloDoTipo(chave: string): string {
  return TIPOS[chave]?.rotulo ?? chave;
}

export function emojiDoTipo(chave: string): string {
  return TIPOS[chave]?.emoji ?? '❓';
}

const PASTA_PEROLAS = 'Pérolas';

const sessoes = () => repositorio('sessoes_estudo');
const anotacoes = () => repositorio('anotacao');
const pastas = () => repositorio('pasta');

/** A pasta “Pérolas”, criada na primeira vez que alguém guarda uma. */
async function idDaPastaPerolas(): Promise<number> {
  const lista = await pastas().todos<Registro & { id?: number; nome?: string }>();
  const existente = lista.find((pasta) => pasta.nome === PASTA_PEROLAS);
  if (existente?.id !== undefined) return existente.id;

  return pastas().salvar({ nome: PASTA_PEROLAS, data_criacao: Date.now() });
}

export function listarSessoes(): Promise<Sessao[]> {
  return sessoes().todos<Sessao>();
}

/** Mais recente primeiro. */
export function ordenar(lista: readonly Sessao[]): Sessao[] {
  return [...lista].sort((a, b) => (b.concluido_em || 0) - (a.concluido_em || 0));
}

export function totalDeMinutos(lista: readonly Sessao[]): number {
  return lista.reduce((total, sessao) => total + (Number(sessao.duracao_minutos) || 0), 0);
}

/** `3h 20m` a partir de minutos. */
export function horasEMinutos(minutos: number): string {
  return `${Math.floor(minutos / 60)}h ${minutos % 60}m`;
}

/** `MM:SS` a partir de segundos. */
export function relogio(segundos: number): string {
  const m = String(Math.floor(segundos / 60)).padStart(2, '0');
  const s = String(segundos % 60).padStart(2, '0');
  return `${m}:${s}`;
}

export function salvarSessao(sessao: Sessao): Promise<number> {
  return sessoes().salvar(sessao);
}

export function excluirSessao(id: number): Promise<void> {
  return sessoes().excluir(id);
}

/** Texto digitado → HTML seguro de um parágrafo. */
function comoParagrafo(texto: string): string {
  const escapado = texto
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>');
  return `<p>${escapado}</p>`;
}

/**
 * A pérola de uma sessão vira anotação na pasta “Pérolas”. Marca a sessão para
 * que a mesma pérola não seja duplicada num segundo toque.
 */
export async function perolaComoAnotacao(sessao: Sessao): Promise<void> {
  const texto = sessao.nota_meditacao.trim();
  if (texto === '' || sessao.anotacao_criada === 1) return;

  const agora = Date.now();
  const assunto = sessao.assunto === '' ? rotuloDoTipo(sessao.tipo_ciclo) : sessao.assunto;

  await anotacoes().salvar({
    titulo: `Pérola — ${assunto}`,
    conteudo: comoParagrafo(texto),
    tipo_modelo: 'estudo',
    pasta_id: await idDaPastaPerolas(),
    esta_fixada: 0,
    esta_arquivada: 0,
    data_criacao: agora,
    data_modificacao: agora,
  });

  await salvarSessao({ ...sessao, anotacao_criada: 1 });
}

/** A pérola no Caderno de Estudo, com a origem marcada. */
export async function perolaNoCaderno(sessao: Sessao): Promise<void> {
  const texto = sessao.nota_meditacao.trim();
  if (texto === '') return;

  const referencia = sessao.assunto === '' ? rotuloDoTipo(sessao.tipo_ciclo) : sessao.assunto;

  await gravarNoCaderno({
    origem: 'estudo',
    referencia,
    titulo: `Estudo — ${referencia}`,
    conteudo: texto,
  });
}
