// ── Índice de Prontidão ─────────────────────────────────────────────────────

/** O perfil da calculadora: quem come, com que gasto, e quantos são. */
export interface Perfil {
  readonly idade: FaixaDeIdade;
  readonly atividade: NivelDeAtividade;
  readonly pessoas: number;
}

export const PERFIL_PADRAO: Perfil = { idade: 'ADULTO_M', atividade: 'MODERADO', pessoas: 2 };

/** Um item do inventário, no mínimo que as fórmulas exigem. */
export interface ItemComCalorias {
  readonly quantidade: number;
  readonly peso_unitario: number;
  readonly calorias_por_100g: number;
}

/** As calorias de um item; `null` quando falta algum dos três números. */
export function caloriasDoItem(item: ItemComCalorias): number | null {
  if (item.quantidade === 0 || item.peso_unitario === 0 || item.calorias_por_100g === 0) {
    return null;
  }

  return Math.round((item.quantidade * item.peso_unitario * item.calorias_por_100g) / 100);
}

export function necessidadePorPessoa(perfil: Perfil): number {
  const base = IDADES[perfil.idade]?.kcal ?? 2000;
  return Math.round(base * (ATIVIDADES[perfil.atividade]?.multiplicador ?? 1));
}

export function necessidadeDoGrupo(perfil: Perfil): number {
  return Math.max(1, necessidadePorPessoa(perfil) * Math.max(1, perfil.pessoas));
}

/** Dias de autonomia: as calorias do estoque divididas pelo gasto diário. */
export function diasDeAutonomia(estoque: readonly ItemComCalorias[], perfil: Perfil): number {
  const total = estoque.reduce((soma, item) => soma + (caloriasDoItem(item) ?? 0), 0);
  return Math.floor(total / necessidadeDoGrupo(perfil));
}

/** Um checklist, no mínimo que o índice exige. */
export interface KitComItens {
  readonly id?: number;
  readonly itens?: readonly { readonly id: number }[];
}

/** Progresso dos kits: por id do kit, os itens marcados. */
export type ProgressoDosKits = Readonly<Record<string, Readonly<Record<string, boolean>>>>;

export function percentualDoKit(kit: KitComItens, progresso: ProgressoDosKits): number {
  const itens = kit.itens ?? [];
  if (itens.length === 0) return 0;

  const marcados = progresso[String(kit.id)] ?? {};
  return Math.round(
    (itens.filter((item) => marcados[String(item.id)] === true).length / itens.length) * 100,
  );
}

/**
 * O índice de prontidão (0 a 100): 60% do avanço dos checklists e 40% da
 * autonomia alimentar, com 30 dias valendo o máximo. As duas metades existem
 * porque uma sozinha engana: mochila pronta sem comida, ou comida sem nada
 * organizado, não é estar preparado.
 */
export function calcularProntidao(entrada: {
  readonly kits: readonly KitComItens[];
  readonly progresso: ProgressoDosKits;
  readonly estoque: readonly ItemComCalorias[];
  readonly perfil: Perfil;
}): number {
  const checklists =
    entrada.kits.length === 0
      ? 0
      : entrada.kits.reduce(
          (soma, kit) => soma + percentualDoKit(kit, entrada.progresso) / 100,
          0,
        ) / entrada.kits.length;

  const alimentos = Math.min(diasDeAutonomia(entrada.estoque, entrada.perfil) / DIAS_ALVO, 1);

  return Math.round((checklists * 0.6 + alimentos * 0.4) * 100);
}

/** O tom do índice, para a barra da home. */
export function tomDaProntidao(percentual: number): 'sucesso' | 'aviso' | 'perigo' {
  if (percentual >= 70) return 'sucesso';
  if (percentual >= 40) return 'aviso';
  return 'perigo';
}
