/**
 * A tela do Língua Pura — porte da seção `jogo` do `index.html` legado.
 *
 * Três vistas: lobby, quiz e resultado. Nenhuma delas é rota, como no legado:
 * uma partida em andamento não pode ser abandonada pelo botão de voltar do
 * navegador sem que o jogo saiba — e o voltar da casca, aqui, sai do módulo.
 *
 * O timer do modo Desafio conta pelo relógio, não por ticks: guarda o instante
 * em que a pergunta expira e deriva o restante dele. Um `setInterval` que
 * decrementa 1 por segundo atrasa sempre que a aba perde prioridade, e daria ao
 * jogador mais tempo do que a dificuldade escolhida promete.
 */

import { sanitizeHtml } from '@marinx/stratum/components/editor/editor.js';
import { html, nothing, type TemplateResult } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { navegar } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { prepararRascunho } from '../caderno/dados.ts';
import {
  type Alternativa,
  alternativasDe,
  CUSTO_DICA,
  carregarPerguntas,
  DIFICULDADES,
  type Dificuldade,
  disponiveis,
  ehCorreta,
  lerProgresso,
  type Modo,
  montarPartida,
  multiplicador,
  nivel,
  ocultarPelaDica,
  type Pergunta,
  type Progresso,
  partidas,
  progressoVazio,
  registrarId,
  restantes,
  salvarProgresso,
  segundosDoTimer,
  xpDoAcerto,
} from './dados.ts';

type Vista = 'lobby' | 'quiz' | 'resultado';

let vista: Vista = 'lobby';

let todasPerguntas: Pergunta[] = [];
let progresso: Progresso = progressoVazio();

let modo: Modo = 'estudo';
let dificuldade: Dificuldade = 0;
let aviso = '';

let daPartida: Pergunta[] = [];
let indice = 0;
let alternativas: Alternativa[] = [];
let respondida = false;
let selecionada: number | null = null;
let acertou = false;
let tempoEsgotado = false;
let xpDaResposta = 0;
let acertosDaPartida = 0;
let xpDaPartida = 0;

let dicaUsada = false;
let ocultas: number[] = [];

let restanteSeg = 0;
let totalSeg = 0;
let fimMs = 0;
let pausado = false;
let intervalo: ReturnType<typeof setInterval> | undefined;

let carregado = false;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;
  vigiarSaida();

  void (async () => {
    try {
      todasPerguntas = await carregarPerguntas();
      progresso = lerProgresso();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

let vigiando = false;

/**
 * Sair do módulo com uma pergunta cronometrada aberta pausa a partida.
 *
 * Sem isto o intervalo continuaria correndo fora da tela e, ao zerar, marcaria
 * como errada uma pergunta que o jogador não estava nem vendo. A casca não avisa
 * quando uma tela sai de cena, então quem observa é o próprio hash — o mesmo
 * lugar de onde o legado se ressincronizava.
 */
function vigiarSaida(): void {
  if (vigiando) return;
  vigiando = true;

  addEventListener('hashchange', () => {
    if (location.hash.replace(/^#\/?/, '').split('/')[0] === 'jogo') return;

    if (vista === 'quiz' && modo === 'desafio' && !respondida) {
      pausado = true;
      restanteSeg = Math.max(0, Math.ceil((fimMs - Date.now()) / 1000));
    }
    pararTimer();
  });
}

// ── Timer ───────────────────────────────────────────────────────────────────

function pararTimer(): void {
  clearInterval(intervalo);
  intervalo = undefined;
}

/** Passa a acompanhar o `fimMs` já marcado. */
function agendar(): void {
  pararTimer();
  intervalo = setInterval(() => {
    restanteSeg = Math.max(0, Math.ceil((fimMs - Date.now()) / 1000));

    if (restanteSeg === 0) {
      pararTimer();
      // Tempo esgotado conta como erro: é a aposta do modo Desafio.
      responder(null);
      return;
    }

    atualizar();
  }, 250);
}

function iniciarTimer(): void {
  totalSeg = segundosDoTimer(dificuldade);
  restanteSeg = totalSeg;
  fimMs = Date.now() + totalSeg * 1000;
  pausado = false;
  agendar();
}

/**
 * Pausar não congela o relógio — ele continua andando —, então retomar remarca o
 * fim a partir do que sobrava. O intervalo é derrubado na pausa em vez de rodar
 * em vão, o que também é o que deixa a partida intacta ao sair do módulo.
 */
function alternarPausa(): void {
  pausado = !pausado;

  if (pausado) {
    restanteSeg = Math.max(0, Math.ceil((fimMs - Date.now()) / 1000));
    pararTimer();
  } else {
    fimMs = Date.now() + restanteSeg * 1000;
    agendar();
  }

  atualizar();
}

// ── Partida ─────────────────────────────────────────────────────────────────

function perguntaAtual(): Pergunta | undefined {
  return daPartida[indice];
}

function prepararPergunta(): void {
  const pergunta = perguntaAtual();
  if (pergunta === undefined) return;

  respondida = false;
  selecionada = null;
  acertou = false;
  tempoEsgotado = false;
  xpDaResposta = 0;
  dicaUsada = false;
  ocultas = [];
  alternativas = alternativasDe(pergunta);

  pararTimer();
  pausado = false;
  if (modo === 'desafio') {
    iniciarTimer();
  } else {
    totalSeg = 0;
    restanteSeg = 0;
  }
}

function iniciarPartida(): void {
  if (disponiveis(todasPerguntas, dificuldade).length < 2) {
    aviso = S.jogo.semPerguntas;
    atualizar();
    return;
  }

  aviso = '';
  daPartida = montarPartida(todasPerguntas, dificuldade, progresso);
  indice = 0;
  acertosDaPartida = 0;
  xpDaPartida = 0;

  prepararPergunta();
  vista = 'quiz';
  atualizar();
}

/** `null` em `escolhida` é o tempo esgotado. */
function responder(escolhida: Alternativa | null): void {
  if (respondida) return;

  const pergunta = perguntaAtual();
  if (pergunta === undefined) return;

  pararTimer();
  respondida = true;
  tempoEsgotado = escolhida === null;
  acertou = escolhida !== null && ehCorreta(pergunta, escolhida);

  if (acertou) {
    acertosDaPartida += 1;
    progresso.acertosTotal += 1;
    progresso.sequenciaAtual += 1;

    xpDaResposta = xpDoAcerto(pergunta, progresso.sequenciaAtual, restanteSeg, totalSeg);
    progresso.xpSaldo += xpDaResposta;
    progresso.xpHistorico += xpDaResposta;
    xpDaPartida += xpDaResposta;

    registrarId(progresso.perguntasAcertadas, pergunta.id);
  } else {
    progresso.errosTotal += 1;
    progresso.sequenciaAtual = 0;
  }

  // Gravado a cada resposta, e não no fim: quem fecha o app no meio da partida
  // não perde o que já acertou.
  registrarId(progresso.perguntasRespondidas, pergunta.id);
  salvarProgresso(progresso);
  atualizar();
}

function avancar(): void {
  if (indice + 1 >= daPartida.length) {
    vista = 'resultado';
    atualizar();
    return;
  }

  indice += 1;
  prepararPergunta();
  atualizar();
}

function abandonar(): void {
  // O progresso já foi gravado a cada resposta; aqui só se limpa a partida.
  pararTimer();
  vista = 'lobby';
  atualizar();
}

function usarDica(): void {
  const pergunta = perguntaAtual();
  if (pergunta === undefined || respondida || dicaUsada || progresso.xpSaldo < CUSTO_DICA) return;

  progresso.xpSaldo -= CUSTO_DICA;
  salvarProgresso(progresso);

  ocultas = ocultarPelaDica(pergunta, alternativas);
  dicaUsada = true;
  atualizar();
}

async function reiniciarPerguntas(): Promise<void> {
  const ok = await confirmar({
    titulo: S.jogo.reiniciarTitulo,
    texto: S.jogo.reiniciarTexto,
    rotuloConfirmar: S.jogo.reiniciar,
  });
  if (!ok) return;

  // Zera só o que foi visto — o XP conquistado fica.
  progresso.perguntasRespondidas = [];
  progresso.perguntasAcertadas = [];
  salvarProgresso(progresso);
  atualizar();
}

// ── Lobby ───────────────────────────────────────────────────────────────────

function placar(valor: number | string, rotulo: string, tom = 'neutro'): TemplateResult {
  return html`
    <div class="placar">
      <span class="placar__valor" data-tom=${tom}>${valor}</span>
      <span class="placar__rotulo">${rotulo}</span>
    </div>
  `;
}

function telaDoLobby(): TemplateResult {
  const doFiltro = disponiveis(todasPerguntas, dificuldade);
  const faltam = restantes(doFiltro, progresso);
  const concluido = doFiltro.length > 0 && faltam === 0;
  const semBanco = todasPerguntas.length === 0;

  return html`
    <div class="placares">
      ${placar(faltam, S.jogo.restantes, 'primaria')}
      ${placar(progresso.acertosTotal, S.jogo.acertos, 'sucesso')}
      ${placar(progresso.errosTotal, S.jogo.erros, 'perigo')}
      ${placar(partidas(progresso), S.jogo.partidas)}
      ${placar(progresso.xpSaldo, S.jogo.xpDisponivel, 'aviso')}
    </div>

    <h2 class="secao">${S.jogo.modo}</h2>
    <div class="modos">
      ${(['estudo', 'desafio'] as const).map(
        (chave) => html`
          <button
            class="modo"
            ?data-ativo=${modo === chave}
            @click=${() => {
              modo = chave;
              aviso = '';
              atualizar();
            }}
          >
            <st-icon name=${chave === 'estudo' ? 'book' : 'bolt'}></st-icon>
            ${S.jogo.modos[chave]}
          </button>
        `,
      )}
    </div>
    ${modo === 'desafio' ? html`<p class="discreto">${S.jogo.desafioAjuda}</p>` : nothing}

    <h2 class="secao">${S.jogo.dificuldade}</h2>
    <div class="chips">
      ${DIFICULDADES.map(
        (chave) => html`
          <button
            class="chip"
            ?data-ativo=${dificuldade === chave}
            @click=${() => {
              dificuldade = chave;
              aviso = '';
              atualizar();
            }}
          >
            ${S.jogo.dificuldades[chave]}
          </button>
        `,
      )}
    </div>

    <st-button variant="primary" class="jogo__jogar" ?disabled=${semBanco} @click=${iniciarPartida}>
      <st-icon slot="prefix" name="player-play"></st-icon>
      ${semBanco ? S.jogo.semBanco : S.jogo.jogar}
    </st-button>

    ${aviso === '' ? nothing : html`<st-alert variant="warning" open>${aviso}</st-alert>`}

    ${
      concluido
        ? html`
          <st-alert variant="success" open>
            <st-icon slot="icon" name="trophy"></st-icon>
            ${S.jogo.tudoConcluido}
            <st-button size="small" variant="success" outline @click=${() => void reiniciarPerguntas()}>
              <st-icon slot="prefix" name="rotate"></st-icon>${S.jogo.reiniciar}
            </st-button>
          </st-alert>
        `
        : nothing
    }
  `;
}

// ── Quiz ────────────────────────────────────────────────────────────────────

/** Com grupo de captura, o `split` devolve também os endereços encontrados. */
const PARTIR_NA_URL = /(https?:\/\/[^\s<]+)/g;
/** O mesmo padrão sem `g`: `test` de um regex global carrega `lastIndex`. */
const EH_URL = /^https?:\/\/[^\s<]+$/;

/**
 * A referência com os endereços clicáveis. O legado escapava o HTML à mão para
 * depois injetar as âncoras; aqui os pedaços de texto entram como texto (o Lit
 * escapa) e só os links viram elemento — não há string de HTML a montar.
 */
function referencia(texto: string): TemplateResult {
  return html`
    <p class="jogo__referencia">
      ${texto
        .split(PARTIR_NA_URL)
        .map((parte) =>
          EH_URL.test(parte)
            ? html`<a href=${parte} target="_blank" rel="noopener">${parte}</a>`
            : parte,
        )}
    </p>
  `;
}

/** O estado visual de uma alternativa depois da resposta. */
function tomDaAlternativa(pergunta: Pergunta, alternativa: Alternativa, posicao: number): string {
  if (!respondida) return 'neutro';
  if (ehCorreta(pergunta, alternativa)) return 'certa';
  return posicao === selecionada ? 'errada' : 'apagada';
}

function letra(posicao: number): string {
  return String.fromCharCode(65 + posicao);
}

function barraDoQuiz(): TemplateResult {
  const percentual = daPartida.length === 0 ? 0 : Math.round((indice / daPartida.length) * 100);
  const multi = multiplicador(progresso.sequenciaAtual);

  return html`
    <div class="quiz__topo">
      <st-icon-button name="x" label=${S.jogo.encerrar} @click=${abandonar}></st-icon-button>

      <div class="quiz__barra" role="presentation">
        <div class="quiz__preenchido" style=${`width:${percentual}%`}></div>
      </div>

      <span class="quiz__contagem">${indice + 1}/${daPartida.length}</span>

      ${multi > 1 ? html`<st-badge variant="warning" pill>x${multi}</st-badge>` : nothing}
      ${
        modo === 'desafio'
          ? html`
            <st-badge variant=${restanteSeg <= 10 ? 'danger' : 'neutral'} pill>
              ${pausado ? S.jogo.pausadoSelo : S.jogo.segundos(restanteSeg)}
            </st-badge>
          `
          : nothing
      }
    </div>
  `;
}

function telaDoQuiz(): TemplateResult {
  const pergunta = perguntaAtual();
  if (pergunta === undefined) return html`<div class="carregando"><st-spinner></st-spinner></div>`;

  return html`
    ${barraDoQuiz()}

    <div class="jogo__pergunta">${unsafeHTML(sanitizeHtml(pergunta.pergunta))}</div>
    ${pergunta.referencia === '' ? nothing : referencia(pergunta.referencia)}

    <div class="alternativas">
      ${alternativas.map(
        (alternativa, posicao) => html`
          <button
            class="alternativa"
            data-tom=${tomDaAlternativa(pergunta, alternativa, posicao)}
            ?data-oculta=${ocultas.includes(posicao)}
            ?disabled=${respondida || ocultas.includes(posicao)}
            @click=${() => responder(alternativa)}
          >
            <span class="alternativa__letra">${letra(posicao)}</span>
            <span>${alternativa.texto}</span>
          </button>
        `,
      )}
    </div>

    ${
      respondida
        ? html`
          <st-alert variant=${acertou ? 'success' : 'danger'} open>
            ${
              tempoEsgotado
                ? S.jogo.feedbackTempo
                : acertou
                  ? S.jogo.feedbackCorreto(xpDaResposta)
                  : S.jogo.feedbackIncorreto
            }
          </st-alert>

          ${
            pergunta.explicacao === ''
              ? nothing
              : html`
                <div class="explicacao">
                  <span class="explicacao__rotulo">
                    <st-icon name="info-circle"></st-icon>${S.jogo.explicacao}
                  </span>
                  <div class="prosa">${unsafeHTML(sanitizeHtml(pergunta.explicacao))}</div>
                </div>
              `
          }

          <st-button variant="primary" class="jogo__jogar" @click=${avancar}>
            ${indice + 1 < daPartida.length ? S.jogo.proxima : S.jogo.verResultado}
            <st-icon slot="suffix" name="arrow-right"></st-icon>
          </st-button>
        `
        : html`
          <div class="jogo__controles">
            <st-button
              size="small"
              variant="primary"
              outline
              ?disabled=${dicaUsada || progresso.xpSaldo < CUSTO_DICA}
              @click=${usarDica}
            >
              <st-icon slot="prefix" name="bulb"></st-icon>${S.jogo.dica(CUSTO_DICA)}
            </st-button>

            ${
              modo === 'desafio'
                ? html`
                  <st-button size="small" outline @click=${alternarPausa}>
                    <st-icon
                      slot="prefix"
                      name=${pausado ? 'player-play' : 'player-pause'}
                    ></st-icon>
                    ${pausado ? S.jogo.retomar : S.jogo.pausar}
                  </st-button>
                `
                : nothing
            }
          </div>
        `
    }
  `;
}

// ── Resultado ───────────────────────────────────────────────────────────────

function mensagemDoResultado(percentual: number): string {
  if (percentual === 100) return S.jogo.resultados.perfeito;
  if (percentual >= 80) return S.jogo.resultados.excelente;
  if (percentual >= 60) return S.jogo.resultados.muitoBem;
  if (percentual >= 40) return S.jogo.resultados.continue;
  return S.jogo.resultados.naoDesista;
}

function telaDoResultado(): TemplateResult {
  const total = daPartida.length;
  const percentual = total === 0 ? 0 : Math.round((acertosDaPartida / total) * 100);

  return html`
    <h2 class="resultado__titulo">${mensagemDoResultado(percentual)}</h2>
    <p class="resultado__linha">${S.jogo.acertosDe(acertosDaPartida, total, percentual)}</p>

    <div class="placares">
      ${placar(`+${xpDaPartida}`, S.jogo.xpGanho, 'aviso')}
      ${placar(`Nv ${nivel(progresso.xpHistorico)}`, S.jogo.nivel, 'primaria')}
      ${placar(progresso.xpSaldo, S.jogo.xpSaldo)}
    </div>

    <st-button
      variant="primary"
      outline
      class="jogo__jogar"
      @click=${() =>
        navegar(
          prepararRascunho({
            origem: 'jogo',
            referencia: S.jogo.cadernoReferencia,
            titulo: S.jogo.cadernoTitulo,
            conteudo: S.jogo.cadernoConteudo(acertosDaPartida, total, percentual),
          }),
        )}
    >
      <st-icon slot="prefix" name="bookmark"></st-icon>${S.jogo.anotarNoCaderno}
    </st-button>

    <div class="jogo__controles">
      <st-button
        outline
        @click=${() => {
          vista = 'lobby';
          progresso = lerProgresso();
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="rotate"></st-icon>${S.jogo.jogarDeNovo}
      </st-button>
      <st-button @click=${() => navegar('home')}>
        <st-icon slot="prefix" name="home"></st-icon>${S.jogo.inicio}
      </st-button>
    </div>
  `;
}

export const telaJogo: Tela = {
  voltarPara() {
    // O Jogo vive no hub Estudo, como no legado.
    return 'hub/estudo';
  },

  titulo() {
    return vista === 'resultado' ? S.jogo.tituloResultado : undefined;
  },

  conteudo() {
    carregar();

    if (!carregado) return html`<div class="carregando"><st-spinner></st-spinner></div>`;
    if (vista === 'quiz') return telaDoQuiz();
    if (vista === 'resultado') return telaDoResultado();
    return telaDoLobby();
  },
};
