/**
 * Os dados do Calendário — porte de `modulos/calendario/calendario.js`.
 *
 * Dois stores privados: os tipos de evento (semeados do catálogo curado do admin,
 * depois do usuário) e os eventos. Nada disso sai do aparelho.
 *
 * Datas são guardadas como epoch do **início do dia local** mais os minutos desde
 * a meia-noite, e nunca como um instante único: um evento de "quarta às 19h30" é
 * um compromisso do calendário, não uma marca na linha do tempo universal. Toda
 * a conversão passa por `datas.ts`, que nunca usa `toISOString()`.
 */

import { dataLocalISO, epochDeDataISO } from '../../datas.ts';
import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';
import { semearTiposCalendarioPadrao } from '../../db/sincronizar.ts';

/** As cores dos tipos, por chave — espelha o `CalendarioPage::cores` do admin. */
export const CORES: Readonly<Record<string, string>> = {
  primary: '#0d6efd',
  secondary: '#6c757d',
  tertiary: '#6f42c1',
  positive: '#198754',
  aviso: '#ffc107',
  perigo: '#dc3545',
};

/** Os ícones dos tipos: a chave curada do admin → o nome no Stratum. */
export const ICONES: Readonly<Record<string, string>> = {
  grupo: 'users',
  evento: 'calendar-event',
  relogio: 'clock',
  estrela: 'star',
  pessoa: 'user',
  notificacao: 'bell',
};

/**
 * Tipos embutidos, usados só quando o catálogo curado não chegou: primeiro uso
 * offline, ou abertura do módulo antes da sincronização. Com rede, quem semeia é
 * `semearTiposCalendarioPadrao`.
 */
const TIPOS_PADRAO: readonly Omit<Tipo, 'id'>[] = [
  { nome: 'Reunião', cor_chave: 'primary', icone: 'grupo', ordem: 0, marca_especial: 0 },
  { nome: 'Compromisso', cor_chave: 'secondary', icone: 'evento', ordem: 1, marca_especial: 0 },
  { nome: 'Bloco de tempo', cor_chave: 'tertiary', icone: 'relogio', ordem: 2, marca_especial: 0 },
  { nome: 'Especial', cor_chave: 'positive', icone: 'estrela', ordem: 3, marca_especial: 1 },
  { nome: 'Pessoal', cor_chave: 'aviso', icone: 'pessoa', ordem: 4, marca_especial: 0 },
  { nome: 'Lembrete', cor_chave: 'perigo', icone: 'notificacao', ordem: 5, marca_especial: 0 },
];

export interface Tipo extends Registro {
  id?: number;
  nome: string;
  cor_chave: string;
  icone: string;
  ordem: number;
  /** 1 marca o tipo que alimenta o KPI "próximo especial". */
  marca_especial: number;
}

export interface Evento extends Registro {
  id?: number;
  titulo: string;
  tipo_id: number;
  /** Epoch do início do dia local. */
  data_inicio_epoch: number;
  hora_inicio_min: number;
  data_fim_epoch: number;
  hora_fim_min: number;
  dia_inteiro: number;
  descricao: string;
}

const tipos = () => repositorio('calendario_tipos');
const eventos = () => repositorio('calendario_eventos');

// ── Horários ────────────────────────────────────────────────────────────────

/** Minutos desde a meia-noite em `HH:MM`. */
export function comoHora(minutos: number): string {
  const total = Math.max(0, minutos);
  return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}

/** `HH:MM` em minutos desde a meia-noite. */
export function deHora(texto: string): number {
  const [horas = 0, minutos = 0] = texto.split(':').map(Number);
  return Math.min(23, Math.max(0, horas)) * 60 + Math.min(59, Math.max(0, minutos));
}

// ── Carga e semeadura ───────────────────────────────────────────────────────

export interface Dados {
  readonly tipos: Tipo[];
  readonly eventos: Evento[];
}

/**
 * Garante que exista um catálogo de tipos e devolve tudo.
 *
 * A semeadura da sincronização é aguardada (é a mesma promessa memoizada que o
 * boot usa) para que as duas não inserissem os seis tipos cada uma. Só se ela
 * não trouxer nada é que o fallback embutido entra.
 */
export async function carregar(): Promise<Dados> {
  await semearTiposCalendarioPadrao();

  let lista = await tipos().todos<Tipo>();

  if (lista.length === 0) {
    for (const padrao of TIPOS_PADRAO) await tipos().salvar({ ...padrao });
    lista = await tipos().todos<Tipo>();
  }

  const agenda = await eventos().todos<Evento>();
  const semDuplicados = await removerTiposDuplicados(lista, agenda);

  return {
    tipos: [...semDuplicados].sort((a, b) => a.ordem - b.ordem || (a.id ?? 0) - (b.id ?? 0)),
    eventos: agenda,
  };
}

/**
 * Cura bancos que juntaram tipos repetidos em reinicializações antigas: do mesmo
 * nome fica o de menor id, e as cópias só saem se nenhum evento as usar — apagar
 * um tipo em uso deixaria eventos órfãos, sem cor nem nome.
 */
async function removerTiposDuplicados(
  lista: readonly Tipo[],
  agenda: readonly Evento[],
): Promise<Tipo[]> {
  const usados = new Set(agenda.map((evento) => evento.tipo_id));
  const vistos = new Set<string>();
  let removeu = false;

  for (const tipo of [...lista].sort((a, b) => (a.id ?? 0) - (b.id ?? 0))) {
    if (!vistos.has(tipo.nome)) {
      vistos.add(tipo.nome);
      continue;
    }

    if (tipo.id !== undefined && !usados.has(tipo.id)) {
      await tipos().excluir(tipo.id);
      removeu = true;
    }
  }

  return removeu ? await tipos().todos<Tipo>() : [...lista];
}

// ── Consulta dos tipos ──────────────────────────────────────────────────────

export function tipoPorId(lista: readonly Tipo[], id: number): Tipo | undefined {
  return lista.find((tipo) => tipo.id === id);
}

export function corDoTipo(lista: readonly Tipo[], id: number): string {
  return CORES[tipoPorId(lista, id)?.cor_chave ?? ''] ?? CORES.secondary ?? '#6c757d';
}

export function iconeDoTipo(lista: readonly Tipo[], id: number): string {
  return ICONES[tipoPorId(lista, id)?.icone ?? ''] ?? 'calendar-event';
}

// ── Intervalos ──────────────────────────────────────────────────────────────

/** O dia (`YYYY-MM-DD`) em que o evento começa. */
export function diaInicial(evento: Evento): string {
  return dataLocalISO(evento.data_inicio_epoch);
}

/** O dia em que o evento termina — inclusivo, como está gravado. */
export function diaFinal(evento: Evento): string {
  return dataLocalISO(evento.data_fim_epoch);
}

/** Os eventos que tocam o dia dado, ordenados pela hora de início. */
export function eventosDoDia(lista: readonly Evento[], dia: string): Evento[] {
  return lista
    .filter((evento) => diaInicial(evento) <= dia && diaFinal(evento) >= dia)
    .sort(
      (a, b) =>
        b.dia_inteiro - a.dia_inteiro ||
        a.hora_inicio_min - b.hora_inicio_min ||
        a.hora_fim_min - b.hora_fim_min,
    );
}

/** Os eventos que tocam a faixa `[de, ate]`, ambos inclusivos. */
export function eventosNaFaixa(lista: readonly Evento[], de: string, ate: string): Evento[] {
  return lista.filter((evento) => diaInicial(evento) <= ate && diaFinal(evento) >= de);
}

/** Duração em horas: um evento de dia inteiro conta o dia todo. */
export function duracaoHoras(evento: Evento): number {
  if (evento.dia_inteiro === 1) return 24;

  const inicio = evento.hora_inicio_min;
  const fim = evento.hora_fim_min;
  // Fim antes do início é evento que atravessa a meia-noite.
  return (fim > inicio ? fim - inicio : 24 * 60 - inicio + fim) / 60;
}

function seSobrepoem(a: Evento, b: Evento): boolean {
  const aInicio = diaInicial(a);
  const aFim = diaFinal(a);
  const bInicio = diaInicial(b);
  const bFim = diaFinal(b);

  if (aFim < bInicio || bFim < aInicio) return false;

  // Só compara horas quando os dois são do mesmo dia único; um evento de vários
  // dias que cruza o outro já é conflito, qualquer que seja a hora.
  if (aInicio === aFim && bInicio === bFim && aInicio === bInicio) {
    return a.hora_inicio_min < b.hora_fim_min && b.hora_inicio_min < a.hora_fim_min;
  }

  return true;
}

/** Quantos pares de eventos com hora marcada colidem na lista. */
export function contarConflitos(lista: readonly Evento[]): number {
  const comHora = lista.filter((evento) => evento.dia_inteiro === 0);
  let total = 0;

  for (let i = 0; i < comHora.length; i++) {
    for (let j = i + 1; j < comHora.length; j++) {
      const a = comHora[i];
      const b = comHora[j];
      if (a !== undefined && b !== undefined && seSobrepoem(a, b)) total += 1;
    }
  }

  return total;
}

// ── KPIs ────────────────────────────────────────────────────────────────────

export interface Kpis {
  readonly horas: number;
  readonly conflitos: number;
  /** Dias até o próximo evento de tipo especial; `null` quando não há nenhum. */
  readonly diasParaEspecial: number | null;
}

/** Segunda-feira da semana em que a data cai. */
export function inicioDaSemana(data: Date): Date {
  const dia = new Date(data);
  dia.setDate(dia.getDate() - ((dia.getDay() + 6) % 7));
  dia.setHours(0, 0, 0, 0);
  return dia;
}

/**
 * Os três números do painel, todos da semana corrente — menos o "próximo
 * especial", que olha para a frente.
 *
 * O especial **ignora o que já passou**: um evento de ontem não é "próximo". É a
 * mesma regra que faz o resumo do módulo não anunciar compromisso vencido.
 */
export function calcularKpis(lista: readonly Evento[], catalogo: readonly Tipo[]): Kpis {
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);

  const inicio = inicioDaSemana(hoje);
  const fim = new Date(inicio);
  fim.setDate(fim.getDate() + 6);

  const daSemana = eventosNaFaixa(lista, dataLocalISO(inicio), dataLocalISO(fim));
  const horas = Math.round(daSemana.reduce((soma, ev) => soma + duracaoHoras(ev), 0) * 10) / 10;

  const especiais = new Set(
    catalogo.filter((tipo) => tipo.marca_especial === 1).map((tipo) => tipo.id),
  );
  const hojeISO = dataLocalISO(hoje);
  let dias: number | null = null;

  for (const evento of lista) {
    if (!especiais.has(evento.tipo_id)) continue;

    const inicioDoEvento = diaInicial(evento);
    if (inicioDoEvento < hojeISO) continue;

    const distancia = Math.round((epochDeDataISO(inicioDoEvento) - hoje.getTime()) / 86_400_000);
    if (dias === null || distancia < dias) dias = distancia;
  }

  return { horas, conflitos: contarConflitos(daSemana), diasParaEspecial: dias };
}

// ── Gravação ────────────────────────────────────────────────────────────────

export function salvarEvento(evento: Evento): Promise<number> {
  return eventos().salvar(evento);
}

export function excluirEvento(id: number): Promise<void> {
  return eventos().excluir(id);
}

export function salvarTipo(tipo: Tipo): Promise<number> {
  return tipos().salvar(tipo);
}

export function excluirTipo(id: number): Promise<void> {
  return tipos().excluir(id);
}

/** A próxima ordem livre do catálogo. */
export function proximaOrdem(lista: readonly Tipo[]): number {
  return lista.reduce((maior, tipo) => Math.max(maior, tipo.ordem), -1) + 1;
}

export function tipoEmUso(lista: readonly Evento[], id: number): boolean {
  return lista.some((evento) => evento.tipo_id === id);
}
