/**
 * Os dados e as regras do Língua Pura — porte de `modulos/jogo/jogo.js`.
 *
 * As perguntas são conteúdo curado (só leitura); o progresso é do
 * aparelho e vive no `localStorage`, na mesma chave do legado —
 * `papiro_jogo_progresso`, que as **Metas** já leem para a categoria "Perguntas
 * Respondidas" (ver `modulos/metas/dados.ts`). Mudar essa chave ou o formato
 * dela quebraria aquela meta em silêncio.
 *
 * A economia tem dois números que é fácil confundir: `xpSaldo` é gastável (a
 * dica desconta dele) e `xpHistorico` nunca desce — é ele que define o nível.
 * Se o nível saísse do saldo, pedir uma dica rebaixaria o jogador.
 *
 * Tudo aqui é puro ou toca só o `localStorage`: quem sorteia, cronometra e
 * desenha é a tela.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

export interface Pergunta extends Registro {
  id?: number;
  pergunta: string;
  referencia: string;
  dificuldade: number;
  resposta1: string;
  resposta2: string;
  resposta3: string;
  resposta4: string;
  /** Qual das quatro respostas é a certa, de 1 a 4. */
  correta: number;
  explicacao: string;
}

/** Perguntas por partida. */
export const TAMANHO_PARTIDA = 10;

/** XP gasto para revelar uma dica. */
export const CUSTO_DICA = 15;

/** XP base por dificuldade da pergunta, antes do multiplicador da sequência. */
const XP_BASE: Readonly<Record<number, number>> = { 1: 10, 2: 15, 3: 20 };

/** Segundos do timer por dificuldade escolhida, no modo Desafio. */
const TIMERS: Readonly<Record<number, number>> = { 0: 45, 1: 60, 2: 50, 3: 30 };

/** Bônus máximo de velocidade, somado quando a resposta certa vem rápido. */
const BONUS_VELOCIDADE = 20;

export type Modo = 'estudo' | 'desafio';

/** 0 = todas as dificuldades. */
export type Dificuldade = 0 | 1 | 2 | 3;

export const DIFICULDADES: readonly Dificuldade[] = [0, 1, 2, 3];

// ── Progresso ───────────────────────────────────────────────────────────────

const CHAVE_PROGRESSO = 'papiro_jogo_progresso';

export interface Progresso {
  /** XP gastável — a dica desconta daqui. */
  xpSaldo: number;
  /** XP acumulado desde sempre; é dele que sai o nível. */
  xpHistorico: number;
  sequenciaAtual: number;
  acertosTotal: number;
  errosTotal: number;
  perguntasRespondidas: number[];
  perguntasAcertadas: number[];
}

export function progressoVazio(): Progresso {
  return {
    xpSaldo: 0,
    xpHistorico: 0,
    sequenciaAtual: 0,
    acertosTotal: 0,
    errosTotal: 0,
    perguntasRespondidas: [],
    perguntasAcertadas: [],
  };
}

export function lerProgresso(): Progresso {
  try {
    const bruto = JSON.parse(localStorage.getItem(CHAVE_PROGRESSO) ?? 'null') as unknown;
    return { ...progressoVazio(), ...(bruto as Partial<Progresso> | null) };
  } catch {
    return progressoVazio();
  }
}

export function salvarProgresso(progresso: Progresso): void {
  localStorage.setItem(CHAVE_PROGRESSO, JSON.stringify(progresso));
}

// ── Fórmulas ────────────────────────────────────────────────────────────────

/** Nível pelo XP histórico: cada nível custa um degrau mais que o anterior. */
export function nivel(xpHistorico: number): number {
  return Math.floor(Math.sqrt(Math.max(0, xpHistorico) / 100));
}

/** Multiplicador da sequência de acertos: 5 dobra, 10 triplica, 20 quadruplica. */
export function multiplicador(sequencia: number): number {
  if (sequencia >= 20) return 4;
  if (sequencia >= 10) return 3;
  if (sequencia >= 5) return 2;
  return 1;
}

export function xpBase(dificuldade: number): number {
  return XP_BASE[dificuldade] ?? 10;
}

export function segundosDoTimer(dificuldade: Dificuldade): number {
  return TIMERS[dificuldade] ?? 45;
}

/**
 * O XP de um acerto: base da dificuldade × multiplicador da sequência, mais o
 * bônus de velocidade quando a partida é cronometrada.
 */
export function xpDoAcerto(
  pergunta: Pergunta,
  sequencia: number,
  restanteSeg: number,
  totalSeg: number,
): number {
  const base = xpBase(Number(pergunta.dificuldade)) * multiplicador(sequencia);
  if (totalSeg <= 0) return base;

  return base + Math.floor((restanteSeg / totalSeg) * BONUS_VELOCIDADE);
}

/** Partidas fechadas: cada dez perguntas respondidas contam uma. */
export function partidas(progresso: Progresso): number {
  return Math.floor((progresso.acertosTotal + progresso.errosTotal) / TAMANHO_PARTIDA);
}

// ── Sorteio ─────────────────────────────────────────────────────────────────

export function embaralhar<T>(itens: readonly T[]): T[] {
  const copia = [...itens];

  for (let i = copia.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const trocado = copia[i] as T;
    copia[i] = copia[j] as T;
    copia[j] = trocado;
  }

  return copia;
}

/** Uma alternativa já embaralhada, que lembra de qual resposta ela veio. */
export interface Alternativa {
  readonly texto: string;
  /** 1 a 4 — comparado com `pergunta.correta`. */
  readonly original: number;
}

export function alternativasDe(pergunta: Pergunta): Alternativa[] {
  return embaralhar([
    { texto: pergunta.resposta1, original: 1 },
    { texto: pergunta.resposta2, original: 2 },
    { texto: pergunta.resposta3, original: 3 },
    { texto: pergunta.resposta4, original: 4 },
  ]);
}

export function ehCorreta(pergunta: Pergunta, alternativa: Alternativa): boolean {
  return alternativa.original === Number(pergunta.correta);
}

export function disponiveis(
  todas: readonly Pergunta[],
  dificuldade: Dificuldade,
): readonly Pergunta[] {
  if (dificuldade === 0) return todas;
  return todas.filter((pergunta) => Number(pergunta.dificuldade) === dificuldade);
}

export function restantes(todas: readonly Pergunta[], progresso: Progresso): number {
  const feitas = new Set(progresso.perguntasRespondidas);
  return todas.filter((pergunta) => !feitas.has(pergunta.id ?? -1)).length;
}

/**
 * Monta a partida priorizando o que o jogador ainda não viu e completando com
 * repetidas só se faltar para fechar as dez. É reforço quando o banco é pequeno
 * ou já foi todo respondido — melhor que uma partida de três perguntas.
 */
export function montarPartida(
  todas: readonly Pergunta[],
  dificuldade: Dificuldade,
  progresso: Progresso,
): Pergunta[] {
  const feitas = new Set(progresso.perguntasRespondidas);
  const pool = disponiveis(todas, dificuldade);

  const novas = embaralhar(pool.filter((pergunta) => !feitas.has(pergunta.id ?? -1)));
  const antigas = embaralhar(pool.filter((pergunta) => feitas.has(pergunta.id ?? -1)));

  return [...novas, ...antigas].slice(0, TAMANHO_PARTIDA);
}

/** Índices de duas alternativas erradas, para a dica esconder. */
export function ocultarPelaDica(
  pergunta: Pergunta,
  alternativas: readonly Alternativa[],
): number[] {
  const erradas = alternativas
    .map((alternativa, indice) => ({ alternativa, indice }))
    .filter(({ alternativa }) => !ehCorreta(pergunta, alternativa));

  return embaralhar(erradas)
    .slice(0, 2)
    .map(({ indice }) => indice);
}

/** Registra o id na lista sem duplicar — é um conjunto guardado como array. */
export function registrarId(lista: number[], id: number | undefined): void {
  if (id !== undefined && !lista.includes(id)) lista.push(id);
}

// ── Carga ───────────────────────────────────────────────────────────────────

export function carregarPerguntas(): Promise<Pergunta[]> {
  return repositorio('perguntas').todos<Pergunta>();
}
