/**
 * O Cofre do Esteja Preparado — porte de `modulos/prep/cofre.js` e
 * `modulos/prep/cripto.js`.
 *
 * Cada documento é cifrado com **AES-256-GCM**, com a chave derivada do PIN por
 * PBKDF2 (200 mil iterações, SHA-256). O blob gravado é `[sal(16) | iv(12) |
 * cifra]`: o sal e o iv viajam junto do dado porque são públicos por definição —
 * o que precisa ser secreto é o PIN, e ele não é gravado em lugar nenhum.
 *
 * O que fica em `localStorage` é o **hash** SHA-256 do PIN, e ele serve só para
 * dizer "esse PIN é o mesmo de antes" antes de tentar decifrar. Ele não abre nada:
 * a chave de verdade é derivada do PIN digitado, e sem o PIN os blobs no banco são
 * bytes sem sentido — inclusive para quem tiver o banco em mãos.
 *
 * O rótulo do documento é metadado em texto puro. É uma escolha, não um descuido:
 * a lista precisa ser legível com o cofre trancado para o usuário saber o que tem
 * ali; quem quiser esconder o nome, põe no nome o que quiser.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

const CHAVE_PIN = 'papiro_cofre_pin';

const ITERACOES = 200_000;
const TAMANHO_SAL = 16;
const TAMANHO_IV = 12;

/**
 * Bytes com o buffer explícito. Sem o parâmetro, o `Uint8Array` do TS aceitaria
 * um `SharedArrayBuffer`, que a Web Crypto não recebe.
 */
export type Bytes = Uint8Array<ArrayBuffer>;

export interface Documento extends Registro {
  id?: number;
  rotulo: string;
  tipo_mime: string;
  blob_criptografado: Bytes;
  data_criacao: number;
}

const cofre = () => repositorio('documentos_cofre');

// ── Criptografia ────────────────────────────────────────────────────────────

async function derivarChave(pin: string, sal: Bytes): Promise<CryptoKey> {
  const material = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(pin),
    'PBKDF2',
    false,
    ['deriveKey'],
  );

  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt: sal, iterations: ITERACOES, hash: 'SHA-256' },
    material,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt'],
  );
}

export async function criptografar(pin: string, dados: ArrayBuffer): Promise<Bytes> {
  const sal = crypto.getRandomValues(new Uint8Array(TAMANHO_SAL));
  const iv = crypto.getRandomValues(new Uint8Array(TAMANHO_IV));
  const chave = await derivarChave(pin, sal);
  const cifra = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, chave, dados);

  const blob: Bytes = new Uint8Array(TAMANHO_SAL + TAMANHO_IV + cifra.byteLength);
  blob.set(sal, 0);
  blob.set(iv, TAMANHO_SAL);
  blob.set(new Uint8Array(cifra), TAMANHO_SAL + TAMANHO_IV);

  return blob;
}

export async function descriptografar(pin: string, blob: Bytes): Promise<ArrayBuffer> {
  const sal = blob.slice(0, TAMANHO_SAL);
  const iv = blob.slice(TAMANHO_SAL, TAMANHO_SAL + TAMANHO_IV);
  const cifra = blob.slice(TAMANHO_SAL + TAMANHO_IV);
  const chave = await derivarChave(pin, sal);

  return crypto.subtle.decrypt({ name: 'AES-GCM', iv }, chave, cifra);
}

/** SHA-256 do PIN em hexadecimal, que é o que fica guardado. */
export async function hashDoPin(pin: string): Promise<string> {
  const resumo = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(pin));

  return [...new Uint8Array(resumo)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

// ── PIN ─────────────────────────────────────────────────────────────────────

/** Mínimo de dígitos do PIN. */
export const MINIMO_PIN = 4;

export function cofreConfigurado(): boolean {
  return localStorage.getItem(CHAVE_PIN) !== null;
}

export async function pinCorreto(pin: string): Promise<boolean> {
  return (await hashDoPin(pin)) === localStorage.getItem(CHAVE_PIN);
}

export async function definirPin(pin: string): Promise<void> {
  localStorage.setItem(CHAVE_PIN, await hashDoPin(pin));
}

// ── Documentos ──────────────────────────────────────────────────────────────

export function listarDocumentos(): Promise<Documento[]> {
  return cofre().todos<Documento>();
}

export async function guardarDocumento(pin: string, arquivo: File, rotulo: string): Promise<void> {
  await cofre().salvar({
    rotulo,
    tipo_mime: arquivo.type === '' ? 'application/octet-stream' : arquivo.type,
    blob_criptografado: await criptografar(pin, await arquivo.arrayBuffer()),
    data_criacao: Date.now(),
  });
}

/** Renomear não pede o PIN: o rótulo nunca foi cifrado. */
export function renomearDocumento(documento: Documento, rotulo: string): Promise<number> {
  return cofre().salvar({ ...documento, rotulo });
}

export function excluirDocumento(id: number): Promise<void> {
  return cofre().excluir(id);
}

/** Uma URL temporária do documento decifrado, para a pré-visualização. */
export async function abrirDocumento(pin: string, documento: Documento): Promise<string> {
  const claro = await descriptografar(pin, documento.blob_criptografado);
  return URL.createObjectURL(new Blob([claro], { type: documento.tipo_mime }));
}
