/**
 * Os dados de Vida e Ministério — porte de `modulos/ministerio/ministerio.js`.
 *
 * Quatro stores privados, que nunca saem do aparelho: os relatórios mensais, o
 * contador do mês corrente, os estudos bíblicos e a linha do tempo de cada
 * estudo. As **Metas** leem `relatorios_ministerio` (horas), `estudos_biblicos`
 * (quantidade) e `contadores_ministerio` (revisitas) para o progresso automático
 * delas (ver `modulos/metas/dados.ts`) — os nomes dos campos são contrato.
 *
 * O algoritmo que dá identidade ao módulo é o **L7**: um estudo sem registro na
 * linha do tempo há 15 dias ou mais está "esfriando". Ele não olha a data do
 * cadastro nem um campo de status que alguém precise manter — olha a última
 * sessão de fato registrada, que é o único dado que não mente.
 */

import type { Registro as RegistroDoBanco } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';
import { S } from '../../strings.ts';

/** Dias sem registro que marcam um estudo como esfriando. */
export const L7_DIAS = 15;

const L7_MS = L7_DIAS * 86_400_000;

/** Meses com o índice 1 = Janeiro, como vêm gravados. */
export const MESES = [
  '',
  'Janeiro',
  'Fevereiro',
  'Março',
  'Abril',
  'Maio',
  'Junho',
  'Julho',
  'Agosto',
  'Setembro',
  'Outubro',
  'Novembro',
  'Dezembro',
] as const;

export type TipoPublicador = 'publicador' | 'auxiliar' | 'regular' | 'especial';

export const TIPOS_PUBLICADOR: Readonly<Record<TipoPublicador, string>> = {
  publicador: 'Publicador',
  auxiliar: 'Pioneiro Auxiliar',
  regular: 'Pioneiro Regular',
  especial: 'Pioneiro Especial',
};

export const DIAS_DA_SEMANA = [
  'Segunda',
  'Terça',
  'Quarta',
  'Quinta',
  'Sexta',
  'Sábado',
  'Domingo',
] as const;

/** Só o pioneiro relata horas; o publicador relata participação e estudos. */
export function relataHoras(tipo: string): boolean {
  return tipo === 'auxiliar' || tipo === 'regular' || tipo === 'especial';
}

/** O ano de serviço vai de setembro a agosto. */
export function anoDeServico(mes: number, ano: number): number {
  return mes >= 9 ? ano + 1 : ano;
}

// ── Tipos dos registros ─────────────────────────────────────────────────────

export interface Relatorio extends RegistroDoBanco {
  id?: number;
  mes: number;
  ano: number;
  ano_servico: number;
  horas: number;
  estudos: number;
  participacao: number;
  tipo_publicador: string;
  meta_horas: number;
  notas_publicacoes: string;
  telefone_dirigente: string;
  nome_dirigente: string;
  relatorio_enviado: number;
  data_envio_relatorio: number;
}

export interface Contador extends RegistroDoBanco {
  id?: number;
  mes: number;
  ano: number;
  minutos: number;
  estudos: number;
  revisitas: number;
  publicacoes: number;
  videos: number;
  data_atualizacao?: number;
}

/** Os campos do contador que o +/− ajusta. */
export type CampoDoContador = 'minutos' | 'estudos' | 'revisitas' | 'publicacoes' | 'videos';

export interface Estudo extends RegistroDoBanco {
  id?: number;
  nome: string;
  contato: string;
  endereco: string;
  publicacao_atual: string;
  dia_semana: string;
  horario_minutos: number;
  notas: string;
}

export interface RegistroDeEstudo extends RegistroDoBanco {
  id?: number;
  estudo_id: number;
  registrado_em: number;
  onde_parou: string;
  comentario: string;
}

const relatorios = () => repositorio('relatorios_ministerio');
const contadores = () => repositorio('contadores_ministerio');
const estudos = () => repositorio('estudos_biblicos');
const registros = () => repositorio('estudo_registros');

// ── Carga ───────────────────────────────────────────────────────────────────

export interface Dados {
  readonly relatorios: Relatorio[];
  readonly estudos: Estudo[];
  readonly registros: RegistroDeEstudo[];
  readonly contador: Contador;
}

export async function carregar(): Promise<Dados> {
  const [lista, cadastros, linhaDoTempo, tally] = await Promise.all([
    relatorios().todos<Relatorio>(),
    estudos().todos<Estudo>(),
    registros().todos<RegistroDeEstudo>(),
    contadores().todos<Contador>(),
  ]);

  const agora = new Date();
  const mes = agora.getMonth() + 1;
  const ano = agora.getFullYear();

  // O contador é do mês corrente e só; sem registro, um zerado em memória, que
  // só vai ao banco quando o usuário mexer nele.
  const emBranco: Contador = {
    mes,
    ano,
    minutos: 0,
    estudos: 0,
    revisitas: 0,
    publicacoes: 0,
    videos: 0,
  };
  const contador = tally.find((item) => item.mes === mes && item.ano === ano) ?? emBranco;

  return { relatorios: lista, estudos: cadastros, registros: linhaDoTempo, contador };
}

// ── Formatação ──────────────────────────────────────────────────────────────

/** Minutos desde a meia-noite em `HH:MM` — o horário do estudo. */
export function comoHorario(minutos: number | undefined): string {
  const total = Math.max(0, Number(minutos) || 0);
  const horas = String(Math.floor(total / 60)).padStart(2, '0');
  return `${horas}:${String(total % 60).padStart(2, '0')}`;
}

/** `HH:MM` de volta para minutos, preso ao dia. */
export function deHorario(texto: string): number {
  const [horas = 0, minutos = 0] = texto.split(':').map(Number);
  return Math.max(0, Math.min(1439, horas * 60 + minutos));
}

export function mesEAno(mes: number, ano: number): string {
  return `${MESES[mes] ?? ''} ${ano}`;
}

// ── Relatórios ──────────────────────────────────────────────────────────────

/** Mais recentes primeiro. */
export function ordenarRelatorios(lista: readonly Relatorio[]): Relatorio[] {
  return [...lista].sort((a, b) => b.ano - a.ano || b.mes - a.mes);
}

export function ultimoRelatorio(lista: readonly Relatorio[]): Relatorio | null {
  return ordenarRelatorios(lista)[0] ?? null;
}

/** O mês que o lembrete cobra, quando há um a cobrar. */
export interface Lembrete {
  readonly mes: number;
  readonly ano: number;
  /** `true` quando o relatório existe mas não foi marcado como enviado. */
  readonly existe: boolean;
}

/**
 * O lembrete só aparece na janela em que o relatório costuma ser entregue: no
 * fim do mês (dia 26 em diante) ele cobra o mês corrente; no começo (até o dia
 * 10) cobra o anterior. No meio do mês não há nada a cobrar — e um aviso
 * permanente é um aviso que ninguém mais lê.
 */
export function lembreteDoRelatorio(
  lista: readonly Relatorio[],
  hoje: Date = new Date(),
): Lembrete | null {
  const dia = hoje.getDate();
  let mes: number;
  let ano: number;

  if (dia <= 10) {
    const anterior = new Date(hoje.getFullYear(), hoje.getMonth() - 1, 1);
    mes = anterior.getMonth() + 1;
    ano = anterior.getFullYear();
  } else if (dia >= 26) {
    mes = hoje.getMonth() + 1;
    ano = hoje.getFullYear();
  } else {
    return null;
  }

  const relatorio = lista.find((item) => item.mes === mes && item.ano === ano);
  if (relatorio !== undefined && relatorio.relatorio_enviado === 1) return null;

  return { mes, ano, existe: relatorio !== undefined };
}

/** O texto que vai no compartilhamento — o relatório como se entrega. */
export function textoDoRelatorio(relatorio: Relatorio): string {
  const linhas = [
    S.ministerio.relatorioDe(mesEAno(relatorio.mes, relatorio.ano)),
    S.ministerio.linhaTipo(
      TIPOS_PUBLICADOR[relatorio.tipo_publicador as TipoPublicador] ?? relatorio.tipo_publicador,
    ),
    S.ministerio.linhaParticipacao(relatorio.participacao === 1),
  ];

  if (relataHoras(relatorio.tipo_publicador)) {
    linhas.push(S.ministerio.linhaHoras(relatorio.horas));
  }
  linhas.push(S.ministerio.linhaEstudos(relatorio.estudos));

  if (relatorio.notas_publicacoes !== '') {
    linhas.push(S.ministerio.linhaObservacoes(relatorio.notas_publicacoes));
  }

  return linhas.join('\n');
}

export function salvarRelatorio(relatorio: Relatorio): Promise<number> {
  return relatorios().salvar({
    ...relatorio,
    ano_servico: anoDeServico(relatorio.mes, relatorio.ano),
  });
}

export function excluirRelatorio(id: number): Promise<void> {
  return relatorios().excluir(id);
}

/** Marca como enviado (com a data) ou volta a pendente. */
export function alternarEnviado(relatorio: Relatorio): Promise<number> {
  const enviado = relatorio.relatorio_enviado === 1 ? 0 : 1;

  return salvarRelatorio({
    ...relatorio,
    relatorio_enviado: enviado,
    data_envio_relatorio: enviado === 1 ? Date.now() : 0,
  });
}

// ── Contador do mês ─────────────────────────────────────────────────────────

export function contadorTemAtividade(contador: Contador): boolean {
  return (
    contador.minutos > 0 ||
    contador.estudos > 0 ||
    contador.revisitas > 0 ||
    contador.publicacoes > 0 ||
    contador.videos > 0
  );
}

/** Grava o contador e devolve a versão com o id, quando ele acabou de nascer. */
export async function salvarContador(contador: Contador): Promise<Contador> {
  const registro: Contador = {
    ...(contador.id === undefined ? {} : { id: contador.id }),
    mes: contador.mes,
    ano: contador.ano,
    minutos: Math.max(0, Number(contador.minutos) || 0),
    estudos: Math.max(0, Number(contador.estudos) || 0),
    revisitas: Math.max(0, Number(contador.revisitas) || 0),
    publicacoes: Math.max(0, Number(contador.publicacoes) || 0),
    videos: Math.max(0, Number(contador.videos) || 0),
    data_atualizacao: Date.now(),
  };

  const id = await contadores().salvar(registro);
  return { ...registro, id };
}

export function ajustado(contador: Contador, campo: CampoDoContador, passo: number): Contador {
  return { ...contador, [campo]: Math.max(0, (Number(contador[campo]) || 0) + passo) };
}

export function contadorZerado(contador: Contador): Contador {
  return { ...contador, minutos: 0, estudos: 0, revisitas: 0, publicacoes: 0, videos: 0 };
}

/**
 * As observações que o relatório oficial não tem campo para receber.
 *
 * Desde 2023 o relatório pede participação e estudos (mais horas, do pioneiro).
 * Revisitas, publicações, vídeos e tempo continuam no contador porque são
 * acompanhamento pessoal — e vão para as observações em vez de se perderem.
 */
export function observacoesDoContador(contador: Contador): string {
  return [
    contador.revisitas > 0 ? S.ministerio.obsRevisitas(contador.revisitas) : '',
    contador.publicacoes > 0 ? S.ministerio.obsPublicacoes(contador.publicacoes) : '',
    contador.videos > 0 ? S.ministerio.obsVideos(contador.videos) : '',
    contador.minutos > 0 ? S.ministerio.obsTempo(comoHorario(contador.minutos)) : '',
  ]
    .filter((parte) => parte !== '')
    .join(' · ');
}

/** Minutos em horas de meia em meia — a unidade em que as horas são relatadas. */
export function horasDoContador(minutos: number): number {
  return Math.round((minutos / 60) * 2) / 2;
}

// ── Estudos (o CRM e o L7) ──────────────────────────────────────────────────

/** A linha do tempo de um estudo, mais recente primeiro. */
export function registrosDoEstudo(
  todos: readonly RegistroDeEstudo[],
  estudoId: number | undefined,
): RegistroDeEstudo[] {
  if (estudoId === undefined) return [];

  return todos
    .filter((registro) => registro.estudo_id === estudoId)
    .sort((a, b) => (b.registrado_em || 0) - (a.registrado_em || 0));
}

/** Epoch do registro mais recente; 0 quando o estudo nunca foi registrado. */
export function ultimoRegistroEm(todos: readonly RegistroDeEstudo[], estudo: Estudo): number {
  return registrosDoEstudo(todos, estudo.id)[0]?.registrado_em ?? 0;
}

/** L7: sem registro há 15 dias ou mais — ou nunca registrado. */
export function estaEsfriando(todos: readonly RegistroDeEstudo[], estudo: Estudo): boolean {
  const ultimo = ultimoRegistroEm(todos, estudo);
  return ultimo === 0 || Date.now() - ultimo >= L7_MS;
}

export function esfriando(lista: readonly Estudo[], todos: readonly RegistroDeEstudo[]): Estudo[] {
  return lista.filter((estudo) => estaEsfriando(todos, estudo));
}

/** Iniciais para o avatar: a primeira letra do primeiro e do último nome. */
export function iniciais(estudo: Estudo): string {
  const partes = (estudo.nome === '' ? '?' : estudo.nome).trim().split(/\s+/);
  const primeira = partes[0]?.[0] ?? '';
  const ultima = partes.length > 1 ? (partes.at(-1)?.[0] ?? '') : '';

  return (primeira + ultima || '?').toUpperCase();
}

const CORES_AVATAR = [
  '#0d6efd',
  '#6f42c1',
  '#20c997',
  '#fd7e14',
  '#0dcaf0',
  '#d63384',
  '#198754',
  '#6610f2',
] as const;

/**
 * Cor estável derivada do nome: a mesma pessoa tem sempre o mesmo avatar, sem
 * guardar cor nenhuma no registro.
 */
export function corDoEstudo(estudo: Estudo): string {
  let hash = 0;
  for (const caractere of estudo.nome) hash = (hash * 31 + caractere.charCodeAt(0)) >>> 0;

  return CORES_AVATAR[hash % CORES_AVATAR.length] ?? CORES_AVATAR[0];
}

/** O último estudo em linguagem de gente: hoje, ontem, "há N dias". */
export interface Relativo {
  readonly texto: string;
  readonly tom: 'nunca' | 'recente' | 'frio' | 'normal';
}

export function ultimoRelativo(todos: readonly RegistroDeEstudo[], estudo: Estudo): Relativo {
  const ultimo = ultimoRegistroEm(todos, estudo);
  if (ultimo === 0) return { texto: S.ministerio.nenhumRegistro, tom: 'nunca' };

  // Comparação por dia civil, e não por 24 h: um estudo das 21h de ontem é
  // "ontem", não "há 0 dias".
  const hoje = new Date().setHours(0, 0, 0, 0);
  const dias = Math.round((hoje - new Date(ultimo).setHours(0, 0, 0, 0)) / 86_400_000);

  if (dias <= 0) return { texto: S.ministerio.hoje, tom: 'recente' };
  if (dias === 1) return { texto: S.ministerio.ontem, tom: 'recente' };

  return { texto: S.ministerio.haDias(dias), tom: dias >= L7_DIAS ? 'frio' : 'normal' };
}

/** Filtra pela busca e ordena: esfriando primeiro, depois o registro mais novo. */
export function estudosVisiveis(
  lista: readonly Estudo[],
  todos: readonly RegistroDeEstudo[],
  busca: string,
): Estudo[] {
  const alvo = busca.trim().toLowerCase();

  const filtrados =
    alvo === ''
      ? [...lista]
      : lista.filter(
          (estudo) =>
            estudo.nome.toLowerCase().includes(alvo) ||
            estudo.contato.toLowerCase().includes(alvo) ||
            estudo.publicacao_atual.toLowerCase().includes(alvo),
        );

  return filtrados.sort((a, b) => {
    const frios = Number(estaEsfriando(todos, a)) - Number(estaEsfriando(todos, b));
    if (frios !== 0) return -frios;

    return ultimoRegistroEm(todos, b) - ultimoRegistroEm(todos, a);
  });
}

/** O texto do compartilhamento de um estudo: o que se passa a outro publicador. */
export function textoDoEstudo(estudo: Estudo, todos: readonly RegistroDeEstudo[]): string {
  const ultimo = registrosDoEstudo(todos, estudo.id)[0];

  return [
    S.ministerio.estudoDe(estudo.nome),
    estudo.publicacao_atual === '' ? '' : S.ministerio.linhaPublicacao(estudo.publicacao_atual),
    ultimo === undefined ? '' : S.ministerio.linhaOndeParou(ultimo.onde_parou),
    estudo.dia_semana === ''
      ? ''
      : S.ministerio.linhaDia(estudo.dia_semana, comoHorario(estudo.horario_minutos)),
    estudo.contato === '' ? '' : S.ministerio.linhaContato(estudo.contato),
    estudo.endereco === '' ? '' : S.ministerio.linhaEndereco(estudo.endereco),
  ]
    .filter((linha) => linha !== '')
    .join('\n');
}

export function salvarEstudo(estudo: Estudo): Promise<number> {
  return estudos().salvar(estudo);
}

/**
 * Apaga o estudo e a linha do tempo dele. Os registros não têm cascade — o store
 * é um par chave/valor —, então quem responde pela integridade é este código.
 */
export async function excluirEstudo(id: number, todos: readonly RegistroDeEstudo[]): Promise<void> {
  for (const registro of registrosDoEstudo(todos, id)) {
    if (registro.id !== undefined) await registros().excluir(registro.id);
  }

  await estudos().excluir(id);
}

// ── Linha do tempo ──────────────────────────────────────────────────────────

export function salvarRegistro(registro: RegistroDeEstudo): Promise<number> {
  return registros().salvar(registro);
}

export function excluirRegistro(id: number): Promise<void> {
  return registros().excluir(id);
}
