/**
 * A derivação guiada do "Entenda Melhor" — arquétipo `etapas`.
 *
 * Os módulos desta categoria não escondem uma resposta para o investigador
 * adivinhar: eles CONDUZEM um raciocínio que costuma travar as pessoas, quebrado
 * numa trilha de passos curtos. Cada passo tem uma pergunta, UM controle e uma
 * leitura ao vivo — quem move o controle vê a conta se formar e fecha o passo
 * sozinho. No fim, a pessoa refez a derivação inteira com as próprias mãos, em
 * vez de ler uma tabela pronta.
 *
 * `fase` nomeia o que a cena 3D mostra; `medir(v)` é a fonte única da leitura,
 * do erro e do que a viz desenha.
 */

import { S } from '../../../strings.ts';
import {
  ACERTO,
  type Info,
  type Opcao,
  type PassoVisivel,
  type Puzzle,
  type Renderizador,
  type Resultado,
  type Valores,
  type VizSpec,
} from './base.ts';

/** O que uma medição de passo devolve, além dos campos que a viz consome. */
export interface Medida {
  readonly ok: boolean;
  readonly leitura: string;
  readonly erro?: string;
  readonly [campo: string]: unknown;
}

interface PassoComum {
  readonly id: string;
  /** Nome da cena que a viz monta neste passo. */
  readonly fase: string;
  readonly titulo: string;
  readonly pergunta: string;
  readonly verso: string;
  /** O texto que fica registrado quando o passo fecha. */
  readonly acerto: string;
  /**
   * Só para o passo cuja conclusão é PREMISSA do seguinte — a régua que o
   * próximo usa, ou um elo de uma conta única. Aí ela continua em cena, porque
   * sem ela a pergunta nova não se sustenta. Fora esses casos, cada fase mostra
   * apenas os próprios textos: conclusão de fase encerrada não acompanha a
   * seguinte.
   */
  readonly encadeia?: boolean;
}

export interface PassoEscolha extends PassoComum {
  readonly entrada: 'escolha';
  readonly opcoes: readonly Opcao[];
  readonly correta: string;
  /** Resposta a cada opção errada — é onde o ensino de fato acontece. */
  readonly erros: Readonly<Record<string, string>>;
}

export interface PassoSlider extends PassoComum {
  readonly entrada: 'slider';
  readonly prop: string;
  readonly rotulo: string;
  readonly suf?: string;
  readonly min: number;
  readonly max: number;
  readonly step: number;
  readonly inicial: number;
  medir(valor: number): Medida;
}

export type Passo = PassoEscolha | PassoSlider;

/** Mede o passo atual com os valores em tela — fonte única de `info` e `check`. */
function medirPasso(puzzle: Puzzle, passos: readonly Passo[]): Medida & { readonly passo: Passo } {
  const passo = passos[puzzle.atual ?? 0] ?? passos[0];
  if (passo === undefined) return { passo: passos[0] as Passo, ok: false, leitura: '' };

  if (passo.entrada === 'escolha') {
    const ok = puzzle.escolhido === passo.correta;
    return {
      passo,
      ok,
      escolhido: puzzle.escolhido,
      leitura: ok ? passo.acerto : '',
      erro: passo.erros[puzzle.escolhido ?? ''] ?? S.criacao.erro,
    };
  }

  const bruto = puzzle.valores[passo.prop];
  const valor = typeof bruto === 'number' && Number.isFinite(bruto) ? bruto : passo.inicial;
  return { passo, ...passo.medir(valor) };
}

function valoresIniciais(passos: readonly Passo[]): Valores {
  const valores: Valores = {};
  for (const passo of passos) {
    if (passo.entrada === 'slider') valores[passo.prop] = passo.inicial;
  }
  return valores;
}

/** Só os campos que o markup lê — `medir` fica de fora do estado. */
function visiveis(passos: readonly Passo[]): PassoVisivel[] {
  return passos.map((passo) =>
    passo.entrada === 'escolha'
      ? {
          id: passo.id,
          titulo: passo.titulo,
          pergunta: passo.pergunta,
          verso: passo.verso,
          entrada: 'escolha',
          opcoes: passo.opcoes,
        }
      : {
          id: passo.id,
          titulo: passo.titulo,
          pergunta: passo.pergunta,
          verso: passo.verso,
          entrada: 'slider',
          prop: passo.prop,
          rotulo: passo.rotulo,
          ...(passo.suf === undefined ? {} : { suf: passo.suf }),
          min: passo.min,
          max: passo.max,
          step: passo.step,
        },
  );
}

/**
 * Monta o renderizador de uma trilha. Toda derivação guiada tem o mesmo
 * esqueleto: sliders no valor inicial, leitura do passo atual e um `verificar`
 * que fecha o passo e libera o seguinte — o último conclui o módulo.
 */
export function trilha(passos: readonly Passo[], viz: VizSpec): Renderizador {
  return {
    arquetipo: 'etapas',
    criar() {
      const puzzle: Puzzle = {
        arquetipo: 'etapas',
        extra: viz.comp,
        viz,
        passos: visiveis(passos),
        atual: 0,
        escolhido: null,
        // Só a conclusão de um passo `encadeia` atravessa a virada de fase, e
        // num bloco próprio, rotulado: no legado ela sobrava no feedback do
        // botão, onde parecia a resposta da pergunta nova.
        conclusao: null,
        conclusaoTitulo: '',
        valores: valoresIniciais(passos),
      };

      return {
        puzzle,
        info: (): Info => {
          // `passo` fica de fora: o snapshot da viz precisa ser dado puro.
          const { passo, ...medida } = medirPasso(puzzle, passos);
          return {
            ...medida,
            fase: passo.fase,
            idx: puzzle.atual ?? 0,
            total: passos.length,
          };
        },
        verificar: (): Resultado => {
          const medida = medirPasso(puzzle, passos);
          if (!medida.ok) return { tipo: 'erro', mensagem: medida.erro ?? S.criacao.erro };

          const atual = puzzle.atual ?? 0;
          // O último passo fecha o módulo; os demais liberam o seguinte.
          if (atual >= passos.length - 1) return { tipo: 'ok', mensagem: medida.passo.acerto };

          const encadeia = medida.passo.encadeia === true;
          puzzle.conclusao = encadeia ? medida.passo.acerto : null;
          puzzle.conclusaoTitulo = encadeia ? medida.passo.titulo : '';
          puzzle.atual = atual + 1;
          puzzle.escolhido = null;
          return { tipo: 'avanco' };
        },
      };
    },
  };
}

export { ACERTO };
