/**
 * Favoritos por módulo — porte de `util/favoritos.js` do legado.
 *
 * Ficam em `localStorage`, e não no banco: são preferência de aparelho, não
 * conteúdo. Um acervo curado é substituído inteiro a cada sincronização, e
 * gravar a estrela dentro do registro a perderia junto.
 *
 * A chave de cada item é a origem mais o id (`c12`, `l3`): o mesmo número pode
 * existir no acervo curado e no local, e são coisas diferentes.
 */

export type Origem = 'curado' | 'local';

export function chaveFavorito(origem: Origem, id: number | undefined): string {
  return (origem === 'local' ? 'l' : 'c') + String(id ?? '');
}

export function lerFavoritos(chave: string): Set<string> {
  try {
    const bruto = JSON.parse(localStorage.getItem(chave) ?? '[]') as unknown;
    return new Set(Array.isArray(bruto) ? bruto.map(String) : []);
  } catch {
    return new Set();
  }
}

export function salvarFavoritos(chave: string, favoritos: ReadonlySet<string>): void {
  localStorage.setItem(chave, JSON.stringify([...favoritos]));
}

/** Liga/desliga o favorito e devolve o conjunto novo, já persistido. */
export function alternarFavorito(
  chave: string,
  favoritos: ReadonlySet<string>,
  item: string,
): Set<string> {
  const novo = new Set(favoritos);
  if (!novo.delete(item)) novo.add(item);
  salvarFavoritos(chave, novo);
  return novo;
}
