type SubTela = 'painel' | 'kits' | 'estoque' | 'cofre' | 'checklist';

interface FormChecklist {
  id: number;
  nome: string;
  icone: string;
  itens: ItemEmEdicao[];
  criacao: number;
}

interface FormItemDoEstoque {
  id: number;
  item: string;
  categoria: string;
  quantidade: number;
  peso: number;
  kcal: number;
  vencimento: string;
}

let kits: Kit[] = [];
let progresso: Progresso = {};
let estoque: ItemDoEstoque[] = [];
let perfil: Perfil = lerPerfil();

let expandidos = new Set<string>();
let gruposAbertos = new Set<string>();
let alertasAbertos = false;
let buscaEstoque = '';

let formChecklist: FormChecklist | null = null;
let formItem: FormItemDoEstoque | null = null;

/** O PIN só existe em memória, e só enquanto o cofre está aberto. */
let pinNaMemoria: string | null = null;
let documentos: Documento[] = [];
let pinDigitado = '';
let pinConfirmacao = '';
let erroDoCofre = '';
let previa: { rotulo: string; url: string; tipo: string } | null = null;

let carregado = false;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregar(): Promise<void> {
  [kits, estoque] = await Promise.all([carregarKits(), carregarEstoque()]);
  progresso = lerProgresso();
  atualizar();
}

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;
  vigiarSaida();

  void (async () => {
    try {
      await recarregar();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

function subTelaDe(rota: Rota): SubTela {
  const sub = rota.args[0];
  if (sub === 'kits' || sub === 'estoque' || sub === 'cofre' || sub === 'checklist') return sub;
  return 'painel';
}

function trancarCofre(): void {
  pinNaMemoria = null;
  documentos = [];
  pinDigitado = '';
  pinConfirmacao = '';
  erroDoCofre = '';
  fecharPrevia();
}

function fecharPrevia(): void {
  if (previa !== null) URL.revokeObjectURL(previa.url);
  previa = null;
}

let vigiando = false;

/**
 * Sair de `#/prep/cofre` tranca o cofre — inclusive ao ir para outra sub-tela do
 * próprio módulo. A casca não avisa quando uma tela sai de cena, então quem
 * observa é o hash, como o `_sincronizar` do legado fazia.
 */
function vigiarSaida(): void {
  if (vigiando) return;
  vigiando = true;

  addEventListener('hashchange', () => {
    const partes = location.hash.replace(/^#\/?/, '').split('/');
    if (partes[0] === 'prep' && partes[1] === 'cofre') return;

    trancarCofre();
  });
}

// ── Painel ──────────────────────────────────────────────────────────────────

function telaDoPainel(): TemplateResult {
  const percentual = calcularProntidao({ kits, progresso, estoque, perfil });
  const tom = tomDaProntidao(percentual);
  const autonomia = calcularAutonomia(estoque, perfil);

  return html`
    <div class="prontidao" data-tom=${tom}>
      <div class="prontidao__topo">
        <span class="prontidao__texto">
          ${S.prep.indice}
          <small>${S.prep.indiceAjuda}</small>
        </span>
        <span class="prontidao__percentual">${percentual}%</span>
      </div>
      <div class="prontidao__barra" role="presentation">
        <div class="prontidao__preenchido" style=${`width:${percentual}%`}></div>
      </div>
    </div>

    <div class="atalhos atalhos--quatro">
      ${(
        [
          ['clipboard-list', S.prep.kits, S.prep.contagemKits(kits.length), 'prep/kits'],
          ['package', S.prep.estoque, S.prep.diasAutonomia(autonomia.dias), 'prep/estoque'],
          ['lock', S.prep.cofre, S.prep.cofreResumo, 'prep/cofre'],
          ['map-2', S.prep.guias, S.prep.guiasResumo, 'guias'],
        ] as const
      ).map(
        ([icone, rotulo, resumo, destino]) => html`
          <button class="atalho" @click=${() => navegar(destino)}>
            <st-icon class="atalho__icone" name=${icone}></st-icon>
            <span class="atalho__rotulo">${rotulo}</span>
            <span class="atalho__resumo">${resumo}</span>
          </button>
        `,
      )}
    </div>
  `;
}

// ── Kits ────────────────────────────────────────────────────────────────────

function telaDosKits(): TemplateResult {
  if (kits.length === 0) {
    return html`
      <div class="vazio">
        <st-icon class="vazio__icone" name="clipboard-list"></st-icon>
        <p>${S.prep.semKits}</p>
      </div>
    `;
  }

  return html`
    <div class="livros">
      ${kits.map((kit) => {
        const chave = String(kit.id);
        const aberto = expandidos.has(chave);
        const completo = kitCompleto(progresso, kit);

        return html`
          <div class="livro" ?data-completo=${completo}>
            <button
              type="button"
              class="livro__alvo"
              aria-expanded=${aberto}
              @click=${() => {
                const novo = new Set(expandidos);
                if (!novo.delete(chave)) novo.add(chave);
                expandidos = novo;
                atualizar();
              }}
            >
              <span class="livro__icone">${kit.icone === '' ? '📋' : kit.icone}</span>
              <span class="livro__nome">${kit.nome}</span>
              <span class="livro__contagem">
                ${marcadosDoKit(progresso, kit)}/${kit.itens.length}
              </span>
              <st-icon name=${aberto ? 'chevron-up' : 'chevron-down'}></st-icon>
            </button>

            <div class="progresso-leitura__barra" role="presentation">
              <div
                class="progresso-leitura__preenchido"
                style=${`width:${percentualDoKit(progresso, kit)}%`}
              ></div>
            </div>

            ${
              aberto
                ? html`
                  <div class="itens-do-kit">
                    ${kit.itens.map(
                      (item) => html`
                        <button
                          class="item-do-kit"
                          ?data-marcado=${itemMarcado(progresso, kit, item.id)}
                          aria-pressed=${itemMarcado(progresso, kit, item.id)}
                          @click=${() => {
                            progresso = alternarItem(progresso, kit, item.id);
                            atualizar();
                          }}
                        >
                          <st-icon
                            name=${itemMarcado(progresso, kit, item.id) ? 'circle-check' : 'circle'}
                          ></st-icon>
                          <span class="item-do-kit__texto">
                            <span class="item-do-kit__descricao">${item.descricao}</span>
                            ${
                              item.quantidade === '' &&
                              item.observacoes === '' &&
                              item.data_vencimento === 0
                                ? nothing
                                : html`
                                  <span class="item-do-kit__detalhe">
                                    ${item.quantidade === '' ? '' : item.quantidade}
                                    ${item.observacoes === '' ? '' : `· ${item.observacoes}`}
                                    ${
                                      item.data_vencimento === 0
                                        ? ''
                                        : `· ${S.prep.vence(dataBR(item.data_vencimento))}`
                                    }
                                  </span>
                                `
                            }
                          </span>
                        </button>
                      `,
                    )}
                  </div>

                  <div class="capitulos__acoes">
                    <st-button
                      size="small"
                      outline
                      @click=${() => navegar(`prep/checklist/${kit.id ?? ''}`)}
                    >
                      <st-icon slot="prefix" name="pencil"></st-icon>${S.acoes.editar}
                    </st-button>
                    <st-button
                      size="small"
                      variant="danger"
                      outline
                      @click=${() => void apagarKit(kit)}
                    >
                      <st-icon slot="prefix" name="trash"></st-icon>${S.acoes.excluir}
                    </st-button>
                  </div>
                `
                : nothing
            }
          </div>
        `;
      })}
    </div>
  `;
}

async function apagarKit(kit: Kit): Promise<void> {
  const ok = await confirmar({
    titulo: S.prep.excluirKit,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  progresso = await excluirKit(kit, progresso);
  notificar(S.prep.kitExcluido);
  await recarregar();
}

// ── Editor de checklist ─────────────────────────────────────────────────────

function itemVazio(): ItemEmEdicao {
  return { id: 0, descricao: '', quantidade: '', observacoes: '', vencimento: '' };
}

let checklistCarregado: string | null = null;

/** Monta o formulário quando a rota do editor muda. */
function prepararChecklist(rota: Rota): void {
  const chave = rota.args.join('/');
  if (checklistCarregado === chave) return;
  checklistCarregado = chave;

  const bruto = rota.args[1];

  if (bruto === undefined) {
    formChecklist = { id: 0, nome: '', icone: '', itens: [itemVazio()], criacao: 0 };
    atualizar();
    return;
  }

  void (async () => {
    const kit = await obterKit(Number.parseInt(bruto, 10));
    if (kit === undefined) {
      navegar('prep/kits');
      return;
    }

    formChecklist = {
      id: kit.id ?? 0,
      nome: kit.nome,
      icone: kit.icone,
      criacao: kit.data_criacao,
      itens:
        kit.itens.length === 0
          ? [itemVazio()]
          : kit.itens.map((item) => ({
              id: item.id,
              descricao: item.descricao,
              quantidade: item.quantidade,
              observacoes: item.observacoes,
              vencimento: item.data_vencimento === 0 ? '' : dataLocalISO(item.data_vencimento),
            })),
    };
    atualizar();
  })();
}

function telaDoChecklist(form: FormChecklist): TemplateResult {
  const trocar = (indice: number, campo: keyof ItemEmEdicao, valor: string): void => {
    const itens = form.itens.map((item, i) => (i === indice ? { ...item, [campo]: valor } : item));
    formChecklist = { ...form, itens };
  };

  return html`
    <div class="formulario">
      <st-input
        label=${S.prep.nomeDoKit}
        .value=${form.nome}
        @st-input=${(evento: Event) => {
          formChecklist = { ...form, nome: (evento.target as HTMLInputElement).value };
        }}
      ></st-input>

      <st-input
        label=${S.prep.emoji}
        maxlength="4"
        .value=${form.icone}
        help-text=${S.prep.emojiAjuda}
        @st-input=${(evento: Event) => {
          formChecklist = { ...form, icone: (evento.target as HTMLInputElement).value };
        }}
      ></st-input>

      <h2 class="secao">${S.prep.itens}</h2>

      ${form.itens.map(
        (item, indice) => html`
          <div class="item-editor">
            <div class="item-editor__topo">
              <st-input
                class="item-editor__descricao"
                placeholder=${S.prep.descricaoDoItem}
                .value=${item.descricao}
                @st-input=${(evento: Event) =>
                  trocar(indice, 'descricao', (evento.target as HTMLInputElement).value)}
              ></st-input>
              <st-icon-button
                name="trash"
                label=${S.prep.removerItem}
                @click=${() => void removerItem(form, indice)}
              ></st-icon-button>
            </div>

            <div class="formulario__par">
              <st-input
                size="small"
                placeholder=${S.prep.quantidade}
                .value=${item.quantidade}
                @st-input=${(evento: Event) =>
                  trocar(indice, 'quantidade', (evento.target as HTMLInputElement).value)}
              ></st-input>
              <st-input
                size="small"
                type="date"
                .value=${item.vencimento}
                @st-change=${(evento: Event) =>
                  trocar(indice, 'vencimento', (evento.target as HTMLInputElement).value)}
              ></st-input>
            </div>

            <st-input
              size="small"
              placeholder=${S.prep.observacoes}
              .value=${item.observacoes}
              @st-input=${(evento: Event) =>
                trocar(indice, 'observacoes', (evento.target as HTMLInputElement).value)}
            ></st-input>
          </div>
        `,
      )}

      <st-button
        outline
        @click=${() => {
          formChecklist = { ...form, itens: [...form.itens, itemVazio()] };
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="plus"></st-icon>${S.prep.adicionarItem}
      </st-button>

      <div class="editor__acoes">
        <st-button variant="primary" @click=${() => void gravarChecklist(form)}>
          <st-icon slot="prefix" name="check"></st-icon>${S.acoes.salvar}
        </st-button>
        <st-button @click=${() => navegar('prep/kits')}>${S.acoes.cancelar}</st-button>
      </div>
    </div>
  `;
}

async function removerItem(form: FormChecklist, indice: number): Promise<void> {
  const ok = await confirmar({
    titulo: S.prep.removerItem,
    texto: S.prep.removerItemTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  formChecklist = { ...form, itens: form.itens.filter((_, i) => i !== indice) };
  atualizar();
}

async function gravarChecklist(form: FormChecklist): Promise<void> {
  const temItem = form.itens.some((item) => item.descricao.trim() !== '');

  // Nada preenchido é desistência, não erro: volta sem gravar um kit vazio.
  if (form.nome.trim() === '' && !temItem) {
    navegar('prep/kits');
    return;
  }

  await salvarKit(form);
  formChecklist = null;
  checklistCarregado = null;
  notificar(S.prep.kitSalvo);
  await recarregar();
  navegar('prep/kits');
}

// ── Estoque ─────────────────────────────────────────────────────────────────

function itemNovo(): FormItemDoEstoque {
  return {
    id: 0,
    item: '',
    categoria: CATEGORIA_PADRAO,
    quantidade: 1,
    peso: 0,
    kcal: 0,
    vencimento: '',
  };
}

async function gravarItem(form: FormItemDoEstoque): Promise<void> {
  await salvarItem({
    ...(form.id > 0 ? { id: form.id } : {}),
    item: form.item.trim(),
    categoria: form.categoria === '' ? CATEGORIA_PADRAO : form.categoria,
    quantidade: Number(form.quantidade),
    peso_unitario: Number(form.peso),
    calorias_por_100g: Number(form.kcal),
    data_vencimento: form.vencimento === '' ? 0 : epochDoVencimento(form.vencimento),
  });

  formItem = null;
  notificar(S.prep.itemSalvo);
  await recarregar();
}

function epochDoVencimento(ymd: string): number {
  const [ano = 1970, mes = 1, dia = 1] = ymd.split('-').map(Number);
  return new Date(ano, mes - 1, dia).getTime();
}

