function calculadora(autonomia: Autonomia): TemplateResult {
  const trocar = (novo: Partial<Perfil>): void => {
    perfil = { ...perfil, ...novo, pessoas: Math.max(1, novo.pessoas ?? perfil.pessoas) };
    salvarPerfil(perfil);
    atualizar();
  };

  const logistica = calcularLogistica(estoque, perfil);

  return html`
    <div class="tally">
      <div class="tally__topo">
        <st-icon class="tally__icone" name="calculator"></st-icon>
        <span class="tally__titulo">
          ${S.prep.calculadora}
          <small>${S.prep.calculadoraAjuda}</small>
        </span>
      </div>

      <div class="formulario__par">
        <st-select
          label=${S.prep.faixaEtaria}
          size="small"
          .value=${perfil.idade}
          @st-change=${(evento: Event) =>
            trocar({ idade: (evento.target as HTMLInputElement).value as Perfil['idade'] })}
        >
          ${FAIXAS.map(
            (faixa) => html`<st-option value=${faixa}>${rotuloDaFaixa(faixa)}</st-option>`,
          )}
        </st-select>

        <st-select
          label=${S.prep.atividade}
          size="small"
          .value=${perfil.atividade}
          @st-change=${(evento: Event) =>
            trocar({
              atividade: (evento.target as HTMLInputElement).value as Perfil['atividade'],
            })}
        >
          ${NIVEIS.map(
            (nivel) => html`<st-option value=${nivel}>${rotuloDoNivel(nivel)}</st-option>`,
          )}
        </st-select>
      </div>

      <div class="tally__linha">
        <span class="tally__nome"><st-icon name="users"></st-icon>${S.prep.pessoas}</span>
        <st-icon-button
          name="minus"
          label=${S.prep.menosPessoas}
          @click=${() => trocar({ pessoas: perfil.pessoas - 1 })}
        ></st-icon-button>
        <span class="tally__valor">${perfil.pessoas}</span>
        <st-icon-button
          name="plus"
          label=${S.prep.maisPessoas}
          @click=${() => trocar({ pessoas: perfil.pessoas + 1 })}
        ></st-icon-button>
      </div>

      <div class="placares">
        <div class="placar">
          <span class="placar__valor" data-tom=${autonomia.tom === 'sucesso' ? 'sucesso' : autonomia.tom === 'aviso' ? 'aviso' : 'perigo'}>
            ${autonomia.dias}
          </span>
          <span class="placar__rotulo">${S.prep.diasDeAutonomia}</span>
        </div>
        <div class="placar">
          <span class="placar__valor">${numero(autonomia.litrosDeAgua)} L</span>
          <span class="placar__rotulo">${S.prep.aguaSugerida}</span>
        </div>
        <div class="placar">
          <span class="placar__valor">${numero(autonomia.pesoTotalKg)} kg</span>
          <span class="placar__rotulo">${S.prep.pesoTotal}</span>
        </div>
      </div>

      <div class="progresso-leitura__barra" role="presentation">
        <div
          class="progresso-leitura__preenchido"
          style=${`width:${autonomia.metaPercentual}%`}
        ></div>
      </div>
      <p class="discreto">
        ${S.prep.metaAutonomia(autonomia.metaPercentual)} ·
        ${S.prep.necessidadeDiaria(numero(autonomia.doGrupo))}
      </p>

      <h3 class="secao">${S.prep.logistica}</h3>
      <div class="placares">
        <div class="placar">
          <span class="placar__valor">${logistica.diasFrios}</span>
          <span class="placar__rotulo">${S.prep.diasSemFogo}</span>
        </div>
        <div class="placar">
          <span class="placar__valor">${logistica.diasTotais}</span>
          <span class="placar__rotulo">${S.prep.diasComFogo}</span>
        </div>
        <div class="placar">
          <span class="placar__valor" data-tom=${logistica.vulneravel ? 'perigo' : 'sucesso'}>
            ${logistica.fibras}
          </span>
          <span class="placar__rotulo">${S.prep.itensDeFibra}</span>
        </div>
      </div>

      ${
        logistica.vulneravel
          ? html`
            <st-alert variant="warning" open>
              <st-icon slot="icon" name="alert-triangle"></st-icon>
              ${S.prep.vulneravel}
            </st-alert>
          `
          : nothing
      }
    </div>
  `;
}

function pilulaDeValidade(item: ItemDoEstoque): TemplateResult | typeof nothing {
  const dias = diasParaVencer(item);
  if (dias === null) return nothing;

  if (dias < 0) {
    return html`<st-badge variant="danger" pill>${S.prep.vencidoHa(Math.abs(dias))}</st-badge>`;
  }
  if (dias === 0) return html`<st-badge variant="danger" pill>${S.prep.venceHoje}</st-badge>`;
  if (dias < 7) return html`<st-badge variant="warning" pill>${S.prep.venceEm(dias)}</st-badge>`;

  return nothing;
}

function linhaDoEstoque(item: ItemDoEstoque): TemplateResult {
  const info = categoria(item.categoria);
  const kcal = caloriasDoItem(item);

  return html`
    <div class="registro" data-status=${statusDeValidade(item)}>
      <span class="registro__avatar" style=${`background:color-mix(in oklab, ${info.cor} 15%, transparent)`}>
        ${info.emoji}
      </span>

      <button class="registro__alvo" @click=${() => void editarItemDoEstoque(item)}>
        <span class="registro__topo">
          <span class="registro__titulo">${item.item}</span>
          ${pilulaDeValidade(item)}
        </span>
        <span class="registro__resumo">
          ${S.prep.resumoDoItem(item.quantidade, numero(item.peso_unitario))}
          ${kcal === null ? '' : `· ${numero(kcal)} kcal`}
        </span>
        ${
          item.data_vencimento === 0
            ? nothing
            : html`<span class="registro__resumo">${S.prep.vence(dataBR(item.data_vencimento))}</span>`
        }
      </button>

      <div class="registro__acoes">
        <st-icon-button
          name="pencil"
          label=${S.acoes.editar}
          @click=${() => void editarItemDoEstoque(item)}
        ></st-icon-button>
        <st-icon-button
          name="trash"
          label=${S.prep.excluirItem}
          @click=${() => void apagarItem(item)}
        ></st-icon-button>
      </div>
    </div>
  `;
}

async function editarItemDoEstoque(item: ItemDoEstoque): Promise<void> {
  if (item.id === undefined) return;

  const atual = (await obterItem(item.id)) ?? item;
  formItem = {
    id: atual.id ?? 0,
    item: atual.item,
    categoria: atual.categoria,
    quantidade: atual.quantidade,
    peso: atual.peso_unitario,
    kcal: atual.calorias_por_100g,
    vencimento: atual.data_vencimento === 0 ? '' : dataLocalISO(atual.data_vencimento),
  };
  atualizar();
}

async function apagarItem(item: ItemDoEstoque): Promise<void> {
  const ok = await confirmar({
    titulo: S.prep.excluirItem,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok || item.id === undefined) return;

  await excluirItem(item.id);
  notificar(S.prep.itemExcluido);
  await recarregar();
}

function telaDoEstoque(): TemplateResult {
  if (formItem !== null) return formularioDoItem(formItem);

  const autonomia = calcularAutonomia(estoque, perfil);
  const aviso = alertas(estoque);
  const grupos = porCategoria(visiveis(estoque, buscaEstoque));

  return html`
    ${
      aviso.total === 0
        ? nothing
        : html`
          <div class="alertas">
            <button
              class="alertas__alvo"
              aria-expanded=${alertasAbertos}
              @click=${() => {
                alertasAbertos = !alertasAbertos;
                atualizar();
              }}
            >
              <st-icon name="alert-triangle"></st-icon>
              <span class="alertas__titulo">${S.prep.alertas(aviso.total)}</span>
              <st-icon name=${alertasAbertos ? 'chevron-up' : 'chevron-down'}></st-icon>
            </button>

            ${
              alertasAbertos
                ? html`
                  <div class="alertas__lista">
                    ${[...aviso.vencidos, ...aviso.aVencer].map(
                      (item) => html`
                        <span class="alertas__item">
                          ${pilulaDeValidade(item)}
                          <span>${item.item}</span>
                        </span>
                      `,
                    )}
                  </div>
                `
                : nothing
            }
          </div>
        `
    }

    ${calculadora(autonomia)}

    <div class="filtros">
      <st-input
        class="filtros__busca"
        type="search"
        clearable
        placeholder=${S.prep.buscarItens}
        .value=${buscaEstoque}
        @st-input=${(evento: Event) => {
          buscaEstoque = (evento.target as HTMLInputElement).value;
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="search"></st-icon>
      </st-input>
    </div>

    ${
      grupos.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="package"></st-icon>
            <p>${estoque.length === 0 ? S.prep.semEstoque : S.prep.semEstoqueFiltro}</p>
          </div>
        `
        : html`
          <div class="grupos">
            ${grupos.map((grupo) => {
              const aberto = gruposAbertos.has(grupo.nome);

              return html`
                <div class="grupo">
                  <button
                    class="grupo__alvo"
                    aria-expanded=${aberto}
                    @click=${() => {
                      const novo = new Set(gruposAbertos);
                      if (!novo.delete(grupo.nome)) novo.add(grupo.nome);
                      gruposAbertos = novo;
                      atualizar();
                    }}
                  >
                    <span class="grupo__emoji">${grupo.info.emoji}</span>
                    <span class="grupo__nome">${grupo.nome}</span>
                    <span class="grupo__contagem">${grupo.itens.length}</span>
                    <st-icon name=${aberto ? 'chevron-up' : 'chevron-down'}></st-icon>
                  </button>

                  ${
                    aberto
                      ? html`
                        <div class="registros">
                          ${grupo.itens.map((item) => linhaDoEstoque(item))}
                        </div>
                      `
                      : nothing
                  }
                </div>
              `;
            })}
          </div>
        `
    }
  `;
}

// ── Cofre ───────────────────────────────────────────────────────────────────

async function abrirCofre(): Promise<void> {
  erroDoCofre = '';

  if (pinDigitado === '') {
    erroDoCofre = S.prep.digitePin;
    atualizar();
    return;
  }

  if (!(await pinCorreto(pinDigitado))) {
    erroDoCofre = S.prep.pinIncorreto;
    pinDigitado = '';
    atualizar();
    return;
  }

  pinNaMemoria = pinDigitado;
  pinDigitado = '';
  documentos = await listarDocumentos();
  atualizar();
}

async function criarPin(): Promise<void> {
  erroDoCofre = '';

  if (pinDigitado.length < MINIMO_PIN) {
    erroDoCofre = S.prep.pinCurto(MINIMO_PIN);
    atualizar();
    return;
  }
  if (pinDigitado !== pinConfirmacao) {
    erroDoCofre = S.prep.pinNaoConfere;
    atualizar();
    return;
  }

  await definirPin(pinDigitado);
  pinNaMemoria = pinDigitado;
  pinDigitado = '';
  pinConfirmacao = '';
  documentos = await listarDocumentos();
  atualizar();
}

async function enviarArquivo(entrada: HTMLInputElement): Promise<void> {
  const arquivo = entrada.files?.[0];
  if (arquivo === undefined || pinNaMemoria === null) return;

  const rotulo = await pedirTexto({
    titulo: S.prep.nomeDoDocumento,
    valor: arquivo.name,
    placeholder: S.prep.nomeDoDocumento,
    rotuloConfirmar: S.acoes.salvar,
    erroVazio: S.prep.informeNome,
  });

  entrada.value = '';
  if (rotulo === null) return;

  await guardarDocumento(pinNaMemoria, arquivo, rotulo);
  documentos = await listarDocumentos();
  notificar(S.prep.documentoGuardado);
  atualizar();
}

function telaDoCofre(): TemplateResult {
  if (!cofreConfigurado()) {
    return html`
      <div class="formulario formulario--cartao">
        <h2 class="formulario__titulo">${S.prep.configurarPin}</h2>
        <p class="discreto">${S.prep.pinAjuda}</p>

        <st-input
          type="password"
          inputmode="numeric"
          password-toggle
          label=${S.prep.pin}
          .value=${pinDigitado}
          @st-input=${(evento: Event) => {
            pinDigitado = (evento.target as HTMLInputElement).value;
          }}
        ></st-input>
        <st-input
          type="password"
          inputmode="numeric"
          label=${S.prep.confirmarPin}
          .value=${pinConfirmacao}
          @st-input=${(evento: Event) => {
            pinConfirmacao = (evento.target as HTMLInputElement).value;
          }}
        ></st-input>

        ${erroDoCofre === '' ? nothing : html`<p class="erro">${erroDoCofre}</p>`}

        <st-button variant="primary" @click=${() => void criarPin()}>
          <st-icon slot="prefix" name="lock"></st-icon>${S.prep.criarCofre}
        </st-button>
      </div>
    `;
  }

  if (pinNaMemoria === null) {
    return html`
      <div class="formulario formulario--cartao">
        <h2 class="formulario__titulo">${S.prep.cofreTrancado}</h2>
        <p class="discreto">${S.prep.destranqueAjuda}</p>

        <st-input
          type="password"
          inputmode="numeric"
          password-toggle
          label=${S.prep.pin}
          .value=${pinDigitado}
          @st-input=${(evento: Event) => {
            pinDigitado = (evento.target as HTMLInputElement).value;
          }}
          @keydown=${(evento: KeyboardEvent) => {
            if (evento.key === 'Enter') void abrirCofre();
          }}
        ></st-input>

        ${erroDoCofre === '' ? nothing : html`<p class="erro">${erroDoCofre}</p>`}

        <st-button variant="primary" @click=${() => void abrirCofre()}>
          <st-icon slot="prefix" name="lock-open"></st-icon>${S.prep.destrancar}
        </st-button>
      </div>
    `;
  }

  return html`
    <div class="cofre__acoes">
      <label class="cofre__enviar">
        <st-icon name="upload"></st-icon>
        ${S.prep.guardarDocumento}
        <input
          type="file"
          @change=${(evento: Event) => void enviarArquivo(evento.target as HTMLInputElement)}
        />
      </label>
      <st-button
        outline
        @click=${() => {
          trancarCofre();
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="lock"></st-icon>${S.prep.trancar}
      </st-button>
    </div>

    ${
      documentos.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="lock"></st-icon>
            <p>${S.prep.semDocumentos}</p>
          </div>
        `
        : html`
          <div class="registros">
            ${documentos.map(
              (documento) => html`
                <div class="registro">
                  <span class="registro__avatar"><st-icon name="file"></st-icon></span>

                  <button class="registro__alvo" @click=${() => void verDocumento(documento)}>
                    <span class="registro__titulo">${documento.rotulo}</span>
                    <span class="registro__resumo">
                      ${documento.tipo_mime} · ${dataBR(documento.data_criacao)}
                    </span>
                  </button>

                  <div class="registro__acoes">
                    <st-icon-button
                      name="pencil"
                      label=${S.acoes.renomear}
                      @click=${() => void renomear(documento)}
                    ></st-icon-button>
                    <st-icon-button
                      name="trash"
                      label=${S.prep.excluirDocumento}
                      @click=${() => void apagarDocumento(documento)}
                    ></st-icon-button>
                  </div>
                </div>
              `,
            )}
          </div>
        `
    }

    ${
      previa === null
        ? nothing
        : html`
          <st-dialog
            open
            label=${previa.rotulo}
            @st-after-hide=${() => {
              fecharPrevia();
              atualizar();
            }}
          >
            ${
              previa.tipo.startsWith('image/')
                ? html`<img class="previa" src=${previa.url} alt=${previa.rotulo} />`
                : html`
                  <p>${S.prep.semPreVisualizacao}</p>
                  <st-button variant="primary" href=${previa.url} download=${previa.rotulo}>
                    <st-icon slot="prefix" name="download"></st-icon>${S.prep.baixar}
                  </st-button>
                `
            }
          </st-dialog>
        `
    }
  `;
}

async function verDocumento(documento: Documento): Promise<void> {
  if (pinNaMemoria === null) return;

  try {
    fecharPrevia();
    previa = {
      rotulo: documento.rotulo,
      url: await abrirDocumento(pinNaMemoria, documento),
      tipo: documento.tipo_mime,
    };
    atualizar();
  } catch {
    // Falha de decifragem quer dizer que o PIN mudou desde a gravação: os bytes
    // continuam lá, mas com outra chave. Dizer isso é mais útil que "erro".
    notificar(S.prep.falhaAoDecifrar, 'warning');
  }
}

async function renomear(documento: Documento): Promise<void> {
  const rotulo = await pedirTexto({
    titulo: S.prep.renomearDocumento,
    valor: documento.rotulo,
    placeholder: S.prep.nomeDoDocumento,
    rotuloConfirmar: S.acoes.renomear,
    erroVazio: S.prep.informeNome,
  });
  if (rotulo === null || rotulo === documento.rotulo) return;

  await renomearDocumento(documento, rotulo);
  documentos = await listarDocumentos();
  atualizar();
}

async function apagarDocumento(documento: Documento): Promise<void> {
  const ok = await confirmar({
    titulo: S.prep.excluirDocumento,
    texto: S.prep.excluirDocumentoTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok || documento.id === undefined) return;

  await excluirDocumento(documento.id);
  documentos = await listarDocumentos();
  notificar(S.prep.documentoExcluido);
  atualizar();
}

// ── A tela ──────────────────────────────────────────────────────────────────

const TITULOS: Readonly<Record<SubTela, string | undefined>> = {
  painel: undefined,
  kits: S.prep.kits,
  estoque: S.prep.estoque,
  cofre: S.prep.cofre,
  checklist: undefined,
};

export const telaPrep: Tela = {
  voltarPara(rota) {
    const sub = subTelaDe(rota);
    if (sub === 'painel') return 'home';
    if (sub === 'checklist') return 'prep/kits';
    return 'prep';
  },

  /**
   * Com o formulário de um item aberto, o ← fecha o formulário e mostra a lista
   * — não sai do módulo.
   *
   * O formulário não é rota: é o `formItem` por cima de `#/prep/estoque`. Antes
   * o ← levava direto ao painel do "Esteja Preparado" e ainda deixava o
   * rascunho de pé, então voltar ao estoque reabria a edição que se acabou de
   * abandonar. Sair sem salvar cancela — que é o que "sair sem salvar" quer
   * dizer em qualquer outro lugar do app.
   */
  aoVoltar(rota) {
    if (subTelaDe(rota) !== 'estoque' || formItem === null) return false;
    formItem = null;
    atualizar();
    return true;
  },

  titulo(rota) {
    const sub = subTelaDe(rota);
    if (sub !== 'checklist') return TITULOS[sub];
    return formChecklist !== null && formChecklist.id > 0 ? S.prep.editarKit : S.prep.novoKit;
  },

  acoes(rota) {
    const sub = subTelaDe(rota);

    if (sub === 'kits') {
      return html`
        <st-icon-button
          name="plus"
          label=${S.prep.novoKit}
          @click=${() => navegar('prep/checklist')}
        ></st-icon-button>
      `;
    }

    if (sub === 'estoque' && formItem === null) {
      return html`
        <st-icon-button
          name="plus"
          label=${S.prep.novoItem}
          @click=${() => {
            formItem = itemNovo();
            atualizar();
          }}
        ></st-icon-button>
      `;
    }

    return undefined;
  },

  conteudo(rota) {
    carregar();
    const sub = subTelaDe(rota);

    if (sub === 'checklist') {
      prepararChecklist(rota);
      return formChecklist === null
        ? html`<div class="carregando"><st-spinner></st-spinner></div>`
        : telaDoChecklist(formChecklist);
    }

    // O editor saiu de cena: o próximo que entrar precisa ser remontado.
    checklistCarregado = null;

    // Idem para o formulário do estoque, que também não é rota: quem saiu da
    // sub-tela por outro caminho (o rodapé, um atalho da barra, o voltar do
    // navegador) desistiu da edição do mesmo jeito.
    if (sub !== 'estoque') formItem = null;

    if (!carregado) return html`<div class="carregando"><st-spinner></st-spinner></div>`;

    if (sub === 'kits') return telaDosKits();
    if (sub === 'estoque') return telaDoEstoque();
    if (sub === 'cofre') return telaDoCofre();
    return telaDoPainel();
  },
};
