/**
 * A geometria das cinco vistas do Calendário — dia, semana, mês, ano e agenda.
 *
 * No legado isto era o FullCalendar. Aqui é aritmética de datas: cada vista se
 * resume a "quais dias entram" e "de que dia a que dia vai o período", e a
 * apresentação é grade CSS. O que o FullCalendar dava e não voltou é arrastar e
 * redimensionar o evento — mudar de horário passa pelo formulário, que já tinha
 * os campos de data e hora.
 *
 * Tudo aqui é puro e trabalha com `YYYY-MM-DD` local: nenhuma função abre o
 * banco nem olha a rota.
 */

import { dataLocalISO } from '../../datas.ts';

export const VISTAS = ['dia', 'semana', 'mes', 'ano', 'agenda'] as const;

export type Vista = (typeof VISTAS)[number];

/** Domingo a sábado, na ordem em que a grade os desenha (segunda primeiro). */
export const CABECALHOS_SEMANA = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'] as const;

/** A primeira e a última hora que a grade de horas mostra, como no legado. */
export const HORA_INICIAL = 6;
export const HORA_FINAL = 23;

function comMeiaNoite(data: Date): Date {
  const copia = new Date(data);
  copia.setHours(0, 0, 0, 0);
  return copia;
}

function maisDias(data: Date, dias: number): Date {
  const copia = comMeiaNoite(data);
  copia.setDate(copia.getDate() + dias);
  return copia;
}

/** Segunda-feira da semana da data. */
export function segundaDaSemana(data: Date): Date {
  return maisDias(data, -((data.getDay() + 6) % 7));
}

/** O período que a vista cobre a partir da data de referência. */
export interface Periodo {
  readonly de: string;
  readonly ate: string;
}

export function periodoDa(vista: Vista, referencia: Date): Periodo {
  if (vista === 'dia') {
    const dia = dataLocalISO(referencia);
    return { de: dia, ate: dia };
  }

  if (vista === 'semana' || vista === 'agenda') {
    const segunda = segundaDaSemana(referencia);
    return { de: dataLocalISO(segunda), ate: dataLocalISO(maisDias(segunda, 6)) };
  }

  if (vista === 'mes') {
    const primeiro = new Date(referencia.getFullYear(), referencia.getMonth(), 1);
    const ultimo = new Date(referencia.getFullYear(), referencia.getMonth() + 1, 0);
    return { de: dataLocalISO(primeiro), ate: dataLocalISO(ultimo) };
  }

  const primeiro = new Date(referencia.getFullYear(), 0, 1);
  const ultimo = new Date(referencia.getFullYear(), 11, 31);
  return { de: dataLocalISO(primeiro), ate: dataLocalISO(ultimo) };
}

/** Quanto o "anterior"/"próximo" anda em cada vista. */
export function navegado(vista: Vista, referencia: Date, sentido: number): Date {
  const nova = comMeiaNoite(referencia);

  if (vista === 'dia') nova.setDate(nova.getDate() + sentido);
  else if (vista === 'semana' || vista === 'agenda') nova.setDate(nova.getDate() + sentido * 7);
  else if (vista === 'mes') nova.setMonth(nova.getMonth() + sentido, 1);
  else nova.setFullYear(nova.getFullYear() + sentido, 0, 1);

  return nova;
}

/** O título do período, como o cabeçalho do FullCalendar mostrava. */
export function tituloDoPeriodo(vista: Vista, referencia: Date): string {
  if (vista === 'dia') {
    return referencia.toLocaleDateString('pt-BR', {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric',
    });
  }

  if (vista === 'semana' || vista === 'agenda') {
    const segunda = segundaDaSemana(referencia);
    const domingo = maisDias(segunda, 6);
    const curto: Intl.DateTimeFormatOptions = { day: 'numeric', month: 'short' };

    return `${segunda.toLocaleDateString('pt-BR', curto)} – ${domingo.toLocaleDateString('pt-BR', curto)} de ${domingo.getFullYear()}`;
  }

  if (vista === 'mes') {
    return referencia.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
  }

  return String(referencia.getFullYear());
}

/** Uma célula da grade do mês. */
export interface CelulaDoMes {
  readonly dia: string;
  readonly numero: number;
  /** `false` nos dias que só estão ali para fechar a primeira/última semana. */
  readonly doMes: boolean;
}

/**
 * A grade do mês: sempre semanas completas de segunda a domingo, para que as
 * colunas signifiquem sempre o mesmo dia da semana.
 */
export function gradeDoMes(ano: number, mes: number): CelulaDoMes[] {
  const primeiro = new Date(ano, mes, 1);
  const inicio = segundaDaSemana(primeiro);
  const ultimo = new Date(ano, mes + 1, 0);
  const fim = maisDias(segundaDaSemana(ultimo), 6);

  const celulas: CelulaDoMes[] = [];
  for (let dia = inicio; dia <= fim; dia = maisDias(dia, 1)) {
    celulas.push({
      dia: dataLocalISO(dia),
      numero: dia.getDate(),
      doMes: dia.getMonth() === mes,
    });
  }

  return celulas;
}

/** Os sete dias da semana da referência. */
export function diasDaSemana(referencia: Date): { dia: string; rotulo: string; numero: number }[] {
  const segunda = segundaDaSemana(referencia);

  return Array.from({ length: 7 }, (_, indice) => {
    const dia = maisDias(segunda, indice);
    return {
      dia: dataLocalISO(dia),
      rotulo: CABECALHOS_SEMANA[indice] ?? '',
      numero: dia.getDate(),
    };
  });
}

/** As horas que a grade de dia/semana mostra. */
export function horasDaGrade(): number[] {
  return Array.from({ length: HORA_FINAL - HORA_INICIAL }, (_, i) => HORA_INICIAL + i);
}

/** Os doze meses do ano, cada um com a própria grade. */
export function mesesDoAno(ano: number): { mes: number; rotulo: string; celulas: CelulaDoMes[] }[] {
  return Array.from({ length: 12 }, (_, mes) => ({
    mes,
    rotulo: new Date(ano, mes, 1).toLocaleDateString('pt-BR', { month: 'long' }),
    celulas: gradeDoMes(ano, mes),
  }));
}

/** Os dias do período, para a agenda listar um por um. */
export function diasDoPeriodo(periodo: Periodo): string[] {
  const dias: string[] = [];
  const [anoDe = 1970, mesDe = 1, diaDe = 1] = periodo.de.split('-').map(Number);

  for (let cursor = new Date(anoDe, mesDe - 1, diaDe); ; cursor = maisDias(cursor, 1)) {
    const iso = dataLocalISO(cursor);
    if (iso > periodo.ate) break;
    dias.push(iso);
  }

  return dias;
}

/** `sexta, 14 de agosto` — o cabeçalho de um dia na agenda. */
export function rotuloLongoDoDia(dia: string): string {
  const [ano = 1970, mes = 1, numero = 1] = dia.split('-').map(Number);

  return new Date(ano, mes - 1, numero).toLocaleDateString('pt-BR', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  });
}

/**
 * A faixa que o evento ocupa na grade de horas, em fração de 0 a 1 da janela
 * visível. Evento fora dela é preso à borda para não desaparecer da vista.
 */
export function faixaNaGrade(inicioMin: number, fimMin: number): { topo: number; altura: number } {
  const janelaInicio = HORA_INICIAL * 60;
  const janelaFim = HORA_FINAL * 60;
  const janela = janelaFim - janelaInicio;

  const de = Math.min(Math.max(inicioMin, janelaInicio), janelaFim);
  const ate = Math.min(Math.max(fimMin > inicioMin ? fimMin : janelaFim, de + 15), janelaFim);

  return { topo: (de - janelaInicio) / janela, altura: (ate - de) / janela };
}
