/** O primeiro e o último ano do eixo. */
export const ANO_INICIAL = -900;
export const ANO_FINAL = 2026;

/**
 * Âncoras do eixo comprimido: `[ano, posição]`, com a posição entre 0 e 1.
 *
 * Um eixo linear daria 84% da tela aos vinte e cinco séculos anteriores a
 * Tyndale — onde cabem seis marcos — e espremeria os cinco séculos seguintes,
 * onde estão vinte, num dedo de largura. A compressão é declarada aqui em vez de
 * sair de um logaritmo porque assim ela é AUDITÁVEL: dá para ver quanto cada era
 * ganhou, e o desenho marca as âncoras no eixo, para que a distorção fique à
 * vista de quem lê.
 */
const ANCORAS: readonly (readonly [number, number])[] = [
  [-900, 0],
  [100, 0.2],
  [500, 0.32],
  [1500, 0.46],
  [1700, 0.6],
  [1900, 0.72],
  [1950, 0.8],
  [2026, 1],
];

/** A posição de um ano no eixo, entre 0 e 1 — monótona e contínua. */
export function posicaoDoAno(ano: number): number {
  const alvo = Math.max(ANO_INICIAL, Math.min(ANO_FINAL, ano));

  for (let i = 1; i < ANCORAS.length; i++) {
    const anterior = ANCORAS[i - 1];
    const atual = ANCORAS[i];
    if (anterior === undefined || atual === undefined) continue;

    const [anoA, posA] = anterior;
    const [anoB, posB] = atual;
    if (alvo <= anoB) {
      const fatia = (alvo - anoA) / (anoB - anoA);
      return posA + fatia * (posB - posA);
    }
  }

  return 1;
}

/**
 * Como escrever um ano do eixo, com a era.
 *
 * Sem separador de milhar, de propósito: ano é numeral ordinal de calendário, e
 * "1.008 EC" se lê como quantidade, não como data.
 */
export function anoEmTexto(ano: number): string {
  return ano < 0 ? `${-ano} AEC` : `${ano} EC`;
}

/**
 * O estado do nome divino nos manuscritos e traduções, ano a ano.
 *
 * Não é uma opinião distribuída numa régua: cada virada tem um marco documentado
 * atrás dela. Até o século 3 o Tetragrama está no texto hebraico, nas cópias
 * gregas da Septuaginta e até em cerâmica de uso diário. Entre o século 4 e 1530
 * ele não está nos manuscritos gregos principais nem nas traduções que saem
 * deles. De 1530 em diante volta — em ALGUMAS traduções, o que é coisa diferente
 * de ter voltado.
 */
export type EstadoDoNome = 'presente' | 'retirado' | 'parcial';

export function nomeNoAno(ano: number): EstadoDoNome {
  if (ano < 320) return 'presente';
  if (ano < 1530) return 'retirado';
  return 'parcial';
}

/** Quantos marcos a trajetória já acumulou até um ano — a leitura da faixa. */
export function marcosAte(ano: number): number {
  return MARCOS.filter((marco) => marco.ano <= ano).length;
}

/**
 * Os manuscritos gregos por século, e se cada um traz o nome divino.
 *
 * É desta tabela que sai a leitura do passo do sumiço: o usuário arrasta o
 * século e vê a resposta virar, em vez de ler que "no século 4 o nome sumiu".
 */
const MANUSCRITOS: readonly {
  readonly seculo: number;
  readonly nome: string;
  readonly tem: boolean;
}[] = [
  { seculo: 1, nome: 'cópias da Septuaginta como as dos dias de Jesus', tem: true },
  { seculo: 2, nome: 'primeiras versões — latim antigo, siríaco, copta', tem: true },
  { seculo: 3, nome: 'os escritos cristãos que a Tosefta descreve', tem: true },
  { seculo: 4, nome: 'Códice Vaticano e Códice Sinaítico', tem: false },
  { seculo: 5, nome: 'Códice Alexandrino', tem: false },
  { seculo: 6, nome: 'as cópias gregas que restaram', tem: false },
];

/** O que se lê num século: qual manuscrito o representa e se ele traz o Nome. */
export function manuscritoDoSeculo(seculo: number): {
  readonly nome: string;
  readonly tem: boolean;
} {
  const achado = MANUSCRITOS.find((item) => item.seculo === Math.round(seculo));
  return achado ?? { nome: 'sem manuscrito representativo', tem: false };
}

