/**
 * Os dados do Tutorial.
 *
 * O acervo é curado (`pap_tutorial`, um tópico por módulo mais a visão geral) e
 * chega pela sincronização como todos os outros. Enquanto ela não trouxer nada,
 * valem os tópicos de fábrica de `@marinx/core` — os mesmos que o admin usa para
 * semear a tabela, e por isso um texto só, não duas cópias para divergirem.
 */

import { TOPICOS_FABRICA } from '@marinx/core';
import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

/** Um tópico do tutorial. `modulo_id` vazio é a visão geral do app. */
export interface Topico extends Registro {
  id?: number;
  modulo_id: string;
  titulo: string;
  resumo: string;
  /** HTML curado, escrito no admin. */
  conteudo: string;
  ordem?: number;
  publicar?: number;
}

const topicos = () => repositorio('tutorial');

/** Os tópicos publicados, em ordem; cai no de fábrica enquanto o store está vazio. */
export async function listarTopicos(): Promise<Topico[]> {
  const curados = await topicos()
    .todos<Topico>()
    .catch(() => []);

  const lista: readonly Topico[] = curados.length === 0 ? TOPICOS_FABRICA : curados;

  // A sincronização já baixa só o que está publicado; filtrar aqui é defesa
  // contra um export antigo que tenha vindo completo.
  return [...lista]
    .filter((item) => item.publicar !== 0)
    .sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0));
}

/** O tópico da visão geral (o de `modulo_id` vazio). */
export function visaoGeral(lista: readonly Topico[]): Topico | undefined {
  return lista.find((item) => item.modulo_id === '');
}

export function porModulo(lista: readonly Topico[]): Map<string, Topico> {
  return new Map(
    lista.filter((item) => item.modulo_id !== '').map((item) => [item.modulo_id, item]),
  );
}
