/**
 * Os dados da Cronologia — porte de `modulos/cronologia/cronologia.js`.
 *
 * Conteúdo 100% curado (store `cronologia`). Não há CRUD: o que o usuário produz
 * sobre um evento vai para o Caderno de Estudo.
 *
 * O agrupamento por era e o filtro por trilha são funções puras: é a regra que
 * decide o que a linha do tempo mostra, e vale testar sem navegador.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

/** Um evento da linha do tempo, como o admin o exporta. */
export interface Evento extends Registro {
  id?: number;
  trilha: string;
  era: string;
  ano_inicio: number;
  ano_fim: number;
  ordem_absoluta: number;
  /** `exato` ou `aprox` — o "c." antes do ano. */
  precisao: string;
  periodo: string;
  titulo: string;
  resumo: string;
  referencia: string;
  link_fonte: string;
  obra_fonte: string;
  destaque?: number;
}

/**
 * Eras narrativas em ordem cronológica — espelham `CronologiaPage::PERIODOS` do
 * admin. São os agrupadores da linha e as paradas da barra de contexto.
 */
export const PERIODOS: Readonly<Record<string, string>> = {
  criacao: 'A Criação',
  pre_diluvio: 'Antes do Dilúvio',
  patriarcas: 'Os Patriarcas',
  exodo_juizes: 'Êxodo e Juízes',
  reis: 'Os Reis',
  exilio: 'O Exílio',
  restauracao: 'A Restauração',
  jesus: 'Jesus na Terra',
  primeiro_seculo: 'O Primeiro Século',
  apostasia: 'A Grande Apostasia',
  restauracao_moderna: 'Restauração Moderna',
  // De 1914 em diante são três eras, não uma: o acervo é denso demais aí para
  // caber num agrupador só.
  ultimos_dias: 'Os Últimos Dias',
  expansao_mundial: 'Expansão Mundial',
  nossos_dias: 'Nossos Dias',
};

export const ORDEM_PERIODOS = Object.keys(PERIODOS);

/**
 * Três trilhas, duas colunas: `biblica` cai à esquerda do eixo; `mundial` e
 * `historica` à direita. A diferença entre essas duas é a **procedência** —
 * `mundial` é história contada pela literatura de jw.org; `historica` vem de
 * acervo oficial externo (UNESCO, Louvre, ONU, arquivos e museus) e segue a
 * datação acadêmica convencional. Por isso cada uma tem sua cor.
 */
export const TRILHAS: Readonly<Record<string, string>> = {
  biblica: 'Bíblica',
  mundial: 'Mundial',
  historica: 'Histórica',
};

const eventos = () => repositorio('cronologia');

/** Os eventos curados, na ordem absoluta (o id desempata). */
export async function listarEventos(): Promise<Evento[]> {
  const lista = await eventos()
    .todos<Evento>()
    .catch(() => []);

  return lista.sort(
    (a, b) =>
      Number(a.ordem_absoluta) - Number(b.ordem_absoluta) || Number(a.id ?? 0) - Number(b.id ?? 0),
  );
}

/** Quais trilhas estão visíveis, e o texto buscado. */
export interface Filtros {
  readonly trilhas: Readonly<Record<string, boolean>>;
  readonly busca: string;
}

export const FILTROS_INICIAIS: Filtros = {
  trilhas: { biblica: true, mundial: true, historica: true },
  busca: '',
};

export function filtrar(lista: readonly Evento[], filtros: Filtros): Evento[] {
  const alvo = filtros.busca.trim().toLowerCase();

  return lista.filter((evento) => {
    if (filtros.trilhas[evento.trilha] === false) return false;
    if (alvo === '') return true;

    return (
      evento.titulo.toLowerCase().includes(alvo) ||
      evento.resumo.toLowerCase().includes(alvo) ||
      evento.referencia.toLowerCase().includes(alvo)
    );
  });
}

/** Um trecho da linha: uma era e os eventos dela. */
export interface Grupo {
  readonly chave: string;
  readonly rotulo: string;
  readonly eventos: readonly Evento[];
}

/** Eventos fatiados por era narrativa, na ordem de `PERIODOS`. */
export function agrupar(lista: readonly Evento[]): Grupo[] {
  const mapa = new Map<string, Evento[]>();

  for (const evento of lista) {
    // Um período desconhecido cai no primeiro: melhor aparecer no começo da
    // linha do que desaparecer da tela.
    const chave = PERIODOS[evento.periodo] === undefined ? ORDEM_PERIODOS[0] : evento.periodo;
    if (chave === undefined) continue;

    const grupo = mapa.get(chave);
    if (grupo === undefined) mapa.set(chave, [evento]);
    else grupo.push(evento);
  }

  return ORDEM_PERIODOS.filter((chave) => (mapa.get(chave)?.length ?? 0) > 0).map((chave) => ({
    chave,
    rotulo: PERIODOS[chave] ?? chave,
    eventos: mapa.get(chave) ?? [],
  }));
}

/** Uma parada da barra de contexto. */
export interface Parada {
  readonly chave: string;
  readonly rotulo: string;
  /** `false` quando o filtro atual escondeu a era: a régua não muda de tamanho. */
  readonly presente: boolean;
}

/**
 * As paradas da barra: **todos** os períodos que existem no acervo, e não só os
 * filtrados — assim a régua não encolhe enquanto se digita na busca.
 */
export function paradas(todos: readonly Evento[], grupos: readonly Grupo[]): Parada[] {
  const noAcervo = new Set(todos.map((evento) => evento.periodo));
  const visiveis = new Set(grupos.map((grupo) => grupo.chave));

  return ORDEM_PERIODOS.filter((chave) => noAcervo.has(chave)).map((chave) => ({
    chave,
    rotulo: PERIODOS[chave] ?? chave,
    presente: visiveis.has(chave),
  }));
}

/** `c. 2370 AEC` · `1943–1918 AEC` · `1914 EC` */
export function rotuloDoAno(evento: Evento): string {
  const prefixo = evento.precisao === 'aprox' ? 'c. ' : '';
  const fim = Number(evento.ano_fim) > 0 ? `–${evento.ano_fim}` : '';
  return `${prefixo}${evento.ano_inicio}${fim} ${evento.era}`;
}
