/**
 * A tela de "Teve um Projeto?" e "Entenda Melhor" — porte da seção `criacao` do
 * `index.html` legado e do runner de `modulos/criacao/criacao.js`.
 *
 * Uma tela só para os dois módulos: o legado já compartilhava a engine inteira
 * entre `#/criacao` e `#/entenda`, e quem decide o título, o filtro e o
 * agrupamento é o modo (ver `dados.ts`). Duplicar isto seria duplicar dez
 * arquétipos de puzzle.
 *
 * **O que mudou em relação ao legado:** lá o fluxo conceito → interativo vivia
 * numa variável (`etapa`), fora do endereço; o botão de voltar do navegador
 * saltava do meio de um puzzle direto para fora do módulo. Aqui cada etapa é
 * rota — `#/criacao/<id>` abre o conceito e `#/criacao/<id>/jogar` abre o
 * puzzle —, então voltar faz o que promete e um puzzle pode ser compartilhado
 * por link. É o mesmo caminho já seguido pelas Anotações e pela Leitura.
 *
 * A instância do puzzle é criada uma vez por abertura e guardada aqui: ela
 * carrega o estado que o usuário montou (a ordem das flores, o passo da trilha)
 * e recriá-la a cada redesenho jogaria esse trabalho fora.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { keyed } from 'lit/directives/keyed.js';
import { createRef, ref } from 'lit/directives/ref.js';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { gravarNoCaderno, removerDoCaderno } from '../caderno/dados.ts';
import {
  agrupar,
  carregarCaderno,
  carregarModulos,
  concluido as estaConcluido,
  type Grupo,
  lerConfig,
  lerProgresso,
  type ModoId,
  type ModuloCriacao,
  modo as modoDe,
  type Progresso,
  progressoVazio,
  refCaderno,
  registrarConclusao,
} from './dados.ts';
import type { Info, Instancia, Puzzle } from './renderizadores/base.ts';
import { renderizador } from './renderizadores/index.ts';
import { distanciaDaRota } from './renderizadores/montagem.ts';
import { carregarViz, type VizDoPuzzle } from './viz/index.ts';

let modulos: ModuloCriacao[] = [];
let progresso: Progresso = progressoVazio();
let caderno = new Map<number, string>();

let carregado = false;
let carregando = false;

/** O puzzle em cena e de qual módulo ele é. */
let instancia: Instancia | null = null;
let instanciaDe = -1;

let resolvido = false;
let concluidoInline = false;
let feedback = '';
let feedbackTipo: 'ok' | 'erro' | 'dica' | '' = '';
let rascunho = '';

let zoomImagem: string | null = null;
let zoomAmpliado = false;

let viz: VizDoPuzzle | null = null;
let vizMontando = false;
const canvasRef = createRef<HTMLCanvasElement>();

// ── Carga ───────────────────────────────────────────────────────────────────

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      [modulos, caderno] = await Promise.all([carregarModulos(), carregarCaderno()]);
      progresso = lerProgresso();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

function moduloPorId(id: number): ModuloCriacao | undefined {
  return modulos.find((m) => m.id === id);
}

/** Os módulos do modo em cena, na ordem do catálogo. */
function doModo(id: ModoId): ModuloCriacao[] {
  return modulos.filter((m) => modoDe(id).inclui(m));
}

function diligente(m: ModuloCriacao | undefined): boolean {
  return (
    m?.id !== undefined && estaConcluido(progresso, m) && (caderno.get(m.id) ?? '').trim() !== ''
  );
}

// ── Puzzle ──────────────────────────────────────────────────────────────────

/**
 * Garante o puzzle do módulo aberto. Trocar de módulo destrói a cena anterior:
 * uma viz viva de outro puzzle continuaria animando por baixo do novo.
 */
function garantirInstancia(m: ModuloCriacao): Instancia {
  if (instancia !== null && instanciaDe === m.id) return instancia;

  destruirViz();
  instancia = renderizador(m.tipo).criar(lerConfig(m));
  instanciaDe = m.id ?? -1;
  resolvido = false;
  concluidoInline = false;
  feedback = '';
  feedbackTipo = '';
  rascunho = m.id === undefined ? '' : (caderno.get(m.id) ?? '');
  return instancia;
}

function largar(): void {
  destruirViz();
  instancia = null;
  instanciaDe = -1;
  resolvido = false;
  concluidoInline = false;
  feedback = '';
  feedbackTipo = '';
}

/**
 * Verificar só habilita quando já há uma resposta para conferir — varia por
 * arquétipo. Sliders sempre têm valor, então ficam sempre prontos.
 */
function podeVerificar(puzzle: Puzzle): boolean {
  switch (puzzle.arquetipo) {
    case 'numerico':
      return (puzzle.campos ?? []).every((campo) => {
        const valor = puzzle.valores[campo.prop];
        return valor !== undefined && valor !== '';
      });
    case 'escolha':
      return puzzle.escolhido !== null && puzzle.escolhido !== undefined;
    case 'pares':
      return (puzzle.selecionados?.length ?? 0) > 0;
    case 'rota':
      return (
        (puzzle.pontos?.length ?? 0) > 0 &&
        (puzzle.ordemPontos?.length ?? 0) === (puzzle.pontos?.length ?? 0)
      );
    case 'ordenar':
      return (puzzle.ordem?.length ?? 0) === (puzzle.itens?.length ?? 0);
    case 'ciclos':
      // Só habilita quando todos os ciclos têm os estágios posicionados.
      return Object.values(puzzle.ciclos ?? {}).every(
        (ciclo) => ciclo.ordem.length === ciclo.itens.length,
      );
    case 'etapas': {
      const passo = (puzzle.passos ?? [])[puzzle.atual ?? 0];
      return passo?.entrada === 'escolha'
        ? puzzle.escolhido !== null && puzzle.escolhido !== undefined
        : true;
    }
    case 'explorar':
      return (puzzle.vistos?.length ?? 0) === (puzzle.mapa?.length ?? 0);
    case 'solar':
      // No lançamento, só depois de o corpo assentar.
      return puzzle.solar?.modo === 'lancamento'
        ? puzzle.resultado !== null &&
            puzzle.resultado !== undefined &&
            puzzle.resultado.situacao !== 'voando'
        : true;
    default:
      return true;
  }
}

/** Enquanto o corpo lançado percorre a trajetória, os controles ficam travados. */
function emVoo(puzzle: Puzzle): boolean {
  return puzzle.resultado?.situacao === 'voando';
}

function verificar(m: ModuloCriacao, atual: Instancia): void {
  if (resolvido) return;

  const desfecho = atual.verificar();

  if (desfecho.tipo === 'avanco') {
    feedback = '';
    feedbackTipo = '';
  } else if (desfecho.tipo === 'ok') {
    resolvido = true;
    feedbackTipo = 'ok';
    feedback = desfecho.mensagem ?? S.criacao.acerto;
    registrar(m);
  } else {
    feedbackTipo = desfecho.tipo;
    feedback = desfecho.mensagem ?? S.criacao.erro;
  }

  // `verificar` é o único caminho que troca a fase (`atual`) e o `resolvido`, e a
  // cena guarda um retrato próprio: sem sincronizar aqui, ela seguiria desenhando
  // a fase anterior — com os textos dela — até o primeiro toque num controle.
  sincronizarViz(atual);
  atualizar();
}

/** Registra a conclusão e revela a Reflexão na mesma tela. Uma vez por abertura. */
function registrar(m: ModuloCriacao): void {
  if (concluidoInline || m.id === undefined) return;
  progresso = registrarConclusao(progresso, m.id);
  concluidoInline = true;
}

/** O tipo `pronto` não tem o que verificar: conclui ao tocar no botão. */
function concluirPronto(m: ModuloCriacao): void {
  resolvido = true;
  registrar(m);
  atualizar();
}

// ── Caderno do Investigador ─────────────────────────────────────────────────

let salvarAgendado: ReturnType<typeof setTimeout> | undefined;

/**
 * Texto vazio remove a anotação — e, com ela, o selo de Estudo Diligente. É
 * gravação direta no Caderno de Estudo, sem passar pela tela dele: o que se
 * escreve aqui já é a anotação daquele módulo.
 */
function agendarSalvarCaderno(m: ModuloCriacao): void {
  clearTimeout(salvarAgendado);
  salvarAgendado = setTimeout(() => {
    void (async () => {
      if (m.id === undefined) return;
      const texto = rascunho.trim();

      if (texto === '') {
        await removerDoCaderno(refCaderno(m.id));
        caderno.delete(m.id);
      } else {
        await gravarNoCaderno({
          origem: 'criacao',
          referencia: m.titulo,
          titulo: `${modoDe(m.categoria === 'entenda' ? 'entenda' : 'criacao').titulo} — ${m.titulo}`,
          conteudo: texto,
          ref_chave: refCaderno(m.id),
        });
        caderno.set(m.id, texto);
      }

      atualizar();
    })();
  }, 500);
}

// ── Visualização ────────────────────────────────────────────────────────────

/**
 * O retrato do estado que a viz consome.
 *
 * O legado serializava o puzzle inteiro para JSON a cada quadro só para que o
 * Alpine notasse as dependências; aqui a tela chama `aplicar` quando de fato
 * mudou alguma coisa, e o retrato carrega apenas o que as viz leem.
 */
function retrato(atual: Instancia): Readonly<Record<string, unknown>> {
  const puzzle = atual.puzzle;

  return {
    info: atual.info(),
    valores: puzzle.valores,
    escolhido: puzzle.escolhido,
    selecionados: puzzle.selecionados,
    ordem: puzzle.ordem,
    ordemPontos: puzzle.ordemPontos,
    colunas: puzzle.colunas,
    pontos: puzzle.pontos,
    colmeia: puzzle.colmeia,
    itens: puzzle.itens,
    ciclos: puzzle.ciclos,
    ativo: puzzle.ativo,
    ativoMapa: puzzle.ativoMapa,
    vistos: puzzle.vistos,
    resultado: puzzle.resultado,
    extra: puzzle.extra,
    resolvido,
  };
}

function montarViz(atual: Instancia): void {
  const canvas = canvasRef.value;
  const nome = atual.puzzle.viz?.comp;
  if (canvas === undefined || nome === undefined || viz !== null || vizMontando) return;

  vizMontando = true;
  void (async () => {
    try {
      const fabrica = await carregarViz(nome);
      // O usuário pode ter saído da etapa enquanto a cena carregava.
      if (fabrica === undefined || instancia !== atual || !canvas.isConnected) return;

      viz = fabrica(canvas, {
        ...(atual.puzzle.solar === undefined ? {} : { modo: atual.puzzle.solar.modo }),
        aoAtualizar: (dados) => {
          atual.puzzle.vizDados = { ...dados };
          atualizar();
        },
        aoMudarEstado: (estado) => {
          atual.puzzle.resultado = { ...estado };
          atualizar();
        },
      });
      viz.aplicar?.(retrato(atual));
    } finally {
      vizMontando = false;
    }
  })();
}

function destruirViz(): void {
  viz?.destruir();
  viz = null;
}

/** Reflete o estado atual na cena. Chamado a cada mudança de controle. */
function sincronizarViz(atual: Instancia): void {
  viz?.aplicar?.(retrato(atual));
}

// ── Ajudantes de marcação ───────────────────────────────────────────────────

function valorDe(puzzle: Puzzle, prop: string): number {
  const bruto = puzzle.valores[prop];
  return typeof bruto === 'number' ? bruto : 0;
}

function mexer(atual: Instancia, prop: string, valor: number): void {
  atual.puzzle.valores[prop] = valor;
  feedback = '';
  feedbackTipo = '';
  sincronizarViz(atual);
  atualizar();
}

/** O quadro da leitura ao vivo, verde quando a medida entra na faixa. */
function leitura(info: Info | null): TemplateResult | typeof nothing {
  if (info === null || info.leitura === '') return nothing;
  return html`<p class="criacao__leitura ${info.ok ? 'criacao__leitura--ok' : ''}">${info.leitura}</p>`;
}

// ── Lista ───────────────────────────────────────────────────────────────────

function cartao(m: ModuloCriacao): TemplateResult {
  return html`
    <button class="criacao__cartao" @click=${() => navegar(`${rotaDoModo(m)}/${m.id}`)}>
      <st-icon class="criacao__icone" name=${iconeDe(m)}></st-icon>
      <span class="criacao__titulo">${m.titulo}</span>
      <span class="criacao__selos">
        ${
          estaConcluido(progresso, m)
            ? html`<st-icon name="check" class="criacao__selo criacao__selo--ok"></st-icon>`
            : nothing
        }
        ${
          diligente(m)
            ? html`
              <st-icon
                name="school"
                class="criacao__selo criacao__selo--diligente"
                title=${S.criacao.diligenteSelo}
              ></st-icon>
            `
            : nothing
        }
      </span>
    </button>
  `;
}

/**
 * O ícone curado no admin, que hoje já vem como nome do Stratum.
 *
 * Enquanto a coluna guardava nomes do Bootstrap Icons (`bi-*`) esta função tinha
 * de ignorá-la e devolver um ícone por categoria — todo cartão de "Teve um
 * Projeto?" saía com a mesma bússola. A reserva por categoria continua, para o
 * caso de um registro vir com a coluna vazia.
 */
function iconeDe(m: ModuloCriacao): string {
  if (m.icone !== '') return m.icone;
  return m.categoria === 'entenda' ? 'bulb' : 'compass';
}

function rotaDoModo(m: ModuloCriacao): ModoId {
  return m.categoria === 'entenda' ? 'entenda' : 'criacao';
}

function grupo(g: Grupo, agrupado: boolean): TemplateResult {
  return html`
    <section class="criacao__grupo">
      ${
        agrupado
          ? html`
            <h2 class="criacao__categoria">
              ${g.rotulo}
              ${g.concluida ? html`<st-icon name="rosette-discount-check"></st-icon>` : nothing}
            </h2>
          `
          : nothing
      }
      <div class="criacao__grade">${g.modulos.map(cartao)}</div>
    </section>
  `;
}

function lista(id: ModoId): TemplateResult {
  const doCatalogo = doModo(id);
  const feitos = doCatalogo.filter((m) => estaConcluido(progresso, m)).length;
  const percentual = doCatalogo.length > 0 ? Math.round((feitos / doCatalogo.length) * 100) : 0;

  if (doCatalogo.length === 0) {
    return html`<p class="vazio">${carregando ? S.app.carregando : S.criacao.vazio}</p>`;
  }

  return html`
    <div class="criacao">
      <p class="criacao__subtitulo">${modoDe(id).subtitulo}</p>

      <div class="criacao__progresso">
        <st-progress-bar value=${percentual}></st-progress-bar>
        <span class="criacao__contagem">${feitos}/${doCatalogo.length}</span>
      </div>

      ${agrupar(doCatalogo, (m) => estaConcluido(progresso, m)).map((g) =>
        grupo(g, modoDe(id).agrupado),
      )}
    </div>
  `;
}

// ── Conceito e desafio ──────────────────────────────────────────────────────

function conceito(m: ModuloCriacao): TemplateResult {
  return html`
    <div class="criacao">
      <article class="criacao__bloco">
        <h2 class="criacao__secao">${S.criacao.conceito}</h2>
        <div class="prosa">${unsafeHTML(m.conceito)}</div>

        ${
          m.imagem === ''
            ? nothing
            : html`
              <figure class="criacao__figura">
                <img
                  src=${`imagens/${m.imagem}`}
                  alt=${m.titulo}
                  loading="lazy"
                  @click=${() => {
                    zoomImagem = m.imagem;
                    zoomAmpliado = false;
                    atualizar();
                  }}
                />
                <figcaption>${S.criacao.ampliar}</figcaption>
              </figure>
            `
        }
      </article>

      <article class="criacao__bloco criacao__bloco--desafio">
        <h2 class="criacao__secao">${S.criacao.desafio}</h2>
        <div class="prosa">${unsafeHTML(m.desafio)}</div>
      </article>

      ${
        m.link_jw === ''
          ? nothing
          : html`
            <p class="criacao__fonte">
              <a href=${m.link_jw} target="_blank" rel="noopener">${S.criacao.fonte}</a>
            </p>
          `
      }

      <p class="criacao__dica">${S.criacao.diligenteDica}</p>

      <st-button variant="primary" @click=${() => navegar(`${rotaDoModo(m)}/${m.id}/jogar`)}>
        ${S.criacao.comecar}
      </st-button>
    </div>
  `;
}

// ── Arquétipos ──────────────────────────────────────────────────────────────

function controles(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const travado = resolvido || emVoo(puzzle);

  return html`
    ${(puzzle.controles ?? []).map(
      (c) => html`
        <div class="criacao__controle">
          <label class="criacao__rotulo">
            <span>${c.rotulo}</span>
            <strong>${valorDe(puzzle, c.prop)}${c.suf ?? ''}</strong>
          </label>

          ${
            c.botoes === true
              ? html`
                <div class="criacao__passos">
                  <st-button
                    ?disabled=${travado || valorDe(puzzle, c.prop) <= c.min}
                    @click=${() =>
                      mexer(atual, c.prop, Math.max(c.min, valorDe(puzzle, c.prop) - c.step))}
                  >−</st-button>
                  <span class="criacao__valor">${valorDe(puzzle, c.prop)}${c.suf ?? ''}</span>
                  <st-button
                    variant="primary"
                    ?disabled=${travado || valorDe(puzzle, c.prop) >= c.max}
                    @click=${() =>
                      mexer(atual, c.prop, Math.min(c.max, valorDe(puzzle, c.prop) + c.step))}
                  >+</st-button>
                </div>
              `
              : nothing
          }

          <input
            type="range"
            min=${c.min}
            max=${c.max}
            step=${c.step}
            .value=${String(valorDe(puzzle, c.prop))}
            ?disabled=${travado}
            @input=${(e: Event) =>
              mexer(atual, c.prop, Number((e.target as HTMLInputElement).value))}
          />
        </div>
      `,
    )}
  `;
}

function numerico(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const info = atual.info();
  const sequencia = Array.isArray(info?.sequencia) ? (info.sequencia as number[]) : [];

  if (puzzle.extra === 'sequencia') {
    const n = valorDe(puzzle, 'n');
    return html`
      <div class="criacao__sequencia">
        ${sequencia.map((valor) => html`<span class="criacao__numero">${valor}</span>`)}
        <span class="criacao__numero criacao__numero--alvo">${n > 0 ? n : '?'}</span>
      </div>
      <div class="criacao__controle">
        <label class="criacao__rotulo">
          <span>${S.criacao.proximoNumero}</span><strong>${n}</strong>
        </label>
        <input
          type="range"
          min="0"
          max="50"
          step="1"
          .value=${String(n)}
          ?disabled=${resolvido}
          @input=${(e: Event) => mexer(atual, 'n', Number((e.target as HTMLInputElement).value))}
        />
      </div>
    `;
  }

  return html`
    ${(puzzle.campos ?? []).map(
      (campo) => html`
        <st-input
          label=${campo.rotulo}
          type="number"
          ?disabled=${resolvido}
          .value=${String(puzzle.valores[campo.prop] ?? '')}
          @st-input=${(e: Event) =>
            mexer(atual, campo.prop, Number((e.target as HTMLInputElement).value))}
        ></st-input>
      `,
    )}
  `;
}

function escolha(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;

  return html`
    <div class="criacao__opcoes">
      ${(puzzle.opcoes ?? []).map(
        (opcao) => html`
          <button
            class="criacao__opcao ${puzzle.escolhido === opcao.id ? 'criacao__opcao--ativa' : ''}"
            ?disabled=${resolvido}
            @click=${() => {
              puzzle.escolhido = opcao.id;
              feedback = '';
              sincronizarViz(atual);
              atualizar();
            }}
          >
            <strong>${opcao.rotulo}</strong>
            ${opcao.nota === undefined ? nothing : html`<small>${opcao.nota}</small>`}
          </button>
        `,
      )}
    </div>
  `;
}

function pares(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const marcados = puzzle.selecionados ?? [];

  return html`
    <p class="criacao__dica">${S.criacao.paresDica}</p>
    <div class="criacao__fita">
      ${(puzzle.colunas ?? []).map(
        (coluna, i) => html`
          <button
            class="criacao__base ${marcados.includes(i) ? 'criacao__base--marcada' : ''}"
            ?disabled=${resolvido}
            @click=${() => {
              const pos = marcados.indexOf(i);
              if (pos >= 0) marcados.splice(pos, 1);
              else marcados.push(i);
              sincronizarViz(atual);
              atualizar();
            }}
          >
            <span>${coluna.a}</span><span class="criacao__ligacao">·</span><span>${coluna.b}</span>
          </button>
        `,
      )}
    </div>
  `;
}

function rota(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const ordem = puzzle.ordemPontos ?? [];
  const colmeia = puzzle.colmeia ?? ([50, 8] as const);
  const pontos = puzzle.pontos ?? [];

  // A polilinha fecha na colmeia só depois de todas as flores visitadas.
  const trajeto = [colmeia, ...ordem.map((i) => pontos[i] ?? colmeia)];
  if (ordem.length === pontos.length && ordem.length > 0) trajeto.push(colmeia);
  const ultimo = ordem.length > 0 ? (pontos[ordem[ordem.length - 1] ?? 0] ?? colmeia) : colmeia;

  return html`
    <p class="criacao__dica">${S.criacao.rotaDica}</p>
    <div class="criacao__campo">
      <svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">
        <polyline
          points=${trajeto.map((p) => `${p[0]},${p[1]}`).join(' ')}
          class=${resolvido ? 'criacao__trilha criacao__trilha--ok' : 'criacao__trilha'}
        ></polyline>
      </svg>

      <span class="criacao__colmeia" style=${`left:${colmeia[0]}%;top:${colmeia[1]}%`}>🍯</span>

      ${pontos.map(
        (ponto, i) => html`
          <button
            class="criacao__flor ${ordem.includes(i) ? 'criacao__flor--visitada' : ''}"
            style=${`left:${ponto[0]}%;top:${ponto[1]}%`}
            ?disabled=${resolvido}
            @click=${() => {
              const pos = ordem.indexOf(i);
              // Tocar de novo desfaz, para corrigir sem recomeçar tudo.
              if (pos >= 0) ordem.splice(pos, 1);
              else ordem.push(i);
              puzzle.dist = distanciaDaRota(puzzle);
              sincronizarViz(atual);
              atualizar();
            }}
          >
            ${ordem.includes(i) ? ordem.indexOf(i) + 1 : '🌸'}
          </button>
        `,
      )}

      <span class="criacao__abelha" style=${`left:${ultimo[0]}%;top:${ultimo[1]}%`}>🐝</span>
    </div>

    <div class="criacao__medida">
      <span>${S.criacao.rotaMedida(Math.round(puzzle.dist ?? 0), Math.round(puzzle.otima ?? 0))}</span>
      <st-button
        size="small"
        ?disabled=${resolvido}
        @click=${() => {
          puzzle.ordemPontos = [];
          puzzle.dist = 0;
          feedback = '';
          sincronizarViz(atual);
          atualizar();
        }}
      >${S.criacao.recomecar}</st-button>
    </div>
  `;
}

function ordenar(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const ordem = puzzle.ordem ?? [];

  return html`
    <div class="criacao__cabecalho-lista">
      <p class="criacao__dica">${S.criacao.ordenarDica}</p>
      <st-button
        size="small"
        ?disabled=${resolvido || ordem.length === 0}
        @click=${() => {
          puzzle.ordem = [];
          feedback = '';
          sincronizarViz(atual);
          atualizar();
        }}
      >${S.criacao.recomecar}</st-button>
    </div>

    <div class="criacao__cards">
      ${(puzzle.itens ?? []).map(
        (item) => html`
          <button
            class="criacao__card ${ordem.includes(item.id) ? 'criacao__card--posto' : ''}"
            ?disabled=${resolvido}
            @click=${() => {
              const pos = ordem.indexOf(item.id);
              if (pos >= 0) ordem.splice(pos, 1);
              else ordem.push(item.id);
              feedback = '';
              sincronizarViz(atual);
              atualizar();
            }}
          >
            <span class="criacao__ordem">${ordem.indexOf(item.id) + 1 || '+'}</span>
            <span>${item.texto}</span>
          </button>
        `,
      )}
    </div>

    ${leitura(atual.info())}
  `;
}

function ciclos(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const todos = puzzle.ciclos ?? {};
  const ativo = todos[puzzle.ativo ?? 'agua'];
  if (ativo === undefined) return html``;

  return html`
    <div class="criacao__abas">
      ${Object.entries(todos).map(
        ([id, ciclo]) => html`
          <button
            class="criacao__aba ${puzzle.ativo === id ? 'criacao__aba--ativa' : ''}"
            ?disabled=${resolvido}
            @click=${() => {
              puzzle.ativo = id;
              sincronizarViz(atual);
              atualizar();
            }}
          >
            ${ciclo.nome}
          </button>
        `,
      )}
    </div>

    <div class="criacao__cabecalho-lista">
      <span></span>
      <st-button
        size="small"
        ?disabled=${resolvido || ativo.ordem.length === 0}
        @click=${() => {
          ativo.ordem = [];
          feedback = '';
          sincronizarViz(atual);
          atualizar();
        }}
      >${S.criacao.ciclosRecomecar}</st-button>
    </div>

    <div class="criacao__cards">
      ${ativo.itens.map(
        (item) => html`
          <button
            class="criacao__card ${ativo.ordem.includes(item.id) ? 'criacao__card--posto' : ''}"
            ?disabled=${resolvido}
            @click=${() => {
              const pos = ativo.ordem.indexOf(item.id);
              if (pos >= 0) ativo.ordem.splice(pos, 1);
              else ativo.ordem.push(item.id);
              feedback = '';
              sincronizarViz(atual);
              atualizar();
            }}
          >
            <span class="criacao__ordem">${ativo.ordem.indexOf(item.id) + 1 || '+'}</span>
            <span>
              <strong>${item.curto}</strong>
              <small>${item.texto}</small>
            </span>
          </button>
        `,
      )}
    </div>

    ${leitura(atual.info())}
  `;
}

function etapas(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const passos = puzzle.passos ?? [];
  const indice = puzzle.atual ?? 0;
  const passo = passos[indice];
  if (passo === undefined) return html``;

  return html`
    <div class="criacao__trilha-passos">
      ${passos.map(
        (_, i) => html`
          <span
            class="criacao__degrau ${i < indice ? 'criacao__degrau--feito' : i === indice ? 'criacao__degrau--atual' : ''}"
          ></span>
        `,
      )}
      <span class="criacao__contagem">${indice + 1}/${passos.length}</span>
    </div>

    ${
      puzzle.conclusao === null || puzzle.conclusao === undefined
        ? nothing
        : html`
          <div class="criacao__conclusao">
            <strong>${puzzle.conclusaoTitulo}</strong>
            <p>${puzzle.conclusao}</p>
          </div>
        `
    }

    <h2 class="criacao__passo-titulo">${passo.titulo}</h2>
    <p class="criacao__passo-pergunta">${passo.pergunta}</p>
    <p class="criacao__verso">${passo.verso}</p>

    ${
      passo.entrada === 'escolha'
        ? html`
          <div class="criacao__opcoes">
            ${(passo.opcoes ?? []).map(
              (opcao) => html`
                <button
                  class="criacao__opcao ${puzzle.escolhido === opcao.id ? 'criacao__opcao--ativa' : ''}"
                  ?disabled=${resolvido}
                  @click=${() => {
                    puzzle.escolhido = opcao.id;
                    feedback = '';
                    sincronizarViz(atual);
                    atualizar();
                  }}
                >
                  <strong>${opcao.rotulo}</strong>
                  ${opcao.nota === undefined ? nothing : html`<small>${opcao.nota}</small>`}
                </button>
              `,
            )}
          </div>
        `
        : html`
          <div class="criacao__controle">
            <label class="criacao__rotulo">
              <span>${passo.rotulo}</span>
              <strong>${valorDe(puzzle, passo.prop ?? '')}${passo.suf ?? ''}</strong>
            </label>
            <input
              type="range"
              min=${passo.min ?? 0}
              max=${passo.max ?? 100}
              step=${passo.step ?? 1}
              .value=${String(valorDe(puzzle, passo.prop ?? ''))}
              ?disabled=${resolvido}
              @input=${(e: Event) =>
                mexer(atual, passo.prop ?? '', Number((e.target as HTMLInputElement).value))}
            />
          </div>
          ${leitura(atual.info())}
        `
    }
  `;
}

function explorar(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;
  const info = atual.info();
  if (info === null) return html``;

  const vistos = puzzle.vistos ?? [];

  return html`
    <div class="criacao__cabecalho-lista">
      <span class="criacao__contagem ${info.ok ? 'criacao__contagem--ok' : ''}">
        ${vistos.length}/${puzzle.mapa?.length ?? 0} ${S.criacao.visoes}
      </span>
      <span class="criacao__dica">${S.criacao.explorarDica}</span>
    </div>

    <div class="criacao__mapa">
      ${(puzzle.mapa ?? []).map(
        (item) => html`
          <button
            class="criacao__ponto ${
              puzzle.ativoMapa === item.id
                ? 'criacao__ponto--ativo'
                : vistos.includes(item.id)
                  ? 'criacao__ponto--visto'
                  : ''
            }"
            @click=${() => {
              if (resolvido) return;
              puzzle.ativoMapa = item.id;
              if (!vistos.includes(item.id)) vistos.push(item.id);
              feedback = '';
              sincronizarViz(atual);
              atualizar();
            }}
          >
            ${item.rotulo}
          </button>
        `,
      )}
    </div>

    <article class="criacao__visao">
      <header>
        <span class="criacao__contagem">${String(info.rotulo)} visão</span>
        <span class="criacao__verso">Apocalipse ${String(info.ref)}</span>
        ${info.desdobra === true ? html`<span class="criacao__desdobra">${S.criacao.explorarDesdobra}</span>` : nothing}
      </header>
      <p>${String(info.resumo)}</p>
      <p class="criacao__encaixe ${info.desdobra === true ? 'criacao__encaixe--forte' : ''}">
        ${String(info.encaixe)}
      </p>
    </article>

    ${leitura(info)}
  `;
}

function solar(atual: Instancia): TemplateResult {
  const puzzle = atual.puzzle;

  return html`
    ${
      puzzle.solar?.modo === 'lancamento'
        ? html`
          <st-button
            variant="primary"
            ?disabled=${resolvido || emVoo(puzzle)}
            @click=${() => {
              puzzle.resultado = { situacao: 'voando' };
              viz?.lancar?.({ ...puzzle.valores });
              atualizar();
            }}
          >${emVoo(puzzle) ? S.criacao.orbVoando : S.criacao.lancar}</st-button>
        `
        : nothing
    }
    ${controles(atual)}
    ${leitura(atual.info())}
  `;
}

/** Os painéis que alguns puzzles põem acima do gráfico. */
function painel(atual: Instancia): TemplateResult | typeof nothing {
  const info = atual.info();
  const comp = atual.puzzle.viz?.comp;
  if (info === null) return nothing;

  if (comp === 'proteina') {
    const relogio = info.relogio as
      | {
          necessarias: number;
          disponiveis: number;
          faltam: number;
          anos: number;
          concluido: boolean;
        }
      | undefined;
    const dados = atual.puzzle.vizDados;

    return html`
      <div class="criacao__painel">
        <span class="criacao__marca">
          ${S.criacao.proteinaRecorde}: ${dados?.recorde ?? 0} / ${dados?.total ?? valorDe(atual.puzzle, 'aa')}
        </span>
        <span class="criacao__marca">${S.criacao.proteinaAgora}: ${dados?.acertos ?? 0}</span>
      </div>
      ${
        relogio === undefined
          ? nothing
          : html`
            <div class="criacao__relogio">
              <strong>${S.criacao.proteinaRelogio}</strong>
              <p>${S.criacao.proteinaNecessarias}: 1 em 10<sup>${relogio.necessarias}</sup></p>
              ${
                relogio.concluido
                  ? nothing
                  : html`
                    <p>${S.criacao.proteinaFaltam} 10<sup>${relogio.faltam}</sup> vezes mais tentativas.</p>
                    <p>${S.criacao.proteinaTempo} ~10<sup>${relogio.anos}</sup> ${S.criacao.proteinaAnos}</p>
                  `
              }
            </div>
          `
      }
    `;
  }

  if (comp === 'elementos') {
    return html`
      <div class="criacao__elemento" style=${`--cor:${String(info.catCor)}`}>
        <span class="criacao__simbolo">
          <strong>${String(info.simbolo)}</strong><small>${String(info.z)}</small>
        </span>
        <span class="criacao__ficha">
          <strong>${String(info.nome)}</strong>
          <span class="criacao__marcas">
            <span class="criacao__marca">${String(info.massaTxt)}</span>
            <span class="criacao__marca">${String(info.catNome)}</span>
            <span class="criacao__marca">${String(info.estadoNome)}</span>
            <span class="criacao__marca">${S.criacao.camadas}: ${String(info.camadasTxt)}</span>
          </span>
          ${info.fato === '' ? nothing : html`<small class="criacao__fato">${String(info.fato)}</small>`}
        </span>
      </div>
    `;
  }

  if (comp === 'ciclos') {
    const feitos = Array.isArray(info.feitos) ? info.feitos.length : 0;
    const total = Array.isArray(info.ids) ? info.ids.length : 0;
    return html`
      <div class="criacao__painel">
        <span class="criacao__marca ${info.ok ? 'criacao__contagem--ok' : ''}">
          ${feitos}/${total} ${S.criacao.ciclosFechados}
        </span>
      </div>
    `;
  }

  if (comp === 'terra_criacao') {
    return html`
      <div class="criacao__painel">
        <span class="criacao__marca">${String(info.rotulo)}</span>
        <span class="criacao__verso">${String(info.verso)}</span>
      </div>
    `;
  }

  if (comp === 'gaivota') {
    const arranjo = atual.puzzle.valores.arranjo;
    return html`
      <div class="criacao__abas">
        <button
          class="criacao__aba ${arranjo === 'mesmo' ? 'criacao__aba--ativa' : ''}"
          ?disabled=${resolvido}
          @click=${() => {
            atual.puzzle.valores.arranjo = 'mesmo';
            sincronizarViz(atual);
            atualizar();
          }}
        >${S.criacao.gaivotaMesmo}</button>
        <button
          class="criacao__aba ${arranjo === 'oposto' ? 'criacao__aba--ativa' : ''}"
          ?disabled=${resolvido}
          @click=${() => {
            atual.puzzle.valores.arranjo = 'oposto';
            sincronizarViz(atual);
            atualizar();
          }}
        >${S.criacao.gaivotaOposto}</button>
      </div>
      <div class="criacao__painel">
        <span class="criacao__marca">
          ${S.criacao.gaivotaVolta}: <strong>${Number(info.tRetorno).toFixed(1).replace('.', ',')} °C</strong>
        </span>
        <span class="criacao__marca">
          ${S.criacao.gaivotaPe}: <strong>${Number(info.tPe).toFixed(1).replace('.', ',')} °C</strong>
        </span>
        <span class="criacao__marca ${info.ok ? 'criacao__contagem--ok' : ''}">
          ${S.criacao.gaivotaCalor}: <strong>${String(info.pct)}%</strong>
        </span>
      </div>
    `;
  }

  return nothing;
}

function corpoDoPuzzle(atual: Instancia): TemplateResult {
  switch (atual.puzzle.arquetipo) {
    case 'numerico':
      return numerico(atual);
    case 'slider':
      return html`${controles(atual)}${leitura(atual.info())}`;
    case 'escolha':
      return escolha(atual);
    case 'pares':
      return pares(atual);
    case 'rota':
      return rota(atual);
    case 'ordenar':
      return ordenar(atual);
    case 'ciclos':
      return ciclos(atual);
    case 'etapas':
      return etapas(atual);
    case 'explorar':
      return explorar(atual);
    case 'solar':
      return solar(atual);
    default:
      return html`<p class="criacao__dica">${S.criacao.leiaReflexao}</p>`;
  }
}

function rotuloDoBotao(puzzle: Puzzle): string {
  if (puzzle.arquetipo === 'etapas' && (puzzle.atual ?? 0) < (puzzle.passos?.length ?? 1) - 1) {
    return S.criacao.avancar;
  }
  return puzzle.arquetipo === 'explorar' ? S.criacao.concluirMapa : S.criacao.verificar;
}

// ── Interativo ──────────────────────────────────────────────────────────────

function interativo(m: ModuloCriacao): TemplateResult {
  const atual = garantirInstancia(m);
  const puzzle = atual.puzzle;

  return html`
    <div class="criacao">
      <article class="criacao__bloco">
        ${
          puzzle.viz === undefined
            ? nothing
            : html`
              <div class="criacao__viz">
                ${painel(atual)}
                ${
                  // Chaveado pelo módulo: um `<canvas>` só aceita UM tipo de
                  // contexto na vida. Reaproveitar o elemento entre um puzzle 3D
                  // (PixiJS, WebGL) e um 2D fazia `getContext('2d')` devolver
                  // `null`, e a cena seguinte não desenhava mais nada.
                  keyed(
                    m.id,
                    html`
                      <canvas
                        ${ref(canvasRef)}
                        style=${`aspect-ratio:${puzzle.viz.aspecto ?? '16/10'}`}
                      ></canvas>
                    `,
                  )
                }
                ${puzzle.viz.dica === undefined ? nothing : html`<p class="criacao__dica">${puzzle.viz.dica}</p>`}
              </div>
            `
        }

        ${corpoDoPuzzle(atual)}

        ${
          feedback === ''
            ? nothing
            : html`<p class="criacao__feedback criacao__feedback--${feedbackTipo}">${feedback}</p>`
        }

        ${
          puzzle.arquetipo === 'pronto'
            ? nothing
            : html`
              <st-button
                variant="primary"
                ?disabled=${!podeVerificar(puzzle) || resolvido}
                @click=${() => verificar(m, atual)}
              >${rotuloDoBotao(puzzle)}</st-button>
            `
        }
      </article>

      ${
        puzzle.arquetipo === 'pronto' && !concluidoInline
          ? html`
            <st-button variant="success" @click=${() => concluirPronto(m)}>
              ${S.criacao.concluir}
            </st-button>
          `
          : nothing
      }

      ${concluidoInline ? reflexao(m) : nothing}
    </div>
  `;
}

