// ── Zoom da ilustração ──────────────────────────────────────────────────────

function zoom(m: ModuloCriacao): TemplateResult | typeof nothing {
  if (zoomImagem === null) return nothing;

  return html`
    <div
      class="criacao__zoom"
      @click=${(e: Event) => {
        if (e.target === e.currentTarget) {
          zoomImagem = null;
          atualizar();
        }
      }}
    >
      <st-icon-button
        name="x"
        label=${S.criacao.fechar}
        @click=${() => {
          zoomImagem = null;
          atualizar();
        }}
      ></st-icon-button>
      <img
        src=${`imagens/${zoomImagem}`}
        alt=${m.titulo}
        class=${zoomAmpliado ? 'criacao__zoom-img criacao__zoom-img--ampliada' : 'criacao__zoom-img'}
        @click=${() => {
          zoomAmpliado = !zoomAmpliado;
          atualizar();
        }}
      />
    </div>
  `;
}

// ── A tela ──────────────────────────────────────────────────────────────────

/** O módulo aberto pela rota, se houver. */
function abertoNa(rota: Rota): ModuloCriacao | undefined {
  const id = Number(rota.args[0]);
  return Number.isFinite(id) ? moduloPorId(id) : undefined;
}

function jogando(rota: Rota): boolean {
  return rota.args[1] === 'jogar';
}

export const telaCriacao: Tela = {
  titulo(rota) {
    return abertoNa(rota)?.titulo;
  },

  voltarPara(rota) {
    const modo = rota.modulo === 'entenda' ? 'entenda' : 'criacao';
    const aberto = abertoNa(rota);
    // Da raiz dos dois módulos volta-se para o hub de onde se entrou, não para
    // a home: os tiles de "Teve um Projeto?" e "Entenda Melhor" estão dentro de
    // "Meu Estudo Pessoal", e cair no painel era sair um degrau demais.
    if (aberto === undefined) return 'hub/estudo';
    return jogando(rota) ? `${modo}/${aberto.id}` : modo;
  },

  conteudo(rota) {
    carregar();

    const modo: ModoId = rota.modulo === 'entenda' ? 'entenda' : 'criacao';
    const aberto = abertoNa(rota);

    // Sair do puzzle libera a cena: uma viz viva fora da tela continuaria
    // animando (e, no caso do sistema solar, integrando uma trajetória).
    if (aberto === undefined || !jogando(rota)) {
      if (instancia !== null) largar();
      zoomAmpliado = zoomImagem === null ? false : zoomAmpliado;
    }

    if (aberto === undefined) return lista(modo);
    if (!jogando(rota)) return html`${conceito(aberto)}${zoom(aberto)}`;

    const marcacao = interativo(aberto);
    // O canvas só existe depois deste desenho; montar aqui é o equivalente ao
    // `x-init` do legado, sem depender de um evento do elemento.
    queueMicrotask(() => {
      if (instancia !== null) montarViz(instancia);
    });
    return marcacao;
  },
};
