/**
 * Os tópicos de fábrica do Tutorial do Papiro.
 *
 * Moraram em `apps/papiro/src/modulos/tutorial/dados.ts` enquanto o Tutorial não
 * tinha tabela: eram o que o PWA mostrava na primeira execução. Agora que
 * `pap_tutorial` existe, eles têm dois consumidores — o admin, que semeia a
 * tabela com eles na criação do banco local, e o PWA, que continua caindo neles
 * enquanto a sincronização não trouxer o acervo curado. Duas cópias do mesmo
 * texto seria uma para envelhecer sozinha, então o texto mora aqui.
 *
 * São curtos de propósito: dizem para que o módulo serve, como se usa e o que
 * costuma escapar. Texto longo é trabalho do admin, que pode reescrever sem
 * rebuild do app.
 */

import type { TopicoDeFabrica } from '../db/extras.ts';

function topico(
  id: number,
  moduloId: string,
  titulo: string,
  resumo: string,
  paragrafos: readonly string[],
): TopicoDeFabrica {
  return {
    id,
    modulo_id: moduloId,
    titulo,
    resumo,
    conteudo: paragrafos.map((texto) => `<p>${texto}</p>`).join(''),
    ordem: id,
    publicar: 1,
  };
}

