/**
 * A tela das Metas — porte de `modulos/metas/metas.js` e da seção correspondente
 * do `index.html` legado.
 *
 * Lista (`#/metas`) e formulário (`#/metas/nova`, `#/metas/<id>`). O acento
 * lateral e a cor da barra vêm do prazo: atrasada, esta semana, ou em dia — é a
 * leitura que o usuário faz de longe, antes de ler qualquer número.
 *
 * Nas metas automáticas o formulário não oferece campo de progresso: ele é
 * derivado do módulo de origem (ver `dados.ts`), e um campo editável ali seria
 * uma promessa falsa.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { dataBR, dataLocalISO, epochDeDataISO, hojeMaisDiasISO } from '../../datas.ts';
import { S } from '../../strings.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { notificar } from '../../ui/notificar.ts';
import {
  AUTOMATICAS,
  ajustar,
  alternarConclusao,
  CATEGORIAS,
  carregarFontes,
  categoriaDe,
  concluida,
  excluirMeta,
  type Filtro,
  type Fontes,
  listar,
  listarMetas,
  type Meta,
  medida,
  percentual,
  rotuloCategoria,
  salvarMeta,
  statusPrazo,
  sufixo,
  valorAtual,
  valorAutomatico,
} from './dados.ts';

/** O formulário, com as datas em `YYYY-MM-DD` para caber no campo de data. */
interface Formulario {
  id: number;
  titulo: string;
  item: string;
  ativoNome: string;
  dataMeta: string;
  prazoFinal: string;
  progressoAtual: number;
  progressoAlvo: number;
  concluida: number;
}

let todas: Meta[] = [];
let fontes: Fontes | null = null;
let categoriasFinanceiro: { id?: number; nome?: string }[] = [];
let filtro: Filtro = 'ativas';
let busca = '';
let form: Formulario | null = null;

let carregada: string | undefined;
let carregando = false;

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregar(): Promise<void> {
  const [lista, origens] = await Promise.all([listarMetas(), carregarFontes()]);
  todas = lista;
  fontes = origens.fontes;
  categoriasFinanceiro = origens.categoriasFinanceiro;
  atualizar();
}

function formNovo(): Formulario {
  return {
    id: 0,
    titulo: '',
    item: CATEGORIAS[0]?.chave ?? '',
    ativoNome: '',
    dataMeta: dataLocalISO(),
    prazoFinal: hojeMaisDiasISO(30),
    progressoAtual: 0,
    progressoAlvo: 100,
    concluida: 0,
  };
}

function sincronizar(rota: Rota): void {
  const chave = rota.args.join('/');
  if (carregada === chave || carregando) return;

  carregada = chave;
  carregando = true;

  void (async () => {
    try {
      // Recalcula ao (re)entrar: reflete o que mudou nos módulos de origem.
      await recarregar();

      const [primeiro] = rota.args;

      if (primeiro === undefined) {
        form = null;
      } else if (primeiro === 'nova') {
        form = formNovo();
      } else {
        const meta = todas.find((item) => item.id === Number.parseInt(primeiro, 10));
        if (meta === undefined) {
          navegar('metas');
          return;
        }

        form = {
          id: meta.id ?? 0,
          titulo: meta.titulo,
          item: meta.item,
          ativoNome: meta.ativo_nome,
          dataMeta: meta.data_meta ? dataLocalISO(meta.data_meta) : dataLocalISO(),
          prazoFinal: meta.prazo_final ? dataLocalISO(meta.prazo_final) : hojeMaisDiasISO(30),
          progressoAtual: meta.progresso_atual,
          progressoAlvo: meta.progresso_alvo,
          concluida: meta.esta_concluida,
        };
      }
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Lista ───────────────────────────────────────────────────────────────────

function cartao(meta: Meta): TemplateResult {
  const status = statusPrazo(meta, fontes);
  const automatica = AUTOMATICAS.has(meta.item);
  const fechada = concluida(meta, fontes);

  return html`
    <div class="meta" data-status=${status}>
      <div class="meta__topo">
        <span class="meta__titulo">${meta.titulo}</span>
        <st-badge variant=${fechada ? 'success' : 'neutral'} pill>
          ${percentual(meta, fontes)}%
        </st-badge>
      </div>

      <span class="meta__categoria">${rotuloCategoria(meta)}</span>

      <div class="meta__barra" role="presentation">
        <div class="meta__preenchido" style=${`width:${percentual(meta, fontes)}%`}></div>
      </div>

      <div class="meta__numeros">
        <span>
          ${medida(valorAtual(meta, fontes), meta.item)} /
          ${medida(meta.progresso_alvo, meta.item)}
        </span>
        <span class="meta__prazo">${S.metas.prazo(dataBR(meta.prazo_final))}</span>
      </div>

      <div class="meta__acoes">
        ${
          automatica
            ? html`
              <span class="meta__auto" title=${S.metas.automaticaAjuda}>
                <st-icon name="refresh"></st-icon>${S.metas.automatica}
              </span>
            `
            : html`
              <st-icon-button
                name="minus"
                label=${S.metas.diminuir}
                @click=${async () => {
                  await ajustar(meta, -1);
                  await recarregar();
                }}
              ></st-icon-button>
              <st-icon-button
                name="plus"
                label=${S.metas.aumentar}
                @click=${async () => {
                  await ajustar(meta, 1);
                  await recarregar();
                }}
              ></st-icon-button>
            `
        }

        <st-button
          size="small"
          variant=${fechada ? 'neutral' : 'success'}
          outline
          @click=${async () => {
            await alternarConclusao(meta);
            await recarregar();
          }}
        >
          <st-icon slot="prefix" name=${fechada ? 'rotate' : 'check'}></st-icon>
          ${fechada ? S.metas.reabrir : S.metas.concluir}
        </st-button>

        <st-icon-button
          name="pencil"
          label=${S.acoes.editar}
          @click=${() => navegar(`metas/${meta.id ?? ''}`)}
        ></st-icon-button>
        <st-icon-button
          name="trash"
          label=${S.metas.excluir}
          @click=${() => void excluir(meta)}
        ></st-icon-button>
      </div>
    </div>
  `;
}

async function excluir(meta: Meta): Promise<void> {
  const ok = await confirmar({
    titulo: S.metas.excluir,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok || meta.id === undefined) return;

  await excluirMeta(meta.id);
  notificar(S.metas.excluida);
  await recarregar();
}

function telaDaLista(): TemplateResult {
  const visiveis = listar(todas, fontes, filtro, busca);
  const abertas = todas.filter((meta) => !concluida(meta, fontes)).length;

  return html`
    <p class="intro">${S.metas.resumo(abertas, todas.length - abertas)}</p>

    <div class="filtros">
      <st-input
        class="filtros__busca"
        type="search"
        clearable
        placeholder=${S.metas.buscar}
        .value=${busca}
        @st-input=${(evento: Event) => {
          busca = (evento.target as HTMLInputElement).value;
          atualizar();
        }}
      >
        <st-icon slot="prefix" name="search"></st-icon>
      </st-input>
    </div>

    <div class="chips">
      ${(['ativas', 'concluidas', 'todas'] as const).map(
        (chave) => html`
          <button
            class="chip"
            ?data-ativo=${filtro === chave}
            @click=${() => {
              filtro = chave;
              atualizar();
            }}
          >
            ${S.metas.filtros[chave]}
          </button>
        `,
      )}
    </div>

    ${
      visiveis.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="target"></st-icon>
            <p>${todas.length === 0 ? S.metas.vazio : S.metas.semFiltro}</p>
          </div>
        `
        : html`<div class="metas">${visiveis.map((meta) => cartao(meta))}</div>`
    }
  `;
}

// ── Formulário ──────────────────────────────────────────────────────────────

async function salvar(): Promise<void> {
  if (form === null) return;

  if (form.titulo.trim() === '') {
    notificar(S.metas.informeTitulo, 'warning');
    return;
  }

  const automatica = AUTOMATICAS.has(form.item);
  const alvo = Number(form.progressoAlvo) > 0 ? Number(form.progressoAlvo) : 1;
  // Automática não guarda progresso à mão: ele é derivado, e gravar um número
  // aqui criaria duas versões da mesma verdade.
  const atual = automatica ? 0 : Math.max(0, Number(form.progressoAtual));

  const registro: Meta = {
    ...(form.id > 0 ? { id: form.id } : {}),
    titulo: form.titulo,
    item: form.item,
    ativo_id: 0,
    ativo_nome: categoriaDe(form.item).precisaAtivo === true ? form.ativoNome : '',
    data_meta: form.dataMeta === '' ? Date.now() : epochDeDataISO(form.dataMeta),
    prazo_final: form.prazoFinal === '' ? Date.now() : epochDeDataISO(form.prazoFinal),
    progresso_atual: atual,
    progresso_alvo: alvo,
    esta_concluida: form.concluida === 1 || (!automatica && atual >= alvo) ? 1 : 0,
  };

  await salvarMeta(registro);
  notificar(S.metas.salva);
  navegar('metas');
}

function telaDoFormulario(estado: Formulario): TemplateResult {
  const categoria = categoriaDe(estado.item);
  const automatica = AUTOMATICAS.has(estado.item);

  // Uma meta automática mostra o valor que já vem do módulo de origem: é a
  // resposta à pergunta "e quanto disso eu já fiz?" na hora de escolher o alvo.
  const derivado = valorAutomatico(
    {
      titulo: estado.titulo,
      item: estado.item,
      ativo_nome: estado.ativoNome,
      data_meta: 0,
      prazo_final: 0,
      progresso_atual: estado.progressoAtual,
      progresso_alvo: estado.progressoAlvo,
      esta_concluida: estado.concluida,
    },
    fontes,
  );

  return html`
    <div class="formulario">
      <st-input
        label=${S.metas.titulo}
        placeholder=${S.metas.tituloPlaceholder}
        .value=${estado.titulo}
        @st-input=${(evento: Event) => {
          form = { ...estado, titulo: (evento.target as HTMLInputElement).value };
        }}
      ></st-input>

      <st-select
        label=${S.metas.categoria}
        .value=${estado.item}
        @st-change=${(evento: Event) => {
          form = { ...estado, item: (evento.target as HTMLInputElement).value };
          atualizar();
        }}
      >
        ${CATEGORIAS.map(
          (item) => html`<st-option value=${item.chave}>${item.modulo}: ${item.ativo}</st-option>`,
        )}
      </st-select>

      ${
        categoria.precisaAtivo !== true
          ? nothing
          : html`
            <st-select
              label=${S.metas.ativo}
              .value=${estado.ativoNome}
              @st-change=${(evento: Event) => {
                form = { ...estado, ativoNome: (evento.target as HTMLInputElement).value };
                atualizar();
              }}
            >
              <st-option value="">${S.perfil.selecione}</st-option>
              ${categoriasFinanceiro.map(
                (item) => html`<st-option value=${item.nome ?? ''}>${item.nome}</st-option>`,
              )}
            </st-select>
          `
      }

      <div class="formulario__par">
        <st-input
          type="number"
          label=${S.metas.alvo(sufixo(estado.item))}
          .value=${String(estado.progressoAlvo)}
          @st-input=${(evento: Event) => {
            form = { ...estado, progressoAlvo: Number((evento.target as HTMLInputElement).value) };
          }}
        ></st-input>

        ${
          automatica
            ? html`
              <st-input
                readonly
                label=${S.metas.atualAutomatico}
                .value=${medida(derivado ?? 0, estado.item)}
                help-text=${S.metas.automaticaAjuda}
              ></st-input>
            `
            : html`
              <st-input
                type="number"
                label=${S.metas.atual(sufixo(estado.item))}
                .value=${String(estado.progressoAtual)}
                @st-input=${(evento: Event) => {
                  form = {
                    ...estado,
                    progressoAtual: Number((evento.target as HTMLInputElement).value),
                  };
                }}
              ></st-input>
            `
        }
      </div>

      <div class="formulario__par">
        <st-input
          type="date"
          label=${S.metas.inicio}
          .value=${estado.dataMeta}
          @st-change=${(evento: Event) => {
            form = { ...estado, dataMeta: (evento.target as HTMLInputElement).value };
          }}
        ></st-input>
        <st-input
          type="date"
          label=${S.metas.prazoFinal}
          .value=${estado.prazoFinal}
          @st-change=${(evento: Event) => {
            form = { ...estado, prazoFinal: (evento.target as HTMLInputElement).value };
          }}
        ></st-input>
      </div>

      <div class="editor__acoes">
        <st-button variant="primary" @click=${() => void salvar()}>
          <st-icon slot="prefix" name="check"></st-icon>${S.acoes.salvar}
        </st-button>
        <st-button @click=${() => navegar('metas')}>${S.acoes.cancelar}</st-button>
      </div>
    </div>
  `;
}

export const telaMetas: Tela = {
  voltarPara(rota) {
    // As Metas saíram de "Vida e Ministério" e entraram no hub "Pessoal"
    // (Leva 4.3): metas de vida são do usuário, não do ministério.
    return rota.args.length === 0 ? 'hub/pessoal' : 'metas';
  },

  titulo(rota) {
    if (rota.args.length === 0) return undefined;
    return form !== null && form.id > 0 ? S.metas.editar : S.metas.nova;
  },

  acoes(rota) {
    if (rota.args.length > 0) return undefined;

    return html`
      <st-icon-button
        name="plus"
        label=${S.metas.nova}
        @click=${() => navegar('metas/nova')}
      ></st-icon-button>
    `;
  },

  conteudo(rota) {
    sincronizar(rota);

    if (rota.args.length === 0) return telaDaLista();
    return form === null
      ? html`<div class="carregando"><st-spinner></st-spinner></div>`
      : telaDoFormulario(form);
  },
};
