/**
 * Os dados das Receitas — porte da parte de banco de
 * `sang.local/src/Papiro/Pwa/modulos/receitas/receitas.js`.
 *
 * Dois stores (`receitas` curado e `receitas_local`), como Guias e Poesia, com
 * uma diferença que vem do legado: aqui o usuário edita e exclui **também** as
 * curadas. Uma receita mexida na cozinha dele é dele; se um export futuro do
 * admin trouxer a original de volta, é o comportamento esperado — o acervo é a
 * fonte, a cópia no aparelho é a dele.
 */

import { repositorio } from '../../db/banco.ts';
import { buscar, type ComOrigem, type ItemDeAcervo, juntar } from '../acervo.ts';

/** Uma receita, curada ou local. Ingredientes e preparo são texto puro. */
export interface Receita extends ItemDeAcervo {
  id?: number;
  titulo: string;
  categoria: string;
  ingredientes: string;
  instrucoes: string;
  publicar?: number;
  data_criacao?: number;
  data_atualizacao?: number;
}

/**
 * As categorias oferecidas no editor — espelham o app Kotlin, como no legado.
 */
// biome-ignore format: uma grade de emoji em coluna única é ilegível
export const CATEGORIAS: readonly string[] = [
  '🍽️', '🥗', '🍲', '🍰', '🥤', '🍞', '🍝', '🥩', '🐟', '🍕', '☕', '🍎',
  '🎂', '🧁', '🍫', '🥧', '🍮', '🥞', '🍳', '🧀', '🥘', '🍤', '🍚', '🍜',
  '🌮', '🥟', '🥦', '🍓', '🍇', '🥑', '🍯', '🥛',
];

export const CHAVE_FAVORITOS = 'papiro_fav_receitas';

const curadas = () => repositorio('receitas');
const locais = () => repositorio('receitas_local');

/** O que a lista precisa: os itens filtrados e as categorias presentes neles. */
export interface Acervo {
  readonly itens: readonly ComOrigem<Receita>[];
  /** Todas as categorias do acervo — não só as que sobraram no filtro. */
  readonly categorias: readonly string[];
}

/**
 * A lista das duas origens. A ordem é a do legado: as suas primeiro, o acervo
 * curado depois. O filtro de categoria não pode encolher a lista de chips, ou o
 * usuário ficaria preso na categoria que escolheu — por isso as categorias saem
 * do acervo inteiro, antes de filtrar.
 */
export async function listarReceitas(termo: string, categoria: string): Promise<Acervo> {
  const [doAdmin, doAparelho] = await Promise.all([
    curadas().todos<Receita>(),
    locais().todos<Receita>(),
  ]);

  const todas = juntar(doAdmin, doAparelho);
  const categorias = [...new Set(todas.map((receita) => receita.categoria).filter(Boolean))].sort();

  let itens = buscar(todas, termo, (receita) => [receita.titulo, receita.categoria]);
  if (categoria !== '') itens = itens.filter((receita) => receita.categoria === categoria);

  return { itens, categorias };
}

export function obterReceita(id: number, local: boolean): Promise<Receita | undefined> {
  return (local ? locais() : curadas()).obter<Receita>(id);
}

export function salvarReceita(receita: Receita, local: boolean): Promise<number> {
  return (local ? locais() : curadas()).salvar(receita);
}

export function excluirReceita(id: number, local: boolean): Promise<void> {
  return (local ? locais() : curadas()).excluir(id);
}
