/**
 * Sincronização do conteúdo curado — porte de `sync/conteudo.js` do legado.
 *
 * O admin exporta `dados/*.json` e um `manifesto.json` em que a versão de cada
 * módulo é o hash do próprio arquivo. Por isso um export que mexeu num módulo só
 * não arrasta os outros: comparamos a versão do manifesto com a que ficou
 * guardada no aparelho e baixamos apenas o que mudou.
 */

import { papiro } from '@marinx/flavors';
import { repositorio, STORES_CURADOS } from './banco.ts';

/** Onde as versões já aplicadas ficam registradas entre sessões. */
const CHAVE_VERSOES = 'papiro_versoes_curado';

/** Nome do arquivo JSON → store local. Iguais hoje, mas o mapa é o contrato. */
const ARQUIVO_PARA_STORE: Readonly<Record<string, string>> = {
  perguntas: 'perguntas',
  poesias: 'poesias',
  receitas: 'receitas',
  guias: 'guias',
  kits: 'kits',
  criacao_modulos: 'criacao_modulos',
  cronologia: 'cronologia',
  anotacao_modelos: 'anotacao_modelos',
  estoque_catalogo: 'estoque_catalogo',
  tutorial: 'tutorial',
};

interface Manifesto {
  readonly modulos?: Readonly<Record<string, { readonly versao?: string }>>;
}

/** O que a sincronização conseguiu fazer nesta tentativa. */
export type ResultadoSync =
  | { readonly ok: true; readonly atualizados: readonly string[] }
  | { readonly ok: false; readonly motivo: 'offline' | 'sem-manifesto' };

function versoesLocais(): Record<string, string> {
  try {
    return JSON.parse(localStorage.getItem(CHAVE_VERSOES) ?? '{}') as Record<string, string>;
  } catch {
    return {};
  }
}

async function baixarJson<T>(arquivo: string): Promise<T | undefined> {
  try {
    const resposta = await fetch(`${papiro.apiEndpoint}/${arquivo}`, { cache: 'no-cache' });
    if (!resposta.ok) return undefined;
    return (await resposta.json()) as T;
  } catch {
    return undefined;
  }
}

/** Baixa e aplica o que mudou desde a última sincronização. */
export async function sincronizarConteudo(): Promise<ResultadoSync> {
  const manifesto = await baixarJson<Manifesto>('manifesto.json');
  if (manifesto === undefined) return { ok: false, motivo: 'offline' };

  const modulos = manifesto.modulos;
  if (modulos === undefined) return { ok: false, motivo: 'sem-manifesto' };

  const locais = versoesLocais();
  const atualizados: string[] = [];

  for (const [nome, info] of Object.entries(modulos)) {
    const store = ARQUIVO_PARA_STORE[nome];
    if (store === undefined || !STORES_CURADOS.includes(store as never)) continue;
    if (info.versao !== undefined && locais[nome] === info.versao) continue;

    const registros = await baixarJson<Record<string, unknown>[]>(`${nome}.json`);
    // Falha num módulo não derruba os outros nem apaga o que já estava lá: a
    // versão local fica como estava e a próxima sincronização tenta de novo.
    if (registros === undefined) continue;

    await repositorio(store).substituirTudo(registros);
    if (info.versao !== undefined) locais[nome] = info.versao;
    atualizados.push(nome);
  }

  localStorage.setItem(CHAVE_VERSOES, JSON.stringify(locais));

  await semearPadrao('categorias_financeiro', 'categorias.json');
  await semearTiposCalendarioPadrao();

  return { ok: true, atualizados };
}

/**
 * Semeia um store privado a partir de um arquivo curado, APENAS quando ele está
 * vazio. Depois disso o store é do usuário: a sincronização nunca o substitui —
 * é a diferença entre um padrão de fábrica e conteúdo curado.
 */
async function semearPadrao(store: string, arquivo: string): Promise<void> {
  const repo = repositorio(store);
  const existentes = await repo.todos().catch(() => []);
  if (existentes.length > 0) return;

  const itens = await baixarJson<Record<string, unknown>[]>(arquivo);
  if (itens === undefined) return;

  for (const item of itens) {
    // `publicar` é a chave do admin que decide o que sai no export; do lado do
    // aparelho ela não significa nada.
    const { publicar: _, ...resto } = item;
    await repo.salvar(resto);
  }
}

let semeandoTipos: Promise<void> | undefined;

/**
 * Os tipos de evento padrão do calendário.
 *
 * Exposta, e não só chamada pela sincronização, porque o módulo Calendário
 * também precisa dela no próprio init. A promessa memoizada garante que as duas
 * chamadas concorrentes esperem a MESMA semeadura — sem isso, cada uma insere os
 * seis tipos por conta própria e o usuário abre o app com doze.
 */
export function semearTiposCalendarioPadrao(): Promise<void> {
  semeandoTipos ??= semearPadrao('calendario_tipos', 'calendario_tipos.json');
  return semeandoTipos;
}
