/**
 * Notas de rodapé na leitura — porte de `notas.js` do legado.
 *
 * O editor grava só a marcação (`<a class="papiro-nota-ref" data-nota="…">`);
 * quem numera as referências e monta a lista no fim do texto é isto aqui.
 *
 * Duas diferenças em relação ao original, ambas por o app já não ser Alpine:
 * não há `MutationObserver` vigiando o `<body>` — o container é processado
 * quando a tela que o contém termina de desenhar —, e o popover de leitura
 * rápida saiu em favor do `title`, que o navegador já posiciona e anuncia.
 * O toque continua atendido pelo caminho principal: tocar na referência rola
 * até a nota, e a seta ↩ traz de volta.
 */

import { S } from '../strings.ts';

/** Os links de nota não navegam por hash: `#nota-1` destruiria a rota do app. */
function rolarAte(alvo: Element | undefined): void {
  alvo?.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

/**
 * Numera as notas de um container de leitura e monta o rodapé. Reprocessar o
 * mesmo container é seguro: o rodapé anterior é descartado antes.
 */
export function processarNotas(container: HTMLElement): void {
  container.querySelector(':scope > .rodape-notas')?.remove();

  const refs = container.querySelectorAll<HTMLAnchorElement>('.papiro-nota-ref[data-nota]');
  if (refs.length === 0) return;

  const rodape = document.createElement('div');
  rodape.className = 'rodape-notas';

  const titulo = document.createElement('h3');
  titulo.textContent = S.notas.titulo;

  const lista = document.createElement('ol');
  rodape.append(titulo, lista);

  for (const [indice, ref] of refs.entries()) {
    const nota = ref.getAttribute('data-nota') ?? '';

    ref.textContent = String(indice + 1);
    ref.href = '#';
    ref.title = nota;

    const item = document.createElement('li');
    item.textContent = nota;

    const voltar = document.createElement('a');
    voltar.className = 'rodape-notas__voltar';
    voltar.href = '#';
    voltar.textContent = '↩';
    voltar.setAttribute('aria-label', S.notas.voltar);
    voltar.addEventListener('click', (evento) => {
      evento.preventDefault();
      rolarAte(ref);
    });

    item.append(' ', voltar);
    lista.append(item);

    ref.addEventListener('click', (evento) => {
      evento.preventDefault();
      rolarAte(item);
    });
  }

  container.append(rodape);
}
