/**
 * A tela das Receitas — porte de `modulos/receitas/receitas.js` e da seção
 * correspondente do `index.html` do legado.
 *
 * Mesmas três vistas dos outros acervos (lista, leitura, editor). O que é próprio
 * daqui: os chips de categoria por emoji, os favoritos e um editor sem texto
 * rico — ingredientes e preparo são campos de linhas, um item por linha.
 *
 * A leitura ainda passa pelo `sanitizeHtml`: o acervo antigo foi escrito no editor
 * rico e traz `<ul>`/`<ol>`, enquanto o que o usuário digita hoje é texto puro
 * cujas quebras de linha o CSS preserva.
 */

import { sanitizeHtml } from '@marinx/stratum/components/editor/editor.js';
import { html, nothing, type TemplateResult } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { alternarFavorito, chaveFavorito, lerFavoritos } from '../../favoritos.ts';
import { S } from '../../strings.ts';
import { dataHora, textoLimpo } from '../../texto.ts';
import { compartilhar } from '../../ui/compartilhar.ts';
import { confirmar } from '../../ui/dialogo.ts';
import { Leitura } from '../../ui/leitura.ts';
import { notificar } from '../../ui/notificar.ts';
import { type ComOrigem, soIcone } from '../acervo.ts';
import {
  CATEGORIAS,
  CHAVE_FAVORITOS,
  excluirReceita,
  listarReceitas,
  obterReceita,
  type Receita,
  salvarReceita,
} from './dados.ts';

const ESPERA_BUSCA_MS = 400;
const ESPERA_SALVAR_MS = 1200;

interface Edicao {
  id: number | null;
  /** `false` quando o que está aberto é uma receita do acervo curado. */
  local: boolean;
  titulo: string;
  categoria: string;
  ingredientes: string;
  instrucoes: string;
  status: string;
}

let lista: readonly ComOrigem<Receita>[] = [];
let categorias: readonly string[] = [];
let busca = '';
let categoria = '';
let favoritos = new Set<string>();
let favoritosCarregados = false;

let aberta: Receita | null = null;
let abertaLocal = false;

let edicao: Edicao | null = null;

let carregada: string | undefined;
let carregando = false;

let timerBusca: ReturnType<typeof setTimeout> | undefined;
let timerSalvar: ReturnType<typeof setTimeout> | undefined;

const leitura = new Leitura();

// ── Favoritos ───────────────────────────────────────────────────────────────

function chave(receita: Receita, local: boolean): string {
  return chaveFavorito(local ? 'local' : 'curado', receita.id);
}

function eFavorita(receita: Receita, local: boolean): boolean {
  return favoritos.has(chave(receita, local));
}

function alternar(receita: Receita, local: boolean): void {
  favoritos = alternarFavorito(CHAVE_FAVORITOS, favoritos, chave(receita, local));
  atualizar();
}

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregarLista(): Promise<void> {
  const acervo = await listarReceitas(busca, categoria);
  lista = acervo.itens;
  categorias = acervo.categorias;
  atualizar();
}

async function abrirLeitura(id: number, local: boolean): Promise<void> {
  abertaLocal = local;
  aberta = (await obterReceita(id, local)) ?? null;
  if (aberta === null) navegar('receitas');
}

async function abrirEditor(id: number | null, local: boolean): Promise<void> {
  if (id === null) {
    edicao = {
      id: null,
      local: true,
      titulo: '',
      categoria: CATEGORIAS[0] ?? '',
      ingredientes: '',
      instrucoes: '',
      status: '',
    };
    atualizar();
    return;
  }

  const receita = await obterReceita(id, local);
  if (receita === undefined) {
    navegar('receitas');
    return;
  }

  edicao = {
    id: receita.id ?? null,
    local,
    titulo: receita.titulo,
    categoria: receita.categoria || (CATEGORIAS[0] ?? ''),
    ingredientes: receita.ingredientes,
    instrucoes: receita.instrucoes,
    status: '',
  };
  atualizar();
}

function sincronizar(rota: Rota): void {
  const chaveRota = rota.args.join('/');
  if (carregada === chaveRota || carregando) return;

  carregada = chaveRota;
  carregando = true;
  leitura.fechar();

  if (!favoritosCarregados) {
    favoritos = lerFavoritos(CHAVE_FAVORITOS);
    favoritosCarregados = true;
  }

  void (async () => {
    try {
      const [primeiro, segundo] = rota.args;
      const id = Number.parseInt(segundo ?? '', 10);

      if (primeiro === undefined) {
        aberta = null;
        edicao = null;
        await recarregarLista();
      } else if (primeiro === 'nova') {
        aberta = null;
        await abrirEditor(null, true);
      } else if (primeiro === 'editar') {
        aberta = null;
        await abrirEditor(id, true);
      } else if (primeiro === 'editar-curada') {
        aberta = null;
        await abrirEditor(id, false);
      } else if (primeiro === 'local') {
        edicao = null;
        await abrirLeitura(id, true);
      } else {
        edicao = null;
        await abrirLeitura(Number.parseInt(primeiro, 10), false);
      }
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

function noEditor(rota: Rota): boolean {
  const [primeiro] = rota.args;
  return primeiro === 'nova' || primeiro === 'editar' || primeiro === 'editar-curada';
}

// ── Lista ───────────────────────────────────────────────────────────────────

function aoBuscar(texto: string): void {
  busca = texto;
  clearTimeout(timerBusca);
  timerBusca = setTimeout(() => void recarregarLista(), ESPERA_BUSCA_MS);
}

function filtrarPor(cat: string): void {
  // Tocar de novo na categoria ativa desliga o filtro, como no legado.
  categoria = categoria === cat ? '' : cat;
  void recarregarLista();
}

function cartao(receita: ComOrigem<Receita>): TemplateResult {
  const favorita = eFavorita(receita, receita.local);

  return html`
    <div class="cartao cartao--com-acao" ?data-favorito=${favorita}>
      <button
        class="cartao__alvo"
        @click=${() =>
          navegar(
            receita.local ? `receitas/local/${receita.id ?? ''}` : `receitas/${receita.id ?? ''}`,
          )}
      >
        <span class="cartao__topo">
          <span class="cartao__emoji" aria-hidden="true">${soIcone(receita.categoria)}</span>
          <span class="cartao__titulo">${receita.titulo || S.acervo.semTitulo}</span>
          ${
            receita.local
              ? html`<st-badge variant="success" pill>${S.acervo.meu}</st-badge>`
              : nothing
          }
        </span>
      </button>

      <st-icon-button
        class="cartao__estrela"
        name="star"
        variant=${favorita ? 'filled' : 'outline'}
        label=${favorita ? S.receitas.desfavoritar : S.receitas.favoritar}
        @click=${() => alternar(receita, receita.local)}
      ></st-icon-button>
    </div>
  `;
}

function telaDaLista(): TemplateResult {
  return html`
    <div class="filtros">
      <st-input
        class="filtros__busca"
        type="search"
        clearable
        placeholder=${S.receitas.buscar}
        .value=${busca}
        @st-input=${(evento: Event) => aoBuscar((evento.target as HTMLInputElement).value)}
      >
        <st-icon slot="prefix" name="search"></st-icon>
      </st-input>
    </div>

    ${
      categorias.length === 0
        ? nothing
        : html`
          <div class="chips">
            <button class="chip" ?data-ativo=${categoria === ''} @click=${() => filtrarPor('')}>
              ${S.receitas.todas}
            </button>
            ${categorias.map(
              (cat) => html`
                <button
                  class="chip chip--emoji"
                  ?data-ativo=${categoria === cat}
                  title=${cat}
                  @click=${() => filtrarPor(cat)}
                >
                  ${soIcone(cat)}
                </button>
              `,
            )}
          </div>
        `
    }

    ${
      lista.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="chef-hat"></st-icon>
            <p>${S.receitas.vazio}</p>
          </div>
        `
        : html`<div class="cartoes">${lista.map((receita) => cartao(receita))}</div>`
    }
  `;
}

// ── Leitura ─────────────────────────────────────────────────────────────────

function textoDaReceita(receita: Receita): string {
  return (
    `${receita.titulo}. ${S.receitas.ingredientes}. ${textoLimpo(receita.ingredientes)}. ` +
    `${S.receitas.preparo}. ${textoLimpo(receita.instrucoes)}`
  );
}

function corpo(receita: Receita): TemplateResult {
  return html`
    ${
      receita.categoria === ''
        ? nothing
        : html`<p class="receita__categoria" aria-hidden="true">${soIcone(receita.categoria)}</p>`
    }

    <h2 class="secao">${S.receitas.ingredientes}</h2>
    <div class="prosa prosa--linhas">${unsafeHTML(sanitizeHtml(receita.ingredientes))}</div>

    <h2 class="secao">${S.receitas.preparo}</h2>
    <div class="prosa prosa--linhas">${unsafeHTML(sanitizeHtml(receita.instrucoes))}</div>
  `;
}

function telaDaLeitura(receita: Receita): TemplateResult {
  return html`
    ${corpo(receita)}
    ${leitura.overlay(
      html`
          <h1>${receita.titulo}</h1>
          ${corpo(receita)}
        `,
      () => textoDaReceita(receita),
    )}
  `;
}

async function excluirAtual(): Promise<void> {
  const id = aberta?.id;
  if (id === undefined) return;

  const ok = await confirmar({
    titulo: S.receitas.excluir,
    texto: S.acervo.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await excluirReceita(id, abertaLocal);
  notificar(S.receitas.excluida);
  navegar('receitas');
}

// ── Editor ──────────────────────────────────────────────────────────────────

function agendarSalvar(): void {
  if (edicao === null) return;
  edicao = { ...edicao, status: S.acervo.salvando };
  atualizar();

  clearTimeout(timerSalvar);
  timerSalvar = setTimeout(() => void salvar(), ESPERA_SALVAR_MS);
}

/** Grava a receita. Só o título é obrigatório, como no legado. */
async function salvar(): Promise<void> {
  if (edicao === null) return;

  if (edicao.titulo.trim() === '') {
    edicao = { ...edicao, status: S.acervo.informeTitulo };
    atualizar();
    return;
  }

  const agora = Date.now();
  // Preserva os campos que esta tela não conhece (`publicar`, `e_favorito` do
  // acervo curado): gravar só o que o editor mostra os apagaria.
  const base = edicao.id === null ? {} : ((await obterReceita(edicao.id, edicao.local)) ?? {});

  const registro: Receita = {
    ...base,
    titulo: edicao.titulo,
    categoria: edicao.categoria,
    ingredientes: edicao.ingredientes,
    instrucoes: edicao.instrucoes,
    data_atualizacao: agora,
    ...(edicao.id === null ? { publicar: 0, data_criacao: agora } : { id: edicao.id }),
  };

  const id = await salvarReceita(registro, edicao.local);

  if (edicao.id === null) {
    edicao = { ...edicao, id };
    history.replaceState(null, '', `#/receitas/editar/${id}`);
  }

  edicao = { ...edicao, status: S.acervo.salvoAs(dataHora(agora)) };
  atualizar();
}

function telaDoEditor(estado: Edicao): TemplateResult {
  const escolhida = (cat: string): boolean =>
    estado.categoria === cat || soIcone(estado.categoria) === cat;

  return html`
    <div class="editor">
      <st-input
        class="editor__titulo"
        placeholder=${S.receitas.tituloPlaceholder}
        .value=${estado.titulo}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, titulo: (evento.target as HTMLInputElement).value };
          agendarSalvar();
        }}
      ></st-input>

      <div class="editor__linha">
        <span class="editor__status">${estado.status}</span>
      </div>

      <h2 class="secao">${S.receitas.categoria}</h2>
      <div class="chips">
        ${CATEGORIAS.map(
          (cat) => html`
            <button
              class="chip chip--emoji"
              ?data-ativo=${escolhida(cat)}
              @click=${() => {
                edicao = { ...estado, categoria: cat };
                agendarSalvar();
              }}
            >
              ${cat}
            </button>
          `,
        )}
      </div>

      <h2 class="secao">${S.receitas.ingredientes}</h2>
      <st-textarea
        rows="8"
        resize="auto"
        placeholder=${S.receitas.ingredientesPlaceholder}
        .value=${estado.ingredientes}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, ingredientes: (evento.target as HTMLTextAreaElement).value };
          agendarSalvar();
        }}
      ></st-textarea>

      <h2 class="secao">${S.receitas.preparo}</h2>
      <st-textarea
        rows="10"
        resize="auto"
        placeholder=${S.receitas.preparoPlaceholder}
        .value=${estado.instrucoes}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, instrucoes: (evento.target as HTMLTextAreaElement).value };
          agendarSalvar();
        }}
      ></st-textarea>
    </div>
  `;
}

// ── A tela ──────────────────────────────────────────────────────────────────

function acoesDaLeitura(receita: Receita): TemplateResult {
  const favorita = eFavorita(receita, abertaLocal);
  const rota = abertaLocal ? 'receitas/editar/' : 'receitas/editar-curada/';

  return html`
    <st-icon-button
      name="star"
      variant=${favorita ? 'filled' : 'outline'}
      label=${favorita ? S.receitas.desfavoritar : S.receitas.favoritar}
      @click=${() => alternar(receita, abertaLocal)}
    ></st-icon-button>
    ${leitura.botaoApresentar()}
    ${leitura.botaoFala(() => textoDaReceita(receita))}
    <st-icon-button
      name="share"
      label=${S.leitura.compartilhar}
      @click=${() => void compartilhar(receita.titulo, textoDaReceita(receita))}
    ></st-icon-button>
    <st-icon-button
      name="pencil"
      label=${S.acoes.editar}
      @click=${() => navegar(`${rota}${receita.id ?? ''}`)}
    ></st-icon-button>
    <st-icon-button
      name="trash"
      label=${S.receitas.excluir}
      @click=${() => void excluirAtual()}
    ></st-icon-button>
  `;
}

export const telaReceitas: Tela = {
  voltarPara(rota) {
    return rota.args.length === 0 ? 'home' : 'receitas';
  },

  titulo(rota) {
    const [primeiro] = rota.args;
    if (primeiro === undefined) return undefined;

    if (noEditor(rota)) {
      const titulo = edicao?.titulo.trim() ?? '';
      return titulo === '' ? S.receitas.novaTitulo : titulo;
    }

    return aberta?.titulo;
  },

  acoes(rota) {
    const [primeiro] = rota.args;

    if (primeiro === undefined) {
      return html`
        <st-icon-button
          name="plus"
          label=${S.receitas.nova}
          @click=${() => navegar('receitas/nova')}
        ></st-icon-button>
      `;
    }

    if (noEditor(rota)) return undefined;
    return aberta === null ? undefined : acoesDaLeitura(aberta);
  },

  conteudo(rota) {
    sincronizar(rota);

    const [primeiro] = rota.args;
    if (primeiro === undefined) return telaDaLista();

    if (noEditor(rota)) {
      return edicao === null
        ? html`<div class="carregando"><st-spinner></st-spinner></div>`
        : telaDoEditor(edicao);
    }

    return aberta === null
      ? html`<div class="carregando"><st-spinner></st-spinner></div>`
      : telaDaLeitura(aberta);
  },
};
