/**
 * "Como fazer mais para Jeová" — a tela que transforma uma meta em agenda.
 *
 * A ordem da tela é a ordem da conversa: escolhe-se a modalidade (que preenche
 * o alvo), ajusta-se o alvo e o prazo, marcam-se os dias em que se pretende
 * sair, e só então aparece o que aquilo significa por saída. O calendário do
 * mês vem por último porque é a conclusão, não o começo.
 *
 * A conta inteira está em `dados.ts`, em funções puras. Aqui só se escolhe e se
 * desenha — é o que permite testar a distribuição sem DOM.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { navegar, type Rota } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { salvarMeta } from '../metas/dados.ts';
import {
  DIAS_DA_SEMANA,
  type Escolha,
  gradeDoMes,
  horasEMinutos,
  MODALIDADES,
  metaDoPlano,
  modalidadeDe,
  nomeDoMes,
  planejar,
  saidasNoMes,
} from './dados.ts';

/** Domingo e quarta: um fim de semana e um dia de semana, para começar. */
const DIAS_PADRAO = [0, 3];

let modalidade = 'regular';
let totalHoras = 600;
let meses = 12;
let dias: number[] = [...DIAS_PADRAO];
let mesDaGrade = 0;
let gravando = false;
let gravada = false;

function escolha(): Escolha {
  return { totalHoras, meses, dias };
}

// ── Controles ───────────────────────────────────────────────────────────────

function trocarModalidade(chave: string): void {
  modalidade = chave;
  const horas = modalidadeDe(chave).horasMes;
  // Publicador não tem cota: o alvo fica onde estava, para não zerar o que o
  // usuário já tinha ajustado à mão.
  if (horas > 0) totalHoras = horas * meses;
  gravada = false;
  atualizar();
}

function ajustarMeses(novo: number): void {
  const horas = modalidadeDe(modalidade).horasMes;
  meses = novo;
  if (horas > 0) totalHoras = horas * novo;
  gravada = false;
  atualizar();
}

function alternarDia(indice: number): void {
  dias = dias.includes(indice) ? dias.filter((d) => d !== indice) : [...dias, indice].sort();
  gravada = false;
  atualizar();
}

function controle(
  rotulo: string,
  valor: string,
  minimo: number,
  maximo: number,
  passo: number,
  atual: number,
  aoMudar: (v: number) => void,
): TemplateResult {
  return html`
    <div class="servico__controle">
      <label class="servico__rotulo">
        <span>${rotulo}</span>
        <strong>${valor}</strong>
      </label>
      <input
        type="range"
        min=${minimo}
        max=${maximo}
        step=${passo}
        .value=${String(atual)}
        @input=${(e: Event) => aoMudar(Number((e.target as HTMLInputElement).value))}
      />
    </div>
  `;
}

// ── Blocos da tela ──────────────────────────────────────────────────────────

function seletorDeModalidade(): TemplateResult {
  const atual = modalidadeDe(modalidade);

  return html`
    <section class="servico__bloco">
      <h2 class="servico__titulo">${S.servico.modalidade}</h2>
      <div class="servico__modalidades">
        ${MODALIDADES.map(
          (m) => html`
            <button
              class="servico__modalidade ${m.chave === modalidade ? 'servico__modalidade--ativa' : ''}"
              @click=${() => trocarModalidade(m.chave)}
            >
              <strong>${m.nome}</strong>
              <span>${m.horasMes === 0 ? S.servico.semCota : S.servico.horasMes(m.horasMes)}</span>
            </button>
          `,
        )}
      </div>
      <p class="servico__nota">${atual.resumo}</p>
    </section>
  `;
}

function seletorDeDias(): TemplateResult {
  return html`
    <section class="servico__bloco">
      <h2 class="servico__titulo">${S.servico.diasTitulo}</h2>
      <div class="servico__dias">
        ${DIAS_DA_SEMANA.map(
          (nome, i) => html`
            <button
              class="servico__dia ${dias.includes(i) ? 'servico__dia--ativo' : ''}"
              aria-pressed=${dias.includes(i)}
              @click=${() => alternarDia(i)}
            >${nome}</button>
          `,
        )}
      </div>
    </section>
  `;
}

/** A grade dia/semana/mês/ano/resumo — o que a meta significa em cada escala. */
function grade(): TemplateResult {
  const plano = planejar(escolha());

  const linha = (rotulo: string, valor: string, destaque = false): TemplateResult => html`
    <div class="servico__linha ${destaque ? 'servico__linha--destaque' : ''}">
      <span>${rotulo}</span>
      <strong>${valor}</strong>
    </div>
  `;

  return html`
    <section class="servico__bloco">
      <h2 class="servico__titulo">${S.servico.gradeTitulo}</h2>

      ${
        dias.length === 0
          ? html`<st-alert variant="warning" open>${S.servico.semDias}</st-alert>`
          : linha(S.servico.porSaida, horasEMinutos(plano.porSaida), true)
      }
      ${linha(S.servico.porSemana, horasEMinutos(plano.porSemana))}
      ${linha(S.servico.porMes, horasEMinutos(plano.porMes))}
      ${linha(S.servico.porAno, horasEMinutos(plano.porAno))}
      ${linha(S.servico.saidas, S.servico.saidasValor(plano.saidasTotais))}

      ${
        plano.inviavel
          ? html`<st-alert variant="danger" open>${S.servico.inviavel}</st-alert>`
          : nothing
      }
    </section>
  `;
}

/** O calendário do mês, com os dias de serviço marcados e a hora de cada um. */
function calendario(): TemplateResult {
  const plano = planejar(escolha());
  const hoje = new Date();
  const referencia = new Date(hoje.getFullYear(), hoje.getMonth() + mesDaGrade, 1);
  const ano = referencia.getFullYear();
  const mes = referencia.getMonth();

  const saidas = saidasNoMes(ano, mes, dias);
  // A grade do mês real, e não a média: fevereiro com quatro domingos exige
  // mais de cada saída do que março com cinco.
  const porSaidaNoMes = saidas === 0 ? 0 : plano.porMes / saidas;

  return html`
    <section class="servico__bloco">
      <div class="servico__mesbarra">
        <st-icon-button
          name="chevron-left"
          label=${S.servico.mesAnterior}
          ?disabled=${mesDaGrade === 0}
          @click=${() => {
            mesDaGrade = Math.max(0, mesDaGrade - 1);
            atualizar();
          }}
        ></st-icon-button>
        <strong>${nomeDoMes(ano, mes)}</strong>
        <st-icon-button
          name="chevron-right"
          label=${S.servico.mesSeguinte}
          ?disabled=${mesDaGrade >= meses - 1}
          @click=${() => {
            mesDaGrade = Math.min(meses - 1, mesDaGrade + 1);
            atualizar();
          }}
        ></st-icon-button>
      </div>

      <div class="servico__grade">
        ${DIAS_DA_SEMANA.map((nome) => html`<span class="servico__cabeca">${nome}</span>`)}
        ${gradeDoMes(ano, mes, dias).map(
          (d) => html`
            <span
              class="servico__cela ${d.fora ? 'servico__cela--fora' : ''} ${
                d.deServico ? 'servico__cela--servico' : ''
              }"
            >
              ${d.fora ? '' : d.dia}
              ${d.deServico ? html`<small>${horasEMinutos(porSaidaNoMes)}</small>` : nothing}
            </span>
          `,
        )}
      </div>

      <p class="servico__nota">
        ${S.servico.resumoDoMes(saidas, horasEMinutos(plano.porMes))}
      </p>
    </section>
  `;
}

function registrar(): void {
  if (gravando) return;
  gravando = true;
  atualizar();

  void (async () => {
    try {
      await salvarMeta(
        metaDoPlano(escolha(), S.servico.tituloDaMeta(modalidadeDe(modalidade).nome)),
      );
      gravada = true;
    } finally {
      gravando = false;
      atualizar();
    }
  })();
}

function acoes(): TemplateResult {
  return html`
    <section class="servico__bloco">
      <st-button variant="primary" ?disabled=${gravando || totalHoras <= 0} @click=${registrar}>
        ${gravando ? S.servico.gravando : S.servico.registrar}
      </st-button>

      ${
        gravada
          ? html`
            <st-alert variant="success" open>
              ${S.servico.gravada}
              <st-button size="small" variant="success" @click=${() => navegar('metas')}>
                ${S.servico.verMetas}
              </st-button>
            </st-alert>
          `
          : nothing
      }

      <p class="servico__nota servico__nota--fonte">
        ${S.servico.fonteAviso}
        ${S.servico.referencias.map(
          (r) => html`
            <a href=${r.url} target="_blank" rel="noreferrer noopener">${r.rotulo}</a>
          `,
        )}
      </p>
    </section>
  `;
}

export const telaServico: Tela = {
  voltarPara: () => 'ministerio',

  conteudo(_rota: Rota): TemplateResult {
    const plano = planejar(escolha());

    return html`
      <div class="servico">
        <p class="servico__intro">${S.servico.intro}</p>

        ${seletorDeModalidade()}

        <section class="servico__bloco">
          ${controle(
            S.servico.alvo,
            S.servico.alvoValor(totalHoras),
            0,
            2400,
            10,
            totalHoras,
            (v) => {
              totalHoras = v;
              gravada = false;
              atualizar();
            },
          )}
          ${controle(S.servico.prazo, S.servico.prazoValor(meses), 1, 12, 1, meses, (v) => {
            ajustarMeses(v);
            mesDaGrade = Math.min(mesDaGrade, v - 1);
          })}
          <p class="servico__nota">${S.servico.mediaMes(horasEMinutos(plano.porMes))}</p>
        </section>

        ${seletorDeDias()}
        ${grade()}
        ${calendario()}
        ${acoes()}
      </div>
    `;
  },
};
