const anotacoes = () => repositorio('anotacao');
const pastas = () => repositorio('pasta');
const modelos = () => repositorio('anotacao_modelos');

// ── Regras da lista (puras) ─────────────────────────────────────────────────

/** Os filtros da lista. Combinam entre si, como no legado. */
export interface Filtros {
  /** `true` mostra o arquivo em vez das ativas. */
  readonly arquivadas: boolean;
  /** `null` = todas as pastas. */
  readonly pastaId: number | null;
  /** `''` = todos os modelos. */
  readonly modeloChave: string;
  readonly busca: string;
}

export const FILTROS_INICIAIS: Filtros = {
  arquivadas: false,
  pastaId: null,
  modeloChave: '',
  busca: '',
};

/** Aplica os filtros. A busca olha título e conteúdo, sem diferenciar caixa. */
export function filtrar(lista: readonly Anotacao[], filtros: Filtros): Anotacao[] {
  const busca = filtros.busca.trim().toLowerCase();

  return lista.filter((anotacao) => {
    if ((anotacao.esta_arquivada === 1) !== filtros.arquivadas) return false;
    if (filtros.pastaId !== null && anotacao.pasta_id !== filtros.pastaId) return false;
    if (filtros.modeloChave !== '' && anotacao.tipo_modelo !== filtros.modeloChave) return false;
    if (busca === '') return true;

    return (
      anotacao.titulo.toLowerCase().includes(busca) ||
      anotacao.conteudo.toLowerCase().includes(busca)
    );
  });
}

/** Fixadas primeiro; dentro de cada grupo, a mais recente na frente. */
export function ordenar(lista: readonly Anotacao[]): Anotacao[] {
  return [...lista].sort((a, b) => {
    if (a.esta_fixada !== b.esta_fixada) return b.esta_fixada - a.esta_fixada;
    return b.data_modificacao - a.data_modificacao;
  });
}

// ── Leitura ─────────────────────────────────────────────────────────────────

export async function listarAnotacoes(filtros: Filtros): Promise<Anotacao[]> {
  return ordenar(filtrar(await anotacoes().todos<Anotacao>(), filtros));
}

export function obterAnotacao(id: number): Promise<Anotacao | undefined> {
  return anotacoes().obter<Anotacao>(id);
}

export function listarPastas(): Promise<Pasta[]> {
  return pastas().todos<Pasta>();
}

/** Os modelos curados, em ordem; cai no fallback enquanto o store está vazio. */
export async function listarModelos(): Promise<Modelo[]> {
  const curados = await modelos()
    .todos<Registro & Modelo>()
    .catch(() => []);

  const lista: readonly Modelo[] = curados.length === 0 ? MODELOS_FALLBACK : curados;
  return [...lista].sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0));
}

// ── Escrita ─────────────────────────────────────────────────────────────────

/** Grava a anotação e devolve o id — o informado, ou o gerado se ela é nova. */
export function salvarAnotacao(anotacao: Anotacao): Promise<number> {
  return anotacoes().salvar(anotacao);
}

export function excluirAnotacao(id: number): Promise<void> {
  return anotacoes().excluir(id);
}

export async function criarPasta(nome: string): Promise<void> {
  await pastas().salvar({ nome, data_criacao: Date.now() });
}

export async function renomearPasta(pasta: Pasta, nome: string): Promise<void> {
  await pastas().salvar({ ...pasta, nome });
}

/**
 * Exclui a pasta e solta as anotações que estavam nela. Perder a pasta não pode
 * significar perder o que havia dentro.
 */
export async function excluirPasta(id: number): Promise<void> {
  const dentro = (await anotacoes().todos<Anotacao>()).filter(
    (anotacao) => anotacao.pasta_id === id,
  );

  for (const anotacao of dentro) {
    await anotacoes().salvar({ ...anotacao, pasta_id: null });
  }

  await pastas().excluir(id);
}
