/**
 * Os documentos institucionais do Papiro — porte das cinco páginas soltas de
 * `sang.local/src/Papiro/Pwa/publico/` (`guia-do-usuario`, `termos-de-uso`,
 * `politica-privacidade`, `direitos-de-terceiros`, `licenca`).
 *
 * No legado eram cinco HTML independentes, cada um com `<style>` próprio
 * redeclarando fundo, borda e acento — o app abria fora de si mesmo, perdia a
 * barra de topo e voltava por um link "← Voltar ao app". Aqui são dados, e a
 * tela do Sobre os desenha com os componentes do Stratum: um CSS só, offline
 * pelo mesmo service worker, e o botão de voltar da casca funcionando.
 *
 * O conteúdo é estrutura, não HTML: um documento é uma lista de blocos, e a tela
 * decide como cada tipo aparece. Guardar `<p class="mb-0 small text-muted">` num
 * arquivo de dados seria trazer o Bootstrap junto.
 */

/** Um trecho de texto com ênfase — o `<strong>` do original, sem HTML. */
export interface Trecho {
  readonly texto: string;
  readonly forte?: boolean;
}

export type Bloco =
  | { readonly tipo: 'titulo'; readonly texto: string }
  | { readonly tipo: 'paragrafo'; readonly partes: readonly Trecho[] }
  | { readonly tipo: 'lista'; readonly itens: readonly (readonly Trecho[])[] }
  /** Item de glossário: um nome em destaque e a explicação ao lado. */
  | { readonly tipo: 'definicoes'; readonly itens: readonly { nome: string; texto: string }[] }
  | {
      readonly tipo: 'tabela';
      readonly colunas: readonly [string, string];
      readonly linhas: readonly (readonly [string, string])[];
    }
  /** Link para outro documento desta mesma lista. */
  | { readonly tipo: 'veja'; readonly documentos: readonly DocumentoId[] };

export type DocumentoId = 'guia' | 'termos' | 'privacidade' | 'terceiros' | 'licenca';

export interface Documento {
  readonly id: DocumentoId;
  readonly titulo: string;
  readonly icone: string;
  /** Linha abaixo do título — resumo ou data de atualização. */
  readonly subtitulo: string;
  readonly blocos: readonly Bloco[];
}

/** Atalho para o caso comum: um parágrafo sem ênfase nenhuma. */
function p(texto: string): Bloco {
  return { tipo: 'paragrafo', partes: [{ texto }] };
}

/** Parágrafo com ênfase: os pedaços alternam normal/forte, começando em normal. */
function pf(...pedacos: readonly string[]): Bloco {
  return {
    tipo: 'paragrafo',
    partes: pedacos
      .map((texto, i) => ({ texto, forte: i % 2 === 1 }))
      .filter((parte) => parte.texto !== ''),
  };
}

function t(texto: string): Bloco {
  return { tipo: 'titulo', texto };
}

function lista(...itens: readonly string[]): Bloco {
  return { tipo: 'lista', itens: itens.map((texto) => [{ texto }]) };
}

