/**
 * O progresso da Leitura da Bíblia — porte de `modulos/leitura/leitura.js`.
 *
 * Fica em `localStorage`, nas mesmas três chaves do legado: quem já usava o app
 * abre esta versão com os capítulos que marcou. É preferência de aparelho, como
 * os favoritos — não conteúdo a sincronizar.
 *
 * O formato guardado também é o do legado (`{ [livro]: { [capítulo]: 1 } }`).
 * Em memória ele vira `Map<number, Set<number>>`, que é o que as contagens
 * pedem; a conversão acontece só na borda, ao ler e ao gravar.
 */

import {
  DETALHES,
  GRUPOS_ESCRITOR,
  type GrupoEscritor,
  LIVROS,
  ORDEM_CRONOLOGICA,
  ROTEIRO_CELEBRACAO,
  TOTAL_CAPITULOS,
} from './biblia.ts';

const CHAVE_LEITURA = 'papiro_leitura_biblia';
const CHAVE_VISAO = 'papiro_leitura_visao';
const CHAVE_CELEBRACAO = 'papiro_leitura_celebracao';

export const VISOES = ['canonica', 'cronologica', 'escritor', 'celebracao'] as const;

export type Visao = (typeof VISOES)[number];

/** Capítulos lidos por livro, pelo índice em `LIVROS`. */
export type Lidos = Map<number, Set<number>>;

function lerBruto(chave: string): Record<string, unknown> {
  try {
    const bruto = JSON.parse(localStorage.getItem(chave) ?? '{}') as unknown;
    return typeof bruto === 'object' && bruto !== null ? (bruto as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

/** Lê o progresso por capítulo do formato do legado. */
export function lerLidos(): Lidos {
  const lidos: Lidos = new Map();

  for (const [livro, capitulos] of Object.entries(lerBruto(CHAVE_LEITURA))) {
    if (typeof capitulos !== 'object' || capitulos === null) continue;

    const marcados = Object.keys(capitulos)
      .map(Number)
      .filter((capitulo) => Number.isInteger(capitulo));
    if (marcados.length > 0) lidos.set(Number(livro), new Set(marcados));
  }

  return lidos;
}

/** Grava de volta no formato do legado — o mapa de mapas com `1` por capítulo. */
export function salvarLidos(lidos: Lidos): void {
  const bruto: Record<string, Record<string, number>> = {};

  for (const [livro, capitulos] of lidos) {
    if (capitulos.size === 0) continue;
    bruto[String(livro)] = Object.fromEntries([...capitulos].map((cap) => [String(cap), 1]));
  }

  localStorage.setItem(CHAVE_LEITURA, JSON.stringify(bruto));
}

/** Os dias do roteiro da Celebração já lidos. */
export function lerCelebracao(): Set<string> {
  return new Set(Object.keys(lerBruto(CHAVE_CELEBRACAO)));
}

export function salvarCelebracao(dias: ReadonlySet<string>): void {
  localStorage.setItem(
    CHAVE_CELEBRACAO,
    JSON.stringify(Object.fromEntries([...dias].map((id) => [id, 1]))),
  );
}

export function lerVisao(): Visao {
  const guardada = localStorage.getItem(CHAVE_VISAO);
  return VISOES.includes(guardada as Visao) ? (guardada as Visao) : 'canonica';
}

export function salvarVisao(visao: Visao): void {
  localStorage.setItem(CHAVE_VISAO, visao);
}

// ── Contagens ───────────────────────────────────────────────────────────────

export function capitulosDe(livro: number): number {
  return LIVROS[livro]?.capitulos ?? 0;
}

export function lidosDoLivro(lidos: Lidos, livro: number): number {
  return lidos.get(livro)?.size ?? 0;
}

export function capituloLido(lidos: Lidos, livro: number, capitulo: number): boolean {
  return lidos.get(livro)?.has(capitulo) === true;
}

export function percentualDoLivro(lidos: Lidos, livro: number): number {
  const total = capitulosDe(livro);
  return total === 0 ? 0 : Math.round((lidosDoLivro(lidos, livro) / total) * 100);
}

export function livroCompleto(lidos: Lidos, livro: number): boolean {
  const total = capitulosDe(livro);
  return total > 0 && lidosDoLivro(lidos, livro) >= total;
}

export function totalLidos(lidos: Lidos): number {
  let total = 0;
  for (const capitulos of lidos.values()) total += capitulos.size;
  return total;
}

export function percentualGeral(lidos: Lidos): number {
  return Math.round((totalLidos(lidos) / TOTAL_CAPITULOS) * 100);
}

export function livrosConcluidos(lidos: Lidos): number {
  return LIVROS.reduce((total, _, livro) => total + (livroCompleto(lidos, livro) ? 1 : 0), 0);
}

export function lidosDoGrupo(lidos: Lidos, livros: readonly number[]): number {
  return livros.reduce((total, livro) => total + lidosDoLivro(lidos, livro), 0);
}

export function capitulosDoGrupo(livros: readonly number[]): number {
  return livros.reduce((total, livro) => total + capitulosDe(livro), 0);
}

export function percentualCelebracao(dias: ReadonlySet<string>): number {
  return Math.round((diasLidos(dias) / ROTEIRO_CELEBRACAO.length) * 100);
}

export function diasLidos(dias: ReadonlySet<string>): number {
  return ROTEIRO_CELEBRACAO.filter((dia) => dias.has(dia.id)).length;
}

// ── Marcações ───────────────────────────────────────────────────────────────

/** Liga/desliga um capítulo e devolve o mapa novo, já persistido. */
export function alternarCapitulo(lidos: Lidos, livro: number, capitulo: number): Lidos {
  const novo: Lidos = new Map(lidos);
  const capitulos = new Set(novo.get(livro));

  if (!capitulos.delete(capitulo)) capitulos.add(capitulo);
  novo.set(livro, capitulos);

  salvarLidos(novo);
  return novo;
}

/** Marca (ou limpa) o livro inteiro. */
export function marcarLivro(lidos: Lidos, livro: number, marcar: boolean): Lidos {
  const novo: Lidos = new Map(lidos);
  const total = capitulosDe(livro);

  novo.set(
    livro,
    marcar ? new Set(Array.from({ length: total }, (_, indice) => indice + 1)) : new Set(),
  );

  salvarLidos(novo);
  return novo;
}

/** Liga/desliga um dia do roteiro e devolve o conjunto novo, já persistido. */
export function alternarDia(dias: ReadonlySet<string>, id: string): Set<string> {
  const novo = new Set(dias);
  if (!novo.delete(id)) novo.add(id);

  salvarCelebracao(novo);
  return novo;
}

// ── Lista das visões de livros ──────────────────────────────────────────────

/**
 * Um item da lista: ou um cabeçalho de grupo (visão por escritor), ou um livro.
 * A lista vem achatada porque é assim que ela é desenhada — o cabeçalho de grupo
 * não é um contêiner dos livros dele, é uma linha antes deles.
 */
export type ItemDaLista =
  | { readonly tipo: 'grupo'; readonly grupo: GrupoEscritor }
  | { readonly tipo: 'livro'; readonly livro: number };

export function itensDaVisao(visao: Visao): ItemDaLista[] {
  if (visao === 'cronologica') {
    return ORDEM_CRONOLOGICA.map((livro) => ({ tipo: 'livro', livro }));
  }

  if (visao === 'escritor') {
    return GRUPOS_ESCRITOR.flatMap((grupo): ItemDaLista[] => [
      { tipo: 'grupo', grupo },
      ...grupo.livros.map((livro): ItemDaLista => ({ tipo: 'livro', livro })),
    ]);
  }

  return LIVROS.map((_, livro): ItemDaLista => ({ tipo: 'livro', livro }));
}

/** A linha de detalhe sob o nome do livro — vazia na visão canônica. */
export function detalheDoLivro(visao: Visao, livro: number): string {
  const detalhe = DETALHES[livro];
  if (detalhe === undefined) return '';

  if (visao === 'cronologica') {
    return `${detalhe.quando} · ${detalhe.escritor} · ${detalhe.local}`;
  }
  if (visao === 'escritor') return `${detalhe.quando} · ${detalhe.local}`;
  return '';
}
