/**
 * Diálogos de confirmação e de texto — porte de `src/js/dialogo.js` do legado.
 *
 * O original montava o overlay à mão com classes do Bootstrap justamente porque
 * o PWA não tinha componente de diálogo. Aqui tem: cada chamada cria um
 * `st-dialog`, resolve a promessa e se remove do documento. O componente já
 * traz foco preso, fechar no Esc e no clique fora — o que no legado era código
 * nosso.
 */

import { html, render, type TemplateResult } from 'lit';
import { S } from '../strings.ts';

interface Comum {
  readonly titulo: string;
  readonly texto?: string;
  readonly rotuloConfirmar?: string;
}

export interface OpcoesConfirmar extends Comum {
  /** Variante do botão que confirma — `danger` no que apaga. */
  readonly variante?: 'primary' | 'danger' | 'warning';
}

export interface OpcoesTexto extends Comum {
  readonly valor?: string;
  readonly placeholder?: string;
  readonly erroVazio?: string;
}

interface Campo extends HTMLElement {
  value: string;
  helpText: string;
  focus(): void;
}

export interface OpcoesAbrir {
  /**
   * Esconde a barra de título do `st-dialog`, para o corpo desenhar a sua. O
   * `rotulo` continua valendo: sem cabeçalho o componente o usa como
   * `aria-label`, então o diálogo segue anunciado.
   */
  readonly semCabecalho?: boolean;
  /** Classe no próprio `st-dialog`, para o CSS do chamador o alcançar. */
  readonly classe?: string;
}

/**
 * Abre um `st-dialog` com o corpo dado e resolve quando ele termina de fechar.
 *
 * `resultado` é preenchido pelos botões antes do fechamento; se o usuário sair
 * pelo Esc, pelo X ou pelo clique fora, ele fica no padrão — que é sempre a
 * recusa (`false`/`null`), nunca a confirmação.
 *
 * O corpo recebe `redesenhar` porque nem todo diálogo é estático: o onboarding
 * troca de passo sem fechar, e redesenhar por dentro evita que ele tenha de
 * repetir a montagem e o ciclo de vida do componente.
 */
export function abrir<T>(
  rotulo: string,
  padrao: T,
  corpo: (
    fechar: (resultado: T) => void,
    dialogo: HTMLElement,
    redesenhar: () => void,
  ) => TemplateResult,
  opcoes: OpcoesAbrir = {},
): Promise<T> {
  const dialogo = document.createElement('st-dialog') as HTMLElement & {
    open: boolean;
    updateComplete: Promise<boolean>;
  };
  dialogo.setAttribute('label', rotulo);
  if (opcoes.semCabecalho === true) dialogo.setAttribute('no-header', '');
  if (opcoes.classe !== undefined) dialogo.className = opcoes.classe;
  document.body.append(dialogo);

  return new Promise<T>((resolver) => {
    let resultado = padrao;

    const fechar = (valor: T): void => {
      resultado = valor;
      dialogo.open = false;
    };

    const redesenhar = (): void => {
      render(corpo(fechar, dialogo, redesenhar), dialogo);
    };

    dialogo.addEventListener('st-after-hide', (evento) => {
      // Componentes de dentro emitem o mesmo evento ao fechar seus próprios
      // popups, e ele sobe até aqui: só o do próprio diálogo encerra.
      if (evento.target !== dialogo) return;
      dialogo.remove();
      resolver(resultado);
    });

    redesenhar();

    // Abrir só depois do primeiro desenho do componente: o `st-dialog` observa
    // `open` com `waitUntilFirstUpdate`, então ligar a chave no mesmo instante
    // em que ele nasce não dispara nada — o diálogo ficaria montado e fechado,
    // sem erro nenhum.
    void dialogo.updateComplete.then(() => {
      dialogo.open = true;
    });
  });
}

/** Confirmação de sim/não. Resolve `false` em qualquer forma de desistir. */
export function confirmar(opcoes: OpcoesConfirmar): Promise<boolean> {
  return abrir(opcoes.titulo, false, (fechar) => {
    return html`
      ${opcoes.texto ?? ''}
      <st-button slot="footer" @click=${() => fechar(false)}>${S.acoes.cancelar}</st-button>
      <st-button
        slot="footer"
        variant=${opcoes.variante ?? 'primary'}
        @click=${() => fechar(true)}
      >
        ${opcoes.rotuloConfirmar ?? S.acoes.confirmar}
      </st-button>
    `;
  });
}

/**
 * Pede um texto de uma linha. Resolve `null` quando o usuário desiste; o campo
 * é obrigatório, como no legado, e um valor vazio não fecha o diálogo.
 */
export function pedirTexto(opcoes: OpcoesTexto): Promise<string | null> {
  return abrir<string | null>(opcoes.titulo, null, (fechar, dialogo) => {
    const confirmarTexto = (): void => {
      const campo = dialogo.querySelector<Campo>('st-input');
      const valor = campo?.value.trim() ?? '';

      if (valor === '') {
        if (campo !== undefined && campo !== null) {
          campo.helpText = opcoes.erroVazio ?? S.acoes.obrigatorio;
          campo.focus();
        }
        return;
      }
      fechar(valor);
    };

    return html`
      ${opcoes.texto === undefined ? '' : html`<p class="dialogo__texto">${opcoes.texto}</p>`}
      <st-input
        autofocus
        placeholder=${opcoes.placeholder ?? ''}
        .value=${opcoes.valor ?? ''}
        @keydown=${(evento: KeyboardEvent) => {
          if (evento.key !== 'Enter') return;
          evento.preventDefault();
          confirmarTexto();
        }}
      ></st-input>
      <st-button slot="footer" @click=${() => fechar(null)}>${S.acoes.cancelar}</st-button>
      <st-button slot="footer" variant="primary" @click=${confirmarTexto}>
        ${opcoes.rotuloConfirmar ?? S.acoes.salvar}
      </st-button>
    `;
  });
}
