/**
 * Os puzzles que não são um slider — porte dos arquétipos `numerico`,
 * `escolha`, `pares`, `rota`, `ordenar`, `ciclos` e `solar` de
 * `modulos/criacao/renderizadores.js`.
 *
 * O que eles têm em comum é a verificação: em vez de comparar um número com uma
 * meta, conferem um ARRANJO que o usuário montou — as colunas erradas do DNA, a
 * ordem das flores, a sequência dos dias criativos, o laço de um ciclo. Por isso
 * cada um traz o próprio `verificar()` em vez de usar a fábrica declarativa.
 */

import { S } from '../../../strings.ts';
import { CICLOS_VIDA, cicloCorreto, ESTAGIOS_CRIACAO } from '../estagios.ts';
import {
  ACERTO,
  type CicloMontado,
  dist2,
  embaralharSem,
  type Info,
  type Instancia,
  int,
  num,
  type Opcao,
  type Puzzle,
  type Renderizador,
  slider,
  type Valores,
} from './base.ts';

function v(valores: Valores, prop: string): number {
  const bruto = valores[prop];
  return typeof bruto === 'number' && Number.isFinite(bruto) ? bruto : 0;
}

// ── Numérico: a sequência de Fibonacci nas plantas ──────────────────────────

/**
 * A filotaxia: as sementes e as folhas crescem seguindo a sequência de
 * Fibonacci, e o próximo número é a soma dos dois anteriores.
 */
export const sequencia: Renderizador = {
  arquetipo: 'numerico',
  criar(cfg) {
    const resposta = num(cfg.resposta, 21);
    const puzzle: Puzzle = {
      arquetipo: 'numerico',
      extra: 'sequencia',
      viz: {
        comp: 'filotaxia',
        dica:
          'O Sol ilumina de cima: pelo ângulo áureo (137,5°) nenhuma semente faz sombra na ' +
          'outra. Ao acertar, a flor desabrocha em pétalas.',
      },
      campos: [{ rotulo: S.criacao.proximoNumero, prop: 'n' }],
      valores: { n: 0 },
    };

    // A viz precisa da sequência e do ângulo; o snapshot os leva junto.
    const sequenciaBase = Array.isArray(cfg.sequencia)
      ? (cfg.sequencia as number[])
      : [3, 5, 8, 13];
    const angulo = num(cfg.angulo, 137.5);

    return {
      puzzle,
      info: (): Info => ({
        ok: v(puzzle.valores, 'n') === resposta,
        sequencia: sequenciaBase,
        angulo,
        leitura: '',
      }),
      verificar: () =>
        v(puzzle.valores, 'n') === resposta ? ACERTO : { tipo: 'erro', mensagem: S.criacao.erro },
    };
  },
};

// ── Escolha ─────────────────────────────────────────────────────────────────

/**
 * O favo de mel: entre as formas que ladrilham o plano sem sobra, o hexágono é
 * a que fecha a mesma área com o menor perímetro — menos cera pelo mesmo espaço.
 */
export const tesselacao: Renderizador = {
  arquetipo: 'escolha',
  criar(cfg) {
    const correta = typeof cfg.correta === 'string' ? cfg.correta : 'hexagono';
    const opcoes: readonly Opcao[] = Array.isArray(cfg.opcoes)
      ? (cfg.opcoes as Opcao[])
      : [
          { id: 'triangulo', rotulo: 'Triângulos', nota: 'encaixam, mas gastam mais material' },
          { id: 'quadrado', rotulo: 'Quadrados', nota: 'encaixam, resistência menor' },
          { id: 'circulo', rotulo: 'Círculos', nota: '≈ 21,46% de área vazia' },
          { id: 'hexagono', rotulo: 'Hexágonos', nota: '0% de desperdício, perímetro mínimo' },
        ];

    const puzzle: Puzzle = {
      arquetipo: 'escolha',
      viz: { comp: 'tesselacao' },
      valores: {},
      opcoes,
      escolhido: null,
    };

    return {
      puzzle,
      info: (): Info => ({ ok: puzzle.escolhido === correta, correta, leitura: '' }),
      verificar: () => {
        if (puzzle.escolhido === null || puzzle.escolhido === undefined) {
          return { tipo: 'erro', mensagem: S.criacao.escolha };
        }
        return puzzle.escolhido === correta ? ACERTO : { tipo: 'erro', mensagem: S.criacao.erro };
      },
    };
  },
};

/**
 * "A Beleza das Equações" (Despertai! nov/2015): a·x + b = c é uma balança, e
 * resolvê-la é achar o x que deixa os dois lados com o mesmo peso. O "=" é o
 * fiel — e a criança vê a balança pender até nivelar.
 */
export const harmonia: Renderizador = slider<{ a: number; b: number; c: number }>({
  viz: { comp: 'balanca' },
  preparar(cfg) {
    const a = Math.max(1, int(cfg.a, 2));
    const b = int(cfg.b, 3);
    const c = int(cfg.c, 11);
    // A solução é inteira nos módulos; o máximo do slider sempre a alcança.
    const solucao = (c - b) / a;

    return {
      params: { a, b, c },
      controles: [
        {
          rotulo: S.criacao.equilValorX,
          prop: 'x',
          min: 0,
          max: Math.max(int(cfg.xMax, 10), Math.ceil(solucao) + 2, 2),
          step: 1,
        },
      ],
      valores: { x: int(cfg.x0, 0) },
    };
  },
  medir(valores, p): Info {
    const x = v(valores, 'x');
    const esquerda = p.a * x + p.b;
    const ok = esquerda === p.c;

    return {
      ok,
      esq: esquerda,
      dir: p.c,
      x,
      a: p.a,
      b: p.b,
      c: p.c,
      leitura: ok
        ? S.criacao.equilOk(p.c)
        : esquerda < p.c
          ? S.criacao.equilPendeDir
          : S.criacao.equilPendeEsq,
    };
  },
});

// ── Pares: o pareamento do DNA ──────────────────────────────────────────────

/**
 * A dupla hélice só funciona porque as bases se emparelham de um jeito fixo:
 * A com T, C com G. Um pareamento fora dessa regra é um erro de cópia.
 */
export const pareamento: Renderizador = {
  arquetipo: 'pares',
  criar(cfg) {
    const fitaA = Array.isArray(cfg.fitaA)
      ? (cfg.fitaA as string[])
      : ['A', 'T', 'C', 'G', 'A', 'C', 'G', 'T'];
    const fitaB = Array.isArray(cfg.fitaB)
      ? (cfg.fitaB as string[])
      : ['T', 'A', 'G', 'C', 'T', 'C', 'C', 'A'];

    const par: Readonly<Record<string, string>> = { A: 'T', T: 'A', C: 'G', G: 'C' };
    const erros: number[] = [];
    fitaA.forEach((base, i) => {
      if (par[base] !== fitaB[i]) erros.push(i);
    });

    const puzzle: Puzzle = {
      arquetipo: 'pares',
      viz: { comp: 'dna' },
      valores: {},
      colunas: fitaA.map((base, i) => ({ a: base, b: fitaB[i] ?? '' })),
      selecionados: [],
    };

    const conferido = (): boolean => {
      const marcados = [...(puzzle.selecionados ?? [])].sort((x, y) => x - y);
      const esperados = [...erros].sort((x, y) => x - y);
      return (
        marcados.length === esperados.length && marcados.every((col, i) => col === esperados[i])
      );
    };

    return {
      puzzle,
      info: (): Info => ({ ok: conferido(), erros, leitura: '' }),
      verificar: () => (conferido() ? ACERTO : { tipo: 'erro', mensagem: S.criacao.paresErro }),
    };
  },
};

// ── Rota: o caixeiro-viajante das abelhas ───────────────────────────────────

/**
 * Comprimento do menor TOUR FECHADO que sai da colmeia, visita todas as flores e
 * volta. Força bruta com poda — são poucos pontos, e é o ótimo real, não uma
 * heurística: o puzzle compara o caminho do usuário com ele.
 */
function menorTour(
  colmeia: readonly [number, number],
  pontos: readonly (readonly [number, number])[],
): number {
  let melhor = Number.POSITIVE_INFINITY;

  const percorrer = (restantes: number[], atual: number | null, acumulado: number): void => {
    if (acumulado >= melhor) return;

    if (restantes.length === 0) {
      const ultimo = atual === null ? colmeia : pontos[atual];
      if (ultimo !== undefined) melhor = Math.min(melhor, acumulado + dist2(ultimo, colmeia));
      return;
    }

    for (let i = 0; i < restantes.length; i++) {
      const proximo = restantes[i];
      if (proximo === undefined) continue;
      const destino = pontos[proximo];
      const origem = atual === null ? colmeia : pontos[atual];
      if (destino === undefined || origem === undefined) continue;

      percorrer(
        restantes.filter((_, j) => j !== i),
        proximo,
        acumulado + dist2(origem, destino),
      );
    }
  };

  percorrer(
    pontos.map((_, i) => i),
    null,
    0,
  );

  return melhor === Number.POSITIVE_INFINITY ? 0 : melhor;
}

/**
 * As abelhas resolvem, voando, um problema que trava computadores: a rota mais
 * curta que passa por todas as flores e volta à colmeia.
 */
export const rotas: Renderizador = {
  arquetipo: 'rota',
  criar(cfg) {
    const brutos = Array.isArray(cfg.pontos)
      ? (cfg.pontos as number[][])
      : [
          [15, 25],
          [80, 15],
          [50, 50],
          [20, 80],
          [85, 75],
          [55, 90],
        ];
    const pontos = brutos.map((p) => [num(p[0], 0), num(p[1], 0)] as const);

    const colmeiaBruta = Array.isArray(cfg.colmeia) ? (cfg.colmeia as number[]) : [50, 8];
    const colmeia = [num(colmeiaBruta[0], 50), num(colmeiaBruta[1], 8)] as const;

    const otima = menorTour(colmeia, pontos);
    const tolerancia = num(cfg.tol, 1.05);

    const puzzle: Puzzle = {
      arquetipo: 'rota',
      valores: {},
      pontos,
      colmeia,
      otima,
      ordemPontos: [],
      dist: 0,
    };

    return {
      puzzle,
      info: (): Info => ({
        ok: (puzzle.dist ?? 0) > 0 && (puzzle.dist ?? 0) <= otima * tolerancia,
        dist: puzzle.dist ?? 0,
        otima,
        leitura: '',
      }),
      verificar: () => {
        const ordem = puzzle.ordemPontos ?? [];
        if (ordem.length !== pontos.length) {
          return { tipo: 'erro', mensagem: S.criacao.rotaIncompleta };
        }
        return (puzzle.dist ?? 0) <= otima * tolerancia
          ? { tipo: 'ok', mensagem: S.criacao.rotaOtima }
          : { tipo: 'erro', mensagem: S.criacao.rotaLonga };
      },
    };
  },
};

/** Distância do trajeto colmeia → flores (na ordem) → colmeia (só ao fechar). */
export function distanciaDaRota(puzzle: Puzzle): number {
  const pontos = puzzle.pontos ?? [];
  const colmeia = puzzle.colmeia;
  const ordem = puzzle.ordemPontos ?? [];
  if (colmeia === undefined || ordem.length === 0) return 0;

  const primeiro = pontos[ordem[0] ?? -1];
  if (primeiro === undefined) return 0;

  let total = dist2(colmeia, primeiro);
  for (let k = 1; k < ordem.length; k++) {
    const anterior = pontos[ordem[k - 1] ?? -1];
    const atual = pontos[ordem[k] ?? -1];
    if (anterior !== undefined && atual !== undefined) total += dist2(anterior, atual);
  }

  if (ordem.length === pontos.length) {
    const ultimo = pontos[ordem[ordem.length - 1] ?? -1];
    if (ultimo !== undefined) total += dist2(ultimo, colmeia);
  }

  return total;
}

// ── Área: dois jeitos de cobrir o mesmo piso ────────────────────────────────

/**
 * "A matemática é para todos": a área de um retângulo é comprimento × largura.
 * Acertar de um jeito revela que há outros — por isso o puzzle só fecha com
 * DOIS pares distintos (3×4 e 4×3 são o mesmo retângulo virado).
 */
export const area: Renderizador = {
  arquetipo: 'slider',
  criar(cfg) {
    const alvo = int(cfg.alvo, 12);
    const ladoMax = int(cfg.lmax, 8);

    const puzzle: Puzzle = {
      arquetipo: 'slider',
      extra: 'area',
      viz: { comp: 'piso' },
      controles: [
        { rotulo: 'Comprimento', prop: 'c', min: 1, max: ladoMax, step: 1, suf: ' m' },
        { rotulo: 'Largura', prop: 'l', min: 1, max: ladoMax, step: 1, suf: ' m' },
      ],
      valores: { c: 3, l: 2 },
    };

    // O primeiro jeito encontrado, para exigir um segundo diferente.
    let jeito1: string | null = null;
    let jeito1Rotulo = '';

    const medir = (): Info => {
      const c = Math.trunc(v(puzzle.valores, 'c'));
      const l = Math.trunc(v(puzzle.valores, 'l'));
      const area = c * l;
      const ok = area === alvo;

      return {
        ok,
        area,
        c,
        l,
        alvo,
        leitura: ok
          ? `${c} m × ${l} m = ${area} m² — cobre o piso! ✓`
          : `${c} m × ${l} m = ${area} m²  (meta: ${alvo} m²)`,
      };
    };

    return {
      puzzle,
      info: medir,
      verificar: () => {
        const c = Math.trunc(v(puzzle.valores, 'c'));
        const l = Math.trunc(v(puzzle.valores, 'l'));

        if (c * l !== alvo) {
          return {
            tipo: 'erro',
            mensagem: `Ainda não são ${alvo} m². Ajuste o comprimento e a largura.`,
          };
        }

        const chave = [Math.min(c, l), Math.max(c, l)].join('x');

        if (jeito1 === null) {
          jeito1 = chave;
          jeito1Rotulo = `${c} × ${l}`;
          return {
            tipo: 'dica',
            mensagem: `Boa! ${c} × ${l} = ${alvo} m². Agora encontre OUTRO jeito, com medidas diferentes, de cobrir ${alvo} m².`,
          };
        }

        if (chave === jeito1) {
          return {
            tipo: 'dica',
            mensagem: `Esse é o mesmo retângulo de ${jeito1Rotulo} (só virado). Tente outras medidas para ${alvo} m².`,
          };
        }

        return {
          tipo: 'ok',
          mensagem: `Perfeito! ${jeito1Rotulo} e ${c} × ${l} — dois jeitos de cobrir ${alvo} m². ✓`,
        };
      },
    };
  },
};

// ── Ordenar: a linha do tempo da criação ────────────────────────────────────

/**
 * "A Linha do Tempo da Criação": os oito estágios de Gênesis 1 em ordem. A Terra
 * 3D se transforma ao vivo conforme cada evento é tocado — as nuvens abrem, a
 * terra firme emerge, o Sol fica VISÍVEL no 4º dia (ele já existia), a vida
 * surge.
 */
export const linhaCriacao: Renderizador = {
  arquetipo: 'ordenar',
  criar() {
    const puzzle: Puzzle = {
      arquetipo: 'ordenar',
      extra: 'linha_criacao',
      viz: { comp: 'terra_criacao', aspecto: '16/11', dica: S.criacao.girar },
      valores: {},
      itens: embaralharSem(ESTAGIOS_CRIACAO.map((e) => ({ id: e.id, texto: e.texto }))),
      ordem: [],
    };

    const certos = (): number =>
      (puzzle.ordem ?? []).filter((id, i) => ESTAGIOS_CRIACAO[i]?.id === id).length;

    const completo = (): boolean => {
      const ordem = puzzle.ordem ?? [];
      return (
        ordem.length === ESTAGIOS_CRIACAO.length &&
        ordem.every((id, i) => ESTAGIOS_CRIACAO[i]?.id === id)
      );
    };

    return {
      puzzle,
      info: (): Info => {
        const ordem = puzzle.ordem ?? [];
        // A viz mostra o estágio do último card colocado (ou o início).
        const ultimo =
          ordem.length > 0
            ? (ESTAGIOS_CRIACAO.find((e) => e.id === ordem[ordem.length - 1]) ??
              ESTAGIOS_CRIACAO[0])
            : ESTAGIOS_CRIACAO[0];
        const ok = completo();

        return {
          ok,
          total: ESTAGIOS_CRIACAO.length,
          colocados: ordem.length,
          certos: certos(),
          estagio: ultimo?.estagio ?? 0,
          rotulo: ultimo?.rotulo ?? '',
          verso: ultimo?.verso ?? '',
          terra: ultimo?.terra,
          leitura: ok
            ? 'A linha do tempo bate com Gênesis 1 — e com a ordem que a ciência descreve. ✔'
            : ordem.length < ESTAGIOS_CRIACAO.length
              ? `Toque os eventos na ordem em que aconteceram (${ordem.length}/${ESTAGIOS_CRIACAO.length}).`
              : 'Todos posicionados — confira a ordem e verifique.',
        };
      },
      verificar: () =>
        completo()
          ? ACERTO
          : {
              tipo: 'erro',
              // Diz quantos estão no lugar, sem entregar quais.
              mensagem: `${certos()} de ${ESTAGIOS_CRIACAO.length} no lugar certo — reordene e tente de novo.`,
            },
    };
  },
};

// ── Ciclos: a reciclagem que mantém o planeta habitável ─────────────────────

/**
 * "Ciclos naturais que sustentam a vida": a Terra recicla o próprio ar e a
 * própria água em LAÇOS fechados. A missão é fechar os três.
 */
export const ciclosVida: Renderizador = {
  arquetipo: 'ciclos',
  criar() {
    const ciclos: Record<string, CicloMontado> = {};

    for (const [id, ciclo] of Object.entries(CICLOS_VIDA)) {
      ciclos[id] = {
        nome: ciclo.nome,
        cor: ciclo.cor,
        correta: ciclo.etapas.map((e) => e.id),
        itens: embaralharSem(
          ciclo.etapas.map((e) => ({ id: e.id, curto: e.curto, texto: e.texto, icone: e.icone })),
        ),
        ordem: [],
      };
    }

    const puzzle: Puzzle = {
      arquetipo: 'ciclos',
      extra: 'ciclos',
      viz: { comp: 'ciclos', aspecto: '16/11', dica: S.criacao.girar },
      valores: {},
      ciclos,
      ativo: 'agua',
    };

    const ids = Object.keys(ciclos);
    const fechado = (id: string): boolean => {
      const ciclo = ciclos[id];
      return ciclo !== undefined && cicloCorreto(ciclo.correta, ciclo.ordem);
    };

    return {
      puzzle,
      info: (): Info => {
        const feitos = ids.filter(fechado);
        const ativo = ciclos[puzzle.ativo ?? 'agua'];
        const ok = feitos.length === ids.length;
        if (ativo === undefined) return { ok, leitura: '' };

        // Etapas na ordem montada, para a viz posicionar no anel.
        const sequencia = ativo.ordem.map((id) => ativo.itens.find((item) => item.id === id));

        return {
          ok,
          ativo: puzzle.ativo,
          cor: ativo.cor,
          nome: ativo.nome,
          completoAtivo: fechado(puzzle.ativo ?? 'agua'),
          seq: sequencia,
          total: ativo.itens.length,
          feitos,
          ids,
          leitura: ok
            ? 'Os três ciclos fecham — o mesmo ar e a mesma água circulam sem parar. Reciclagem perfeita. ✔'
            : fechado(puzzle.ativo ?? 'agua')
              ? `Ciclo da ${ativo.nome.toLowerCase()} fechado! Faltam: ${ids
                  .filter((id) => !feitos.includes(id))
                  .map((id) => ciclos[id]?.nome ?? id)
                  .join(', ')}.`
              : ativo.ordem.length < ativo.itens.length
                ? `Monte o ciclo: toque os estágios na ordem em que a matéria circula (${ativo.ordem.length}/${ativo.itens.length}).`
                : 'Todos posicionados — mas a ordem não fecha o laço. Reordene.',
        };
      },
      verificar: () => {
        const feitos = ids.filter(fechado);
        if (feitos.length === ids.length) return ACERTO;

        const faltam = ids.filter((id) => !feitos.includes(id)).map((id) => ciclos[id]?.nome ?? id);
        return {
          tipo: 'erro',
          mensagem: `${feitos.length} de ${ids.length} ciclos fechados — faltam: ${faltam.join(', ')}.`,
        };
      },
    };
  },
};

// ── Solar: as três cenas do sistema solar ───────────────────────────────────

/**
 * A órbita da Terra: o corpo já herda os ~29,78 km/s do planeta. Acertar não é
 * só ficar em órbita — é ficar numa órbita CIRCULAR, que é o que a Terra tem.
 * Devagar demais e o corpo cai no Sol; rápido demais e escapa (~42,1 km/s).
 */
export const orbita: Renderizador = {
  arquetipo: 'solar',
  criar(cfg) {
    const vCirc = num(cfg.vCirc, 29.78);
    const vEsc = num(cfg.vEsc, 42.1);
    const tolV = num(cfg.tolV, 1.5);

    const puzzle: Puzzle = {
      arquetipo: 'solar',
      viz: { comp: 'solar' },
      solar: { modo: 'lancamento' },
      resultado: null,
      controles: [
        {
          rotulo: 'Velocidade no lançamento',
          prop: 'v',
          min: 15,
          max: 50,
          step: 0.1,
          suf: ' km/s',
        },
      ],
      valores: { v: num(cfg.v0, 18) },
    };

    const circular = (): boolean =>
      puzzle.resultado?.situacao === 'estavel' && Math.abs(v(puzzle.valores, 'v') - vCirc) <= tolV;

    return {
      puzzle,
      info: (): Info => {
        const situacao = puzzle.resultado?.situacao;
        const velocidade = v(puzzle.valores, 'v');

        const porSituacao: Readonly<Record<string, string>> = {
          voando: S.criacao.orbVoando,
          cai: S.criacao.orbCai,
          escapa: S.criacao.orbEscapa,
          estavel:
            Math.abs(velocidade - vCirc) <= tolV
              ? `Órbita circular perfeita a ${vCirc} km/s ✔`
              : velocidade < vCirc
                ? 'Órbita elíptica (oval): acelere até ficar circular.'
                : 'Órbita elíptica (oval): desacelere até ficar circular.',
        };

        const base =
          situacao === undefined
            ? S.criacao.orbInforme
            : (porSituacao[situacao] ?? S.criacao.orbInforme);
        const ok = circular();

        return {
          ok,
          leitura: ok ? base : `${base}  (circular ${vCirc} · escape ${vEsc} km/s)`,
        };
      },
      verificar: () =>
        circular()
          ? { tipo: 'ok', mensagem: `Órbita circular perfeita a ${vCirc} km/s!` }
          : { tipo: 'erro', mensagem: S.criacao.orbAjuste },
    };
  },
};

/**
 * A magnetosfera: o campo magnético da Terra desvia o vento solar para os polos
 * (é de lá que vêm as auroras). Fraco demais, as partículas chegam à superfície.
 */
export const campo: Renderizador = {
  arquetipo: 'solar',
  criar(cfg) {
    const limiar = num(cfg.limiar, 60);

    const puzzle: Puzzle = {
      arquetipo: 'solar',
      viz: { comp: 'solar' },
      solar: { modo: 'escudo' },
      extra: 'escudo',
      controles: [
        {
          rotulo: 'Intensidade do campo magnético',
          prop: 'b',
          min: 0,
          max: 100,
          step: 1,
          suf: '%',
        },
      ],
      valores: { b: num(cfg.b0, 15) },
    };

    const medir = (): Info => {
      const ok = v(puzzle.valores, 'b') >= limiar;
      return { ok, leitura: ok ? S.criacao.escudoOk : S.criacao.escudoFraco };
    };

    return {
      puzzle,
      info: medir,
      verificar: () => (medir().ok ? ACERTO : { tipo: 'erro', mensagem: S.criacao.ajuste }),
    };
  },
};

/**
 * As constantes do sistema: gravidade e distância ao Sol. Fora do ponto exato, o
 * planeta deixa de ser habitável — é a lição inteira do puzzle.
 */
export const sandbox: Renderizador = {
  arquetipo: 'solar',
  criar(cfg) {
    const tol = num(cfg.tol, 1);
    const padrao = [
      { rotulo: 'Gravidade', prop: 'g', min: 90, max: 110, step: 0.5, suf: '%' },
      { rotulo: 'Distância ao Sol', prop: 'd', min: 90, max: 110, step: 0.5, suf: '%' },
    ];

    const controles = (
      Array.isArray(cfg.controles) ? (cfg.controles as Partial<(typeof padrao)[number]>[]) : padrao
    ).map((c) => ({
      step: 0.5,
      suf: '%',
      min: 90,
      max: 110,
      rotulo: '',
      prop: '',
      ...c,
    }));

    const valores: Valores = {};
    for (const controle of controles) valores[controle.prop] = 100;

    const puzzle: Puzzle = {
      arquetipo: 'solar',
      viz: { comp: 'solar' },
      solar: { modo: 'constantes' },
      extra: 'sandbox',
      controles,
      valores,
    };

    const medir = (): Info => {
      const fora = controles.filter((c) => Math.abs(v(puzzle.valores, c.prop) - 100) > tol);
      const ok = fora.length === 0;

      return {
        ok,
        leitura: ok
          ? 'Planeta habitável: tudo em equilíbrio ✔'
          : `Inviável: ${fora.map((c) => c.rotulo.toLowerCase()).join(', ')} fora do ponto exato.`,
      };
    };

    return {
      puzzle,
      info: medir,
      verificar: () => (medir().ok ? ACERTO : { tipo: 'erro', mensagem: S.criacao.ajuste }),
    };
  },
};

/** O módulo sem puzzle: leu o conceito, toca em concluir e vai à reflexão. */
export const pronto: Renderizador = {
  arquetipo: 'pronto',
  criar(): Instancia {
    return {
      puzzle: { arquetipo: 'pronto', valores: {} },
      info: () => null,
      verificar: () => ACERTO,
    };
  },
};
