/**
 * A tela das Anotações — porte de `modulos/anotacoes/anotacoes.js` e da seção
 * correspondente do `index.html` do legado.
 *
 * Duas vistas na mesma rota, como no original: a lista (`#/anotacoes`) e o
 * editor (`#/anotacoes/<id>` ou `#/anotacoes/nova/<MODELO>`). O modelo continua
 * viajando no hash — é o que faz recarregar a página no meio de uma nota nova
 * abrir a mesma nota nova, e não uma em branco.
 *
 * O estado mora no módulo, como nas páginas do admin: cada mudança altera o
 * estado e chama `atualizar()`, que redesenha a casca inteira. Não há
 * componente com ciclo de vida próprio aqui — o único é o `<st-editor>`,
 * justamente porque o cursor do usuário não pode ser redesenhado.
 */

import type StEditor from '@marinx/stratum/components/editor/editor.js';
import { isEmptyHtml, sanitizeHtml } from '@marinx/stratum/components/editor/editor.js';
import { html, nothing, type TemplateResult } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import type { Rota } from '../../app/rotas.ts';
import { navegar } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { dataHora, resumo } from '../../texto.ts';
import { confirmar, pedirTexto } from '../../ui/dialogo.ts';
import { Leitura } from '../../ui/leitura.ts';
import { notificar } from '../../ui/notificar.ts';
import {
  type Anotacao,
  CHAVE_LIVRE,
  criarPasta as criarPastaNoBanco,
  excluirAnotacao,
  excluirPasta as excluirPastaNoBanco,
  FILTROS_INICIAIS,
  type Filtros,
  listarAnotacoes,
  listarModelos,
  listarPastas,
  type Modelo,
  obterAnotacao,
  type Pasta,
  renomearPasta as renomearPastaNoBanco,
  salvarAnotacao,
} from './dados.ts';

/** Espera entre a última tecla e a busca de verdade. */
const ESPERA_BUSCA_MS = 400;
/** Espera entre a última alteração e a gravação automática. */
const ESPERA_SALVAR_MS = 1200;

/** A anotação aberta no editor, enquanto ela ainda não foi gravada. */
interface Edicao {
  id: number | null;
  titulo: string;
  conteudo: string;
  tipoModelo: string;
  pastaId: number | null;
  fixada: boolean;
  arquivada: boolean;
  status: string;
}

let modelos: Modelo[] = [];
let pastas: Pasta[] = [];
let lista: Anotacao[] = [];
let filtros: Filtros = FILTROS_INICIAIS;
let edicao: Edicao | null = null;

/** A rota já carregada, para não recarregar tudo a cada redesenho. */
let carregada: string | undefined;
let carregando = false;

let timerBusca: ReturnType<typeof setTimeout> | undefined;
let timerSalvar: ReturnType<typeof setTimeout> | undefined;

let escolhendoModelo = false;

/** Apresentação e voz, compartilhadas com os módulos de acervo (`ui/leitura.ts`). */
const leitura = new Leitura();

function editorNoDocumento(): StEditor | null {
  return document.querySelector('st-editor');
}

/**
 * Impõe o conteúdo ao editor que está no documento.
 *
 * Atribuir `value` é o que troca o texto inteiro; o componente ignora a
 * atribuição quando o valor é o mesmo que já está lá, e é isso que impede o
 * cursor de voltar ao começo a cada redesenho da tela.
 */
function atribuirAoEditor(conteudo: string): void {
  const editor = editorNoDocumento();
  if (editor !== null) editor.value = conteudo;
}

function rotulo(chave: string): string {
  return modelos.find((modelo) => modelo.chave === chave)?.rotulo ?? chave;
}

function conteudoDoModelo(chave: string): string | undefined {
  return modelos.find((modelo) => modelo.chave === chave)?.conteudo;
}

// ── Carga ───────────────────────────────────────────────────────────────────

async function recarregarLista(): Promise<void> {
  lista = await listarAnotacoes(filtros);
  atualizar();
}

/** Abre o editor: uma anotação existente, ou uma nova já com o modelo aplicado. */
async function abrirEditor(id: number | null, chaveModelo: string): Promise<void> {
  leitura.fechar();

  if (id === null) {
    const modelo = conteudoDoModelo(chaveModelo);
    edicao = {
      id: null,
      titulo: '',
      conteudo: modelo ?? '',
      tipoModelo: modelo === undefined ? CHAVE_LIVRE : chaveModelo,
      pastaId: null,
      fixada: false,
      arquivada: false,
      status: '',
    };
  } else {
    const anotacao = await obterAnotacao(id);
    if (anotacao === undefined) {
      navegar('anotacoes');
      return;
    }

    edicao = {
      id: anotacao.id ?? null,
      titulo: anotacao.titulo,
      conteudo: anotacao.conteudo,
      tipoModelo: anotacao.tipo_modelo,
      pastaId: anotacao.pasta_id,
      fixada: anotacao.esta_fixada === 1,
      arquivada: anotacao.esta_arquivada === 1,
      status: '',
    };
  }

  atualizar();
  // `render()` do Lit é síncrono: o elemento já existe aqui, e é este o ponto
  // em que o conteúdo é imposto ao editor (ver `atribuirAoEditor`).
  atribuirAoEditor(edicao.conteudo);
}

/**
 * Sincroniza a tela com o hash. Roda a cada desenho e sai na hora quando a
 * rota é a mesma — quem redesenha é o estado, não o roteador.
 */
function sincronizar(rota: Rota): void {
  const chave = rota.args.join('/');
  if (carregada === chave || carregando) return;

  carregada = chave;
  carregando = true;

  void (async () => {
    try {
      // Modelos e pastas mudam pouco e são usados nas duas vistas; carregar
      // sempre mantém a lista de pastas correta depois de criar uma no editor.
      [modelos, pastas] = await Promise.all([listarModelos(), listarPastas()]);

      const primeiro = rota.args[0];

      if (primeiro === undefined) {
        edicao = null;
        await recarregarLista();
      } else if (primeiro === 'nova') {
        await abrirEditor(null, rota.args[1] ?? CHAVE_LIVRE);
      } else {
        await abrirEditor(Number.parseInt(primeiro, 10), CHAVE_LIVRE);
      }
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

// ── Lista ───────────────────────────────────────────────────────────────────

function buscar(texto: string): void {
  filtros = { ...filtros, busca: texto };
  clearTimeout(timerBusca);
  timerBusca = setTimeout(() => void recarregarLista(), ESPERA_BUSCA_MS);
}

function filtrarPor(mudanca: Partial<Filtros>): void {
  filtros = { ...filtros, ...mudanca };
  void recarregarLista();
}

async function novaPasta(): Promise<void> {
  const nome = await pedirTexto({
    titulo: S.pasta.nova,
    texto: S.pasta.novaTexto,
    placeholder: S.pasta.placeholder,
    rotuloConfirmar: S.acoes.criar,
    erroVazio: S.pasta.erroVazio,
  });
  if (nome === null) return;

  await criarPastaNoBanco(nome);
  pastas = await listarPastas();
  atualizar();
}

async function renomearPasta(pasta: Pasta): Promise<void> {
  const nome = await pedirTexto({
    titulo: S.pasta.renomear,
    valor: pasta.nome,
    placeholder: S.pasta.placeholder,
    rotuloConfirmar: S.acoes.renomear,
    erroVazio: S.pasta.erroVazio,
  });
  if (nome === null || nome === pasta.nome) return;

  await renomearPastaNoBanco(pasta, nome);
  pastas = await listarPastas();
  await recarregarLista();
}

async function excluirPasta(id: number): Promise<void> {
  const ok = await confirmar({
    titulo: S.pasta.excluir,
    texto: S.pasta.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await excluirPastaNoBanco(id);
  pastas = await listarPastas();

  if (filtros.pastaId === id) filtros = { ...filtros, pastaId: null };
  if (edicao?.pastaId === id) edicao = { ...edicao, pastaId: null };

  await recarregarLista();
}

function cartao(anotacao: Anotacao): TemplateResult {
  const previa = resumo(anotacao.conteudo, 150);

  return html`
    <button
      class="cartao"
      ?data-fixada=${anotacao.esta_fixada === 1}
      @click=${() => navegar(`anotacoes/${anotacao.id ?? ''}`)}
    >
      <span class="cartao__topo">
        ${
          anotacao.esta_fixada === 1
            ? html`<st-icon class="cartao__pino" name="pin" variant="filled"></st-icon>`
            : nothing
        }
        <span class="cartao__titulo">${anotacao.titulo || S.anotacoes.semTitulo}</span>
      </span>

      ${previa === '' ? nothing : html`<span class="cartao__previa">${previa}</span>`}

      <span class="cartao__rodape">
        ${
          anotacao.tipo_modelo === CHAVE_LIVRE
            ? nothing
            : html`<st-badge variant="neutral" pill>${rotulo(anotacao.tipo_modelo)}</st-badge>`
        }
        <span class="cartao__data">${dataHora(anotacao.data_modificacao)}</span>
      </span>
    </button>
  `;
}

function telaDaLista(): TemplateResult {
  const pastaAtual = pastas.find((pasta) => pasta.id === filtros.pastaId);

  return html`
    <div class="filtros">
      <st-input
        class="filtros__busca"
        type="search"
        clearable
        placeholder=${S.anotacoes.buscar}
        .value=${filtros.busca}
        @st-input=${(evento: Event) => buscar((evento.target as HTMLInputElement).value)}
      >
        <st-icon slot="prefix" name="search"></st-icon>
      </st-input>

      <st-select
        .value=${filtros.modeloChave}
        placeholder=${S.anotacoes.todosModelos}
        @st-change=${(evento: Event) =>
          filtrarPor({ modeloChave: (evento.target as HTMLInputElement).value })}
      >
        <st-option value="">${S.anotacoes.todosModelos}</st-option>
        ${modelos.map((modelo) => html`<st-option value=${modelo.chave}>${modelo.rotulo}</st-option>`)}
      </st-select>
    </div>

    <div class="chips">
      <button
        class="chip"
        ?data-ativo=${filtros.pastaId === null && !filtros.arquivadas}
        @click=${() => filtrarPor({ pastaId: null, arquivadas: false })}
      >
        ${S.anotacoes.todas}
      </button>

      ${pastas.map(
        (pasta) => html`
          <button
            class="chip"
            ?data-ativo=${filtros.pastaId === pasta.id}
            @click=${() => filtrarPor({ pastaId: pasta.id ?? null, arquivadas: false })}
          >
            ${pasta.nome}
          </button>
        `,
      )}

      <button
        class="chip"
        ?data-ativo=${filtros.arquivadas}
        @click=${() => filtrarPor({ arquivadas: true, pastaId: null })}
      >
        <st-icon name="archive"></st-icon>${S.anotacoes.arquivadas}
      </button>

      <button class="chip" title=${S.pasta.nova} @click=${() => void novaPasta()}>
        <st-icon name="folder-plus"></st-icon>
      </button>
    </div>

    ${
      pastaAtual === undefined
        ? nothing
        : html`
          <div class="pasta-acoes">
            <span class="pasta-acoes__nome">
              <st-icon name="folder"></st-icon>${pastaAtual.nome}
            </span>
            <st-button size="small" @click=${() => void renomearPasta(pastaAtual)}>
              <st-icon slot="prefix" name="pencil"></st-icon>${S.acoes.renomear}
            </st-button>
            <st-button
              size="small"
              variant="danger"
              outline
              @click=${() => void excluirPasta(pastaAtual.id ?? 0)}
            >
              <st-icon slot="prefix" name="trash"></st-icon>${S.acoes.excluir}
            </st-button>
          </div>
        `
    }

    ${
      lista.length === 0
        ? html`
          <div class="vazio">
            <st-icon class="vazio__icone" name="notes"></st-icon>
            <p>${filtros.arquivadas ? S.anotacoes.semArquivadas : S.anotacoes.semAnotacoes}</p>
          </div>
        `
        : html`<div class="cartoes">${lista.map((anotacao) => cartao(anotacao))}</div>`
    }

    <st-dialog
      label=${S.anotacoes.escolhaModelo}
      ?open=${escolhendoModelo}
      @st-after-hide=${(evento: Event) => {
        if (evento.target !== evento.currentTarget) return;
        escolhendoModelo = false;
      }}
    >
      <div class="modelos">
        ${modelos.map(
          (modelo) => html`
            <button
              class="modelo"
              @click=${() => {
                escolhendoModelo = false;
                navegar(`anotacoes/nova/${modelo.chave}`);
              }}
            >
              <st-icon name=${modelo.chave === CHAVE_LIVRE ? 'file-text' : 'template'}></st-icon>
              <span>${modelo.rotulo}</span>
            </button>
          `,
        )}
      </div>
    </st-dialog>
  `;
}

// ── Editor ──────────────────────────────────────────────────────────────────

function agendarSalvar(): void {
  if (edicao === null) return;
  edicao = { ...edicao, status: S.anotacoes.salvando };
  atualizar();

  clearTimeout(timerSalvar);
  timerSalvar = setTimeout(() => void salvar(), ESPERA_SALVAR_MS);
}

/** Grava a anotação. Sem título não há o que gravar — como no legado. */
async function salvar(): Promise<void> {
  if (edicao === null) return;

  if (edicao.titulo.trim() === '') {
    edicao = { ...edicao, status: S.anotacoes.informeTitulo };
    atualizar();
    return;
  }

  const agora = Date.now();
  const registro: Anotacao = {
    titulo: edicao.titulo,
    conteudo: edicao.conteudo,
    tipo_modelo: edicao.tipoModelo,
    pasta_id: edicao.pastaId,
    esta_fixada: edicao.fixada ? 1 : 0,
    esta_arquivada: edicao.arquivada ? 1 : 0,
    data_modificacao: agora,
    ...(edicao.id === null ? { data_criacao: agora } : { id: edicao.id }),
  };

  const id = await salvarAnotacao(registro);

  if (edicao.id === null) {
    edicao = { ...edicao, id };
    // `replaceState` em vez de navegar: trocar o hash dispararia `hashchange`,
    // e a rota recarregaria o editor no meio da digitação. Como o roteador não
    // é avisado, `carregada` continua sendo a rota da nota nova — é isso que
    // impede `sincronizar()` de reabrir o editor em branco no desenho seguinte.
    history.replaceState(null, '', `#/anotacoes/${id}`);
  }

  edicao = { ...edicao, status: S.anotacoes.salvoAs(dataHora(agora)) };
  atualizar();
}

async function aplicarModelo(chave: string): Promise<void> {
  if (edicao === null) return;

  const anterior = edicao.tipoModelo;
  const conteudo = conteudoDoModelo(chave);
  edicao = { ...edicao, tipoModelo: chave };

  if (conteudo === undefined || conteudo === '') {
    agendarSalvar();
    return;
  }

  // Com texto já escrito, substituir é perder trabalho: confirma antes.
  if (!isEmptyHtml(edicao.conteudo)) {
    const ok = await confirmar({
      titulo: S.anotacoes.aplicarModelo,
      texto: S.anotacoes.aplicarModeloTexto,
      rotuloConfirmar: S.acoes.substituir,
      variante: 'warning',
    });

    // Desistir tem de desfazer também o que o próprio campo já mostrou: sem
    // isto o seletor ficaria exibindo um modelo que não foi aplicado.
    if (!ok) {
      edicao = { ...edicao, tipoModelo: anterior };
      atualizar();
      return;
    }
  }

  edicao = { ...edicao, conteudo };
  atualizar();
  atribuirAoEditor(conteudo);
  agendarSalvar();
}

/** Atalho do legado: sexta é Vida e Ministério, domingo é discurso público. */
function irParaReuniao(): void {
  const dia = new Date().getDay();
  const chave = dia === 5 ? 'VIDA_E_MINISTERIO' : dia === 0 ? 'DISCURSO' : CHAVE_LIVRE;
  void aplicarModelo(chave);
}

async function alternar(campo: 'fixada' | 'arquivada'): Promise<void> {
  if (edicao === null) return;

  edicao =
    campo === 'fixada'
      ? { ...edicao, fixada: !edicao.fixada }
      : { ...edicao, arquivada: !edicao.arquivada };

  atualizar();
  if (edicao.id !== null) await salvar();
}

async function excluir(): Promise<void> {
  const id = edicao?.id;
  if (id === undefined || id === null) return;

  const ok = await confirmar({
    titulo: S.anotacoes.excluir,
    texto: S.anotacoes.excluirTexto,
    rotuloConfirmar: S.acoes.excluir,
    variante: 'danger',
  });
  if (!ok) return;

  await excluirAnotacao(id);
  notificar(S.anotacoes.excluida);
  navegar('anotacoes');
}

function telaDoEditor(estado: Edicao): TemplateResult {
  return html`
    <div class="editor">
      <st-input
        class="editor__titulo"
        placeholder=${S.anotacoes.tituloPlaceholder}
        .value=${estado.titulo}
        @st-input=${(evento: Event) => {
          edicao = { ...estado, titulo: (evento.target as HTMLInputElement).value };
          agendarSalvar();
        }}
      ></st-input>

      <div class="chips">
        <button
          class="chip"
          ?data-ativo=${estado.pastaId === null}
          @click=${() => {
            edicao = { ...estado, pastaId: null };
            agendarSalvar();
          }}
        >
          ${S.anotacoes.semPasta}
        </button>

        ${pastas.map(
          (pasta) => html`
            <button
              class="chip"
              ?data-ativo=${estado.pastaId === pasta.id}
              @click=${() => {
                edicao = { ...estado, pastaId: pasta.id ?? null };
                agendarSalvar();
              }}
            >
              ${pasta.nome}
            </button>
          `,
        )}

        <button class="chip" title=${S.pasta.nova} @click=${() => void novaPasta()}>
          <st-icon name="folder-plus"></st-icon>
        </button>
      </div>

      <div class="editor__linha">
        <st-select
          class="editor__modelo"
          .value=${estado.tipoModelo}
          label=${S.anotacoes.modelo}
          @st-change=${(evento: Event) =>
            void aplicarModelo((evento.target as HTMLInputElement).value)}
        >
          ${modelos.map(
            (modelo) => html`<st-option value=${modelo.chave}>${modelo.rotulo}</st-option>`,
          )}
        </st-select>
        <span class="editor__status">${estado.status}</span>
      </div>

      <st-editor
        @st-input=${(evento: CustomEvent<{ value: string }>) => {
          edicao = { ...estado, conteudo: evento.detail.value };
          agendarSalvar();
        }}
      ></st-editor>
    </div>

    ${apresentacaoDaAnotacao(estado)}
  `;
}

// ── Apresentação ────────────────────────────────────────────────────────────

/** O que a leitura em voz alta pronuncia: o título e o corpo, sem marcação. */
function textoDaFala(estado: Edicao): string {
  return `${estado.titulo}. ${estado.conteudo}`;
}

function apresentacaoDaAnotacao(estado: Edicao): TemplateResult | typeof nothing {
  return leitura.overlay(
    html`
      <h1>${estado.titulo || S.anotacoes.semTitulo}</h1>
      <div class="prosa">${unsafeHTML(sanitizeHtml(estado.conteudo))}</div>
    `,
    () => textoDaFala(estado),
  );
}

// ── A tela ──────────────────────────────────────────────────────────────────

function acoesDaLista(): TemplateResult {
  return html`
    <st-icon-button
      name="plus"
      label=${S.anotacoes.nova}
      @click=${async () => {
        // Recarrega os modelos antes de oferecer: uma sincronização recente
        // pode ter trazido modelos novos desde que a tela abriu.
        modelos = await listarModelos();
        escolhendoModelo = true;
        atualizar();
      }}
    ></st-icon-button>
  `;
}

function acoesDoEditor(estado: Edicao): TemplateResult {
  const gravada = estado.id !== null;

  return html`
    ${
      gravada
        ? html`
          <st-icon-button
            name="pin"
            variant=${estado.fixada ? 'filled' : 'outline'}
            label=${estado.fixada ? S.anotacoes.desafixar : S.anotacoes.fixar}
            @click=${() => void alternar('fixada')}
          ></st-icon-button>
          <st-icon-button
            name="archive"
            variant=${estado.arquivada ? 'filled' : 'outline'}
            label=${estado.arquivada ? S.anotacoes.restaurar : S.anotacoes.arquivar}
            @click=${() => void alternar('arquivada')}
          ></st-icon-button>
          ${leitura.botaoApresentar()}
          <st-icon-button
            name="trash"
            label=${S.anotacoes.excluir}
            @click=${() => void excluir()}
          ></st-icon-button>
        `
        : html`
          <st-icon-button
            name="calendar-check"
            label=${S.anotacoes.reuniao}
            @click=${irParaReuniao}
          ></st-icon-button>
        `
    }
  `;
}

export const telaAnotacoes: Tela = {
  voltarPara(rota) {
    return rota.args.length === 0 ? 'home' : 'anotacoes';
  },

  titulo(rota) {
    if (rota.args.length === 0) return undefined;
    const titulo = edicao?.titulo.trim() ?? '';
    return titulo === '' ? S.anotacoes.nova : titulo;
  },

  acoes(rota) {
    if (rota.args.length === 0) return acoesDaLista();
    return edicao === null ? undefined : acoesDoEditor(edicao);
  },

  conteudo(rota) {
    sincronizar(rota);

    if (rota.args.length === 0) return telaDaLista();
    if (edicao === null) {
      return html`<div class="carregando"><st-spinner></st-spinner></div>`;
    }
    return telaDoEditor(edicao);
  },
};
