/**
 * A tela do Tutorial — a ajuda do app, um tópico por módulo.
 *
 * Duas vistas: o índice (`#/tutorial`) e o artigo (`#/tutorial/<modulo>`, ou
 * `#/tutorial/visao-geral`). É conteúdo curado e só de leitura: não há CRUD aqui,
 * quem escreve é o admin.
 *
 * O deep-link por módulo é o que faz o botão “?” do cabeçalho de qualquer módulo
 * cair direto no tópico certo (ver `paginas/ajuda.ts`).
 */

import { sanitizeHtml } from '@marinx/stratum/components/editor/editor.js';
import { html, nothing, type TemplateResult } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { MODULOS, modulo } from '../../app/modulos.ts';
import { navegar } from '../../app/rotas.ts';
import { atualizar, type Tela } from '../../app/tela.ts';
import { S } from '../../strings.ts';
import { listarTopicos, porModulo, type Topico, visaoGeral } from './dados.ts';

/** O segmento que abre a visão geral: `modulo_id` vazio não caberia num hash. */
export const VISAO_GERAL = 'visao-geral';

let topicos: readonly Topico[] = [];
let carregado = false;
let carregando = false;

function carregar(): void {
  if (carregado || carregando) return;
  carregando = true;

  void (async () => {
    try {
      topicos = await listarTopicos();
      carregado = true;
    } finally {
      carregando = false;
      atualizar();
    }
  })();
}

/**
 * O tópico de um segmento de rota. Devolve `undefined` para um módulo que ainda
 * não tem tópico escrito — o de fábrica cobre os 18 de hoje, mas um módulo novo
 * pode chegar antes do texto dele.
 */
function topicoDe(segmento: string): Topico | undefined {
  if (segmento === VISAO_GERAL) return visaoGeral(topicos);
  return porModulo(topicos).get(segmento);
}

function linha(topico: Topico): TemplateResult {
  const m = modulo(topico.modulo_id);
  const destino = topico.modulo_id === '' ? VISAO_GERAL : topico.modulo_id;

  return html`
    <button
      class="linha"
      style=${m === undefined ? '' : `--cor:${m.cor}`}
      @click=${() => navegar(`tutorial/${destino}`)}
    >
      <st-icon class="linha__icone" name=${m?.icone ?? 'help-circle'}></st-icon>
      <span class="linha__rotulo">
        ${topico.titulo}
        ${topico.resumo === '' ? nothing : html`<small class="linha__resumo">${topico.resumo}</small>`}
      </span>
      <st-icon class="linha__seta" name="chevron-right"></st-icon>
    </button>
  `;
}

function telaDoIndice(): TemplateResult {
  if (topicos.length === 0) {
    return html`
      <div class="vazio">
        <st-icon class="vazio__icone" name="help-circle"></st-icon>
        <p>${S.tutorial.vazio}</p>
      </div>
    `;
  }

  const geral = visaoGeral(topicos);
  const mapa = porModulo(topicos);
  // A ordem da lista é a dos módulos no registro do app, e não a do acervo:
  // é assim que o índice do tutorial espelha o que o usuário vê na home.
  const doModulo = MODULOS.map((m) => mapa.get(m.id)).filter(
    (topico): topico is Topico => topico !== undefined,
  );

  return html`
    <p class="intro">${S.tutorial.intro}</p>

    ${
      geral === undefined
        ? nothing
        : html`
          <h2 class="secao">${S.tutorial.visaoGeral}</h2>
          <div class="lista">${linha(geral)}</div>
        `
    }

    <h2 class="secao">${S.tutorial.modulos}</h2>
    <div class="lista">${doModulo.map((topico) => linha(topico))}</div>
  `;
}

function telaDoArtigo(topico: Topico): TemplateResult {
  return html`<div class="prosa">${unsafeHTML(sanitizeHtml(topico.conteudo))}</div>`;
}

export const telaTutorial: Tela = {
  voltarPara(rota) {
    return rota.args.length === 0 ? 'home' : 'tutorial';
  },

  titulo(rota) {
    const [segmento] = rota.args;
    if (segmento === undefined) return undefined;
    return topicoDe(segmento)?.titulo;
  },

  conteudo(rota) {
    carregar();

    const [segmento] = rota.args;
    if (segmento === undefined) return telaDoIndice();

    const topico = topicoDe(segmento);
    if (topico !== undefined) return telaDoArtigo(topico);

    // Enquanto os tópicos não chegaram, o artigo ainda não existe; depois disso,
    // a ausência é real e o aviso é honesto.
    if (!carregado) return html`<div class="carregando"><st-spinner></st-spinner></div>`;

    return html`
      <div class="vazio">
        <st-icon class="vazio__icone" name="help-circle"></st-icon>
        <p>${S.tutorial.semTopico}</p>
      </div>
    `;
  },
};
