/**
 * Onboarding de boas-vindas — porte de `Pwa/telas/boasvindas.js` e do bloco
 * `x-if="boasVindas.aberto"` do `index.html` legado.
 *
 * Roda uma vez, na primeira abertura, e volta pelo botão da tela Sobre. O "já
 * vi" fica em `localStorage`, e não no SQLite, porque é preferência do
 * aparelho, não conteúdo do usuário — a razão que o legado já dava, e que segue
 * valendo: o banco é sincronizado, a apresentação não.
 *
 * **Não é uma rota.** O legado o desenhava por cima do app, e é o certo: como
 * tela, ele entraria no histórico e o botão de voltar do navegador cairia dentro
 * dele; e a primeira abertura mostraria a apresentação *no lugar* da home em vez
 * de por cima dela. É um `st-dialog` sem cabeçalho — o corpo desenha o seu, com
 * o ícone grande que o passo pede.
 */

import { html, nothing, type TemplateResult } from 'lit';
import { S } from '../strings.ts';
import { abrir } from './dialogo.ts';

/**
 * A chave do legado, preservada: quem já viu a apresentação no app antigo não a
 * vê de novo no Papiro novo.
 */
export const CHAVE_BOAS_VINDAS = 'papiro-boas-vindas-visto';

interface Passo {
  readonly id: keyof typeof S.boasVindas.passos;
  readonly icone: string;
  /**
   * A cor de destaque do passo. Literal, como nos cartões de "Sobre": é
   * identidade de um item de conteúdo, não decisão de tema — os cinco existem
   * para se distinguirem entre si, e um token do Stratum os igualaria.
   */
  readonly cor: string;
}

const PASSOS: readonly Passo[] = [
  { id: 'bemVindo', icone: 'sparkles', cor: '#0d6efd' },
  { id: 'painel', icone: 'layout-grid', cor: '#6f42c1' },
  { id: 'offline', icone: 'wifi-off', cor: '#198754' },
  { id: 'privado', icone: 'shield-lock', cor: '#dc3545' },
  { id: 'instalar', icone: 'device-mobile', cor: '#fd7e14' },
];

/** Se a apresentação já foi vista neste aparelho. */
export function jaViuBoasVindas(): boolean {
  try {
    return localStorage.getItem(CHAVE_BOAS_VINDAS) !== null;
  } catch {
    // Sem `localStorage` não há como lembrar de nada, e repetir a apresentação
    // a cada abertura seria pior do que nunca mostrá-la.
    return true;
  }
}

function marcarVisto(): void {
  try {
    localStorage.setItem(CHAVE_BOAS_VINDAS, '1');
  } catch {
    // Modo privativo: a apresentação volta na próxima abertura, e só.
  }
}

function corpoDoPasso(indice: number): TemplateResult {
  const passo = PASSOS[indice];
  if (passo === undefined) return html``;

  const texto = S.boasVindas.passos[passo.id];

  return html`
    <div class="bv" style="--cor: ${passo.cor}">
      <span class="bv__icone">
        <st-icon name=${passo.icone}></st-icon>
      </span>

      <h2 class="bv__titulo">${texto.titulo}</h2>
      <p class="bv__texto">${texto.texto}</p>

      <p class="bv__dica">
        <st-icon name="bulb"></st-icon>
        ${texto.dica}
      </p>

      <div
        class="bv__passos"
        role="progressbar"
        aria-valuemin="1"
        aria-valuemax=${PASSOS.length}
        aria-valuenow=${indice + 1}
        aria-valuetext=${S.boasVindas.passo(indice + 1, PASSOS.length)}
      >
        ${PASSOS.map(
          (_, i) => html`<span class="bv__ponto ${i === indice ? 'bv__ponto--atual' : ''}"></span>`,
        )}
      </div>
    </div>
  `;
}

/**
 * Abre a apresentação e resolve quando ela fecha, de qualquer jeito — no
 * "Começar a usar", no "Pular", no Esc ou no clique fora.
 *
 * **Fechar conta como visto em todos esses casos.** Quem pulou pulou de
 * propósito; reaparecer na abertura seguinte transformaria a apresentação em
 * cobrança, e o botão do Sobre existe justamente para quem mudar de ideia.
 */
export function abrirBoasVindas(): Promise<void> {
  let indice = 0;

  return abrir<void>(
    S.boasVindas.passos.bemVindo.titulo,
    undefined,
    (fechar, _dialogo, redesenhar) => {
      const ultimo = indice === PASSOS.length - 1;

      const avancar = (): void => {
        if (ultimo) {
          fechar(undefined);
          return;
        }
        indice += 1;
        redesenhar();
      };

      const voltar = (): void => {
        if (indice === 0) return;
        indice -= 1;
        redesenhar();
      };

      return html`
        ${corpoDoPasso(indice)}

        ${
          indice === 0
            ? nothing
            : html`
              <st-button slot="footer" @click=${voltar}>
                <st-icon slot="prefix" name="arrow-left"></st-icon>
                ${S.boasVindas.voltar}
              </st-button>
            `
        }
        ${
          ultimo
            ? nothing
            : html`
              <st-button slot="footer" variant="text" @click=${() => fechar(undefined)}>
                ${S.boasVindas.pular}
              </st-button>
            `
        }
        <st-button slot="footer" variant="primary" @click=${avancar}>
          ${ultimo ? S.boasVindas.comecar : S.boasVindas.proximo}
          <st-icon slot="suffix" name=${ultimo ? 'check' : 'arrow-right'}></st-icon>
        </st-button>
      `;
    },
    { semCabecalho: true, classe: 'bv__dialogo' },
  ).then(marcarVisto);
}

/**
 * A apresentação na primeira abertura. Não faz nada nas seguintes — e é por isso
 * que quem chama não precisa saber se é a primeira.
 */
export async function boasVindasNaPrimeiraAbertura(): Promise<void> {
  if (jaViuBoasVindas()) return;
  await abrirBoasVindas();
}
