/**
 * Os dados do Caderno de Estudo — porte de `modulos/caderno/caderno.js`.
 *
 * Store privado (`pap_caderno_estudo`), 100% local. É o CRUD unificado das
 * anotações de estudo: o que o usuário escreve em "Teve um Projeto?", "Modo
 * Estudo" e "Língua Pura" é guardado aqui, com a origem marcada no registro.
 *
 * `gravarNoCaderno` e `removerDoCaderno` continuam exportadas porque são a porta
 * de entrada dos outros módulos — quando eles chegarem na Fase 3, é por aqui que
 * gravam, sem tocar no store.
 */

import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

/** De onde a anotação foi escrita. */
export type Origem = 'criacao' | 'estudo' | 'jogo' | 'avulso';

export interface Anotacao extends Registro {
  id?: number;
  titulo: string;
  conteudo: string;
  origem: Origem;
  /** Módulo, texto bíblico, assunto — texto livre do usuário. */
  referencia: string;
  /**
   * Identidade do texto-fonte, quando a anotação espelha algo de outro módulo.
   * É por ela que a gravação é um upsert: reeditar o mesmo puzzle atualiza a
   * anotação em vez de criar outra.
   */
  ref_chave: string | null;
  criado: number;
  atualizado: number;
}

/** Rótulo, ícone e cor de cada origem. Os ícones são os do Stratum. */
export const ORIGENS: Readonly<Record<Origem, { rotulo: string; icone: string; cor: string }>> = {
  criacao: { rotulo: 'Teve um Projeto?', icone: 'compass', cor: '#6610f2' },
  estudo: { rotulo: 'Modo Estudo', icone: 'hourglass', cor: '#6f42c1' },
  jogo: { rotulo: 'Língua Pura', icone: 'device-gamepad-2', cor: '#198754' },
  avulso: { rotulo: 'Avulso', icone: 'notes', cor: '#0d6efd' },
};

export function origem(chave: string): { rotulo: string; icone: string; cor: string } {
  return ORIGENS[chave as Origem] ?? ORIGENS.avulso;
}

const repo = () => repositorio('pap_caderno_estudo');

export function listarAnotacoes(): Promise<Anotacao[]> {
  return repo().todos<Anotacao>();
}

export interface Filtros {
  /** `'todas'` ou uma das origens. */
  readonly origem: string;
  readonly busca: string;
}

export const FILTROS_INICIAIS: Filtros = { origem: 'todas', busca: '' };

/** Filtra e ordena (mais recente primeiro). Puro: é a regra da lista. */
export function filtrar(lista: readonly Anotacao[], filtros: Filtros): Anotacao[] {
  const alvo = filtros.busca.trim().toLowerCase();

  return lista
    .filter((item) => filtros.origem === 'todas' || item.origem === filtros.origem)
    .filter(
      (item) =>
        alvo === '' ||
        item.titulo.toLowerCase().includes(alvo) ||
        item.conteudo.toLowerCase().includes(alvo) ||
        item.referencia.toLowerCase().includes(alvo),
    )
    .sort((a, b) => (b.atualizado || 0) - (a.atualizado || 0));
}

export function salvarAnotacao(anotacao: Anotacao): Promise<number> {
  return repo().salvar(anotacao);
}

export function excluirAnotacao(id: number): Promise<void> {
  return repo().excluir(id);
}

/** O que outro módulo manda gravar no caderno. */
export interface Rascunho {
  readonly origem?: Origem;
  readonly referencia?: string;
  readonly titulo?: string;
  readonly conteudo?: string;
  readonly ref_chave?: string | null;
}

/** Onde fica o rascunho que um módulo deixa antes de abrir o caderno. */
export const CHAVE_RASCUNHO = 'papiro_caderno_rascunho';

/** Deixa o contexto para a tela de anotação nova e devolve a rota a abrir. */
export function prepararRascunho(contexto: Rascunho): string {
  sessionStorage.setItem(CHAVE_RASCUNHO, JSON.stringify(contexto));
  return 'caderno/novo';
}

/** Consome o rascunho (uma vez só) deixado por outro módulo. */
export function consumirRascunho(): Rascunho {
  try {
    const bruto = sessionStorage.getItem(CHAVE_RASCUNHO);
    sessionStorage.removeItem(CHAVE_RASCUNHO);
    return bruto === null ? {} : (JSON.parse(bruto) as Rascunho);
  } catch {
    return {};
  }
}

/**
 * Grava direto no store, sem abrir a tela — para módulos que persistem a
 * anotação enquanto o usuário digita. Com `ref_chave`, atualiza a anotação
 * daquele texto-fonte em vez de criar outra.
 */
export async function gravarNoCaderno(rascunho: Rascunho): Promise<number> {
  const agora = Date.now();
  const chave = rascunho.ref_chave ?? null;

  const existente =
    chave === null ? undefined : (await listarAnotacoes()).find((item) => item.ref_chave === chave);

  const registro: Anotacao = {
    ...(existente ?? { criado: agora, ref_chave: chave }),
    titulo: rascunho.titulo ?? '',
    conteudo: rascunho.conteudo ?? '',
    origem: rascunho.origem ?? 'avulso',
    referencia: rascunho.referencia ?? '',
    atualizado: agora,
  };

  return salvarAnotacao(registro);
}

/** Apaga a anotação espelhada de um texto-fonte que ficou vazio. */
export async function removerDoCaderno(refChave: string | null): Promise<void> {
  if (refChave === null || refChave === '') return;

  const alvo = (await listarAnotacoes()).find((item) => item.ref_chave === refChave);
  if (alvo?.id !== undefined) await excluirAnotacao(alvo.id);
}
