/**
 * Tema claro/escuro. Os temas do Stratum são classes no elemento raiz
 * (`st-theme-light` / `st-theme-dark`), e a preferência fica no localStorage —
 * o mesmo par que o script inline do index.html aplica antes da primeira pintura.
 *
 * Diferença para o admin: aqui a `<meta name="theme-color">` acompanha a troca.
 * No modo instalado é ela que pinta a barra do sistema, e uma barra branca sobre
 * um app escuro é a coisa mais visível que existe.
 */

const CHAVE = 'papiro-tema';

const COR_CLARO = '#ffffff';
const COR_ESCURO = '#0f1115';

export type Tema = 'claro' | 'escuro';

export function temaAtual(): Tema {
  return document.documentElement.classList.contains('st-theme-dark') ? 'escuro' : 'claro';
}

export function aplicarTema(tema: Tema): void {
  const escuro = tema === 'escuro';
  const raiz = document.documentElement.classList;
  raiz.toggle('st-theme-dark', escuro);
  raiz.toggle('st-theme-light', !escuro);
  document
    .querySelector('meta[name="theme-color"]')
    ?.setAttribute('content', escuro ? COR_ESCURO : COR_CLARO);
  localStorage.setItem(CHAVE, tema);
}

/** Alterna o tema e devolve o que passou a valer. */
export function alternarTema(): Tema {
  const proximo: Tema = temaAtual() === 'escuro' ? 'claro' : 'escuro';
  aplicarTema(proximo);
  return proximo;
}
