/**
 * Roteador do PWA — porte de `sang.local/src/Papiro/Pwa/roteador.js`.
 *
 * A rota mora no hash (`#/modulo/arg?filtro=x`), e não no caminho, porque o app
 * é hospedado como site estático: sem servidor para devolver o `index.html` em
 * qualquer URL, `history.pushState` quebraria em qualquer recarga que não fosse
 * a raiz. O hash também sobrevive ao `start_url` do manifest no modo instalado.
 */

/** A rota que o hash descreve neste instante. */
export interface Rota {
  /** Primeiro segmento; `home` quando o hash está vazio. */
  readonly modulo: string;
  /** Os segmentos seguintes, já separados. */
  readonly args: readonly string[];
  /** O que vier depois do `?`. */
  readonly query: URLSearchParams;
}

/** Lê a rota do hash atual. */
export function rotaAtual(): Rota {
  const hash = location.hash.replace(/^#\/?/, '');
  const [caminho = '', query = ''] = hash.split('?');
  const partes = caminho.split('/').filter((parte) => parte !== '');

  return {
    modulo: partes[0] ?? 'home',
    args: partes.slice(1),
    query: new URLSearchParams(query),
  };
}

/** Navega para um caminho interno, com ou sem o `#/` na frente. */
export function navegar(caminho: string): void {
  location.hash = caminho.startsWith('#') ? caminho : `#/${caminho.replace(/^\//, '')}`;
}

/**
 * Assina as mudanças de rota e já dispara uma vez com a rota atual — o app não
 * precisa desenhar a primeira tela por fora.
 */
export function aoMudarRota(callback: (rota: Rota) => void): void {
  addEventListener('hashchange', () => callback(rotaAtual()));
  callback(rotaAtual());
}
