/**
 * Os dados do Financeiro — porte de `modulos/financeiro/financeiro.js`.
 *
 * Três stores privados: categorias (com cor, emoji e limite mensal), transações e
 * recorrências. Nada sai do aparelho. As **Metas** leem `transacoes` e
 * `categorias_financeiro` para o progresso automático das categorias do
 * Financeiro (ver `modulos/metas/dados.ts`) — `tipo`, `valor` e `categoria_id`
 * são contrato.
 *
 * A tela é o `st-financeiro` do Stratum, que fala em registros limpos
 * (`FinanceiroTransacao` e companhia) em vez das linhas do banco. A conversão
 * entre as duas formas mora aqui, no mesmo arquivo que conhece o esquema: as
 * colunas que o componente não vê — quando o registro nasceu, de qual
 * recorrência ele veio — são preservadas na gravação a partir da linha antiga.
 *
 * A parte que exige cuidado é a recorrência: ela não guarda as transações
 * futuras, guarda **quando a próxima deve nascer**. Ao abrir o módulo, tudo que
 * já venceu é gerado de uma vez — quem não abre o app por dois meses encontra os
 * dois meses lançados, e não um lançamento só.
 */

import type {
  FinanceiroCategoria,
  FinanceiroPeriodicidade,
  FinanceiroRecorrencia,
  FinanceiroTransacao,
} from '@marinx/stratum/components/financeiro/financeiro.js';
import type { Registro } from '../../db/banco.ts';
import { repositorio } from '../../db/banco.ts';

export const TIPO_RECEITA = 0;
export const TIPO_DESPESA = 1;

export interface Categoria extends Registro {
  id?: number;
  nome: string;
  icone: string;
  hex_cor: string;
  limite_mensal: number;
}

export interface Transacao extends Registro {
  id?: number;
  descricao: string;
  valor: number;
  tipo: number;
  categoria_id: number;
  data_vencimento: number;
  esta_pago: number;
  data_criacao: number;
  data_marcado_pago: number;
  origem_recorrencia?: number;
}

export interface Recorrencia extends Registro {
  id?: number;
  descricao: string;
  valor: number;
  tipo: number;
  categoria_id: number;
  periodicidade: string;
  dia_mes: number;
  dia_semana_iso: number;
  gerar_como_pago: number;
  ativo: number;
  data_criacao: number;
  proxima_geracao_epoch: number;
}

const categorias = () => repositorio('categorias_financeiro');
const transacoes = () => repositorio('transacoes');
const recorrencias = () => repositorio('recorrencias_financeiro');

// ── Recorrências: quando nasce a próxima ────────────────────────────────────

function inicioDoDia(data: Date = new Date()): Date {
  const dia = new Date(data);
  dia.setHours(0, 0, 0, 0);
  return dia;
}

/**
 * O epoch da próxima geração a partir de `base`, sempre **depois** dela: uma
 * recorrência semanal marcada para hoje cai na semana que vem, não hoje de novo —
 * é o que impede a geração em laço de lançar duas vezes no mesmo dia.
 */
export function proximaGeracao(
  recorrencia: Pick<Recorrencia, 'periodicidade' | 'dia_mes' | 'dia_semana_iso'>,
  base: Date = inicioDoDia(),
): number {
  const dia = inicioDoDia(base);

  if (recorrencia.periodicidade === 'diaria') {
    dia.setDate(dia.getDate() + 1);
    return dia.getTime();
  }

  if (recorrencia.periodicidade === 'semanal') {
    const atual = dia.getDay() === 0 ? 7 : dia.getDay();
    const distancia = (recorrencia.dia_semana_iso - atual + 7) % 7;
    dia.setDate(dia.getDate() + (distancia === 0 ? 7 : distancia));
    return dia.getTime();
  }

  if (recorrencia.periodicidade === 'anual') {
    dia.setFullYear(dia.getFullYear() + 1);
    return dia.getTime();
  }

  // Mensal: o dia 31 num mês de 30 cai no último dia, não escorrega para o mês
  // seguinte.
  const alvo = new Date(dia);
  if (recorrencia.dia_mes <= dia.getDate()) alvo.setMonth(alvo.getMonth() + 1, 1);

  const ultimoDoMes = new Date(alvo.getFullYear(), alvo.getMonth() + 1, 0).getDate();
  alvo.setDate(Math.min(recorrencia.dia_mes, ultimoDoMes));

  return inicioDoDia(alvo).getTime();
}

/** Teto de lançamentos por recorrência numa passada, contra laço infinito. */
const LIMITE_GERACAO = 60;

/**
 * Gera as transações vencidas de cada recorrência ativa e avança o marcador.
 * Devolve `true` quando gerou algo — o chamador então recarrega.
 */
export async function gerarPendentes(lista: readonly Recorrencia[]): Promise<boolean> {
  const agora = Date.now();
  let gerou = false;

  for (const recorrencia of lista) {
    if (recorrencia.ativo !== 1) continue;

    let proxima = recorrencia.proxima_geracao_epoch || proximaGeracao(recorrencia);
    let voltas = 0;

    while (proxima <= agora && voltas < LIMITE_GERACAO) {
      await transacoes().salvar({
        descricao: recorrencia.descricao,
        valor: recorrencia.valor,
        tipo: recorrencia.tipo,
        categoria_id: recorrencia.categoria_id,
        data_vencimento: proxima,
        esta_pago: recorrencia.gerar_como_pago === 1 ? 1 : 0,
        data_criacao: agora,
        data_marcado_pago: recorrencia.gerar_como_pago === 1 ? agora : 0,
        origem_recorrencia: recorrencia.id ?? 0,
      });

      proxima = proximaGeracao(recorrencia, inicioDoDia(new Date(proxima)));
      voltas += 1;
      gerou = true;
    }

    if (proxima !== recorrencia.proxima_geracao_epoch) {
      await recorrencias().salvar({ ...recorrencia, proxima_geracao_epoch: proxima });
    }
  }

  return gerou;
}

// ── Carga ───────────────────────────────────────────────────────────────────

export interface Dados {
  readonly categorias: Categoria[];
  readonly transacoes: Transacao[];
  readonly recorrencias: Recorrencia[];
}

export async function carregar(): Promise<Dados> {
  const [lista, movimentos, repetidas] = await Promise.all([
    categorias().todos<Categoria>(),
    transacoes().todos<Transacao>(),
    recorrencias().todos<Recorrencia>(),
  ]);

  return { categorias: lista, transacoes: movimentos, recorrencias: repetidas };
}

// ── Do banco para a tela ────────────────────────────────────────────────────

export function paraCategoria(categoria: Categoria): FinanceiroCategoria {
  return {
    id: categoria.id ?? 0,
    nome: categoria.nome,
    icone: categoria.icone,
    cor: categoria.hex_cor,
    limite: categoria.limite_mensal,
  };
}

export function paraTransacao(transacao: Transacao): FinanceiroTransacao {
  return {
    id: transacao.id ?? 0,
    descricao: transacao.descricao,
    valor: transacao.valor,
    tipo: transacao.tipo === TIPO_RECEITA ? 'receita' : 'despesa',
    categoria: transacao.categoria_id,
    vencimento: transacao.data_vencimento,
    pago: transacao.esta_pago === 1,
  };
}

export function paraRecorrencia(recorrencia: Recorrencia): FinanceiroRecorrencia {
  return {
    id: recorrencia.id ?? 0,
    descricao: recorrencia.descricao,
    valor: recorrencia.valor,
    tipo: recorrencia.tipo === TIPO_RECEITA ? 'receita' : 'despesa',
    categoria: recorrencia.categoria_id,
    periodicidade: recorrencia.periodicidade as FinanceiroPeriodicidade,
    diaMes: recorrencia.dia_mes,
    diaSemana: recorrencia.dia_semana_iso,
    gerarComoPago: recorrencia.gerar_como_pago === 1,
    ativa: recorrencia.ativo === 1,
    proxima: recorrencia.proxima_geracao_epoch,
  };
}

// ── Da tela para o banco ────────────────────────────────────────────────────

/** O `id` só entra na linha quando existe: zero é registro novo. */
function comId(id: number): { id?: number } {
  return id > 0 ? { id } : {};
}

export function salvarCategoria(categoria: FinanceiroCategoria): Promise<number> {
  return categorias().salvar({
    ...comId(categoria.id),
    nome: categoria.nome,
    icone: categoria.icone,
    hex_cor: categoria.cor,
    limite_mensal: Math.max(0, categoria.limite),
  });
}

/**
 * A linha antiga entra na gravação porque o componente não conhece — nem
 * precisa conhecer — quando a transação nasceu nem de qual recorrência ela veio.
 */
export function salvarTransacao(
  transacao: FinanceiroTransacao,
  anterior?: Transacao,
): Promise<number> {
  const agora = Date.now();

  return transacoes().salvar({
    ...comId(transacao.id),
    descricao: transacao.descricao,
    valor: Math.abs(transacao.valor),
    tipo: transacao.tipo === 'receita' ? TIPO_RECEITA : TIPO_DESPESA,
    categoria_id: transacao.categoria,
    data_vencimento: transacao.vencimento,
    esta_pago: transacao.pago ? 1 : 0,
    data_criacao: anterior?.data_criacao === undefined ? agora : anterior.data_criacao,
    data_marcado_pago: transacao.pago ? anterior?.data_marcado_pago || agora : 0,
    ...(anterior?.origem_recorrencia === undefined
      ? {}
      : { origem_recorrencia: anterior.origem_recorrencia }),
  });
}

/**
 * A próxima geração é sempre recalculada na gravação: o componente devolve zero
 * ali de propósito, porque quando o próximo lançamento nasce é decisão de quem
 * guarda os dados.
 */
export function salvarRecorrencia(
  recorrencia: FinanceiroRecorrencia,
  anterior?: Recorrencia,
): Promise<number> {
  const linha: Recorrencia = {
    ...comId(recorrencia.id),
    descricao: recorrencia.descricao,
    valor: Math.abs(recorrencia.valor),
    tipo: recorrencia.tipo === 'receita' ? TIPO_RECEITA : TIPO_DESPESA,
    categoria_id: recorrencia.categoria,
    periodicidade: recorrencia.periodicidade,
    dia_mes: recorrencia.diaMes,
    dia_semana_iso: recorrencia.diaSemana,
    gerar_como_pago: recorrencia.gerarComoPago ? 1 : 0,
    ativo: recorrencia.ativa ? 1 : 0,
    data_criacao: anterior?.data_criacao === undefined ? Date.now() : anterior.data_criacao,
    proxima_geracao_epoch: 0,
  };

  return recorrencias().salvar({ ...linha, proxima_geracao_epoch: proximaGeracao(linha) });
}

/**
 * Paga ou desfaz o pagamento, guardando quando foi marcado. Grava a linha do
 * banco, e não o registro da tela: o botão de pago não é um formulário, e não
 * tem por que passar pela conversão inteira.
 */
export function alternarPago(anterior: Transacao): Promise<number> {
  const pago = anterior.esta_pago === 1 ? 0 : 1;

  return transacoes().salvar({
    ...anterior,
    esta_pago: pago,
    data_marcado_pago: pago === 1 ? Date.now() : 0,
  });
}

/** Pausa ou retoma. O marcador da próxima geração fica onde está. */
export function alternarAtivo(anterior: Recorrencia): Promise<number> {
  return recorrencias().salvar({ ...anterior, ativo: anterior.ativo === 1 ? 0 : 1 });
}

export function excluirCategoria(id: number): Promise<void> {
  return categorias().excluir(id);
}

export function excluirTransacao(id: number): Promise<void> {
  return transacoes().excluir(id);
}

export function excluirRecorrencia(id: number): Promise<void> {
  return recorrencias().excluir(id);
}
